typedef struct {
    LTESERIAL_ID serial_id;
    PHICH_INFO phich_info;
    DL_SRS_CONFIG dl_srs_config; // Optional configuration for DL-SRS resources
} LTE_PHY_RX_FRAME_INFO_T;

typedef struct {
    LTE_PHY_RX_FRAME_INFO_T* data;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} DYNAMIC_ARRAY;

DYNAMIC_ARRAY* initialize_dynamic_array(size_t capacity, bool enable_dl_srs) {
    DYNAMIC_ARRAY* array = (DYNAMIC_ARRAY*) malloc(sizeof(DYNAMIC_ARRAY));
    if (!array) return NULL;

    array->capacity = capacity;
    array->count = 0;
    pthread_mutex_init(&array->mutex, NULL);

    array->data = (LTE_PHY_RX_FRAME_INFO_T*) calloc(capacity, sizeof(LTE_PHY_RX_FRAME_INFO_T));
    if (!array->data) {
        free(array);
        return NULL;
    }

    if (enable_dl_srs) {
        for (size_t i = 0; i < capacity; ++i) {
            array->data[i].dl_srs_config.enabled = true; // Default DL-SRS enabled
            // Adjust PHICH_INFO fields based on varying data rates and future extensions
        }
    } else {
        for (size_t i = 0; i < capacity; ++i) {
            array->data[i].dl_srs_config.enabled = false; // Default DL-SRS disabled
        }
    }

    return array;
}
