    void (*gc)(struct data_struct*); // Garbage collection function
} data_struct;

void init_data_struct(data_struct* ds, size_t initial_capacity) {
    ds->keys = calloc((initial_capacity + 1) * sizeof(pair), 1);
    ds->records = calloc((initial_capacity + 1) * sizeof(record), 1);
    ds->capacity = initial_capacity;
    ds->size = 0;
    pthread_mutex_init(&ds->mutex, NULL);
    ds->gc = NULL; // No garbage collection function by default
}

void resize_data_struct(data_struct* ds) {
    if (ds->capacity == 0) {
        init_data_struct(ds, INITIAL_CAPACITY);
        return;
    }

    size_t new_capacity = ds->capacity * 2;
    pair* new_keys = realloc(ds->keys, (new_capacity + 1) * sizeof(pair));
    if (!new_keys) {
        fprintf(stderr, "Failed to allocate memory for keys.\n");
        return;
    }

    record* new_records = realloc(ds->records, (new_capacity + 1) * sizeof(record));
    if (!new_records) {
        fprintf(stderr, "Failed to allocate memory for records.\n");
        free(new_keys);
        return;
    }

    ds->keys = new_keys;
    ds->records = new_records;
    ds->capacity = new_capacity;
}

