        ds->keys[ds->size].key = key;
        ds->keys[ds->size].offset = (long)(&ds->records[ds->size]);
        ++ds->size;
    } else {
        // Implement garbage collection logic here
    }

    pthread_mutex_unlock(&ds->mutex);
    return false;
}

int get_value(data_struct* ds, int key) {
    pthread_mutex_lock(&ds->mutex);

    for (size_t i = 0; i < ds->size; ++i) {
        if (ds->keys[i].key == key) {
            int value = ds->records[ds->keys[i].offset].value;
            pthread_mutex_unlock(&ds->mutex);
            return value;
