        switch (opt) {
            case 'c':
                global_options.case_insensitive = true;
                break;
            case 's':
                global_options.only_nonempty = false;
                break;
            case 'o':
                output_file = optarg;
                break;
            case 'h':
                std::cout << "Usage: program [options] input_file\n";
                return 0;
        }
    }

