    for (unsigned int i = 0; i < num_threads; ++i) {
        workers[i] = std::thread(counter, argv[optind]);
    }

    // Wait for all worker threads to finish
    for (auto& w : workers) {
        w.join();
    }

    // Handle output file writing concurrently using a buffer and locking mechanism
    std::stringstream ss;
    ss << line_count;
    std::string output_str = ss.str();

    std::ofstream ofs(output_file, std::ios::out | std::ios::trunc);
    std::unique_lock<std::mutex> lock(mtx);
    lock.unlock(); // Acquire the lock but don't block other threads

    auto write_to_file = [&ofs, &output_str](const char* str) {
        ofs << str;
        if (ofs.fail()) {
            std::cerr << "Error: Failed to write output file.\n";
            exit(1);
        }
    };

    lock.lock(); // Block other threads from writing concurrently
    write_to_file(output_str);
    lock.unlock(); // Release the lock to allow other writes

    return 0;
}
