#include <errno.h>
#include <signal.h>
#include <sys/select.h>
#include <time.h>
#include <dlfcn.h>

typedef void (*TransformFunction)(char*, char*); // Custom transformation function type

struct TransformData {
    char* buffer;
    size_t bufferSize;
    size_t pos;
    FILE* file;
    pthread_mutex_t lock;
};

void Transform(TransformFunction func, void* userData, char* buffer, size_t len) {
    for (size_t i = 0; i < len; ++i)
        func((char*)userData + i);
}

void* ReadThread(void* arg) {
    struct TransformData* data = arg;
    char buffer[4096]; // Default buffer size

    while (1) {
        pthread_mutex_lock(&data->lock);
        ssize_t read = fread(buffer, sizeof(char), sizeof(buffer), data->file);
        if (read <= 0) break; // EOF or error

        data->pos += read;
        Transform(data->buffer, buffer, read);

        pthread_mutex_unlock(&data->lock);
    }

    free(data->buffer);
    close(fileno(data->file));
    free(data->file);
    free(data);
    pthread_exit(NULL);
}

void* WriteThread(void* arg) {
    struct TransformData* data = arg;
    FILE* outputFile = data->file;

    while (1) {
        if (data->pos == 0) usleep(50000); // Sleep a bit when no data to write

        pthread_mutex_lock(&data->lock);
        size_t written = fwrite(data->buffer, sizeof(char), data->pos, outputFile);
        if (written < data->pos) { // Error or interrupted system call
            perror("Write error");
            exit(EXIT_FAILURE);
        }
        data->pos = 0;

        pthread_mutex_unlock(&data->lock);
    }

    pthread_exit(NULL);
}

void ProcessFile(char* inputFile, char* outputFile, const char* ruleSet, size_t maxBufferSize, int log) {
    // Load custom transformation rules
    void* handle = dlopen("transformations.so", RTLD_LAZY | RTLD_NOW);
    if (!handle) {
        perror("Failed to load transformations library");
        exit(EXIT_FAILURE);
    }

    TransformFunction transformFunc = dlsym(handle, "transform");

    // Open input and output files
    FILE* inputFileHandle = fopen(inputFile, "r");
    if (!inputFileHandle) {
        perror("Failed to open input file");
        exit(EXIT_FAILURE);
    }
    FILE* outputFileHandle = fopen(outputFile, "w");
    if (!outputFileHandle) {
        perror("Failed to open output file");
        fclose(inputFileHandle);
        exit(EXIT_FAILURE);
    }

    struct TransformData* data = malloc(sizeof(struct TransformData));
    data->bufferSize = maxBufferSize > 0 ? maxBufferSize : 4096;
    data->buffer = mmap(NULL, data->bufferSize, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (data->buffer == MAP_FAILED) {
        perror("Failed to allocate buffer");
        exit(EXIT_FAILURE);
    }
    data->pos = 0;
    data->file = outputFileHandle;
    pthread_mutex_init(&data->lock, NULL);

    // Create reader and writer threads
    pthread_t readerThread, writerThread;
    if (pthread_create(&readerThread, NULL, &ReadThread, data) || pthread_create(&writerThread, NULL, &WriteThread, data)) {
        perror("Failed to create thread");
        exit(EXIT_FAILURE);
    }

    // Apply transformation rules using custom function
    Transform(transformFunc, inputFileHandle, data->buffer, data->bufferSize);

    // Wait for reader and writer threads to finish
    pthread_join(readerThread, NULL);
    pthread_join(writerThread, NULL);

    // Close and free resources
    munmap(data->buffer, data->bufferSize);
    fclose(inputFileHandle);
    dlclose(handle);
}
```

