/* Function to read an integer from standard input, checking for errors and validity */
int64_t get_int(void) {
    int64_t value;
    if (scanf("%" PRId64, &value) != 1) {
        perror("Error reading input");
        exit(EXIT_FAILURE);
    }
    return value;
