/* Function to dynamically allocate memory for an array of integers based on input size */
int64_t* alloc_array(size_t size) {
    int64_t* arr = malloc(sizeof(int64_t) * size);
    if (!arr) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    return arr;
}

/* Function to free memory allocated by alloc_array() */
void free_array(int64_t* arr, size_t size) {
    if (arr) {
        free(arr);
    }
}

/* Comparison function for qsort() to sort array in descending order */
bool compare(const void *a, const void *b) {
    return (*(int64_t *) a > *(int64_t *) b);
}

/* Main function to process the input list of integers and perform required tasks */
void process_input() {
    size_t n = 0; /* Number of elements read so far */
    int64_t *arr = NULL, max = LONG_MIN; /* Current maximum value, initial value set to minimum integer */
    int odd_count = 0, even_count = 0; /* Counts for even and odd integers */

    while (true) {
        int64_t num = get_int();

        if (!num) { /* End of input reached */
            break;
        }

        if (n == 0) {
            arr = alloc_array(2); /* Allocate initial array with room for two elements */
        } else if (n >= size_t(max - LONG_MIN + 1)) {
            int64_t *temp = realloc(arr, sizeof(int64_t) * (2 * n + 1));

            if (!temp) {
                perror("Memory allocation failed");
                exit(EXIT_FAILURE);
            }

            arr = temp;
        }

        arr[n] = num;
        n++;

        max = (num > max) ? num : max;

        if ((num % 2) == 0) {
            even_count++;
        } else {
            odd_count++;
        }
    }

    qsort(arr, n, sizeof(int64_t), compare); /* Sort the array in descending order */

    printf("Largest integer: %" PRId64 "\n", max);
    printf("Count of even integers: %zu\n", even_count);
    printf("Count of odd integers: %zu\n", odd_count);

    free_array(arr, n); /* Free memory allocated for the array */
}

/* Main function to execute the processing and start reading input */
int main() {
    process_input();
    return 0;
}
