import org.apache.http.util.EntityUtils;
import com.google.common.cache.CacheBuilder;
import com.google.common.cache.LoadingCache;
import java.io.IOException;
import java.net.URI;
import java.time.Duration;
import java.util.Map;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class PokemonReportService {
    private static final String API_URL = "https://api.example.com/pokemon/{id}";
    private LoadingCache<Integer, PokemonData> cache;
    private ExecutorService executor;

    public PokemonReportService() {
        int maxSize = 1000;
        Duration expirationTime = Duration.ofMinutes(5);
        this.cache = CacheBuilder.newBuilder()
                .maximumSize(maxSize)
                .expireAfterWrite(expirationTime)
                .build((id) -> fetchPokemonData(id));
        this.executor = Executors.newCachedThreadPool();
    }

    private Future<PokemonData> fetchPokemonData(Integer id) {
