#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <openssl/crypto.h>
#include <dlfcn.h>

typedef void (*hash_func)(unsigned char *, unsigned char *);
typedef void (*cipher_func)(const unsigned char *, unsigned char *, int, const unsigned char *);

struct crypt_info {
    const char *name;
    hash_func hash;
    cipher_func cipher;
};

void *load_crypto(void *arg) {
    void *handle = dlopen("path/to/your/cryptoloader.so", RTLD_LAZY); // Adjust path to your cryptographic module loader shared object
    if (!handle) {
        fprintf(stderr, "Error: %s\n", dlerror());
        return NULL;
    }

    // Assuming the cryptoloader has functions load_hash() and load_cipher(), which dynamically populate the struct array.
    struct crypt_info *cryptos = malloc(sizeof(struct crypt_info));
    if (!cryptos) {
        fprintf(stderr, "Error: Out of memory\n");
        dlclose(handle);
        return NULL;
    }

    load_hash(handle, cryptos);
    load_cipher(handle, cryptos);

    dlclose(handle);
    return cryptos;
}

struct crypt_info *get_crypto_list() {
    pthread_t threads[NUM_THREADS];
    struct crypt_info *cryptos = NULL;

    for (int i = 0; i < NUM_THREADS; ++i)
        pthread_create(&threads[i], NULL, load_crypto, NULL);

    for (int i = 0; i < NUM_THREADS; ++i)
        pthread_join(threads[i], (void**)&cryptos);

    return cryptos;
}

int main() {
    struct crypt_info *crypto_list = get_crypto_list();

    // Do something with the retrieved hash functions and block ciphers...

    free(crypto_list);
    return 0;
}
