// Thread-safe logging structure
struct log_data {
    sem_t write_lock;
    int fd;
};

void log_message(const char *format, ...) {
    va_list args;
    struct log_data *log = get_log();
    sem_wait(&log->write_lock);

    // Write the formatted message to the log file
    va_start(args, format);
    vfprintf(log->fd, format, args);
    va_end(args);

    sem_post(&log->write_lock);
}

void *encrypt_thread(void *arg) {
