    AES_cbc_encrypt(input, output, strlen(input), &ctx->key, ctx->algorithm, AES_ENCRYPT);

    // Log the start time of the encryption operation
    start = time(NULL);
    log_message("Encryption started: %s -> %s\n", input, ctx->algorithm);

    // Process the encrypted data or pass it to other components
    // ...

    // Log the completion time of the encryption operation
    end = time(NULL);
    log_message("Encryption completed: %ld seconds elapsed\n", difftime(end, start));

    return NULL;
}

int main(int argc, char *argv[]) {
    int queue[2], i, ret;
    pthread_t threads[MAX_THREADS];
    encryption_ctx_t ctx[MAX_ALGORITHMS];
    struct log_data log = {.write_lock = PTHREAD_MUTEX_INITIALIZER, .fd = open("logfile.txt", O_WRONLY | O_CREAT | O_APPEND, 0644)};

    // Initialize encryption contexts and algorithms
    for (i = 0; i < MAX_ALGORITHMS; ++i) {
        // ...
    }

    pipe(queue);

    for (i = 0; i < MAX_THREADS; ++i) {
        ret = pthread_create(&threads[i], NULL, encrypt_thread, &ctx[rand() % MAX_ALGORITHMS]);
        if (ret != 0) {
            perror("pthread_create");
            exit(EXIT_FAILURE);
        }
    }

    // Read input data from stdin or another source and send it to the encryption queue
    while (1) {
        char buffer[1024];
        read(STDIN_FILENO, buffer, sizeof(buffer));
        write(queue[1], buffer, strlen(buffer));
    }

    // Join the threads and clean up resources
    for (i = 0; i < MAX_THREADS; ++i) {
