['```cpp
#include <vector>
#include <deque>
#include <mutex>
#include <future>

template<typename Iterator>
void push_back_if(Iterator begin, Iterator end, const Iterator& target, const int value) {
    for (auto it = begin; it != end; ++it) {
        if (*it == *target) {
            it = begin + std::distance(begin, it); // Move the iterator to the position before the target.
            break;
        }
    }

    if (it == end) {
        *it = value;
    } else {
        auto last_position = it;
        ++last_position;
        std::iterator_traits<Iterator>::difference_type offset = std::distance(begin, last_position);
        std::copy_backward(std::next(it), end, last_position);
        *it = value;
    }
}

void insertElement(std::vector<int>& data, int target, int value) {
    std::deque<int> buffer; // Thread-safe buffer to hold data while accessing external source.
    std::mutex mtx;

    auto future = std::async([&]() {
        // Get the current state of the vector without blocking the main thread.
        auto copy_begin = data.cbegin();
        auto copy_end = data.cend();

        for (auto it = copy_begin; it != copy_end; ++it) {
            if (*it == target) {
                buffer.push_back(*it); // Store the element before target in the buffer to maintain stability.
                break;
            }
            buffer.push_back(*it); // Store all elements before the potential location for insertion.
        }
    }, std::deferred>());

    push_back_if(buffer.begin(), buffer.end(), target, value); // Insert element in the local buffer.

    { // Acquire a lock to safely update the vector and merge the buffer with the main data.
        std::unique_lock<std::mutex> lock(mtx);
        future.wait();
        auto buffer_begin = buffer.cbegin();
        auto buffer_end = buffer.cend();

        push_back_if(data.begin(), data.end(), target, value); // Check if the target exists in the updated vector and insert element as required.
        std::copy(buffer_begin, buffer_end, std::inserter(data, std::next(data.end()))); // Merge the buffered elements into the main data vector.
    }
}
