void LoadBalancer::makeRequest(const std::string& url) {
    m_queue.push_back([url, this]() {
        auto it = m_connections.emplace(tcp::socket(m_ioContext), std::thread());
        if (it.first != m_connections.end()) {
            it.first->second = std::ref(*this);

            tcp::resolver::query query(asio::ip::host_name(), url);
            m_resolver.async_resolve(query, [it](const boost::system::error_code& ec, tcp::resolver::results_type results) {
                if (!ec) {
                    it.first->remote_endpoint() = *results.begin();
                    do_connect(*it.first, [it](const boost::system::error_code& ec) {
                        if (!ec) {
                            auto rateLimitTime = m_rateLimiter.acquire(1);
                            if (rateLimitTime > 0) {
                                // Send GET request and process response here
                            }
                        }
                    });
                }
            });
        }
    });
}

void LoadBalancer::run() {
