using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Xml;
using System.Xml.XPath;
using Microsoft.Win32;

public static void GetDirectoryPath(string attributeName)
{
    string currentPath = Environment.GetEnvironmentVariable("DIRECTORY_PATH");
    if (string.IsNullOrEmpty(currentPath))
    {
        RegistryKey key = Registry.CurrentUser.OpenSubKey(@"Environment");
        if (key != null)
        {
            object pathObject = key.GetValue("DIRECTORY_PATH");
            if (pathObject != null && !string.IsNullOrEmpty(pathObject.ToString()))
            {
                currentPath = pathObject.ToString();
                Console.WriteLine($"Warning: DIRECTORY_PATH environment variable already set to '{currentPath}'.");
            }
        }
    }

    XmlDocument xmlDoc = new XmlDocument();
    try
    {
        xmlDoc.Load("large_xml_document.xml");
    }
    catch (Exception ex)
    {
        Console.WriteLine($"Error loading XML document: {ex.Message}");
        return;
    }

    XPathNavigator navigator = xmlDoc.CreateNavigator();
    string xpathExpression = $"/directories/directory[@{attributeName}]";
    List<XPathNodeIterator> iterators = new List<XPathNodeIterator>();
    try
    {
        iterators.Add(navigator.Select(xpathExpression));
    }
    catch (Exception ex)
    {
        Console.WriteLine($"Error evaluating XPath expression: {ex.Message}");
        return;
    }

    int count = 0;
    if (iterators[0].MoveNext())
    {
        do
        {
            count++;
        } while (iterators[0].MoveNext());
    }

    if (count == 0)
    {
        Console.WriteLine($"No directory found with attribute '{attributeName}'.");
        throw new Exception("Directory not found");
    }
    else if (count > 1)
    {
        Console.WriteLine($"Multiple directories found with attribute '{attributeName}'. Expected exactly one.");
        throw new Exception("Multiple directories found");
    }

    XmlElement directoryElement = (XmlElement)iterators[0].Current;
    currentPath = directoryElement.Attributes[attributeName].Value;
    Environment.SetEnvironmentVariable("DIRECTORY_PATH", currentPath);
    Console.WriteLine($"Directory path set to '{currentPath}'.");

    // For auditing and debugging purposes, log the operation details.
    string auditLog = $"Directory path set to '{currentPath}', attributeName: '{attributeName}', outcome: Success.";
    File.AppendAllText("audit_log.txt", auditLog + Environment.NewLine);
}
