char* determineFileType(const char *filename) {
    // Determine the file type based on the last three characters of the filename
    const size_t len = strlen(filename);
    if (len < 3) return nullptr;
    char *end = filename + strlen(filename) - 3;
    return strchr(end, '.') ? end : nullptr;
}

void* modifyFilenameAndProcessFile(const char *original_filename) {
    // Lock the mutex to prevent race conditions when processing files concurrently
    pthread_mutex_lock(&g_mutex);

    const char *filetype = determineFileType(original_filename);
    if (!filetype) {
        log("Error determining file type for filename: " original_filename);
        pthread_mutex_unlock(&g_mutex);
        return nullptr;
    }

    // Calculate checksum and generate a unique sequence of digits to append
    int checksum = calculateChecksum(original_filename);
    char* new_filename = malloc(strlen(original_filename) + 5);
    snprintf(new_filename, strlen(original_filename) + 5, "%s%04d%s", original_filename, checksum, filetype);

    // Open the new and original files using a memory-mapped I/O approach to minimize I/O operations
    struct stat st;
    if (stat(original_filename, &st) < 0 || stat(new_filename, &st) >= 0) {
        log("Error opening file: " new_filename);
        free(new_filename);
        pthread_mutex_unlock(&g_mutex);
        return nullptr;
    }

    int original_fd = open(original_filename, O_RDONLY | O_SYNC);
    int new_fd = open(new_filename, O_WRONLY | O_CREATE | O_TRUNC | O_SYNC);
    mmap(0, st.st_size, PROT_READ, MAP_PRIVATE, original_fd, 0);
    mmap(0, st.st_size, PROT_WRITE, MAP_SHARED, new_fd, 0);

    // Process the file as needed...

    // Unmap and close the files, releasing system resources
    munmap((void *)MAP_START, st.st_size);
    close(original_fd);
    close(new_fd);

    // Release the lock and continue processing other files
    pthread_mutex_unlock(&g_mutex);

    return new_filename;
}

