["```python
import os
import time
import requests
import json
from functools import lru_cache
import logging
import threading
from concurrent.futures import ThreadPoolExecutor

# Set up logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(message)s')

CACHE_EXPIRY = 60 * 5  # Cache data for 5 minutes
API_KEYS = {
    'api1': os.getenv('API1_KEY'),
    'api2': os.getenv('API2_KEY'),
}

def _fetch_weather_data(api):
    url = f'https://{api}.com/weather/{location}'
    try:
        response = requests.get(url, params={'apikey': API_KEYS[api]})
        if response.status_code == 200:
            return json.loads(response.content)
    except Exception as e:
        logging.error(f'Error fetching data from {api}: {str(e)}')
    return None

@lru_cache(maxsize=128)
def get_weather_data(location):
    now = int(time.time())
    for api, key in API_KEYS.items():
        data = _fetch_weather_data(api)
        if data and data['timestamp'] > now - CACHE_EXPIRY:
            logging.info(f'Cache hit for {location} from {api}')
            return data
    return None

def update_cache(location):
    data = {}
    with ThreadPoolExecutor() as executor:
        futures = []
        for api, key in API_KEYS.items():
            if key:
                futures.append(executor.submit(_fetch_weather_data, api, location))

        for future in futures:
            try:
                response_data = future.result()
                if response_data:
                    data[api] = response_data
                    break
            except Exception as e:
                logging.error(f'Error fetching data from {api}: {str(e)}')

        if data:
            current_data = get_weather_data(location)
            for api, new_data in data.items():
                if not current_data or (current_data[api]['timestamp'] < new_data['timestamp']):
                    logging.info(f'Cache updated for {location} from {api}')
                    get_weather_data.cache_clear()
                    get_weather_data.cache._sync()  # Trigger cache update in LRU Cache
                    return 'Cache successfully updated'
        return 'Failed to update cache, no data retrieved or all data outdated'

if __name__ == '__main__':
    location = 'NYC'  # Replace with desired location
    print(update_cache(location))
```

Please note that this is a basic implementation and assumes you have the API keys for the third-party APIs set as environment variables. Make sure to replace `api1`, `api2` and their respective API keys in your own project. Additionally, adjust the caching expiry time according to your requirements.

This code uses an LRU cache with a maximum size of 128 entries for storing weather data, fetches data concurrently from both APIs using the ThreadPoolExecutor, handles potential errors gracefully, and logs successful updates and any encountered errors. The function `update_cache(location)` checks if there is an up-to-date entry in the cache or not, and if necessary, it fetches fresh data from the APIs, updates the cache, and returns a success message if the update was successful, or a failure reason otherwise."]

