<?php

class ConfigReader {
    private $filePath;
    private $config = [];

    public function __construct($filePath) {
        $this->filePath = $filePath;
    }

    public function read() {
        if (file_exists($this->filePath)) {
            $this->config = array_combine(
                $this->getKeysFromFile($this->filePath),
                $this->getValueFromFile($this->filePath)
            );
        } else {
            trigger_error("Config file not found: {$this->filePath}", E_USER_WARNING);
        }
    }

    private function getKeysFromFile($filename) {
        return array_map('trim', file($filename, FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES));
    }

    private function getValueFromFile($filename) {
        $values = [];
        $lineNumber = 0;
        foreach (file($filename, FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES) as $line) {
            if ($lineNumber % 2 === 0) {
                continue; // Skip key lines
            }
            $values[$lines[$lineNumber - 1]] = rtrim($line);
            $lineNumber++;
        }
        return $values;
    }
}

function generateRandomString($charSet, $length) {
    $randomChars = array_fill(0, $length, null);
    $poolSize = count($charSet);

    for ($i = 0; $i < $length; $i++) {
        $index = random_int(0, $poolSize - 1);
        $randomChars[$i] = $charSet[$index];
    }

    return implode('', $randomChars);
}

function main($configFilePath) {
    $configReader = new ConfigReader($configFilePath);
    $configReader->read();

    if (isset($configReader['character_set']) && isset($configReader['length'])) {
        $charSet = $configReader['character_set'];
        $length = intval($configReader['length']);

        echo generateRandomString($charSet, $length);
    } else {
        trigger_error("Invalid configuration", E_USER_WARNING);
    }
}

main('path/to/your/config.ini');
