#include <mutex>
#include <chrono>
#include <queue>
#include <condition_variable>

class Character {
public:
    enum Attack { ATTACK1, ATTACK2, ATTACK3 };
    std::mutex mtx;
    int energy = 100;
    int cooldown[3] = { 0, 0, 0 };
    int energyCost[3] = { 40, 50, 30 };
    int rechargeRate = 20;
    std::chrono::seconds rechargeInterval(10);
    std::chrono::steady_clock::time_point nextRecharge;
    std::queue<Attack> attackQueue;
    std::condition_variable cv;

    void performAttack(Attack a) {
        if (energy < energyCost[static_cast<int>(a)]) {
            std::cout << "Insufficient energy for attack: " << static_cast<int>(a) << std::endl;
            return;
        }
        energy -= energyCost[static_cast<int>(a)];
        cooldown[static_cast<int>(a)] = std::chrono::steady_clock::now() + std::chrono::seconds(cooldownSeconds[static_cast<int>(a)]);
        attackQueue.push(a);
    }

    void update() {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait_until(lock, nextRecharge);
        if (energy < 100) energy += rechargeRate;
    }

    void resetState() {
        std::lock_guard<std::mutex> lock(mtx);
        energy = 100;
        for (size_t i = 0; i < 3; ++i) cooldown[i] = std::chrono::steady_clock::now() + std::chrono::seconds(cooldownSeconds[i]);
    }

private:
    const std::chrono::seconds cooldownSeconds[3] = { std::chrono::seconds(9), std::chrono::seconds(12), std::chrono::seconds(6) };
};

// Function to manage a video game character’s combat strategy, selecting one of three attacks.
void selectAttackAndPerform(Character& chara) {
    while (true) {
        Attack bestAttack = ATTACK1;
        int minCooldown = std::chrono::duration_cast<std::chrono::seconds>(cooldownSeconds[bestAttack]).count();

        for (Character::Attack a = Character::ATTACK1; a <= Character::ATTACK3; ++a) {
            if (cooldown[static_cast<int>(a)] < chara.cooldown[static_cast<int>(bestAttack)] && energy >= energyCost[static_cast<int>(a)]) {
                bestAttack = a;
                minCooldown = std::chrono::duration_cast<std::chrono::seconds>(cooldownSeconds[static_cast<int>(bestAttack)]).count();
            }
        }

        chara.performAttack(bestAttack);
        std::this_thread::sleep_for(std::chrono::seconds(minCooldown));
    }
}
```

