        resolve(result);
      } catch (error) {
        if (error.name === 'TimeoutError') {
          console.error(`Operation ${i} timed out with error:`, error);
          reject(new TimeoutError('Operation timed out'));
        } else {
          console.error(`Error in operation ${i}:`, error);
          reject(error);
        }
      }
    })
  );

  let completedPromises = 0;

  const handleResults = results => {
    if (completedPromises === promises.length) {
      return results[results.length - 1]; // Return the final accumulated value
    }

    let nextAccumulator = results.reduce((acc, val) => acc + val, initialValue);

    const nextPromiseIndex = Math.min(promises.length - 1, completedPromises + 1);
    promises[nextPromiseIndex].then(result => {
      nextAccumulator += result;
      handleResults(results.concat(result));
    }).catch(error => {
      console.error(`Error in handleResults:`, error);
      // If an error occurs, propagate it to the caller but continue processing other results
      if (completedPromises === 0) throw error;
      handleResults(results);
    });
  };

  try {
    promises.forEach(promise => promise.then(result => {}, error => {})); // Preload all promises to allow Axios retries
    handleResults([initialValue]);
  } catch (error) {
    console.error(`asyncReduce failed with error:`, error);
    throw error;
  }
}

class TimeoutError extends Error {
  constructor(message) {
    super(message);
    this.name = 'TimeoutError';
  }
}
```

