// TruncateString module export
const truncateString = (inputText, maxLength, shouldLogWarnings) => {
  if (!inputText || maxLength <= 0 || typeof maxLength !== 'number') {
    throw new Error('Invalid parameters');
  }

  let output = inputText;
  if (output.length > maxLength - 3) {
    output = output.slice(0, maxLength - 3) + '...';
    shouldLogWarnings && console.warn(`Truncated string: ${output}...`);
  }

  return output + '/';
