// FindElementsMatchingSelector module export
const findElementsMatchingSelector = (rootNode, cssSelector, classCheckCallback, maxDepth) => {
  if (!rootNode || typeof rootNode !== 'object' || !cssSelector || !classCheckCallback || typeof maxDepth !== 'number') {
    throw new Error('Invalid parameters');
  }

  const visit = (node, depth = 1) => {
    if (depth > maxDepth || !node.matches || !(node instanceof HTMLElement)) return;

    if (node.matchesSelector(cssSelector) && classCheckCallback(node.className)) {
      results.push(node);
    }

    for (let i = 0; i < node.children.length; i++) visit(node.children[i]);
  };

  const results = [];
  visit(rootNode);
  return results;
};
