#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>
#include <sys/statfs.h>
#include <unistd.h>

char *generate_filename(const char *input, const char *allowed_extensions[], int max_retries) {
    static const char *extension_list[] = {"txt", "doc", "pdf", "jpg"};
    char *new_filename = malloc(128);
    struct statfs fs_stat;
    time_t now = time(NULL);
    long long micros = now * 1000ULL + (long long) ((double)clock() / CLOCKS_PER_SEC * 1000000.0);
    int filename_length = strlen(input);
    int extension_length = strlen(extension_list[rand() % 4]);
    int digits_to_append = 0;
    char *timestamp = malloc(24);
    struct tm tm;
    localtime_r(&now, &tm);
    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", &tm);
    strlcpy(new_filename, input);

    // Replace spaces with underscores and trim the filename
    for (int i = 0; new_filename[i]; ++i) {
        if (new_filename[i] == ' ') {
            new_filename[i] = '_';
        }
    }
    new_filename[filename_length - 1] = '\0';
    filename_length = strlen(new_filename);

    // Determine the number of digits to append
    if (filename_length > extension_length + 12) {
        digits_to_append = filename_length - extension_length - 12;
    } else {
        digits_to_append = extension_length + 12 - filename_length;
    }

    // Generate unique sequence of digits
    snprintf(new_filename + filename_length, 128 - filename_length, "%lld%llu%lld", (long long)getpid(), micros, (long long)fs_stat.f_blocks * fs_stat.f_bsize / 1024);
    snprintf(new_filename + strlen(new_filename), digits_to_append + 1, "%.*d", digits_to_append, rand() % (int)(pow(10, digits_to_append)));

    // Ensure new filename length does not exceed 128 characters
    if (strlen(new_filename) > 128) {
        free(new_filename);
        return NULL;
    }

    // Append a random file extension
    strcat(new_filename, ".");
    strcat(new_filename, extension_list[rand() % 4]);

    // Check if the generated filename already exists and retry if necessary
    int retries = 0;
    char temp_filename[128];
    while (retries < max_retries) {
        snprintf(temp_filename, sizeof(temp_filename), "%s", new_filename);
        if (access(temp_filename, F_OK) != 0) {
            break;
        }
        ++retries;
        strcpy(new_filename, temp_filename);
    }

    // Log the result and any failures during the generation process
    if (retries == max_retries) {
        printf("Failed to generate unique filename after %d retries for input '%s'\n", max_retries, input);
    } else if (retries > 0) {
        printf("Generated unique filename after %d retries for input '%s' -> '%s'\n", retries, input, new_filename);
    }

    return new_filename;
}
```

This code defines a `generate_filename()` function that takes an input filename and generates a new filename based on the specified criteria. The function dynamically determines the number of digits to append using a combination of the filename's length, character frequency, and the available disk space on the target storage medium. It also includes a retry mechanism for cases where the generated filename already exists, ensuring the function attempts to generate a new name up to five times before failing. The log mechanism tracks the number of retries and any failures during the generation process.']

