typedef struct Config {
    int compressionLevel;
    enum { PORTRAIT, LANDSCAPE } pageOrientation;
    int dpiSettings;
} Config;

pid_t convertJPEGToPDF(const char *jpegFilePath, const char *pdfFilePath, const Config *config) {
    pid_t pid = fork();
    if (pid == -1) {
        err(1, "fork");
    }

    if (!pid) {
        // Child process
        char command[1024];
        snprintf(command, sizeof(command), "mogrify -format PDF -compress %d -page %s%s -density %d jpeg:%s pdf:%s",
                 config->compressionLevel, (config->pageOrientation == PORTRAIT) ? "-resize xc:#FFFFFF" : "-resize xc:#000000",
                 (config->pageOrientation == LANDSCAPE) ? " -rotate 90" : "", config->dpiSettings, jpegFilePath, pdfFilePath);
        int status;
        if (system(command)) {
            warn("mogrify command failed");
            _exit(1);
        }
        _exit(0);
    }

    // Parent process
    waitpid(pid, &status, 0);
    return pid;
}

