    while((pid = waitpid(-1, &status, WNOHANG)) > 0)
        wait(&status);

    // clean up child processes on SIGINT or SIGTERM
}

void log_error(const char* error) {
    // write error message to a specified file
}

int execute_commands(struct command cmds[], size_t count, error_callback callback) {
    pid_t pid;
    int i;

    for (i = 0; i < count; ++i) {
        cmds[i].start = cmds[i].timeout = CURRENT_TIME;

        pid = fork();

        if (pid == -1) {
            log_error("Fork failed");
            callback("Fork failed");
            return 1;
        }

        if (!pid) { // child process
            execvp(cmds[i].command_line, cmds[i].command_line);
            _exit(EXIT_FAILURE);
        }
    }

    struct timespec now;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &now);

        for (i = 0; i < count; ++i) {
            if ((now.tv_sec - cmds[i].start.tv_sec >= TIMEOUT ||
                    now.tv_nsec - cmds[i].start.tv_nsec > TIMEOUT * 1_000_000_000L)) {
                log_error("Command execution timed out");
                callback("Command execution timed out");
                break;
            }

            if (now.tv_sec - cmds[i].timeout.tv_sec >= TIMEOUT ||
                now.tv_nsec - cmds[i].timeout.tv_nsec > TIMEOUT * 1_000_000_000L) {
                kill(cmd[i], SIGTERM);
            }
        }

        if (i == count) { // all commands are running, wait for completion
            pid_t pid;
            int status;

            while((pid = waitpid(-1, &status, WNOHANG)) > 0)
                if (WIFEXITED(status)) {
                    if (WEXITSTATUS(status) != 0) {
                        log_error("Command failed");
                        callback("Command failed");
                    }
                } else if (WIFSIGNALED(status)) {
                    log_error("Command received a signal");
                    callback("Command received a signal");
                }

            if (!callback || !callback("All commands completed successfully")) return 0;
        }
    }
}
```
