typedef struct {
    long long session_id;
    long long user_id;
    time_t expiration_time;
    char *refresh_token;
} SessionData;

pthread_mutex_t sessions_mutex = PTHREAD_MUTEX_INITIALIZER;

static GHashTable *active_sessions = NULL;

bool process_session_data(const json_t *session_data) {
    if (!json_is_object(session_data)) {
        return false;
    }

    SessionData session;
    session.user_id = json_integer_value(json_object_get(session_data, "user_id"));
    if (session.user_id < 0) {
        return false;
    }

    const json_t *session_id_json = json_object_get(session_data, "session_id");
    if (!json_is_integer(session_id_json)) {
        return false;
    }
    session.session_id = json_integer_value(session_id_json);

    const json_t *expiration_time_json = json_object_get(session_data, "expiration_time");
    if (!json_is_number(expiration_time_json)) {
        return false;
    }
    time_t expiration_time = json_integer_value(expiration_time_json) + TIME_UTC - TIME_GMT;
    if (time(NULL) > expiration_time) {
        return false;
    }

    const json_t *refresh_token_json = json_object_get(session_data, "refresh_token");
    if (refresh_token_json && !json_is_string(refresh_token_json)) {
        return false;
    }

    pthread_mutex_lock(&sessions_mutex);
    bool unique = true;
    if (active_sessions) {
        GHashTableIter iter;
        gpointer key, value;
        gsize len;

        g_hash_table_iter_init(&iter, active_sessions);
        while (g_hash_table_iter_next(&iter, (gpointer *)&key, &value)) {
            SessionData *session_data_ptr = value;
            if (session.session_id == key) {
                unique = false;
                break;
            }
        }
    }
    pthread_mutex_unlock(&sessions_mutex);

    if (!unique) {
        return false;
    }

    session.expiration_time = expiration_time;
    if (refresh_token_json) {
        session.refresh_token = strdup(json_string_value(refresh_token_json));
    }

    if (!active_sessions) {
        active_sessions = g_hash_table_new_full(g_direct_hash, g_int_hash, g_int_equal, g_free);
    }

    pthread_mutex_lock(&sessions_mutex);
    g_hash_table_insert(active_sessions, &session.session_id, session);
    pthread_mutex_unlock(&sessions_mutex);

    return true;
}
