using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.Security.Cryptography;
using System.Numerics;
using Org.BouncyCastle.Crypto;
using Org.BouncyCastle.Crypto.Parameters;
using Newtonsoft.Json.Linq;

public class MessageProcessor
{
    private readonly ConcurrentQueue<string> _messageQueue;
    private readonly HMACSHA256 _hmac;
    private TripleDESCryptoServiceProvider _tripleDES;
    private byte[] _defaultKey, _defaultIV;
    private string _keyConfig, _ivConfig, _hmacConfig;

    public MessageProcessor()
    {
        _messageQueue = new ConcurrentQueue<string>();
        InitializeHMAC();
        InitializeTripleDES();
    }

    private void InitializeHMAC()
    {
        var hmacJson = JObject.Parse(File.ReadAllText("config.json"));
        _hmacConfig = hmacJson["key"].ToString();
        _hmac = new HMACSHA256(Encoding.UTF8.GetBytes(_hmacConfig));
    }

    private void InitializeTripleDES()
    {
        var tripleDESCryptoKey = GetOptimalKey(_keyConfig);
        _tripleDES = new TripleDESCryptoServiceProvider();
        _tripleDES.Key = tripleDESCryptoKey;
        var tripleDESCryptoIV = GetOptimalIV(_ivConfig);
        _tripleDES.IV = tripleDESCryptoIV;
    }

    private byte[] GetOptimalKey(string config)
    {
        if (string.IsNullOrEmpty(config))
            return _defaultKey ??= Encoding.UTF8.GetBytes("DEFAULT_KEY");

        try
        {
            return Encoding.UTF8.GetBytes(config);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error parsing key: {ex.Message}");
            return _defaultKey;
        }
    }

    private byte[] GetOptimalIV(string config)
    {
        if (string.IsNullOrEmpty(config))
            return _defaultIV ??= new byte[8];

        try
        {
            var bytes = Encoding.UTF8.GetBytes(config);
            if (bytes.Length != 8)
                throw new ArgumentException("Invalid IV length");

            return bytes;
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error parsing IV: {ex.Message}");
            return _defaultIV;
        }
    }

    public async Task<string> ProcessAsync(string encryptedMessage)
    {
        try
        {
            var decoded = Base64Decode(encryptedMessage);
            if (decoded == null)
                Console.WriteLine("Warning: Invalid input, attempted fallback Base64 decoding.");

            var decrypted = Decrypt(decoded);
            if (VerifyHMAC(decrypted))
                return decrypted;
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error processing message: {ex.Message}");
        }

        return null;
    }

    private byte[] Base64Decode(string input)
    {
        try
        {
            return Convert.FromBase64String(input);
        }
        catch (FormatException ex)
        {
            try
            {
                return Convert.FromBase64String(UrlSafeBase64Decode(input));
            }
            catch (Exception e)
            {
                Console.WriteLine($"Error decoding: {e.Message}");
                return null;
            }
        }
    }

    private string UrlSafeBase64Decode(string input) => WebUtility.UrlDecode(input.Replace("-", "+").Replace("_", "/"));

    private string Decrypt(byte[] cipherText)
    {
        using (var ms = new MemoryStream(cipherText))
            return Encoding.UTF8.GetString(_tripleDES.CreateDecryptor().TransformFinalBlock(ms.ToArray(), 0, ms.Length));
    }

    private bool VerifyHMAC(string message)
    {
        var hmac = _hmac.ComputeHash(Encoding.UTF8.GetBytes(message));
        var expectedHmac = GetExpectedHMAC(message);

        return hmac.SequenceEqual(expectedHmac);
    }

    private byte[] GetExpectedHMAC(string message)
    {
        using (var hmacKeyBytes = new Rfc2898DeriveBytes(Encoding.UTF8.GetBytes(_hmacConfig), Encoding.UTF8.GetBytes("salt")))
            return hmacKeyBytes.GetBytes(32).Concat(SHA256.Create().ComputeHash(Encoding.UTF8.GetBytes(message))).ToArray();
    }

    public void EnqueueMessage(string message) => _messageQueue.Enqueue(message);
}
