using System;
using System.IO;
using System.IO.Compression;
using System.Runtime.Serialization;
using System.Runtime.Serialization.Formatters.Binary;
using System.Collections.Concurrent;

namespace CustomDataDeserializer
{
    public class DataStructure : ISerializable
    {
        // Define your custom data structure properties here
    }

    public static class DataDeserializer
    {
        private static readonly ConcurrentDictionary<string, DataStructure> _cache = new ConcurrentDictionary<string, DataStructure>();

        public static DataStructure DeserializeFromCompressedFile(string filePath)
        {
            if (_cache.TryGetValue(filePath, out var cachedData))
                return cachedData;

            using (var stream = File.OpenRead(filePath))
            using (var gzipStream = new GzipStream(stream, CompressionMode.Decompress))
            {
                BinaryFormatter formatter = new BinaryFormatter();
                DataStructure data;
                try
                {
                    data = (DataStructure)formatter.Deserialize(gzipStream);
                }
                catch (SerializationException ex)
                {
                    Console.WriteLine($"Error deserializing data from '{filePath}': {ex.Message}");
                    return default;
                }

                _cache[filePath] = data;
                return data;
            }
        }
    }
}
```

