        objectMapper.registerModule(new ParametrizedTypeFactoryBuilder().constructParametricType(Object.class, Map.class));
        // Configure logging and other settings for ObjectMapper
    }

    public <T> T deserializeFromByteArray(byte[] byteArray, Class<T> clazz) throws IOException {
        try {
            return objectMapper.readValue(new ByteArrayInputStream(byteArray), clazz);
        } catch (Exception e) {
            LOGGER.error("Failed to deserialize object: {}", e.getMessage(), e);
            throw new RuntimeException("Deserialization error", e);
        }
    }

    private Class<?> loadClass(String className) throws ClassNotFoundException {
        URL url = this.getClass().getResource("/" + className.replaceAll("\\.", "/") + ".class");
        return url != null ? Class.forName(className, false, this.getClass().getClassLoader()) : throw new ClassNotFoundException(className);
    }

    public static <T> T createInstanceWithDependencies(Class<T> clazz) throws InstantiationException, IllegalAccessException, IOException, ClassNotFoundException {
        Constructor<?> constructor = clazz.getDeclaredConstructor();
        constructor.setAccessible(true);
        Object instance = constructor.newInstance();

        Arrays.stream(clazz.getDeclaredFields())
                .filter(field -> field.getType().isInterface() || Modifier.isFinal(field.getModifiers()))
                .forEach(field -> {
                    try {
                        String dependentClassName = field.getType().getName();
                        if (dependentClassName != clazz.getName()) {
                            Class<?> dependentClass = loadClass(dependentClassName);
                            Field declaredField = instance.getClass().getDeclaredField(field.getName());
                            declaredField.setAccessible(true);
                            declaredField.set(instance, createInstanceWithDependencies(dependentClass));
                        }
                    } catch (Exception e) {
                        LOGGER.error("Failed to set dependency '{}' for class '{}': {}", field.getName(), clazz.getName(), e.getMessage(), e);
                    }
                });

        return (T) instance;
    }
}
```

