    LineData data;
    while ((bytes_read = fread(buffer, sizeof(char), sizeof(buffer), fp)) > 0) {
        data.line = malloc(sizeof(char) * (bytes_read + 1));
        memcpy(data.line, buffer, bytes_read);
        data.line[bytes_read] = '\0';

        json_object* json = json_tokener_parse(data.line);
        if (!json_obj_is_valid(json)) {
            printf("Invalid JSON: %s\n", data.line);
            free(data.line);
            continue;
        }

        pthread_mutex_lock(&g_mutex);
        data.json = json_object_get_new();
        json_object_object_copy(data.json, json);
        pthread_mutex_unlock(&g_mutex);

        process_line(&data);
    }

    return NULL;
