    int maxVertices = 1000;
    int minEdges = 0;
    int maxEdges = 1000;
};

void add_vertices_and_edges(Graph& graph, TestConfiguration config, IndexMap index_map) {
    std::mt19937 gen(std::random_device{}());
    std::uniform_int_distribution<> dis(config.minVertices, config.maxVertices);
    std::uniform_int_distribution<> edgeDis(config.minEdges, config.maxEdges);

    Vertex v;
    for (auto i = 0; i < dis(gen); ++i) {
        v.id = std::to_string(i);
        v.prop1 = rand() % 100;
        v.prop2 = rand() % 100;
        VertexDescriptor d = add_vertex(graph, index_map);
        put(index_map, d, i);
    }

    for (auto i = 0; i < dis(gen); ++i) {
        auto src = vertex(dis(gen), graph);
        auto dest = vertex(dis(gen), graph);
        add_edge(src, dest, graph).first;
    }
}

void send_http_requests(const std::string& serverEndpoint, const TestDoubleInterfaceTable& table) {
    boost::asio::io_service ioService;
    std::atomic_int requestCount(0);
    std::queue<std::future<bool>> futures;

    for (auto i = 0; i < config.requestCount; ++i) {
        auto task = std::make_shared<std::packaged_task<bool()>>([=](){
            CURL* curl = curl_easy_init();
            if(curl) {
                curl_easy_setopt(curl, CURLOPT_URL, serverEndpoint.c_str());
                curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, nullptr);

                long responseCode;
                CURLcode res = curl_easy_perform(curl);
                if (res == CURLE_OK) {
                    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &responseCode);
                    return responseCode >= 200 && responseCode <= 299;
                }
            }
            return false;
        });

        auto future = task->get_future();
        futures.push(future);

        boost::thread t([=]{
            task->reset();
            curl_easy_setopt(task->get(), CURLOPT_INTERFACE, table.FindVmUuidFromMetadataIp("10.0.0.1").c_str());
            curl_easy_perform(task->get());
        });
        t.detach();
    }

    // Wait for all requests to complete and aggregate results
    while (!futures.empty()) {
        auto future = futures.front().wait_for(std::chrono::seconds(1));
        if (future == std::future_status::ready) {
            requestCount += (future.get() ? 1 : -1);
            futures.pop();
        }
    }

    std::cout << "Successful requests: " << requestCount << "\n";
}

int main(int argc, char* argv[]) {
    TestConfiguration config;
    boost::program_options::options_description desc("Allowed options");
    desc.add_options()
        ("min-vertices", boost::program_options::value<int>(&config.minVertices)->default_value(0), "Minimum number of vertices")
        ("max-vertices", boost::program_options::value<int>(&config.maxVertices)->default_value(1000), "Maximum number of vertices")
        ("min-edges", boost::program_options::value<int>(&config.minEdges)->default_value(0), "Minimum number of edges")
        ("max-edges", boost::program_options::value<int>(&config.maxEdges)->default_value(1000), "Maximum number of edges");

    boost::program_options::variables_map vm;
    boost::program_options::store(boost::program_options::parse_command_line(argc, argv, desc), vm);
    boost::program_options::notify(vm);

    boost::filesystem::path configFile("config.ini");
    if (boost::filesystem::exists(configFile)) {
        boost::property_tree::ptree pt;
        boost::property_tree::read_ini(configFile.string(), pt);

        config.minVertices = pt.get<int>("graph.vertices.min");
        config.maxVertices = pt.get<int>("graph.vertices.max");
        config.minEdges = pt.get<int>("graph.edges.min");
        config.maxEdges = pt.get<int>("graph.edges.max");
    }

    Graph graph;
    IndexMap index_map(boost::make_iterator_property_map(vertices(graph)).first);
    add_vertices_and_edges(graph, config, index_map);

    TestDoubleInterfaceTable table; // Inherit from InterfaceTable and override FindVmUuidFromMetadataIp function as needed.
    send_http_requests("http://example.com", table);

    return 0;
}
