use std::env;
use std::fs;
use std::sync::{Arc, Mutex};
use log::{debug, error, info};
use chrono::Local;
use simple_logger::{SimpleLogger, CombinedFormatter};
use serde_json::Value; // For external logging service integration (assuming you're using a JSON-based service)

// Centralized logging service interface
pub trait Logger {
    fn log(&self, message: &str);
}

struct DirectoryManager {
    parent_dir_env: String,
    dir_name_env: String,
    log: Arc<Mutex<Box<dyn Logger>>>,
}

impl DirectoryManager {
    pub fn new(parent_dir_env: &str, dir_name_env: &str) -> Self {
        DirectoryManager {
            parent_dir_env: parent_dir_env.to_string(),
            dir_name_env: dir_name_env.to_string(),
            log: Arc::new(Mutex::new(Box::new(SimpleLogger::new()))),
        }
    }

    pub fn initialize(&mut self) {
        if env::var_os(self.parent_dir_env.as_str()).is_err() || !fs::exists(self.parent_dir_env) {
            let parent_dir = match fs::create_dir_all(&self.parent_dir_env) {
                Ok(_) => self.parent_dir_env,
                Err(_) => {
                    error!("Failed to create parent directory: {}", self.parent_dir_env);
                    return;
                }
            };

            if let Some(alt_parent_dir) = env::var_os("ALT_PARENT_DIR") {
                self.parent_dir_env = alt_parent_dir.into_string();
            }
        }

        let dir_name = match env::var_os(self.dir_name_env.as_str()) {
            Ok(val) => val,
            Err(_) => {
                let unique_name = format!("{:._12}", Local::now());
                self.set_dir_name(&format!("{}", self.parent_dir_env).concat2("/").concat2(&unique_name));
                fs::read_link(self.parent_dir_env.clone()).unwrap().to_str().unwrap()
                    .concat2("/").concat2(&unique_name)
            }
        };

        let dir_path = self.create_directory(&dir_name);
        if !dir_path.is_err() {
            self.set_dir_name(dir_path.unwrap());
        } else {
            error!("Failed to create directory: {}", dir_name);
        }
    }

    fn set_dir_name(&mut self, value: &str) {
        match env::set_var(self.dir_name_env.as_str(), value) {
            Ok(_) => (),
            Err(_) => error!("Failed to set environment variable: {}", self.dir_name_env),
        }
    }

    fn create_directory(&mut self, dir_path: &str) -> std::io::Result<String> {
        if !fs::metadata(dir_path).is_err() {
            return Ok(dir_path.to_string());
        }

        let mut log = self.log.lock().unwrap();
        match fs::create_dir_all(dir_path) {
            Ok(_) => {
                info!("Created directory: {}", dir_path);
                log.log(&format!("Created directory: {}", dir_path));
                Ok(dir_path.to_string())
            }
            Err(e) => {
                error!("Failed to create directory: {}", e);
                log.log(&format!("Failed to create directory: {}", e));
                Err(e)
            }
        }
    }
}

impl Logger for SimpleLogger {
    fn log(&self, message: &str) {
        let formatter = CombinedFormatter::new()
            .with_style_for(SimpleLogger::LevelFilter::Info, SimpleLogger::Style::default().bold())
            .with_style_for(SimpleLogger::LevelFilter::Error, SimpleLogger::Style::default().red());
        let _ = write!(formatter.finish(), "{}", message);
    }
}
