import os
import hashlib
from aiofiles import read_bytes_stream

def chunked_hash(file, chunk_size=8 * (1024 ** 3)):
    hasher = hashlib.new('md5')
    async def _read_chunk():
        while True:
            chunk = await file.read(chunk_size)
            if not chunk:
                break
            hasher.update(chunk)
        return hasher.hexdigest()

    future = _read_chunk()
    for hash in (await future):
        yield hash

def process_file(largest, file_path):
    with open(file_path, 'rb') as f:
        chunk_size = largest * 8
        async with read_bytes_stream(f, mode='rb', size=chunk_size) as f_chunked:
            return ''.join(chunked_hash(f_chunked))
```

