    size_t size;
    struct malloc_zone *next;
};

inline struct StateList* new_statelist(size_t max_size) {
    struct StateList *state_list = (struct StateList*) mmap(NULL, sizeof(*state_list), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);
    if (!state_list) return NULL;
    pthread_mutex_init(&state_list->mutex, NULL);
    state_list->max_size = max_size;
    state_list->zone = NULL;
    state_list->last_state = 0;
    atomic_set(&state_list->ref_count, 1);
    return state_list;
}

void destroy_statelist(struct StateList *state_list) {
    if (!state_list) return;
    pthread_mutex_destroy(&state_list->mutex);
    munmap(state_list, sizeof(*state_list));
}

inline void* get_zone(struct StateList *state_list) {
    if (!state_list->zone) {
        struct malloc_zone *zone = (struct malloc_zone*) mmap(NULL, state_list->max_size * sizeof(uint32_t), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);
        if (!zone) return NULL;
        struct malloc_zone *current = zone;
        for (size_t i = 0; i < state_list->max_size - 1; ++i) {
            current->next = (struct malloc_zone*)((char*)current + sizeof(uint32_t) * (state_list->max_size));
            current->size = sizeof(uint32_t) * (state_list->max_size);
            current = current->next;
        }
        current->size = 0;
        state_list->zone = zone;
    }
    return state_list->zone;
}

inline void* allocate(struct StateList *state_list, size_t size) {
    if (!get_zone(state_list)) return NULL;
    struct malloc_zone *current = state_list->zone;
    while (current && current->size <= 0) current = current->next;
    if (!current) return NULL;
    void *ptr = (char*)current + current->size;
    current->size -= size;
    atomic_fetch_add(&state_list->ref_count, 1);
    return ptr;
}

