#pragma once
#include <vector>
#include <unordered_map>
#include <mutex>
#include <random>

class LTE_PHY_RX_FRAME_INFO_T {
public:
    int LTESERIAL_ID;
    PHICH_INFO phichInfo;

    LTE_PHY_RX_FRAME_INFO_T(int id, PHICH_INFO info) : LTESERIAL_ID(id), phichInfo(info) {}
};

class LTE_RX_FRAME_MANAGER {
private:
    std::vector<LTE_PHY_RX_FRAME_INFO_T> data;
    std::unordered_map<int, size_t> idToIndex;
    std::mutex mtx;
    bool dlSrsInit = false;
    std::mt19937_64 rng;

public:
    void initialize(bool enableDlSrs) {
        dlSrsInit = enableDlSrs;
        if (dlSrsInit) {
            rng.seed(std::random_device()());
        }
    }

    LTE_PHY_RX_FRAME_INFO_T* getFrameInfoBySerialID(int serialId) {
        std::scoped_lock lock(mtx);
        auto it = idToIndex.find(serialId);
        if (it == idToIndex.end()) {
            size_t index = data.size();
            data.push_back({serialId, PHICH_INFO()});
            it = idToIndex.emplace(serialId, index).first;
        }
        return &data[it->second];
    }

    void removeFrameInfoBySerialID(int serialId) {
        std::scoped_lock lock(mtx);
        auto it = idToIndex.find(serialId);
        if (it != idToIndex.end()) {
            size_t index = it->second;
            data[index] = data.back();
            idToIndex[data.back().LTESERIAL_ID] = index;
            it->second = data.size() - 1;
            data.pop_back();
            idToIndex.erase(it);
        }
    }
};
```

