#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <getopt.h>
#include <jpegsrc.h>
#include <pdf-lib.h>
#include <imagemagick/magick-config.h>
#include <magick/MagickCore.h>
#include <sys/wait.h>
#include <time.h>

typedef struct {
    char *input;
    char *output;
    int width, height;
    double red_factor, green_factor, blue_factor;
    int crop_left, crop_top, crop_width, crop_height;
} Args;

int process_image(Args *args) {
    struct MagickImage img;
    int status;

    // Load image with ImageMagick library
    MagTickleReadStdIn(&img);

    if (args->crop_left || args->crop_top || args->crop_width || args->crop_height) {
        // Crop and resize the image
        MagickCropImage(&img, args->crop_left, args->crop_top, args->crop_width, args->crop_height);
        MagickResizeImage(&img, args->width, args->height, MagickResampleTypeCubic);
    }

    if (args->red_factor || args->green_factor || args->blue_factor) {
        // Adjust colors based on the provided factors
        double *qtable = MagickAllocateQuantumTable(256, QuantumRange);
        for (int i = 0; i < 256; ++i) {
            qtable[i] = (Quantum) ((i / 255.0) * args->red_factor + (i * (1 - args->red_factor)) * QuantumRange);
        }
        MagickColorSpaceType old_type = GetImageDepth(&img);
        SetImageDepth(&img, depth8);
        SetColormap(&img, qtable, 0, FALSE);
        DestroyQuantumTable(qtable);
    }

    // Save the image as a temporary PDF file using pdf-lib library
    char temp_pdf[1024];
    snprintf(temp_pdf, sizeof(temp_pdf), "/tmp/processed_image.%d.pdf", getpid());
    int pdf_result = pdf_document_new();
    if (pdf_result >= 0) {
        pdf_outline_new(pdf_get_document(pdf_result));
        pdf_page_create(pdf_get_document(pdf_result), A4);
        MagickExportPages(&img, "PDF", temp_pdf);
    }

    // Extract metadata using ImageMagick library
    char *exif = MagickGetImageProperty(&img, "Exif*");
    char *iptc = MagickGetImageProperty(&img, "Iptc*");

    // Convert the temporary PDF file to a final PDF file using ghostscript command
    char cmd[1024];
    snprintf(cmd, sizeof(cmd), "gs -dSAFER -dBATCH -q -sDEVICE=pdfwrite -o %s -f %s", args->output, temp_pdf);

    pid_t pid = fork();
    if (pid == 0) {
        // Child process
        execl("/usr/bin/gs", "gs", "-dSAFER", "-dBATCH", "-q", "-sDEVICE=pdfwrite", "-o", args->output, temp_pdf, NULL);
        perror("exec failure");
        exit(1);
    } else if (pid > 0) {
        // Parent process
        int status;
        waitpid(pid, &status, 0);
    } else {
        // Fork failed
        fprintf(stderr, "Error forking\n");
        return 1;
    }

    // Cleanup
    DestroyImage(&img);
    unlink(temp_pdf);

    return 0;
}

int main(int argc, char *argv[]) {
    const char *short_options = "i:o:w:h:r:g:b:l:t:c";
    struct option long_options[] = {
        {"input", required_argument, NULL, 'i'},
        {"output", required_argument, NULL, 'o'},
        {"width", required_argument, NULL, 'w'},
        {"height", required_argument, NULL, 'h'},
        {"red-factor", required_argument, NULL, 'r'},
        {"green-factor", required_argument, NULL, 'g'},
        {"blue-factor", required_argument, NULL, 'b'},
        {"crop-left", required_argument, NULL, 'l'},
        {"crop-top", required_argument, NULL, 't'},
        {"crop-width", required_argument, NULL, 'c'},
        {0, 0, 0, 0}
    };
    int option_index = 0;
    char c;
    Args args;

    memset(&args, 0, sizeof(Args));

    while ((c = getopt_long(argc, argv, short_options, long_options, &option_index)) != -1) {
        switch (c) {
            case 'i': args.input = optarg; break;
            case 'o': args.output = optarg; break;
            case 'w': args.width = atoi(optarg); break;
            case 'h': args.height = atoi(optarg); break;
            case 'r': args.red_factor = atof(optarg); break;
            case 'g': args.green_factor = atof(optarg); break;
            case 'b': args.blue_factor = atof(optarg); break;
            case 'l': args.crop_left = atoi(optarg); break;
            case 't': args.crop_top = atoi(optarg); break;
            case 'c': {
                char *token = strtok(optarg, ",");
                args.crop_width = atoi(token);
                token = strtok(NULL, ",");
                args.crop_height = atoi(token);
            } break;
            default: fprintf(stderr, "Error: unrecognized option\n"); return 1;
        }
    }

    if (!args.input || !args.output) {
        fprintf(stderr, "Error: missing input or output file\n");
        return 1;
    }

    struct stat st;
    if (stat(args.input, &st) != 0) {
        perror("stat failure");
        return 1;
    }

    if (!S_ISREG(st.st_mode)) {
        fprintf(stderr, "Error: input file is not a regular file\n");
        return 1;
    }

    // Implement error handling and resource management here

    clock_t start = clock();
    int result = process_image(&args);
    clock_t end = clock();
    double time_elapsed = (double)(end - start) / CLOCKS_PER_SEC;

    printf("Operation finished in %.2f seconds\n", time_elapsed);

    return result;
}
