}

const char* concatStrings(const char* str1, const char* str2) {
    size_t len1 = strlen(str1);
    size_t len2 = strlen(str2);

    char* result = (char*)malloc((len1 + len2 + 1) * sizeof(char)); // Additional space for null terminator
    strcpy(result, str1);
    strcat(result, str2);

    return result;
}

itoa(int value, char* buffer, int base) {
    int i = 0;
    bool isNegative = false;

    if (value < 0 && base == 10) {
        isNegative = true;
        value *= -1;
    }

    for (; value > 0; ++i) {
        buffer[i] = "0123456789ABCDEF"[value % base];
        value /= base;
    }

    if (isNegative)
        buffer[i--] = '-';

    for (; i >= 0; --i)
        buffer[i] = buffer[i + 1];

    buffer[i] = '\0';
}
