using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Xml.Linq;
using System.Threading.Tasks;
using System.Net.Http;
using log4net;

public class FetchAndProcessFirstMatchingElement
{
    private static readonly ILog Logger = LogManager.GetLogger(typeof(FetchAndProcessFirstMatchingElement));
    private readonly Dictionary<string, XDocument> _cache = new Dictionary<string, XDocument>();

    public async Task<XElement> FetchAndProcess(string inputSource, string elementName)
    {
        try
        {
            if (Uri.IsWellFormedUriString(inputSource, UriKind.Absolute)) // checking for a valid URL
            {
                using var client = new HttpClient();
                var xmlContent = await client.GetStringAsync(inputSource);
                return ProcessXml(xmlContent, elementName);
            }
            else
            {
                if (File.Exists(inputSource)) // checking for a file path
                {
                    return ProcessXml(File.ReadAllText(inputSource), elementName);
                }
                else
                {
                    Logger.Error($"Invalid input source: {inputSource}");
                    throw new FileNotFoundException("Input file not found", inputSource);
                }
            }
        }
        catch (FileNotFoundException ex)
        {
            Logger.Error(ex);
            throw;
        }
        catch (HttpRequestException ex)
        {
            Logger.Error(ex);
            throw new Exception("Network error occurred", ex);
        }
        catch (Exception ex)
        {
            Logger.Error(ex);
            throw new InvalidOperationException("An unexpected error occurred", ex);
        }

        XDocument ProcessXml(string xmlContent, string elementName)
        {
            XDocument document;
            lock (_cache)
            {
                if (_cache.TryGetValue(xmlContent, out document)) return document.Root.Element(elementName);
            }

            try
            {
                document = XDocument.Parse(xmlContent);
            }
            catch (Exception ex)
            {
                Logger.Error($"XML parsing error: {ex}");
                throw new InvalidOperationException("Invalid XML format", ex);
            }

            _cache[xmlContent] = document;
            return document.Root.Element(elementName);
        }
    }
}
