#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* generate_crc_pdu_array(uint32_t n) {
    NFAPI_CRC_INDICATION_PDU_T *arr, *temp;

    if (n <= 0) return NULL;

    arr = (NFAPI_CRC_INDICATION_PDU_T*)calloc(n, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!arr) {
        perror("Calloc failed\n");
        return NULL;
    }

    srand(time(NULL));

    for (size_t i = 0; i < n; ++i) {
        arr[i].RX_UE_INFORMATION_TAG = i * 123456789 + 123456;
        arr[i].RNTI = rand() % 65535 + 1;
        arr[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        arr[i].CRCFLAG = (rand() % 2) == 0; // 50% chance of CRC flag set to 1
    }

    temp = realloc(arr, n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!temp) {
        perror("Realloc failed\n");
        free(arr);
        return NULL;
    }

    arr = temp;

    return arr;
}
```

