    }

    size_t input_data_len = st.st_size;
    size_t output_data_len = 0;
    char *output_data = calloc(input_data_len + output_data_len, 1);

    for (size_t i = 0; i < input_data_len; ++i) {
        if (TransformRule(&args.rules[i], &output_data[output_data_len], 1, &input_data[i])) {
            // Handle failed transformation here
        }
        ++output_data_len;
    }

    // Append external data to output_data if needed

    FILE *output_file = fopen(args.output_file, "w");
    if (!output_file) {
        LogErrorAndExit("Failed to open the output file.");
    }

    fwrite(output_data, 1, output_data_len, output_file);
    fclose(output_file);

    munmap(input_data, st.st_size + 1);
    free(external_data);
    free(output_data);
    curl_easy_cleanup(curl);

    return EXIT_SUCCESS;
}
