```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    char* session_id;
    int auth_status; // 0 for invalid, 1 for valid
    pthread_mutex_t auth_lock;
    struct resource** resources;
    size_t num_resources;
} Session;

struct session_list {
    Session* head;
    size_t count;
};

// Function to initialize the session list with M active sessions.
Session* init_sessions(size_t M) {
    Session* sessions = malloc(sizeof(Session) * M);
    if (!sessions) return NULL;

    for (size_t i = 0; i < M; ++i) {
        sessions[i].session_id = malloc(32 * sizeof(char)); // assuming session_id is max 32 characters
        if (!sessions[i].session_id) goto error;

        pthread_mutex_init(&sessions[i].auth_lock, NULL);
        sessions[i].resources = malloc(sizeof(struct resource*));
        if (!sessions[i].resources) goto error;
        sessions[i].num_resources = 0;
    }

    return sessions;
error:
    for (size_t i = 0; i < M - 1; ++i) {
        free(sessions[i].session_id);
        pthread_mutex_destroy(&sessions[i].auth_lock);
    }
    free(sessions);
    return NULL;
}

// Function to create a new session with a given ID and resources.
Session* create_session(char* id, size_t auth_status, struct resource** resources, size_t num_resources) {
    Session* session = malloc(sizeof(Session));
    if (!session) return NULL;

    session->session_id = strdup(id);
    if (!session->session_id) goto error;

    session->auth_status = auth_status;
    pthread_mutex_init(&session->auth_lock, NULL);
    session->resources = malloc((num_resources + 1) * sizeof(struct resource*));
    if (!session->resources) goto error;
    memcpy(session->resources, resources, num_resources * sizeof(struct resource*));
    session->num_resources = num_resources;

    return session;
error:
    free(session);
    return NULL;
}

// Function to add a new session to the list.
void add_session(Session** sessions, size_t* count, Session* session) {
    session->next = *sessions;
    *sessions = session;
    ++(*count);
}

// Helper function to remove a session from the list and free its resources.
void remove_session(Session** sessions, size_t* count, Session* session) {
    if (!*sessions) return;

    if (*sessions == session) {
        *sessions = session->next;
        --(*count);
    } else {
        Session* current = *sessions;
        while (current->next && current->next != session) current = current->next;

        if (!current->next) return; // not found

        current->next = session->next;
        --(*count);
    }

    free(session->session_id);
    pthread_mutex_destroy(&session->auth_lock);
    free(session->resources);
    free(session);
}

// Function to update a session's authentication status.
void update_session_status(Session* session, int new_status) {
    pthread_mutex_lock(&session->auth_lock);
    session->auth_status = new_status;
    pthread_mutex_unlock(&session->auth_lock);
}

// Function to iterate over the sessions and print their details.
void print_sessions(Session* head) {
    for (Session* current = head; current != NULL; current = current->next) {
        printf("Session ID: %s, Auth Status: %d\n", current->session_id, current->auth_status);
        printf("  Resources:\n");
        for (size_t i = 0; i < current->num_resources; ++i) {
            printf("    Resource ID: %ld\n", current->resources[i]->resource_id);
        }
        printf("\n");
    }
}
