NFAPI_CRC_INDICATION_PDU_T* create_vertex(void* user_data, realtime_data_t* data) {
    GraphData* graph = (GraphData*)user_data;
    pthread_mutex_lock(&graph->mutex);
    size_t new_size = graph->num_vertices + 1;
    NFAPI_CRC_INDICATION_PDU_T* new_graph_data = realloc(graph->graph_data, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_graph_data) {
        pthread_mutex_unlock(&graph->mutex);
        return NULL;
    }
    graph->graph_data = new_graph_data;
    memcpy(&(graph->graph_data[graph->num_vertices]), data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    graph->num_vertices++;
    pthread_mutex_unlock(&graph->mutex);
    return &(graph->graph_data[graph->num_vertices - 1]);
}

void create_edge(void* user_data, const size_t src_index, const size_t dest_index) {
    GraphData* graph = (GraphData*)user_data;
    pthread_mutex_lock(&graph->mutex);
    if (src_index >= graph->num_vertices || dest_index >= graph->num_vertices) {
        pthread_mutex_unlock(&graph->mutex);
        return;
    }
    size_t new_size = graph->num_edges + 1;
    NFAPI_CRC_INDICATION_PDU_T* new_graph_data = realloc(graph->graph_data, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_graph_data) {
        pthread_mutex_unlock(&graph->mutex);
        return;
    }
    graph->graph_data = new_graph_data;

    NFAPI_CRC_INDICATION_PDU_T* edge = &(graph->graph_data[graph->num_edges]);
    memcpy(edge, &(graph->graph_data[src_index]), sizeof(NFAPI_CRC_INDICATION_PDU_T));
    edge->RX_UE_INFORMATION_TAG.tagValue = EDGE_TAG; /* Set edge tag */
    edge->RNTI.tci = dest_index >> 3;
    edge->RNTI.scramblingCode = (dest_index & 0x07) << 28 | src_index >> 3;
    edge->CRC_INDICATION_REL8_TAG.predictiveAnalyticsFlag = should_flag_be_set(); /* Predictive analytics flag function */
    graph->num_edges++;
    pthread_mutex_unlock(&graph->mutex);
