    uint16_t rnti;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

int generateNFAPIReports(const char *srcDir, const char *targetDir, const char *template, int N) {
    DIR *dir = opendir(srcDir);
    if (!dir) return 1;

    struct dirent *entry;
    char path[1024], file[256];
    while ((entry = readdir(dir)) != NULL) {
        snprintf(path, sizeof(path), "%s/%s", srcDir, entry->d_name);
        if (strstr(entry->d_name, template) && is_file(path)) {
            FILE *logFile = fopen(path, "r");
            if (!logFile) continue;

            NFAPI_CRC_INDICATION_PDU_T structure[N];
            int validStructures = 0;
            bool crcflagUsed[N] = {false};

            char line[1024];
            while (fgets(line, sizeof(line), logFile)) {
                uint32_t rx_ue_information_tag, rnti;
                sscanf(line, "%x %hhu", &rx_ue_information_tag, &rnti);
                bool found = false;
                for (int i = 0; i < validStructures && !found; ++i) {
                    if (structure[i].rnti == rnti && structure[i].rx_ue_information_tag == rx_ue_information_tag) found = true;
                }
                if (!found) {
                    structure[validStructures].rx_ue_information_tag = rx_ue_information_tag;
                    structure[validStructures].rnti = rnti;
                    structure[validStructures++].crcflag = rand() % 2;
                } else {
                    for (int i = validStructures - 1; i >= 0 && !crclagUsed[i]; --i) if (structure[i].crcflag == structure[validStructures - 1].crcflag) crclagUsed[i] = true;
                    if (!crclagUsed[validStructures - 1]) {
                        structure[validStructures - 1].crcflag ^= 1;
                        validStructures--;
                    }
                }
            }

            fclose(logFile);

            char reportName[256];
            snprintf(reportName, sizeof(reportName), "%s/%s_report.csv", targetDir, entry->d_name);
            writeCSV(reportName, structure, validStructures);
        }
    }

    closedir(dir);

    char cmd[1024];
    snprintf(cmd, sizeof(cmd), "consolidateReport %s/*_report.csv", targetDir);
    system(cmd);

    return 0;
}

bool is_file(const char *path) {
    struct stat st;
    if (stat(path, &st) < 0 || S_ISDIR(st.st_mode)) return false;
    return true;
}
