NFAPI_CRC_INDICATION_PDU_T* generate_pdus(size_t n) {
    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) return NULL;

    RSA *rsa_key = NULL;
    EVP_MD_CTX *md5_ctx = EVP_MD_CTX_new();
    EVP_MD_CTX *sha1_ctx = EVP_MD_CTX_new();

