        pdus[i].rnti = i + 1;
        pdus[i].crc_indication_rel8_tag[0] = (uint8_t)(rand() & 0xFF);
        pdus[i].crc_indication_rel8_tag[1] = (uint8_t)((rand() << 4) | rand() & 0xF);
        pdus[i].crcflag = rand() % 2;

        RSA_generate_key_ex(rsa_key, 2048, NULL, NULL);
        RSA_sign(NID_sha1, SHA1_digest((unsigned char*)&pdus[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), md5_ctx), RSA_pending(rsa_key), rsa_key, SHA1_new());
        memcpy(pdus[i].crc_indication_rel8_tag + 2, RSA_pending(rsa_key), RSA_size(rsa_key));

        RSA_free(rsa_key);
        EVP_MD_CTX_free(md5_ctx);
        md5_ctx = EVP_MD_CTX_new();
        SHA1_init(sha1_ctx);
    }

    EVP_MD_CTX_free(md5_ctx);
    EVP_MD_CTX_free(sha1_ctx);

    return pdus;
}
