        : id(id), priority(priority), scheduled_execution(scheduled_execution) {}
};

class TaskManager {
public:
    using TaskList = std::vector<Task>;
    using TaskMap = std::unordered_map<int, Task*>;
    using CircularBuffer = boost::circular_buffer<LogMessage>;
    static constexpr int GARBAGE_COLLECTION_INTERVAL = 1000ms; // Adjust as needed

private:
