    TaskMap task_map_;
    std::mutex tasks_mutex_;
    std::condition_variable cv_;
    std::shared_timed_mutex log_mutex_;
    CircularBuffer log_buffer_;
    boost::interprocess::interprocess_semaphore gc_sem_(0, 1); // Semaphore for garbage collection
    std::atomic<bool> is_running_{true};
