    }

    void garbage_collection() {
        while (is_running_) {
            gc_sem_.wait();
            {
                std::lock_guard<std::shared_timed_mutex> lock(log_mutex_);
                // Process and remove log entries older than a certain threshold
            }

            std::unique_lock<std::mutex> tasks_lock(tasks_mutex_);
            cv_.wait_until(tasks_lock, std::chrono::steady_clock::now() + GARBAGE_COLLECTION_INTERVAL,
                           [this] { return tasks_.empty(); });

            for (auto it = task_map_.begin(); it != task_map_.end();) {
                auto task = it->second;
                if (task->scheduled_execution < std::chrono::steady_clock::now()) {
                    remove_task(it);
                } else {
                    ++it;
                }
            }

            tasks_.clear();
            gc_sem_.post(1); // Signal that garbage collection is complete
        }
    }

public:
