        pdu->RNTI = random();
        pdu->CRC_INDICATION_REL8_TAG = static_cast<uint8_t>(random() % 256);
        pdu->CRCFLAG = random() < 0.5;

        usedRTNIs[pdu->RNTI] = true;
        array[numPopulated - 1] = *pdu;
