3. Insert, delete and traverse operations using atomic operations:

```c
void insert_at_head(Node** head, NFAPI_CRC_INDICATION_PDU_T* data) {
    if (!(*head)) {
        (*head) = create_node();
        if (!(*head)) return;
        (*head)->data = *data;
        ++((*head)->count);
        return;
    }
    Node* new_node = create_node();
    if (!new_node) return;
    new_node->data = *data;
    new_node->next = (*head);
    (*head) = new_node;
    ++((*head)->count);
}

void insert_at_tail(Node** tail, NFAPI_CRC_INDICATION_PDU_T* data) {
    if (!(*tail)) {
        (*tail) = create_node();
        if (!(*tail)) return;
        (*tail)->data = *data;
        ++((*tail)->count);
        return;
    }
    Node* new_node = create_node();
    if (!new_node) return;
    new_node->data = *data;
    new_node->next = NULL;
    (*tail)->next = new_node;
    (*tail) = new_node;
    ++((*tail)->count);
}

void delete_at(Node** head, uint32_t index) {
    if (index >= pthread_atomic_load(&(*head)->count)) return; // edge case: out of bounds index
    Node* current = *head;
    for (uint32_t i = 0; i < index; ++i) {
        current = current->next;
    }
    if (!current || !current->next) return; // edge cases: head or tail deletion
    Node* to_delete = current->next;
    current->next = to_delete->next;
    free(to_delete);
    --pthread_atomic_load(&(*head)->count);
}

// Traversal operation (iterate through the list)
void traverse(Node* head) {
    for (Node* current = head; current != NULL; current = current->next) {
        // Access and process data as needed
    }
}
