            current_position += strlen(input_buffer + current_position); // Move the position to next possible integer or end of line
        }
    }

    process_input(valid_numbers, num_valid_integers, &average);

    printf("Number of valid integers: %zu\n", num_valid_integers);
    printf("Average value: %.3f\n", average);

    free(input_buffer);
    free(valid_numbers);

    return 0;
}
