    if (!list) return NULL; // Handle memory allocation errors

    list->queue = minqueue_init(); // Initialize the queue
    list->num_elements = 0;
    list->head = list->tail = NULL;

    return list;
}

void nfapi_crc_indication_list_destroy(NFAPI_CRC_INDICATION_LIST_T *list) {
    if (!list) return; // Handle null pointers

    NFAPI_CRC_INDICATION_PDU_T *curr = list->head;
    while (curr != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *temp = curr;
        curr = curr->next;
        free(temp);
    }

    minqueue_destroy(&list->queue);
    free(list);
}

bool nfapi_crc_indication_list_enqueue(NFAPI_CRC_INDICATION_LIST_T *list, const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (!validate(pdu)) return false; // Validate the input data

    NFAPI_CRC_INDICATION_PDU_T *new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) return false; // Handle memory allocation errors

    new_node->rx_ue_information_tag = pdu->rx_ue_information_tag;
    new_node->rnti = pdu->rnti;
    new_node->crc_indication_rel8_tag = pdu->crc_indication_rel8_tag;
    new_node->prev = NULL;
    new_node->next = NULL;

    if (list->num_elements == 0) {
        list->head = list->tail = new_node;
    } else {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    }

    ++list->num_elements;
    minqueue_enqueue(&list->queue, new_node); // Add the new node to the queue

    return true;
}
