session_t* create_session(size_t initial_capacity) {
    if (!initial_capacity) return NULL;

    session_t *session = malloc(sizeof(session_t));
    if (!session) return NULL;

    pthread_mutex_init(&session->lock, NULL);
    session->sessions = calloc(initial_capacity, sizeof(config_t));
    if (!session->sessions) {
        free(session);
        return NULL;
    }

    session->capacity = initial_capacity;
    session->size = 0;

    return session;
}

void resize_session(session_t* session, size_t new_capacity) {
    if (!new_capacity || !session) return;

    config_t *new_sessions = realloc(session->sessions, new_capacity * sizeof(config_t));
    if (!new_sessions) return;

    session->sessions = new_sessions;
    session->capacity = new_capacity;
}

bool add_config(session_t* session, config_t* config) {
    pthread_mutex_lock(&session->lock);

    if (session->size == session->capacity) resize_session(session, session->capacity * 2);

    for (size_t i = 0; i < session->size; ++i) {
        if (session->sessions[i].tag == config->tag && !memcmp(&session->sessions[i], config, sizeof(config_t))) {
            pthread_mutex_unlock(&session->lock);
            return false; // Duplicate configuration detected
        }
    }

    session->sessions[session->size] = *config;
    ++session->size;

    pthread_mutex_unlock(&session->lock);
    return true;
}
