#include <forward_list>
#include <iterator>
#include <stdexcept>

void insertAfter(std::forward_list<std::string>& flist, const std::string& first, const std::string& second, int index) {
    if (index < 0 || index > static_cast<int>(flist.size())) {
        throw std::out_of_range("Index out of bounds");
    }

    auto it = flist.begin();
    auto prev_it = flist.before_begin();

    // Check if the forward list is empty
    if (flist.empty()) {
        throw std::length_error("Forward list cannot be empty");
    }

    int count = 0;
    for (; it != flist.end() && *it != first; ++it, ++count) {
        prev_it = it;
    }

    if (it == flist.end()) {
        // Insert at the end of the list if the first string is not found before the given index
        if (index == static_cast<int>(flist.size())) {
            flist.push_back(second);
        } else {
            // If the list is not empty, and we've reached the end of the list without finding the first string, throw an error
            throw std::runtime_error("First string not found before the given index");
        }
    } else {
        // Insert after the first occurrence of the first string or at the given index if it is smaller than the current position
        if (index <= count) {
            flist.insert(it, second);
        } else {
            std::advance(prev_it, index - count - 1); // Move the previous iterator to the correct position for insertion
            flist.insert(prev_it, second);           // Insert the second string after the first occurrence of the first string or at the given index if it is larger than the current position
        }
    }
}
```

This code addresses the engineering challenges by:

1. Using a `std::forward_list`, which offers efficient insertion and removal operations, ensuring good performance when integrated into a larger system with strict requirements.
