```c
#include <arpa/inet.h>
#include <errno.h>
#include <fcntl.h>
#include <netinet/in.h>
#include <pthread.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <unistd.h>

typedef struct {
    int valid_count;
    int *valid_numbers;
    size_t buffer_size;
    char *buffer;
} socket_data;

int process_integer(socket_data *data, char *buf) {
    int num = 0;
    int i = 0;

    while (isspace(*buf)) buf++;

    if (*buf == '\0') return 0;

    for (i = 0; i < sizeof(int); i++) {
        if (!isdigit(*buf)) break;
        num = num * 10 + (*buf++ - '0');

        if (num > 1000) break;
    }

    if (i != sizeof(int)) return 0;

    data->valid_numbers[(data->valid_count)++] = num;

    return 1;
}

void *socket_reader(void *arg) {
    int sock = *(int *) arg;
    socket_data *data = (socket_data *) calloc(1, sizeof(socket_data));
    char buf[4096];
    ssize_t num_read;

    data->buffer = calloc(8192, 1);
    data->buffer_size = 8192;

    while (true) {
        memset(buf, 0, sizeof(buf));
        num_read = recv(sock, buf, sizeof(buf), MSG_DONTWAIT);

        if (num_read > 0) {
            memcpy(data->buffer + data->valid_count, buf, num_read);
            data->valid_count += num_read;

            for (size_t i = 0; i < num_read; ++i) {
                if (process_integer(data, data->buffer)) continue;
            }
        }
    }

    free(data->buffer);
    free(data);
}

int main(int argc, char **argv) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in serv_addr;

    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(atoi(argv[1]));
    inet_pton(AF_INET, argv[2], &serv_addr.sin_addr);

    connect(sockfd, (struct sockaddr *) &serv_addr, sizeof(serv_addr));

    pthread_t reader_thread;
    socket_data *data = malloc(sizeof(socket_data));

    data->buffer = calloc(8192, 1);
    data->buffer_size = 8192;

    pthread_create(&reader_thread, NULL, &socket_reader, &sockfd);

    while (true) {
        char buf[4096];
        ssize_t num_read = recv(sockfd, buf, sizeof(buf), 0);

        if (num_read > 0) {
            memcpy(data->buffer + data->valid_count, buf, num_read);
            data->valid_count += num_read;

            for (size_t i = 0; i < num_read; ++i) {
                if (process_integer(data, data->buffer)) continue;
            }
        } else if (num_read == 0) {
            if (errno != EAGAIN) printf("Error: %s\n", strerror(errno));
        } else if (errno != EINTR && errno != EWOULDBLOCK) {
            printf("Error: %s\n", strerror(errno));
        }
    }

    close(sockfd);

    int max_num = 0;
    for (size_t i = 0; i < data->valid_count; ++i) {
        if (data->valid_numbers[i] > max_num) max_num = data->valid_numbers[i];
    }

    printf("Maximum valid number: %d\n", max_num);

    free(data->buffer);
    free(data);

    return 0;
}
```

This code implements a non-blocking socket reader that processes incoming integer data from a connected socket. The main function sets up the socket connection, starts a separate thread for reading, and continues to read data concurrently. The `process_integer` function validates each integer received, and the `socket_reader` function handles potential errors during the read operation.

The dynamically allocated array stores only the valid integers within the specified range (1-1000). When all integers have been processed, the main function identifies and prints the largest integer in the valid array. The code manages memory efficiently by allocating enough buffer space for a given number of bytes at a time to minimize reallocations.

It is important to note that this code is not exhaustive and should be further developed, optimized, and tested based on specific application requirements and constraints. For example, error handling may need to include more detailed diagnostic information for better troubleshooting. Also, the reader thread could be made more efficient by using asynchronous I/O operations instead of polling.']

