['```c
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <semaphore.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t length;
    pthread_mutex_t mutex;
    semaphore_t sem;
} CRCDatabase;

CRCDatabase* create_crcdb(size_t initial_capacity) {
    CRCDatabase *db = malloc(sizeof(CRCDatabase));
    if (!db) return NULL;
    db->data = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!db->data) {
        free(db);
        return NULL;
    }
    db->capacity = initial_capacity;
    db->length = 0;
    pthread_mutex_init(&db->mutex, NULL);
    sem_init(&db->sem, 0, initial_capacity);
    return db;
}

bool add_to_crcdb(CRCDatabase *db, const NFAPI_CRC_INDICATION_PDU_T *data) {
    sem_wait(&db->sem);
    if (db->length == db->capacity) {
        void *tmp = realloc(db->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (db->capacity + 1));
        if (!tmp) {
            sem_post(&db->sem);
            return false;
        }
        db->data = tmp;
        db->capacity++;
    }
    memcpy(db->data + db->length, data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    db->length++;
    sem_post(&db->sem);
    return true;
}

// Implement error recovery, logging, checksum validation, and other required functions here.
```

