#include <string.h>

typedef struct IntListNode {
    int64_t value;
    struct IntListNode *next;
} IntListNode;

sem_t input_mutex;
IntListNode *head = NULL, *tail = NULL;
size_t count = 0;
bool error = false;

void* read_and_append(void* arg) {
    char line[1024];
    while (true) {
        sem_wait(&input_mutex);
        if (error) break;
        fgets(line, sizeof(line), stdin);
        // trim leading and trailing whitespace
        char* start = line;
        char* end = start + strlen(start);
        while (isspace(*start)) start++;
        while (end > start && isspace(*--end));
        size_t len = end - start + 1;
        if (len == 0) {
            printf("Empty line ignored\n");
            continue;
        }
        // check for non-integer characters
        for (size_t i = 0; i < len; ++i) {
            if (!isdigit(start[i])) {
                printf("Invalid character found in input. Line ignored\n");
                error = true;
                break;
            }
        }
        if (error) break;
        // convert the trimmed string to an integer and append it to the list
        int64_t num = strtoll(start, NULL, 10);
        IntListNode* node = malloc(sizeof(IntListNode));
        node->value = num;
        node->next = NULL;
        if (count == 0) {
            head = tail = node;
        } else {
            tail->next = node;
            tail = node;
        }
        ++count;
        printf("Number %" PRId64 " added successfully\n", num);
    }
    pthread_exit(NULL);
}

void log_error(const char* message) {
    // Implement logging mechanism here
}

int main() {
    sem_init(&input_mutex, 0, 1);
    size_t num_threads = strtol("<number_of_threads>", NULL, 10);
    pthread_t threads[num_threads];
    for (size_t i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, &read_and_append, NULL)) {
            log_error("Failed to create thread");
            return 1;
        }
    }
    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }
    sem_destroy(&input_mutex);
    // Implement freeing memory here when needed
    return 0;
}
```

