```cpp
#include <iostream>
#include <list>
#include <memory>
#include <boost/asio.hpp>
#include <boost/thread.hpp>
#include <boost/property_tree/ptree.hpp>
#include <boost/random.hpp>
#include <cstdint>

namespace nfapi {
    struct CRC_INDICATION_PDU_T {
        uint32_t RX_UE_INFORMATION_TAG;
        uint16_t RNTI;
        bool CRCFLAG;
        uint16_t CRC_INDICATION_REL8_TAG;
        std::optional<uint16_t> extendedCRC; // Optional field for the extended CRC indication tag
    };

    class PDUList {
    private:
        std::list<std::unique_ptr<CRC_INDICATION_PDU_T>> pduList;
        boost::mutex mutex;

    public:
        void pushPDU(const CRC_INDICATION_PDU_T& pdu) {
            {
                boost::lock_guard<boost::mutex> lock(mutex);
                pduList.push_back(std::make_unique<CRC_INDICATION_PDU_T>(pdu));
            }
        }

        const std::list<std::unique_ptr<CRC_INDICATION_PDU_T>>& getPDUs() const {
            return pduList;
        }
    };

    class PDUManager {
    private:
        PDUList pduList;
        uint32_t maxThreads;
        uint32_t maxPDUPerSecond;
        bool extendCRC;
        boost::property_tree::ptree config;

    public:
        PDUManager(const boost::property_tree::ptree& _config) : config(_config) {
            extendCRC = config.get<bool>("extended_crc", false);
            maxThreads = config.get<uint32_t>("max_threads", 1000);
            maxPDUPerSecond = config.get<uint32_t>("max_pdu_per_second", 1000);
        }

        void start() {
            boost::thread_group threads;
            for (uint32_t i = 0; i < maxThreads; ++i) {
                threads.create_thread(std::bind(&PDUManager::worker, this));
            }
            threads.join_all();
        }

    private:
        void worker() {
            boost::random::mt19937 generator;
            boost::uniform_int_distribution<> distribution(0, maxPDUPerSecond - 1);
            for (uint32_t i = 0; i < distribution(generator); ++i) {
                CRC_INDICATION_PDU_T pdu{};
                pdu.RX_UE_INFORMATION_TAG = rand();
                pdu.RNTI = rand() % 65535;
                pdu.CRCFLAG = bool(rand() % 2);
                if (extendCRC) {
                    pdu.extendedCRC = uint16_t(rand());
                }
                pduList.pushPDU(pdu);
            }
        }
    };
}

int main(int argc, char* argv[]) {
    boost::property_tree::ptree config;
    // Load configuration from file or command line arguments

    nfapi::PDUManager manager(config);
    manager.start();
    return 0;
}
```

