char* process_filename(const char *input, const bool condition, const size_t buffer_size, const size_t max_ext_len, const char **supported_types) {
    size_t input_len = strlen(input);
    if (input_len > buffer_size) {
        log_error("Filename exceeds the allowed buffer size.");
        return input;
    }

    size_t num_digits = 0;
    for (size_t i = 0; i < input_len; ++i) {
        if (isdigit(input[i])) {
            num_digits++;
        }
    }

    const char *dot_pos = strchr(input, '.');
    if (!dot_pos || dot_pos + 1 >= input + input_len) {
        log_error("Invalid filename: missing extension or improper format.");
        return input;
    }

    size_t ext_len = (dot_pos - input);
    const char *ext = input + ext_len;
    if (num_digits > 9) {
        log_error("Invalid filename: too many digits in extension.");
        return input;
    }

    size_t new_ext_len = std::min(max_ext_len - ext_len, num_digits);
    char new_ext[new_ext_len + 1];
    for (size_t i = 0; i < new_ext_len; ++i) {
        new_ext[i] = input[input_len - num_digits + i];
    }
    new_ext[new_ext_len] = '\0';

    const char *type_pos = strchr(new_ext, '.');
    if (!type_pos || type_pos >= new_ext + new_ext_len) {
        log_error("Invalid extension: missing type or improper format.");
        return input;
    }

    size_t type_len = type_pos - new_ext;
    for (size_t i = 0; i < type_len && supported_types[i]; ++i) {
        if (!strncmp(new_ext + type_pos - new_ext, supported_types[i], type_len)) {
            break;
        }
    }
    if (!supported_types[i]) {
        log_error("Unsupported file type.");
        return input;
    }

    size_t output_len = input_len + new_ext_len - type_len;
    char *output = (char *)malloc(output_len + 1);
    strncpy(output, input, input_len);

    if (condition) {
        memmove(output + ext_len, new_ext, new_ext_len + 1);
    } else {
        log_error("Condition not met. Filename remains unchanged.");
    }

    output[input_len + new_ext_len] = '\0';

    return output;
}
