NetworkEvent* init_network_events(size_t capacity) {
    NetworkEvent *network_events = malloc(capacity * sizeof(NetworkEvent));
    if (!network_events) {
        log_error("Memory allocation failed.");
        return NULL;
    }

    for (size_t i = 0; i < capacity; ++i) {
        network_events[i].DataPayload = NULL;
    }

    return network_events;
}

void add_network_event(NetworkEvent *network_events, size_t *capacity, size_t *size, const time_t timestamp, const enum EventType event_type, const char *payload) {
    if (validate_payload(payload)) {
        // Allocate memory for the payload if it hasn't been allocated already.
        network_events[*size].DataPayload = strdup(payload);
        if (!network_events[*size].DataPayload) {
            log_error("Memory allocation failed.");
            return;
        }

        network_events[*size].Timestamp = timestamp;
        network_events[*size].EventType = event_type;

        (*capacity)++;
        if (*capacity == *size) {
            // Double the capacity when we reach the current size.
            *capacity *= 2;
            NetworkEvent *new_network_events = realloc(network_events, *capacity * sizeof(NetworkEvent));
            if (!new_network_events) {
                log_error("Memory reallocation failed.");
                return;
            }
            network_events = new_network_events;
        }
    } else {
        log_error("Payload validation failed.");
    }
}

void clear_network_events(NetworkEvent *network_events, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        if (network_events[i].DataPayload) {
            free(network_events[i].DataPayload);
            network_events[i].DataPayload = NULL;
        }
    }
}

void destroy_network_events(NetworkEvent *network_events, size_t size) {
    clear_network_events(network_events, size);
    free(network_events);
}
