namespace RandomEngine {
    static log4cxx::LoggerPtr logger = log4cxx::Logger::getLogger("RandomEngine");

    class RNG {
        using engine_type = std::mt19937_64;
        using dist_type = std::uniform_int_distribution<>;
        using frac_dist_type = std::uniform_real_distribution<>;

    public:
        RNG(uint64_t seed) : engine_{seed}, dist_(0, INT32_MAX), fracDist_(0.0, 1.0) {
            if (seed < 0 || seed > std::numeric_limits<uint64_t>::max()) {
                logger->error("Invalid seed value provided: {}"_format(seed));
                throw std::invalid_argument("Invalid seed value");
            }
        }

        static RNG& instance() {
            static RNG singleton{std::random_device{}()};
            return singleton;
        }

        int generateInt(int min, int max) {
            if (min > max) {
                logger->error("Invalid range provided: [{}, {}]"_format(min, max));
                throw std::invalid_argument("Invalid range provided");
            }
            return dist_(engine_, min, max);
        }

        float generateFloat(float min, float max) {
            if (min > max) {
                logger->error("Invalid range provided: [{}, {}]"_format(min, max));
                throw std::invalid_argument("Invalid range provided");
            }
            return fracDist_(engine_, min, max);
        }

    private:
        engine_type engine_;
        dist_type dist_;
        frac_dist_type fracDist_;
    };
} // namespace RandomEngine
