["```python
import os
import sys
import re
import subprocess
import logging
import argparse
from getpass import getpass
from hashlib import sha256

def encrypt_password(password):
    return sha256(password.encode()).hexdigest()

def read_config(file_path):
    try:
        with open(file_path, 'r') as file:
            config = {}
            for line in file:
                match = re.search(r'{(.+)}', line)
                if match:
                    placeholder, _ = match.groups()
                    config[placeholder] = getattr(args, placeholder, None)
                else:
                    config[line.strip()] = None
            return config
    except FileNotFoundError:
        logging.error(f'Missing configuration file: {file_path}')
        raise SystemExit(1)

def update_config(file_path, updated_config):
    with open(file_path, 'w') as file:
        for line, value in sorted((line + '=' + str(value) if value is not None else line for (line, value) from updated_config.items()), key=len):
            file.write(line + '\n')
        file.write('\nencrypted_password: ' + encrypt_password(getpass('Enter password: ')) + '\n')

def process_directory(directory, config_dict):
    for root, _, files in os.walk(directory):
        for file in [f for f in files if f.endswith('.cfg')]:
            file_path = os.path.join(root, file)
            current_config = read_config(file_path)
            updated_config = {k: v or config_dict.get(k) for k, v in current_config.items() if v is None}
            update_config(file_path, updated_config)

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--directory', required=True, help='Directory containing configuration files')
    for placeholder in sys.argv[1:]:
        parser.add_argument(placeholder, type=str, help=f'Value to replace {placeholder} placeholders with')
    args = parser.parse_args()

    process_directory(args.directory, dict(zip(sys.argv[1:], args[1:])))

if __name__ == '__main__':
    main()
```

