// Define a linked list node for the structure
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU data;
    struct Node *next;
} Node;

// Function prototype for logging, enabling/disabling logging at runtime
void log(const char* message, bool enable_logging);

// Global variables for list management and logging configuration
Node* head = NULL;
bool log_enabled = true;
int max_retries = 10;
unsigned int crc_threshold = 5; // Number of consecutive CRC errors to log

// Function to initialize a new NFAPI_CRC_INDICATION_PDU with random CRC flag
NFAPI_CRC_INDICATION_PDU* create_pdu() {
    NFAPI_CRC_INDICATION_PDU* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
    if (!pdu) return NULL;

    pdu->crcflag = rand() % 10 > crc_threshold; // Generate random CRC flag, considering threshold
    return pdu;
}

// Function to insert a new node into the linked list, ensuring unique RNTIs
void insert_node(NFAPI_CRC_INDICATION_PDU* pdu) {
    Node** current = &head;

    while (*current) {
        if ((*current)->data.rnti == pdu->rnti) {
            free(pdu);
            return; // RNTI already exists, free the new node and exit function
        }
        current = &(*current)->next;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        free(pdu);
        return; // Memory allocation failure, free the new PDU and exit function
    }

    new_node->data = *pdu;
    new_node->next = head;
    head = new_node;
}

// Function to handle external data sources with potential delays or failures
void process_external_source() {
    int retries = 0;

    while (retries < max_retries) {
        if (process_data()) break; // Process the data and return if successful
        retries++;

        if (!retries || log_enabled) {
            char message[100];
            sprintf(message, "External source delay or failure after %d attempts", retries);
            log(message, true);
        }

        usleep(100000); // Sleep for 100ms before trying again
    }
}

// Function to enable/disable logging at runtime
void set_logging(bool new_state) {
    log_enabled = new_state;
}

// Function to process the data and validate CRC flags
bool process_data() {
    NFAPI_CRC_INDICATION_PDU* pdu = create_pdu();
    if (!pdu) return false; // Memory allocation failure, free the new PDU and return false

    process_external_source(); // Handle external data source delays or failures

    Node* current = head;
    while (current && current->data.crcflag > crc_threshold) {
        if (current->data.rnti == pdu->rnti) {
            free(pdu); // If a PDU with the same RNTI exists and has exceeded the CRC threshold, discard it
            return false;
        }
        current = current->next;
    }

    insert_node(pdu); // Insert the new PDU into the list if no duplicate RNTIs or memory allocation failures occurred

    return true;
}
