#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    NAS_PDU nas_pdu;
    RRC_Message rrc_message;
} LTE_Uu_Pdu_t;

struct array_wrapper {
    LTE_Uu_Pdu_t* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
};

void nas_pdu_init(NAS_PDU* nas_pdu) {
    nas_pdu->nas_transaction_id = rand();
    nas_pdu->nas_message_type = rand() % 256; // Random NAS_Message_Type from [0, 255]
}

void rrc_message_init(RRC_Message* rrc_message) {
    rrc_message->rrc_transaction_id = rand();
    rrc_message->rrc_message_type = RRC_MESSAGE_TYPE_1; // Assuming a fixed number of message types for simplicity
}

struct array_wrapper* array_wrapper_create(size_t capacity) {
    struct array_wrapper* wrapper = malloc(sizeof(*wrapper));
    if (!wrapper) return NULL;
    wrapper->data = calloc(capacity, sizeof(LTE_Uu_Pdu_t));
    if (!wrapper->data) {
        free(wrapper);
        return NULL;
    }
    pthread_mutex_init(&wrapper->mutex, NULL);
    wrapper->capacity = capacity;
    wrapper->size = 0;
    return wrapper;
}

void array_wrapper_destroy(struct array_wrapper* wrapper) {
    if (wrapper) {
        free(wrapper->data);
        pthread_mutex_destroy(&wrapper->mutex);
        free(wrapper);
    }
}

void array_wrapper_lock(struct array_wrapper* wrapper) {
    pthread_mutex_lock(&wrapper->mutex);
}

void array_wrapper_unlock(struct array_wrapper* wrapper) {
    pthread_mutex_unlock(&wrapper->mutex);
}

int array_wrapper_add(struct array_wrapper* wrapper, const LTE_Uu_Pdu_t* pdu) {
    if (wrapper->size == wrapper->capacity) return -1; // Array is full

    array_wrapper_lock(wrapper);
    if (wrapper->size == wrapper->capacity) array_wrapper_unlock(wrapper);
    else {
        memcpy(&wrapper->data[wrapper->size], pdu, sizeof(*pdu));
        wrapper->size++;
        array_wrapper_unlock(wrapper);
    }

    return 0;
}

LTE_Uu_Pdu_t* array_wrapper_get(struct array_wrapper* wrapper, size_t index) {
    LTE_Uu_Pdu_t* pdu = NULL;

    if (index >= wrapper->size || index < 0) return NULL;

    array_wrapper_lock(wrapper);
    pdu = &wrapper->data[index];
    array_wrapper_unlock(wrapper);

    return pdu;
}

void array_wrapper_remove(struct array_wrapper* wrapper, size_t index) {
    if (index >= wrapper->size || index < 0) return;

    array_wrapper_lock(wrapper);
    memmove(&wrapper->data[index], &wrapper->data[index + 1], (wrapper->size - index - 1) * sizeof(LTE_Uu_Pdu_t));
    wrapper->size--;
    array_wrapper_unlock(wrapper);
}
```

This code provides a thread-safe dynamically allocated array of `LTE_Uu_Pdu_t` structures, where each element includes a valid `NAS_PDU` and a `RRC_Message`. The function to create the wrapper supports concurrent access from multiple threads with `pthread_mutex_lock()` and `pthread_mutex_unlock()`. Memory optimization is achieved by using `calloc()` for dynamic allocation and `free()` for deallocation.

The code also includes a simple initialization function for both `NAS_PDU` and `RRC_Message` structures, which generate valid IDs and types based on the given constraints. Additionally, error handling is included to validate that the index passed to the getter and remover functions is within the bounds of the array size.

Finally, this code can be easily integrated with existing systems by adapting the data types `NAS_PDU` and `RRC_Message` to match the specific system's requirements."]

