public class StateLoader {
    private static final String PATTERN = "^/(?<root>[a-zA-Z0-9_.-]+)/states/([a-zA-Z0-9_.-]+)$";
    private static final long TIMEOUT_MS = 5_000L;
    private static final int BUFFER_SIZE = 8192;
    private static final ConcurrentHashMap<String, State> cache = new ConcurrentHashMap<>();
    private static final StateValidator validator;

