        // Initialize the StateValidator instance here
    }

    public static State loadState(String pathOrUrl) {
        if (!pathOrUrl.matches(PATTERN)) {
            return null;
        }

        String root = pathOrUrl.substring(0, pathOrUrl.lastIndexOf('/'));
        String stateName = pathOrUrl.substring(pathOrUrl.lastIndexOf('/') + 1);

        File file = new File(root, "states/" + stateName);
        if (!file.exists()) {
            createDefaultStateFile(file);
        }

        State state;
        try {
            state = deserialize(file);
        } catch (IOException | ClassNotFoundException e) {
            return null;
        }

        if (!validator.isValid(state)) {
            return null;
        }

        cache.putIfAbsent(pathOrUrl, state);
        return cache.get(pathOrUrl);
    }

    private static void createDefaultStateFile(File file) throws IOException {
        if (!file.exists() && !file.mkdirs()) {
            throw new RuntimeException("Failed to create directory structure");
        }

        try (DataOutputStream outputStream = new DataOutputStream(new BufferedOutputStream(new FileOutputStream(file))) ) {
            State defaultState = new State(); // Initialize your default state object here
            serialize(defaultState, outputStream);
        }
    }

    private static void serialize(Object obj, DataOutput out) throws IOException {
        byte[] bytes = SerializeUtils.serialize(obj);
        out.writeInt(bytes.length);
        out.write(bytes);
    }

    private static Object deserialize(File file) throws IOException, ClassNotFoundException {
        try (DataInputStream inputStream = new DataInputStream(new BufferedInputStream(new FileInputStream(file))) ) {
            int length = inputStream.readInt();
            byte[] bytes = new byte[length];
            inputStream.readFully(bytes);
            return SerializeUtils.deserialize(bytes);
        }
    }

    // Implement the StateValidator interface here, defining your validation criteria
}
