/**
 * Upload images from given URLs with validation, resizing and error handling
 * @param {Array<String>} urls - An array of image URLs to process
 * @returns {Promise<Array<Object>>} - An array of objects containing the uploaded file details (fileId, size, etc.)
 */
async function uploadImages(urls) {
  // Ensure max concurrency limit is not exceeded
  const concurrentLimit = 10;
  const chunkSize = Math.ceil(urls.length / concurrentLimit);

  let promises = [];
  for (let i = 0; i < chunkSize; i++) {
    const start = i * concurrentLimit;
    const end = (i + 1) * concurrentLimit;
    const chunk = urls.slice(start, end);
    promises.push(processChunk(chunk));
  }

  // Execute promises in parallel with error handling and timeout
  return bluebird.gather(promises, { concurrency: concurrentLimit })
    .timeout(5000, 'Upload timed out')
    .catch((error) => {
      console.error('Error while processing images', error);
      throw error;
    });
}

/**
 * Process an array of image URLs and upload them using third-party service
 * @param {Array<String>} urls - An array of image URLs to process
 * @returns {Promise<Array<Object>>} - An array of objects containing the uploaded file details (fileId, size, etc.)
 */
async function processChunk(urls) {
  const promises = [];

  for (const url of urls) {
    // Validate URL and download image using axios
    const response = await axios.get(url, { responseType: 'arraybuffer' });

    try {
      // Resize image using sharp and save it to a buffer
      const resizedImageBuffer = await sharp(response.data)
        .resize(800, 600, { fit: 'inside', withoutMaintainingAspectRatio: true })
        .toBuffer();

      // Upload resized image to third-party service
      const uploadPromise = uploadToService({ file: resizedImageBuffer });

      promises.push(uploadPromise);
    } catch (error) {
      console.error(`Error while processing image ${url}`, error);
    }
  }

  // Execute image uploads in parallel with retries and timeout
  return bluebird.gather(promises, { concurrency: urls.length })
    .timeout(5000, 'Upload timed out')
    .attempts(5, { policy: bluebird.exponentialBackoff({ multiplier: 2, minTimeout: 1000 }) })
    .catch((error) => {
      console.error('Error while uploading images', error);
      throw error;
    });
}

/**
 * Upload image to the third-party service
 * @param {Object} options - Options object for upload (file, metadata, etc.)
 * @returns {Promise<Object>} - The uploaded file details
 */
