            (*list)[i].RNTI = rand() % 65536;
            (*list)[i].CRC_INDICATION_REL8_TAG[0] = i + 1; // Setting a unique CRC tag for each element
            (*list)[i].CRCFLAG = rand() % 2 == 0;
        }
    }
}

EVP_CIPHER *createCipher(int mode) {
    const EVP_CIPHER *cipher;
    EVP_CIPHER_CTX *ctx;
    EVP_CIPHER *result = NULL;

    switch (mode) {
        case ECB:
            cipher = EVP_des_ecb();
            break;
        case EDE:
            cipher = EVP_des_ede();
            break;
        case EDE3:
            cipher = EVP_des_ede3_cbc();
            break;
        case CFB:
            cipher = EVP_des_cfb1();
            break;
        default: // null encryption mode
            return NULL;
    }

    ctx = EVP_CIPHER_CTX_new();
    if (ctx != NULL) {
        EVP_CIPHER_init(ctx, cipher);
        result = EVP_CIPHER_dup(ctx);
    }

    return result;
}
