typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU;

typedef struct listNode {
    NFAPI_CRC_INDICATION_PDU element;
    struct listNode *next;
} listNode;

// Thread-safe dynamic list
listNode* dynamicList = NULL;
pthread_mutex_t listMutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the dynamic list
void initDynamicList() {
    pthread_mutex_lock(&listMutex);
    if (dynamicList == NULL) {
        dynamicList = malloc(sizeof(listNode));
        dynamicList->element.crc_indication.crcflag = random(); // Initialize CRCFLAG with a random value
