void serialize(const nfapi_crc_indication_pdu_t* pdu, char* buffer) {
    int i = 0;
    // Bit-pack the tag, RNTI, and CRC_INDICATION_REL8_TAG into the buffer
    // ...
    *buffer++ = (char)(i >> 24);
    *buffer++ = (char)(i >> 16);
    *buffer++ = (char)(i >> 8);
    *buffer++ = (char)i;
}

bool deserialize(const char* buffer, nfapi_crc_indication_pdu_t* pdu) {
    int i = (*buffer++) << 24 | (*buffer++) << 16 | (*buffer++) << 8 | *buffer++;
    // Bit-unpack the tag, RNTI, and CRC_INDICATION_REL8_TAG from the buffer
    // ...
    pdu->crc_tag.CRCFLAG = (i & BITMASK) != 0;
    return true;
}
