const EventEmitter = require('events');
const lodash = require('lodash');
const axios = require('axios');
const Redis = require('ioredis');

class HighThroughputProcessor {
  constructor(options) {
    this.redis = new Redis(options.redis);
    this.apiUrl = options.apiUrl;
    this.filterFunction = options.filterFunction || lodash.identity;
    this.eventEmitter = new EventEmitter();
    this.processingRateLimit = options.processingRateLimit || 1000; // process events per second
    this.pause = false;

    this.initializeMonitoring();
  }

  initializeMonitoring() {
    setInterval(() => {
      const processingRate = this.stats.processedEvents / this.stats.elapsedSeconds;
      console.log(`Processing rate: ${processingRate} events/second`);
      if (processingRate > this.processingRateLimit) {
        this.adjustFilterFunction(this.filterFunction * 0.95);
      }
    }, 1000);

    this.stats = { processedEvents: 0, elapsedSeconds: 0 };
  }

  adjustFilterFunction(newFilterFunction) {
    this.filterFunction = newFilterFunction;
  }

  async process() {
    if (this.pause) return;

    const eventIds = await this.redis.lrangeAsync(`event-stream`, 0, -1);

    for (let i = 0; i < eventIds.length; i++) {
      const eventId = eventIds[i];

      try {
        const event = await axios.get(`${this.apiUrl}/events/${eventId}`);

        if (this.filterFunction(event.data)) {
          this.eventEmitter.emit('processedEvent', event.data);
          this.redis.lremAsync(`event-stream`, 1, eventId);
          this.stats.processedEvents++;
        }
      } catch (error) {
        console.error(`Error processing event ${eventId}:`, error);
      } finally {
        this.stats.elapsedSeconds++;
      }
    }
  }

  pauseProcessing() {
    this.pause = true;
  }

  resumeProcessing() {
    this.pause = false;
  }
}

module.exports = HighThroughputProcessor;
```

