// Custom FrameHeader structure with reference count, timestamp, sequence number, and payload length.
typedef struct FrameHeader {
    pthread_mutex_t lock; // Mutex for thread-safe access
    int ref_count; // Reference count
    time_t timestamp; // Timestamp of frame creation
    unsigned long seq_num; // Sequence number of the frame
    size_t payload_len; // Length of the frame's payload
} FrameHeader;

// Custom allocator for memory management. Can be replaced with a user-provided one.
void* custom_malloc(size_t size) {
    void* ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ptr == MAP_FAILED) {
        perror("Error allocating memory");
        abort();
    }
    return ptr;
}

// Custom FrameList structure managing a dynamic list of FrameHeaders.
typedef struct FrameList {
    FrameHeader** frames; // Dynamic array of FrameHeaders
    size_t capacity; // Current capacity of the array
    size_t size; // Number of elements currently in the array
    time_t timeout; // Configurable timeout threshold for cleanup (in seconds)
    void (*cleanup)(FrameHeader*); // Custom cleanup function
    pthread_mutex_t lock; // Mutex for thread-safe access to the list
} FrameList;

// Function to initialize a new FrameList with a given initial capacity and timeout threshold.
FrameList frame_list_init(size_t initial_capacity, time_t timeout, void (*cleanup)(FrameHeader*)) {
    FrameList list = { .frames = NULL, .capacity = initial_capacity, .size = 0, .timeout = timeout, .cleanup = cleanup };
    list.frames = custom_malloc(initial_capacity * sizeof(FrameHeader*));
    for (size_t i = 0; i < initial_capacity; ++i) {
        list.frames[i] = NULL;
    }
    pthread_mutex_init(&list.lock, NULL);
    return list;
}

// Function to insert a new FrameHeader into the frame list.
void frame_list_insert(FrameList* list, FrameHeader* frame) {
    // Acquire lock before accessing or modifying the list
    pthread_mutex_lock(&list->lock);

    size_t index = list->size % list->capacity;
    for (; list->frames[index] != NULL; ++index) {}
    list->frames[index] = frame;
    ++list->size;

    // Release lock after insertion
    pthread_mutex_unlock(&list->lock);
}

// Function to retrieve a FrameHeader from the frame list, optionally removing it if the reference count drops to zero.
FrameHeader* frame_list_get(FrameList* list, bool remove) {
    // Acquire lock before accessing or modifying the list
    pthread_mutex_lock(&list->lock);

    FrameHeader** iter = list->frames;
    for (size_t i = 0; i < list->size; ++i, ++iter) {
        if ((*iter)->ref_count > 0 && time(NULL) - (*iter)->timestamp >= list->timeout) {
            // Custom cleanup function can be called here if provided
            if (list->cleanup != NULL) {
                list->cleanup((*iter));
            }
        }
        if ((*iter)->ref_count == 0) {
            FrameHeader* frame = *iter;
            *iter = NULL;
            --list->size;
            if (remove) {
                free(frame);
            }
            break;
        }
    }

    // Release lock after retrieval
    pthread_mutex_unlock(&list->lock);

    return iter != list->frames + list->size ? *iter : NULL;
}
