typedef struct Role {
    int id;
    int parent_id;
    struct Role* child;
    struct Role* sibling;
} Role;

void create_role(Role**, const int id, int parent_id);
bool is_root(const Role* role);
void set_parent(Role*, Role*);
Role* find_child(Role*, int id);
Role* find_sibling(Role*, int id);
void link_roles(Role*, Role*);
void update_role(Role**, const int id, int parent_id);

int populate_role_list(Role*** roles, int roles_count, const int* role_ids, const Role* root) {
    *roles = calloc(roles_count + 1, sizeof(Role));
    if (!*roles) return -1;

    for (int i = 0; i < roles_count; ++i) {
        create_role(roles, role_ids[i], role_ids[i] == root ? -1 : role_ids[find_parent_id(role_ids, role_ids[i])]);
    }

    Role* current = find_role(*roles, root);
    if (!current) return -2; // Root not found or memory allocation failure

    set_parent(current, NULL);
    link_roles(current, find_child(root, current->id));

    for (int i = 0; i < roles_count; ++i) {
        Role* role = find_role(*roles, role_ids[i]);
        if (!role) continue; // Role not found or memory allocation failure

        set_parent(role, current);
        link_roles(role, find_child(root, role->id));
    }

    return 0;
}

void create_role(Role** roles, const int id, int parent_id) {
    *roles = realloc(*roles, sizeof(Role) * (sizeof(*roles)/sizeof(Role)) + 1);
    if (!*roles) return;

    (*roles)[sizeof(*roles)/sizeof(Role)] = malloc(sizeof(Role));
    if (!(*roles)[sizeof(*roles)/sizeof(Role)]) {
        free(*roles);
        *roles = NULL;
        return;
    }

    (*roles)[sizeof(*roles)/sizeof(Role)]->id = id;
    (*roles)[sizeof(*roles)/sizeof(Role)]->parent_id = parent_id;
    (*roles)[sizeof(*roles)/sizeof(Role)]->child = NULL;
    (*roles)[sizeof(*roles)/sizeof(Role)]->sibling = NULL;
}

int find_parent_id(const int* role_ids, const int id) {
    for (int i = 0; i < sizeof(role_ids)/sizeof(int); ++i) {
        if (role_ids[i] == id) return i;
    }
    return -1; // Parent not found
}

bool is_root(const Role* role) {
    return role->parent_id == -1;
}

Role* find_child(Role* root, const int id) {
    for (Role* current = root->child; current; current = current->sibling) {
        if (current->id == id) return current;
    }
    return NULL; // Child not found
}

Role* find_sibling(Role* parent, const int id) {
    for (Role* sibling = parent->child; sibling; sibling = sibling->sibling) {
        if (sibling->id == id && sibling != parent) return sibling;
    }
    return NULL; // Sibling not found
}

void set_parent(Role* role, Role* parent) {
    role->parent_id = parent ? parent->id : -1;
    if (parent) link_roles(parent, role);
}

void link_roles(Role* parent, Role* child) {
    if (!child) return;

    child->sibling = parent->child;
    child->child = NULL;
    parent->child = child;
}

void update_role(Role** roles, const int id, int parent_id) {
    for (int i = 0; i < sizeof(*roles)/sizeof(Role); ++i) {
        if ((*roles)[i].id == id) {
            (*roles)[i].parent_id = parent_id;
            break;
        }
    }
}
```

