    int keys[num_offsets];
    long offsets[num_offsets];

    // Cache for unique key substrings
    static char cache[1024][10];
    size_t num_cache_entries = 0;

    for (size_t i = 0; i < num_offsets; ++i) {
        if (i < num_cache_entries) {
            // Reuse a previously allocated substring if possible
            strcpy((*records + i)->key, cache[i]);
        } else {
            // Allocate a new unique substring for this key value
            keys[i] = i;
            while (true) {
                sprintf(cache[num_cache_entries++], "%lud", keys[i]);
                int j;
                for (j = 0; j < num_offsets && j != i; ++j) {
                    if (!strcmp(cache[num_cache_entries - 1], (*records + j)->key)) {
                        break;
                    }
                }
                if (j == num_offsets) {
                    // Found a unique substring, set it for this key and break the loop
                    strcpy((*records + i)->key, cache[num_cache_entries - 1]);
                    break;
                }
            }
        }

        (*records + i)->value = rand() % 1000 + 1;
    }

    long *offsets_ptr = offsets;
    for (size_t i = 0; i < num_offsets; ++i) {
