record* init_data_structures(int num_records, int min_value, int max_value) {
    if (num_records <= 0 || max_value < min_value) {
        perror("Invalid input parameters");
        return NULL;
    }

    size_t offsets_size = num_records;
    offset *offsets = malloc(offsets_size * sizeof(offset));
    if (!offsets) {
        perror("Memory allocation for offsets failed.");
        goto cleanup;
    }

    size_t keys_size = 0;
    key *keys = NULL;
    size_t records_size = num_records;
    record *records = malloc(records_size * sizeof(record));
    if (!records) {
        perror("Memory allocation for records failed.");
        goto cleanup;
    }

    // Initialize offsets
    for (size_t i = 0; i < offsets_size; ++i) {
        offsets[i].offset = i;
    }

    // Initialize keys and handle duplicates
    keys = malloc((num_records + 1) * sizeof(key));
    if (!keys) {
        perror("Memory allocation for keys failed.");
        goto cleanup;
    }

    for (size_t i = 0; i < num_records; ++i) {
        size_t j = 0;
        bool found = false;

        do {
            if (!keys[j].used) {
                keys[j].key = i + 1;
                keys[j].used = true;
                found = true;
                break;
            }
            ++j;
        } while (j < num_records + 1);

        if (!found) {
            perror("Failed to find unique key.");
            goto cleanup;
        }
    }

    // Initialize records with random values and handle edge cases
    srand(time(NULL));
    for (size_t i = 0; i < records_size; ++i) {
        int value = min_value + rand() % (max_value - min_value + 1);
        bool unique = true;

        for (size_t j = 0; j < i; ++j) {
            if (records[j].value == value) {
                unique = false;
                break;
            }
        }

        if (!unique) {
            i--;
        } else {
            records[i].value = value;
        }
    }

    // Cleanup and return success
cleanup:
    free(keys);
    for (size_t i = 0; i < offsets_size; ++i) {
        free(offsets + i);
    }
    free(offsets);

    if (!records) {
        perror("Memory allocation for records failed.");
        return NULL;
    }

    return records;
}
