#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    void* key;
    void* data;
} Node;

typedef struct {
    double value;
} Data;

typedef struct {
    size_t capacity, size;
    Node** nodes;
    char** keys;
    Data* data;
} MemManager;

void log_error(const char* message) {
    fprintf(stderr, "%s\n", message);
}

MemManager* create_mem_manager(size_t growth_threshold) {
    if (growth_threshold <= 0) return NULL;

    MemManager* mm = malloc(sizeof(MemManager));
    if (!mm) log_error("Memory allocation failure.");

    mm->capacity = growth_threshold;
    mm->size = 0;

    mm->nodes = calloc(growth_threshold, sizeof(Node*));
    if (!mm->nodes) {
        free(mm);
        log_error("Memory allocation failure.");
        return NULL;
    }

    mm->keys = calloc(growth_threshold, sizeof(char*));
    if (!mm->keys) {
        free(mm->nodes);
        free(mm);
        log_error("Memory allocation failure.");
        return NULL;
    }

    mm->data = calloc(growth_threshold, sizeof(Data));
    if (!mm->data) {
        free(mm->keys);
        free(mm->nodes);
        free(mm);
        log_error("Memory allocation failure.");
        return NULL;
    }

    return mm;
}

void resize_mem_manager(MemManager* mm, size_t new_capacity) {
    if (new_capacity <= mm->size || new_capacity < 2 * mm->capacity) return;

    Node** new_nodes = realloc(mm->nodes, new_capacity * sizeof(Node*));
    if (!new_nodes) log_error("Memory allocation failure.");

    char** new_keys = realloc(mm->keys, new_capacity * sizeof(char*));
    if (!new_keys) {
        free(new_nodes);
        log_error("Memory allocation failure.");
        return;
    }

    Data* new_data = realloc(mm->data, new_capacity * sizeof(Data));
    if (!new_data) {
        free(new_keys);
        free(new_nodes);
        log_error("Memory allocation failure.");
        return;
    }

    mm->nodes = new_nodes;
    mm->keys = new_keys;
    mm->data = new_data;
    mm->capacity = new_capacity;
}

void deallocate_mem_manager(MemManager* mm) {
    if (!mm) return;

    for (size_t i = 0; i < mm->size; ++i) {
        free(mm->keys[i]);
        free(mm->nodes[i]->key);
        free(mm->nodes[i]);
    }
    free(mm->keys);
    free(mm->nodes);
    free(mm->data);
    free(mm);
}

void randomize_data(Data* data) {
    data->value = rand() / (double)RAND_MAX;
}

int main() {
    MemManager* mm = create_mem_manager(10);

    srand(time(NULL));

    for (size_t i = 0; i < 100; ++i) {
        if (!mm || !mm->size) break;

        char* key = malloc(10 * sizeof(char));
        if (!key) log_error("Memory allocation failure.");

        sprintf(key, "Key%zu", i);
        mm->keys[mm->size] = key;
        mm->nodes[mm->size] = malloc(sizeof(Node));
        if (!mm->nodes[mm->size]) log_error("Memory allocation failure.");

        mm->nodes[mm->size]->key = strdup(key);
        if (!mm->nodes[mm->size]->key) log_error("Memory allocation failure.");

        Data* data = &(mm->data[mm->size]);
        randomize_data(data);
        mm->size++;

        if (mm->size == mm->capacity) resize_mem_manager(mm, 2 * mm->capacity);
    }

    deallocate_mem_manager(mm);

    return 0;
}
```

