typedef struct LTE_PHY_RX_FRAME_INFO {
    unsigned short LTESERIAL_ID;
    uint8_t PHICH_INFO[16];
    uint8_t DL_SRS[42];
} LTE_PHY_RX_FRAME_INFO_T;

typedef struct FrameListNode {
    LTE_PHY_RX_FRAME_INFO_T frameInfo;
    struct FrameListNode* next;
    pthread_mutex_t lock;
} FrameListNode_T;

FrameListNode_T* create_frame_list(size_t size) {
    FrameListNode_T *head = NULL, *new_node, *current;
    if (size == 0) return head;

    head = (FrameListNode_T*) malloc(sizeof(FrameListNode_T));
    if (!head) return NULL;

    head->frameInfo.LTESERIAL_ID = 1; // Or any valid initial value for LTESERIAL_ID
    pthread_mutex_init(&head->lock, NULL);

    current = head;
    for (size_t i = 1; i < size; ++i) {
        new_node = (FrameListNode_T*) malloc(sizeof(FrameListNode_T));
        if (!new_node) {
            free(head); // Free previous nodes if memory allocation fails for the rest
            return NULL;
        }

        pthread_mutex_init(&new_node->lock, NULL);
        current->next = new_node;
        current = new_node;
    }
    current->next = NULL; // Set end of list

    return head;
}

void resize_frame_list(FrameListNode_T **head_ref, size_t new_size) {
    FrameListNode_T *current, *new_head;
    size_t current_size = 0;

    current = *head_ref;
    while (current != NULL) {
        ++current_size;
        current = current->next;
    }

    if (new_size <= current_size) return; // No resizing needed

    new_head = create_frame_list(new_size - current_size);
    if (!new_head) return;

    current = *head_ref;
    for (size_t i = 0; i < current_size; ++i) {
        FrameListNode_T *next = current->next;
        pthread_mutex_lock(&current->lock);
        if (new_head->next)
            memcpy(&new_head->next->frameInfo, &current->frameInfo, sizeof(LTE_PHY_RX_FRAME_INFO_T));
        else
            new_head->frameInfo = current->frameInfo;
        pthread_mutex_unlock(&current->lock);

        current = next;
        FrameListNode_T *temp = new_head->next;
        if (temp) new_head->next = temp->next;
        else new_head->next = NULL;
        free(temp);
    }
    free(*head_ref);
    *head_ref = new_head;
}
```

