#include <pthread.h>
#include <stdlib.h>
#include <stdbool.h>
#include <semaphore.h>
#include <sys/mman.h>

#define CACHE_SIZE 1024

typedef struct LTE_PHY_RX_FRAME_INFO_T {
    uint32_t LTESerialID;
    PHICH_INFO_T PHICH_INFO;
    DL_SRS_INFO_T DL_SRS_INFO;
} LTE_PHY_RX_FRAME_INFO_T;

typedef struct FrameCacheNode {
    LTE_PHY_RX_FRAME_INFO_T frame;
    struct FrameCacheNode *next;
} FrameCacheNode;

static FrameCacheNode* cacheHead = NULL;
static FrameCacheNode* cacheTail = NULL;
static sem_t cacheMutex = SEM_INITIALIZER_NP;

void initDynamicList(LTE_PHY_RX_FRAME_INFO_T** list, size_t capacity) {
    *list = mmap(NULL, capacity * sizeof(LTE_PHY_RX_FRAME_INFO_T), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    if (*list == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&(*list)->lock, NULL);
}

LTE_PHY_RX_FRAME_INFO_T* getFrameFromCache(LTE_PHY_RX_FRAME_INFO_T key) {
    FrameCacheNode *current = cacheHead;
    sem_wait(&cacheMutex);

    while (current != NULL) {
        if (current->frame.LTESerialID == key) {
            FrameCacheNode* temp = current;
            sem_post(&cacheMutex);
            return &temp->frame;
        }
        current = current->next;
    }

    sem_post(&cacheMutex);
    return NULL;
}

void addFrameToCache(LTE_PHY_RX_FRAME_INFO_T* frame) {
    FrameCacheNode* newNode = malloc(sizeof(FrameCacheNode));
    if (newNode == NULL) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    newNode->frame = *frame;
    newNode->next = NULL;

    sem_wait(&cacheMutex);

    if (cacheHead == NULL || cacheTail == NULL) {
        cacheHead = newNode;
        cacheTail = newNode;
    } else {
        cacheTail->next = newNode;
        cacheTail = newNode;
    }

    sem_post(&cacheMutex);
}
```

This code initializes a dynamic list of LTE_PHY_RX_FRAME_INFO_T structures using mmap for memory management. It also implements a simple LRU (Least Recently Used) cache for frequently accessed frames, with a limit of CACHE_SIZE frames in the cache to prevent excessive memory usage.

The `initDynamicList` function initializes the list and locks it using a mutex. The `getFrameFromCache` function retrieves a frame from the cache if it exists, and `addFrameToCache` adds a frame to the cache if it's not already there (implemented as an LRU cache).

The code assumes that you have defined PHICH_INFO_T and DL_SRS_INFO_T types elsewhere in your project.']

