#include <vector>
#include <atomic>
#include <iterator>
#include <algorithm>
#include <chrono>

struct UE_CONTEXT_INFO {
    int UE_ID;
    int CELL_ID;
    std::vector<std::pair<int, int>> PACKET_DELIVERY_STATUS;
};

// Using atomic to maintain the running total of successful and failed packet deliveries
std::atomic<int> numSuccessfulDeliveries{0};
std::atomic<int> numFailedDeliveries{0};

class DynamicList {
public:
    using iterator = std::vector<UE_CONTEXT_INFO>::iterator;

    // Add an element at the end of the list
    void push_back(const UE_CONTEXT_INFO& data) {
        data.PACKET_DELIVERY_STATUS.reserve(10);  // Preallocate space for tags to avoid frequent reallocations
        m_data.push_back(std::move(data));
    }

    // Add an element at a specified position using move semantics
    iterator insert(iterator position, UE_CONTEXT_INFO&& data) {
        std::rotate(m_data.begin() + (position - m_data.begin()), position, std::next(position));
        m_data.insert(position, std::move(data));
        return position;
    }

    // Erase an element at a specified position using move semantics
    iterator erase(iterator position) {
        auto temp = std::move(*position);
        m_data.erase(position);
        updateDeliveryCounts(temp);
        return position;
    }

    // Update the delivery counts based on the provided data
    void updateDeliveryCounts(const UE_CONTEXT_INFO& data) {
        for (const auto& [transmissionTime, status] : data.PACKET_DELIVERY_STATUS) {
            if (status == PACKET_SUCCESS) {
                ++numSuccessfulDeliveries;
            } else if (status == PACKET_FAILURE) {
                ++numFailedDeliveries;
            }
        }
    }

private:
    std::vector<UE_CONTEXT_INFO> m_data;
};

// Demonstrative example showing how the function might be used in a real-world scenario
int main() {
    DynamicList list;

    // Insert elements at the end of the list
    list.push_back({1, 2, {std::make_pair(0, PACKET_SUCCESS), std::make_pair(1, PACKET_FAILURE)} });
    list.push_back({3, 4, {std::make_pair(2, PACKET_SUCCESS), std::make_pair(3, PACKET_FAILURE)}});

    // Insert an element at a specified position (middle of the list)
    auto it = std::next(list.begin(), list.size() / 2);
    *it = UE_CONTEXT_INFO{5, 6, {std::make_pair(4, PACKET_SUCCESS), std::make_pair(5, PACKET_FAILURE)}};

    // Erase an element at a specified position (head of the list)
    auto headIt = list.begin();
    list.erase(headIt);

    // Handle edge cases such as empty list and out-of-bounds access
    if (!list.empty()) {
        for (auto& info : list) {
            std::cout << "UE_ID: " << info.UE_ID << ", CELL_ID: " << info.CELL_ID << '\n';
            for (const auto& [transmissionTime, status] : info.PACKET_DELIVERY_STATUS) {
                std::cout << "\tPacket Delivery Status: Transmission Time = " << transmissionTime << ", Status = " << status << '\n';
            }
        }
    } else {
        std::cout << "The list is empty.\n";
    }

    // Performance considerations under stress conditions (inserting and deleting elements frequently)
    auto start = std::chrono::high_resolution_clock::now();
    const int numIterations = 100000;
    for (int i = 0; i < numIterations; ++i) {
        list.push_back({i * 2, i * 3, {i, PACKET_SUCCESS}});
        if (i % 100 == 0) {
            list.erase(std::random_access_iterator_tag(), std::next(list.begin(), std::rand() % list.size()));
        }
    }
    auto end = std::chrono::high_resolution_clock::now();
    std::cout << "Execution time: " << std::chrono::duration<double>(end - start).count() << " seconds.\n";
}
