typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct _rnti_pool {
    size_t size;
    size_t used;
    RNTI* pool;
    pthread_mutex_t mutex;
} RNTI_POOL;

RNTI_POOL* create_rnti_pool(size_t size) {
    RNTI_POOL* pool = malloc(sizeof(RNTI_POOL));
    if (!pool) return NULL;
    pool->size = size;
    pool->used = 0;
    pool->pool = calloc(size, sizeof(RNTI));
    if (!pool->pool) {
        free(pool);
        return NULL;
    }
    pthread_mutex_init(&pool->mutex, NULL);
    return pool;
}

RNTI get_available_rnti(RNTI_POOL* pool) {
    pthread_mutex_lock(&pool->mutex);
    for (size_t i = 0; i < pool->size; ++i) {
        if (!pool->pool[i].used) {
            pool->pool[i].used = true;
            RNTI rnti = pool->pool[i];
            pthread_mutex_unlock(&pool->mutex);
            return rnti;
        }
    }
    // If all RNTIs are in use, find an unused one from the pool of candidates.
    for (size_t i = 0; i < pool->size; ++i) {
        if (!pool->pool[i].used && !pool->pool[i].rnti.used) {
            pool->pool[i].used = true;
            RNTI rnti = pool->pool[i];
            pthread_mutex_unlock(&pool->mutex);
            return rnti;
        }
    }
    // If no available RNTIs are found, return a newly generated one.
    RNTI new_rnti = generate_new_rnti();
    pthread_mutex_unlock(&pool->mutex);
    return new_rnti;
}

void free_rnti_pool(RNTI_POOL* pool) {
    if (!pool) return;
    for (size_t i = 0; i < pool->size; ++i) {
        if (pool->pool[i].used) pool->pool[i].used = false;
    }
    free(pool->pool);
    pthread_mutex_destroy(&pool->mutex);
    free(pool);
}

void* generate_new_rnti() {
    // Implement your RNTI generation logic here.
    static size_t next_id = 1;
    return (RNTI){ .id = next_id++, .used = true };
}

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu(RNTI_POOL* rnti_pool) {
    RNTI rnti = get_available_rnti(rnti_pool);
    NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) return NULL;
    pdu->rx_ue_information_tag = generate_ue_information_tag();
    pdu->rnti = rnti;
    pdu->crc_indication_rel8_tag.crcflag = rand() % 2;
    return pdu;
}

void free_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!pdu) return;
    free(pdu);
}
