#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct UE_CONTEXT_INFO {
    uint32_t UE_ID;
    uint32_t CELL_ID;
    uint32_t num_successful_deliveries;
    uint32_t num_failed_deliveries;
    PACKET_DELIVERY_STATUS* packet_statuses;
} UE_CONTEXT_INFO;

typedef struct LIST_NODE {
    UE_CONTEXT_INFO* data;
    struct LIST_NODE* next;
    pthread_mutex_t mutex;
} LIST_NODE;

void init_list(LIST_NODE** list) {
    *list = malloc(sizeof(LIST_NODE));
    (*list)->data = NULL;
    (*list)->next = NULL;
    pthread_mutex_init(&(*list)->mutex, NULL);
}

void insert_head(LIST_NODE** list, UE_CONTEXT_INFO* data) {
    LIST_NODE* new_node = malloc(sizeof(LIST_NODE));
    new_node->data = data;
    new_node->next = *list;
    pthread_mutex_init(&new_node->mutex, NULL);

    pthread_mutex_lock(&(*list)->mutex);
    if (*list != NULL) {
        (*list)->next->mutex = (pthread_mutex_t){0}; // Disable lock on the next node to allow concurrent access
    }
    pthread_mutex_lock(&new_node->mutex);

    new_node->next = *list;
    *list = new_node;

    pthread_mutex_unlock(&new_node->mutex);
    if (*list != NULL && (*list)->next != NULL) {
        pthread_mutex_lock((*list)->next->mutex);
        pthread_mutex_unlock(&(*list)->mutex);
    }
}

void insert_tail(LIST_NODE** list, UE_CONTEXT_INFO* data) {
    LIST_NODE* current = *list;
    LIST_NODE* new_node = malloc(sizeof(LIST_NODE));
    new_node->data = data;
    new_node->next = NULL;
    pthread_mutex_init(&new_node->mutex, NULL);

    pthread_mutex_lock(&current->mutex);
    while (current->next != NULL) {
        current = current->next;
    }
    current->next = new_node;
    pthread_mutex_unlock(&current->mutex);
}

void insert_middle(LIST_NODE** list, size_t index, UE_CONTEXT_INFO* data) {
    LIST_NODE* current = *list;
    size_t i = 0;
    LIST_NODE* new_node = malloc(sizeof(LIST_NODE));
    new_node->data = data;
    new_node->next = NULL;
    pthread_mutex_init(&new_node->mutex, NULL);

    pthread_mutex_lock(&current->mutex);
    while (i < index && current->next != NULL) {
        current = current->next;
        i++;
    }

    if (current->next == NULL) { // Insert at the end
        insert_tail(list, data);
        return;
    }

    new_node->next = current->next;
    current->next = new_node;
    pthread_mutex_unlock(&current->mutex);
}

void delete_head(LIST_NODE** list) {
    LIST_NODE* to_delete = *list;
    *list = (*list)->next;
    free(to_delete);
}

void delete_tail(LIST_NODE** list) {
    LIST_NODE* current = *list;
    while (current->next != NULL && current->next->next != NULL) {
        current = current->next;
    }
    free(current->next);
    current->next = NULL;
}

void delete_middle(LIST_NODE** list, size_t index) {
    LIST_NODE* current = *list;
    size_t i = 0;
    while (i < index && current != NULL) {
        current = current->next;
        i++;
    }

    if (current == NULL || current->next == NULL) return; // Element not found

    LIST_NODE* to_delete = current->next;
    current->next = to_delete->next;
    free(to_delete);
}

void increment_delivery_counts(UE_CONTEXT_INFO* context, enum PACKET_STATUS status) {
    switch (status) {
        case SUCCESS: context->num_successful_deliveries++; break;
        case FAILURE: context->num_failed_deliveries++; break;
    }
}

// Function to handle real-world scenario, e.g., processing a batch of packets and updating the list accordingly
void process_packets(LIST_NODE* list, NFAPI_CRC_INDICATION_PDU_T* packet_batch, size_t num_packets) {
    LIST_NODE* current = list;
    for (size_t i = 0; i < num_packets; ++i) {
        UE_CONTEXT_INFO* context = current->data;

        // Extract RNTI, CRC_INDICATION_REL8_TAG, and check if CRC is valid
        uint32_t rnti = packet_batch[i].RX_UE_INFORMATION_TAG.rnti;
        bool crc_valid = packet_batch[i].CRC_INDICATION_REL8_TAG.crc_flag;

        // Update delivery counts if the RNTI is found in the list and CRC is valid
        if (context != NULL && rnti == context->UE_ID && crc_valid) {
            increment_delivery_counts(context, packet_batch[i].RX_UE_INFORMATION_TAG.packet_status);
        }

        // Move to the next node in the list
        current = current->next;
    }
}
```

This code provides a dynamic list implementation that can efficiently handle up to 10,000 elements with thread-safe insertion and deletion operations. The `process_packets()` function demonstrates how the list can be utilized in a real-world scenario where packets are processed and their delivery counts are updated accordingly.']

