    time_t timestamp;       // Timestamp
    std::vector<std::unique_ptr<ChannelStatus>> channelStatuses;   // Channel statuses vector with smart pointers
    void* packetBuffer;     // Packet buffer pointer (can be a generic pointer)
};

class FrameList {
public:
    FrameList(gsl_rng *rng, size_t capacity) : head_{nullptr}, tail_{nullptr}, capacity_(capacity), rng_(rng) {}

    ~FrameList() {
        clear();
    }

    void push_back(std::unique_ptr<FrameMetadata> frame) {
        if (head_ == nullptr) {
            head_ = tail_ = frame.release();
        } else {
            tail_->next_ = frame.release();
            tail_ = tail_->next_;
        }

        if (size() >= capacity_) {
            pop_front();
        }
    }

    FrameMetadata* front() const {
        return head_;
    }

    size_t size() const {
        size_t count = 0;
        FrameMetadata* current = head_;
        while (current != nullptr) {
            ++count;
            current = current->next_;
        }
        return count;
    }

    void clear() {
        FrameMetadata *current, *next;
        while (head_ != nullptr) {
            current = head_;
            next = head_->next_;
            delete current->channelStatuses; // Delete vector inside FrameMetadata
            delete current;                   // Delete FrameMetadata structure
            head_ = next;
        }
        tail_ = nullptr;
    }

private:
    FrameMetadata* pop_front() {
        if (head_ == nullptr) {
            return nullptr;
        }

        auto result = head_;
        head_ = head_->next_;
        if (head_ == nullptr) {
            tail_ = nullptr;
        }
        return result;
    }

    FrameMetadata* head_, *tail_;     // Head and tail pointers for the linked list
    size_t capacity_;                  // List capacity
    gsl_rng *rng_;                     // Random number generator pointer for generating random data
};
```

In this implementation, we use `std::unique_ptr<FrameMetadata>` and a vector of smart pointers inside the FrameMetadata structure to minimize memory leaks. The linked list can handle up to 10,000 frames with dynamically allocated structures. The size() function provides an efficient way to check the current number of frames in the list.

