    uint16_t RNTI;
    NFAPI_CRC_INDICATION_REL8_TAG CRC_INDICATION;
} NFAPI_CRC_INDICATION_PDU;

typedef struct _doubly_linked_list {
    NFAPI_CRC_INDICATION_PDU *data;
    struct _doubly_linked_list *prev, *next;
} doubly_linked_list;

doubly_linked_list* create_node(void) {
    doubly_linked_list *new_node = malloc(sizeof(doubly_linked_list));
    if (!new_node) {
        perror("malloc failed");
        return NULL;
    }

    new_node->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
    if (!new_node->data) {
        perror("malloc failed");
        free(new_node);
        return NULL;
    }

    memset(new_node->data, 0, sizeof(NFAPI_CRC_INDICATION_PDU));
    new_node->prev = new_node->next = NULL;
    return new_node;
}

void insert_node(doubly_linked_list **head, doubly_linked_list *new_node) {
    if (*head == NULL) {
        *head = new_node;
        return;
    }

    new_node->next = *head;
    (*head)->prev = new_node;
    *head = new_node;
}

doubly_linked_list* init_doubly_linked_list(size_t N) {
    doubly_linked_list *head = NULL, *new_node;
    for (size_t i = 0; i < N && head != MAX_LIST_SIZE; ++i) {
        new_node = create_node();
        if (!new_node) break;

        new_node->data->CRC_INDICATION.CRCFLAG = rand() % 2;
        insert_node(&head, new_node);
    }

    return head;
}

void log_memory_usage(const char *message) {
    static unsigned long long total_allocated = 0;
    static size_t counter = 0;
    unsigned long long current_allocated = malloc_usable();
    total_allocated += current_allocated - total_allocated / (++counter);

    printf("%s: Allocated memory: %llu bytes\n", message, total_allocated);
}

void cleanup(doubly_linked_list *head) {
    doubly_linked_list *current = head;
    while (head != NULL) {
        current = head;
        head = head->next;
        free(current->data);
        free(current);
    }
}
```

