    struct list_node *next;
};

static struct list_node* head = NULL;
static size_t capacity = 0;
static size_t count = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static size_t max_capacity = 80 * (size_t)sysconf(_SC_PHYS_PAGES) / 100;

// Thread-safe enqueue operation
void list_enqueue(LTE_PHY_RX_FRAME_INFO_T frame_info) {
    struct list_node* new_node = malloc(sizeof(struct list_node));
    if (!new_node) return;

    new_node->frame_info = frame_info;
    new_node->next = NULL;

    pthread_mutex_lock(&mutex);
    if (count + 1 > max_capacity || capacity < count + 1) {
        if (capacity > 0) {
            size_t i;
            struct list_node *temp = head;
            for (i = 0; i < capacity - 1; ++i, temp = temp->next)
                free(temp);
            free(head);
            head = NULL;
            capacity -= count;
        }
    }
    if (count + 1 > max_capacity || capacity == 0) {
        if (count > 0) --count;
        free(new_node);
        pthread_mutex_unlock(&mutex);
        return;
    }
    new_node->next = head;
    head = new_node;
    ++count;
    pthread_mutex_unlock(&mutex);
}

// Thread-safe dequeue operation
LTE_PHY_RX_FRAME_INFO_T list_dequeue() {
    LTE_PHY_RX_FRAME_INFO_T frame_info = (head) ? head->frame_info : {};
    struct list_node *temp = head;
    pthread_mutex_lock(&mutex);
    if (head) head = head->next;
    if (head) free(temp);
    else --count;
    pthread_mutex_unlock(&mutex);
    return frame_info;
}

// Clears the list without freeing memory, facilitating reuse.
void list_clear() {
    pthread_mutex_lock(&mutex);
    head = NULL;
    count = 0;
    pthread_mutex_unlock(&mutex);
}
