```cpp
#include <vector>
#include <unordered_map>
#include <list>
#include < boost/circular_buffer > // Boost library for circular buffer
#include <mutex>
#include <chrono>
#include <system_error>
#include <stdexcept>
#include <memory>

class LTEUEContext {
public:
    LTEUEContext(uint64_t id) : m_id(id), m_lastInteraction(std::chrono::steady_clock::now()) {}

    uint64_t getID() const { return m_id; }
    std::list<RRCState> getStates() const { return m_states; }
    auto getLastInteraction() const { return m_lastInteraction; }

    void addState(const RRCState& state) { m_states.push_back(state); }
    void setLastInteraction() { m_lastInteraction = std::chrono::steady_clock::now(); }

private:
    uint64_t m_id;
    boost::circular_buffer<std::chrono::steady_clock::time_point> m_lastInteraction; // Configurable buffer size for inactivity tracking
    std::list<RRCState> m_states;
};

class LTEContextManager {
public:
    void addContext(const LTEUEContext& context) {
        std::unique_lock<std::mutex> lock(m_mutex);
        m_contexts[context.getID()] = context;
        // Periodically purge inactive contexts based on a configurable threshold.
        purgeInactive();
    }

    void updateContextState(uint64_t id, const RRCState& state) {
        std::unique_lock<std::mutex> lock(m_mutex);
        auto it = m_contexts.find(id);
        if (it != m_contexts.end()) {
            it->second.addState(state);
            it->second.setLastInteraction();
        }
    }

    void removeContext(uint64_t id) {
        std::unique_lock<std::mutex> lock(m_mutex);
        auto it = m_contexts.find(id);
        if (it != m_contexts.end()) {
            it->second.clearStates(); // Clear states before erasing the context to prevent memory leaks
            m_contexts.erase(it);
        }
    }

private:
    std::mutex m_mutex;
    std::unordered_map<uint64_t, LTEUEContext> m_contexts;
    std::chrono::steady_clock::time_point m_purgeThreshold; // Configurable threshold for inactivity duration

    void purgeInactive() {
        std::unique_lock<std::mutex> lock(m_mutex);
        auto it = m_contexts.begin();
        while (it != m_contexts.end()) {
            if ((it->second.getLastInteraction() + std::chrono::duration_cast<std::chrono::steady_clock::duration>(m_purgeThreshold - std::chrono::steady_clock::now())) < it->second.getLastInteraction()) {
                it = m_contexts.erase(it);
            } else {
                ++it;
            }
        }
    }
};
```

