    }

    void addEvent(const NetworkEvent& event) {
        pushBackSafe(event);
    }

    std::size_t getNumEvents() const {
        return m_events.size();
    }

    bool resizeIfNeeded() {
        if (m_eventsSizeAtomic.load() >= m_maxSize)
            return false;

        auto newCapacity = static_cast<std::size_t>(m_eventsSizeAtomic.load()) * 2;
        if (!resize(newCapacity))
            return false;

        m_eventsSizeAtomic += newCapacity - m_events.size();
        return true;
    }

private:
    void pushBackSafe(const NetworkEvent& event) {
        auto size = m_events.size();
        if (resizeIfNeeded()) {
            m_events[size] = event;
        }
