    bool resize(std::size_t newCapacity) {
        try {
            m_events.reserve(newCapacity);
            m_events.resize(newCapacity);
            return true;
        } catch (...) {
            return false;
        }
    }

    void reset() {
        m_events.clear();
        m_eventsSizeAtomic = 0;
    }

private:
    std::vector<NetworkEvent> m_events;
    mutable std::atomic<std::size_t> m_eventsSizeAtomic;
