#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    char key[10];
    int value;
} record;

static size_t num_allocated_records = 0;
static size_t total_records = 0;
static size_t memory_pool_size = 0;
static size_t used_memory = 0;
static FILE *log_file = NULL;

void log_mem_event(const char *event, void *ptr) {
    if (log_file == NULL) return;
    time_t current_time = time(NULL);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&current_time));
    fprintf(log_file, "%s: Allocated %s (size: %zu bytes) at 0x%p\n", event, (ptr == NULL) ? "null" : typeid(*ptr).name(), sizeof(*ptr), ptr);
}

void* mem_pool_alloc(size_t size) {
    if (memory_pool_size + size > num_allocated_records) {
        log_mem_event("Expanding memory pool", NULL);
        void *new_pool = realloc(memory_pool_size ? memory_pool_size : malloc(1), num_allocated_records * 2);
        if (!new_pool) return NULL;
        log_mem_event("Allocated new memory pool", new_pool);
        memory_pool_size = num_allocated_records * 2;
    }

    void *ptr = memory_pool_size ? (void *)((char *)memory_pool_size + used_memory) : NULL;
    used_memory += size;
    log_mem_event("Allocated from memory pool", ptr);
    return ptr;
}

void mem_pool_dealloc(void *ptr, size_t size) {
    if (!ptr || !memory_pool_size) return;
    used_memory -= size;
    log_mem_event("Deallocated to memory pool", ptr);
}

record* init_data_structures(size_t num_offsets, record **records) {
    if (!num_offsets || !records) return NULL;

    *records = mem_pool_alloc(sizeof(*records) * (num_offsets + 1));
    if (!*records) {
        fprintf(stderr, "Error: Failed to allocate memory for records.\n");
        return NULL;
    }

    (*records)[num_offsets] = NULL; // Mark the last element as sentinel

    long *offsets = (long *)mem_pool_alloc(sizeof(long) * num_offsets);
    if (!offsets) {
        fprintf(stderr, "Error: Failed to allocate memory for offsets.\n");
        free(*records);
        return NULL;
    }

    int *keys = (int *)mem_pool_alloc(sizeof(int) * num_offsets);
    if (!keys) {
        fprintf(stderr, "Error: Failed to allocate memory for keys.\n");
        free(offsets);
        free(*records);
        return NULL;
    }

    record **record_array = (*records);
    for (size_t i = 0; i < num_offsets; ++i) {
        record *record = mem_pool_alloc(sizeof(record));
        if (!record) {
            fprintf(stderr, "Error: Failed to allocate memory for records.\n");
            free(keys);
            free(offsets);
            free(*records);
            return NULL;
        }

        record->value = rand() % 1000 + 1;
        snprintf(record->key, sizeof(record->key), "%s%ld", "unique_", i); // Ensure unique substrings for char arrays

        log_mem_event("Allocated a new record", record);
        record_array[i] = record;

        offsets[i] = rand();
        keys[i] = i + 1; // Use consecutive integers as keys

        log_mem_event("Initialized an entry in offsets and keys arrays", NULL);
    }

    total_records = num_offsets;
    return *records;
}

record* find_record_by_key(int key, record **records) {
    if (!records || !(*records)) return NULL;

    for (size_t i = 0; i < total_records; ++i) {
        if ((*records)[i] && (*records)[i]->key[5] == key + '0')
            return (*records)[i];
    }

    log_mem_event("No matching record found for the provided key", NULL);
    return NULL;
}

void close_memory(record **records) {
    if (!(*records)) return;

    record *current = *records;
    for (size_t i = 0; i < total_records; ++i, current++) {
        mem_pool_dealloc(current, sizeof(record));
    }
    mem_pool_dealloc(*records, sizeof(record) * (total_records + 1));

    long *offsets = (long *)mem_pool_alloc(sizeof(long) * total_records);
    int *keys = (int *)mem_pool_alloc(sizeof(int) * total_records);
    if (!offsets || !keys) {
        fprintf(stderr, "Error: Failed to allocate memory for temporary offsets and keys arrays.\n");
        free(*records);
        return;
    }

    current = *records;
    for (size_t i = 0; i < total_records; ++i, current++) {
        offsets[i] = current->offset;
        keys[i] = current->key[5] - '0';
    }

    mem_pool_dealloc(offsets, sizeof(long) * total_records);
    mem_pool_dealloc(keys, sizeof(int) * total_records);

    *records = NULL;
}

void open_log_file(const char *filename) {
    FILE *log = fopen(filename, "w");
    if (!log) {
        fprintf(stderr, "Error: Failed to open log file.\n");
    } else {
        log_mem_event("Opened log file", log);
    }
}

void close_log_file(FILE *log) {
    if (log) {
        log_mem_event("Closed log file", log);
        fclose(log);
    }
}

int main() {
    open_log_file("memory_log.txt");

    record *records = init_data_structures(5, &records);
    if (!records) return 1;

    // Use the data structures here...

    close_memory(&records);
    close_log_file(stdout);
    return 0;
}

