#include <limits.h>
#include <math.h>

typedef struct {
    double d;
    short s;
    char c;
} data_point;

void populate_data(data_point* dp, size_t len, double start, double end, double step) {
    for (size_t i = 0; i < len; ++i) {
        dp[i].d = start + i * step;
        dp[i].s = (short)(start + i * step) % SHRT_MAX;
        dp[i].c = (char)((start + i * step) % CHAR_MAX);
    }
}

void allocate_and_initialize(size_t* double_arr, size_t* short_arr, size_t* char_arr, data_point** data_points, size_t len) {
    if (!len) return;

    *double_arr = (size_t)(1.5 * len); // Reserve 50% extra memory for efficient resizing later
    *double_arr = malloc(*double_arr * sizeof(**double_arr));
    if (*double_arr == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for double array\n");
        exit(EXIT_FAILURE);
    }

    *short_arr = (size_t)(1.5 * len); // Reserve 50% extra memory for efficient resizing later
    *short_arr = malloc(*short_arr * sizeof(**short_arr));
    if (*short_arr == NULL) {
        free(*double_arr);
        fprintf(stderr, "Error: failed to allocate memory for short array\n");
        exit(EXIT_FAILURE);
    }

    *char_arr = (size_t)(1.5 * len); // Reserve 50% extra memory for efficient resizing later
    *char_arr = malloc(*char_arr * sizeof(**char_arr));
    if (*char_arr == NULL) {
        free(*double_arr);
        free(*short_arr);
        fprintf(stderr, "Error: failed to allocate memory for char array\n");
        exit(EXIT_FAILURE);
    }

    *data_points = malloc(len * sizeof(**data_points));
    if (*data_points == NULL) {
        free(*double_arr);
        free(*short_arr);
        free(*char_arr);
        fprintf(stderr, "Error: failed to allocate memory for data point array\n");
        exit(EXIT_FAILURE);
    }

    populate_data(*data_points, len, 0.0, 100.0, 1.0);
}
