#include <string.h>

typedef struct Record {
    int key;
    char buffer[51]; // 50 chars + null terminator
} Record;

#define MAX_RECORDS 1000
#define BYTE_PER_RECORD (sizeof(long) + sizeof(int) + MAX_RECORDS * sizeof(Record.buffer))
#define TOTAL_BYTES 10000

long* offsets;
int* keys;
Record* records;
size_t num_records = 0;

void init() {
    if (num_records > 0) return;

    // Calculate the number of records to allocate based on memory constraints.
    size_t total_records = TOTAL_BYTES / BYTE_PER_RECORD;
    if (total_records < 1) {
        fprintf(stderr, "Insufficient memory for requested operation.\n");
        exit(EXIT_FAILURE);
    }

    offsets = malloc(sizeof(long) * total_records);
    keys = malloc(sizeof(int) * total_records);
    records = malloc(sizeof(Record) * total_records);
    num_records = total_records;
}

void update_record(size_t index, int key, const char* new_value) {
    if (index >= num_records || key < 0) {
        fprintf(stderr, "Invalid index or key for record update.\n");
        return;
    }

    // Ensure buffer safety and copy new input to avoid potential overflows.
    size_t len = strlen(new_value);
    if (len > 50) {
        fprintf(stderr, "String too long for record update.\n");
        return;
    }
    strcpy(records[index].buffer, new_value);

    records[index].key = key;
}

void deinit() {
    free(offsets);
    free(keys);
    free(records);
    num_records = 0;
}
