    newNode->data = pdu;
    if (!list->head) list->head = newNode;
    else {
        Node* current = list->head;
        while (current->next != NULL) current = current->next;
        current->next = newNode;
    }
    list->count++;

    pthread_mutex_unlock(&list->mutex);
}

