// Custom memory pool
typedef struct MemPool {
    void* start;
    size_t size;
    size_t allocated;
} MemPool;

MemPool* create_mempool(size_t size) {
    MemPool* pool = (MemPool*)malloc(sizeof(MemPool));
    pool->start = malloc(size);
    pool->size = size;
    pool->allocated = 0;
    return pool;
}

void* mempool_alloc(MemPool* pool) {
    if (pool->allocated + sizeof(struct node) <= pool->size) {
        void* ptr = (char*)pool->start + pool->allocated;
        pool->allocated += sizeof(struct node);
        return ptr;
    }
    return NULL;
}

void mempool_free(MemPool* pool, void* ptr) {
    if (ptr && pool->allocated > 0) {
        pool->allocated -= sizeof(struct node);
    }
}

pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
