    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&list_mutex);
    if (!head) {
        head = tail = new_node;
    } else {
        tail->next = new_node;
        tail = new_node;
    }
    pthread_mutex_unlock(&list_mutex);
}

