} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_ENTRIES 1000

void init_list(NFAPI_CRC_INDICATION_PDU_T** head) {
    *head = NULL;
}

bool add_to_list(NFAPI_CRC_INDICATION_PDU_T** head, NFAPI_CRC_INDICATION_PDU_T* node) {
    if ((*head) == NULL) {
        (*head) = node;
        return true;
    }
    if (MAX_ENTRIES <= (int)(*head - *head->prev))
        return false; // max entries reached

    NFAPI_CRC_INDICATION_PDU_T* tail = *head;
    while(tail->next)
        tail = tail->next;

    node->prev = tail;
    node->next = tail->next;
    if (node->next)
        node->next->prev = node;
    else
        (*head)->next = node;
    tail->next = node;

    return true;
}

void free_list(NFAPI_CRC_INDICATION_PDU_T** head) {
    NFAPI_CRC_INDICATION_PDU_T* curr = *head;
    while (curr != NULL) {
        *head = (*head)->next;
        free(curr);
        curr = *head;
    }
