#include <pthread.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>
#include <sys/mman.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} node_t;

static node_t* head = NULL;
static pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
static bool logging_enabled = false;
static unsigned int max_list_size = 1000;
static time_t prune_threshold = 60; // seconds

void list_init() {
    if (logging_enabled) {
        printf("List initialized\n");
    }
}

void list_deinit() {
    node_t* current = head;
    while (current != NULL) {
        node_t* temp = current;
        current = current->next;
        free(temp);
    }
    head = NULL;

    if (logging_enabled) {
        printf("List deinitialized\n");
    }
}

void list_add(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    node_t* new_node = mmap(NULL, sizeof(node_t), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (new_node == MAP_FAILED) {
        perror("Memory allocation failed");
        return;
    }

    new_node->data = *pdu;
    new_node->next = NULL;

    pthread_mutex_lock(&list_lock);
    node_t* current = head;

    if (!current) {
        head = new_node;
    } else {
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    pthread_mutex_unlock(&list_lock);

    if (logging_enabled) {
        printf("Added PDU to list\n");
    }
}

void list_prune() {
    pthread_mutex_lock(&list_lock);
    node_t* current = head;
    node_t* temp;

    while (current != NULL) {
        time_t current_time = time(NULL);
        if ((current_time - current->data.timestamp) > prune_threshold) {
            temp = current;
            current = current->next;
            pthread_mutex_unlock(&list_lock);
            free(temp);
            if (logging_enabled) {
                printf("Pruned old entry from list\n");
            }
        } else {
            break;
        }
    }

    if (head == NULL) {
        pthread_mutex_unlock(&list_lock);
    } else {
        current = head;
        while (current->next != NULL) {
            if ((current_time - current->next->data.timestamp) > prune_threshold) {
                temp = current->next;
                current->next = current->next->next;
                pthread_mutex_unlock(&list_lock);
                free(temp);
                if (logging_enabled) {
                    printf("Pruned old entry from list\n");
                }
            } else {
                break;
            }
        }
    }

    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&list_lock);
}

size_t list_get_active_entries() {
    size_t count = 0;
    pthread_mutex_lock(&list_lock);
    node_t* current = head;
    while (current != NULL) {
        count++;
        current = current->next;
    }
    pthread_mutex_unlock(&list_lock);
    return count;
}

bool list_is_full() {
    size_t active_entries = list_get_active_entries();
    return active_entries >= max_list_size;
}
```

