#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct CustomObject {
    double value;
    char *str;
} CustomObject;

typedef struct Node {
    CustomObject obj;
    struct Node *next;
} Node;

typedef struct DynamicList {
    Node **nodes;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    size_t max_size;
} DynamicList;

DynamicList* createDynamicList(size_t max_size) {
    DynamicList *list = (DynamicList *) malloc(sizeof(DynamicList));
    list->capacity = 4;
    list->size = 0;
    list->max_size = max_size;
    list->nodes = (Node **) calloc(list->capacity, sizeof(Node *));
    pthread_mutex_init(&(list->mutex), NULL);
    return list;
}

void resize(DynamicList* list) {
    if ((list->size + 2) > list->capacity) {
        list->capacity *= 2;
        Node **newNodes = (Node **) realloc(list->nodes, list->capacity * sizeof(Node *));
        if (!newNodes) {
            fprintf(stderr, "Memory allocation failed!\n");
            exit(-1);
        }
        list->nodes = newNodes;
    }
}

void insert(DynamicList* list, CustomObject obj) {
    pthread_mutex_lock(&(list->mutex));
    resize(list);
    list->nodes[list->size] = (Node *) malloc(sizeof(Node));
    if (!list->nodes[list->size]) {
        fprintf(stderr, "Memory allocation failed!\n");
        pthread_mutex_unlock(&(list->mutex));
        exit(-1);
    }
    list->nodes[list->size]->obj = obj;
    list->nodes[list->size]->next = NULL;
    list->size++;
    pthread_mutex_unlock(&(list->mutex));
}

void remove(DynamicList* list, size_t index) {
    if (index >= list->size || index < 0) {
        fprintf(stderr, "Invalid index!\n");
        return;
    }

    pthread_mutex_lock(&(list->mutex));
    Node *nodeToFree = list->nodes[index];
    list->nodes[index] = nodeToFree->next;
    free(nodeToFree);
    list->size--;
    pthread_mutex_unlock(&(list->mutex));
}

CustomObject* iterate(DynamicList* list, size_t index) {
    if (index >= list->size || index < 0) {
        fprintf(stderr, "Invalid index!\n");
        return NULL;
    }

    pthread_mutex_lock(&(list->mutex));
    CustomObject *obj = &(list->nodes[index]->obj);
    pthread_mutex_unlock(&(list->mutex));
    return obj;
}
```

