#include <atomic>
#include <mutex>

constexpr size_t DEFAULT_INITIAL_CAPACITY = 4;
constexpr float GROWTH_FACTOR = 2.0f;

template<bool HEAP_ALLOCATION>
class DataStructure {
private:
    using Node = std::pair<const std::string, double>;
    using Nodes = typename (HEAP_ALLOCATION ? std::vector : std::array<Node, DEFAULT_INITIAL_CAPACITY>);
    mutable std::mutex mtx;
    size_t capacity;
    size_t currentSize;
    Nodes nodes;
public:
    DataStructure(bool heapAllocation = true) : capacity(DEFAULT_INITIAL_CAPACITY), currentSize(0), nodes(Nodes(DEFAULT_INITIAL_CAPACITY, Node("", 0.0))) {
        if constexpr (HEAP_ALLOCATION) {
            nodes.resize(DEFAULT_INITIAL_CAPACITY);
        }
    }

    DataStructure(size_t initialCapacity, bool heapAllocation = true) : capacity(initialCapacity), currentSize(0), nodes(Nodes(initialCapacity, Node("", 0.0))) {
        if constexpr (HEAP_ALLOCATION) {
            nodes.resize(initialCapacity);
        }
    }

    DataStructure(const DataStructure& other) = delete;
    DataStructure& operator=(const DataStructure& other) = delete;

    ~DataStructure() {}

    void push_back(const std::string& key, double value) {
        std::unique_lock<std::mutex> lock(mtx);
        if (currentSize >= capacity) {
            resize();
        }
        nodes[currentSize] = Node(key, value);
        ++currentSize;
    }

    size_t getCurrentNodeCount() const {
        std::unique_lock<std::mutex> lock(mtx);
        return currentSize;
    }

    double* find(const std::string& key) {
        std::unique_lock<std::mutex> lock(mtx);
        auto it = std::find_if(nodes.cbegin(), nodes.cend(), [&key](const Node& node) { return node.first == key; });
        if (it != nodes.cend()) {
            return &it->second;
        }
        return nullptr;
    }

private:
    void resize() {
        std::unique_lock<std::mutex> lock(mtx);
        capacity *= GROWTH_FACTOR;
        if constexpr (HEAP_ALLOCATION) {
            nodes.resize(capacity);
        } else {
            Nodes tmp(capacity, Node("", 0.0));
            std::copy(nodes.begin(), nodes.end(), tmp.begin());
            nodes = tmp;
        }
    }
};

// Unit tests go here...
