#include <pthread.h>
#include <sys/mman.h> // For slab allocation (if desired)

#define MAX_LIST_SIZE 1024
#define LOG_THRESHOLD 100000
typedef struct LTE_PHY_RX_FRAME_INFO_T {
    uint32_t serial_id;
    PHICH_INFO phich_info;
    DL_SRS config;
} LTE_PHY_RX_FRAME_INFO;

typedef struct NODE {
    LTE_PHY_RX_FRAME_INFO data;
    struct NODE* prev;
    struct NODE* next;
} NODE;

struct slab {
    void *pool;
    size_t pool_size;
    size_t allocated_count;
};

void* node_slab_alloc(struct slab *s) {
    return s->pool + (s->allocated_count++ * sizeof(NODE));
}

void node_slab_free(struct slab *s, void *ptr) {
    ((NODE*)ptr)->next = NULL;
    ((NODE*)ptr)->prev = NULL;
    s->allocated_count--;
}

NODE* create_node() {
    NODE* new_node = malloc(sizeof(NODE));
    if (!new_node) return NULL;
    new_node->data.serial_id = 0;
    new_node->data.phich_info = (PHICH_INFO){ .r = 0, .q = 0 };
    new_node->data.config = (DL_SRS){ .N_cp = 0 };
    new_node->prev = NULL;
    new_node->next = NULL;
    return new_node;
}

void destroy_node(NODE* node) {
    if (!node) return;
    free(node);
}

void init_list(LTE_PHY_RX_FRAME_INFO_T** list, size_t max_size) {
    *list = malloc(max_size * sizeof(LTE_PHY_RX_FRAME_INFO));
    if (!*list) return;

    struct slab slab = { .pool = calloc(1, MAX_LIST_SIZE * sizeof(NODE)),
                         .pool_size = MAX_LIST_SIZE * sizeof(NODE),
                         .allocated_count = 0 };

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    struct NODE* head = NULL, *tail = NULL;

    // Performance monitoring system (replace with your chosen logging mechanism)
    size_t memory_usage = 0;
    double cpu_load = 0.0;

