        realtime_analytics_process_data(analytics_context, &frame_info->serial_id, &frame_info->phich_info, &frame_info->config);
    }

    void insert_node(NODE* node) {
        pthread_mutex_lock(&lock);
        if (head == NULL && tail == NULL) {
            head = node;
            tail = node;
        } else {
            tail->next = node;
            node->prev = tail;
            tail = node;
        }
        pthread_mutex_unlock(&lock);
    }

    void remove_node(NODE* node) {
        pthread_mutex_lock(&lock);
        if (head == tail) { // Only one element in the list
            free(head);
            head = tail = NULL;
        } else if (node == head) { // Node is the first element
            head = head->next;
            node->next->prev = NULL;
        } else if (node == tail) { // Node is the last element
            tail = tail->prev;
            node->prev->next = NULL;
        } else { // Node is in the middle of the list
            node->prev->next = node->next;
            node->next->prev = node->prev;
        }
        pthread_mutex_unlock(&lock);
    }

    NODE* get_node() {
        pthread_mutex_lock(&lock);
        if (head == NULL) {
            pthread_mutex_unlock(&lock);
            return NULL;
        }
        NODE* temp = head;
        head = head->next;
        temp->next = NULL;
        pthread_mutex_unlock(&lock);
        return temp;
    }

    void add_to_list(LTE_PHY_RX_FRAME_INFO_T* frame_info) {
        NODE* new_node = create_node();
        if (!new_node) return;
        new_node->data = *frame_info;
        insert_node(new_node);
    }

    void free_list() {
        pthread_mutex_lock(&lock);
        NODE* temp;
        while (head != NULL) {
            temp = head;
            head = head->next;
            destroy_node(temp);
        }
        free(slab.pool);
        pthread_mutex_destroy(&lock);
    }
}
