public:
    virtual ~MoSTState() = default;

    virtual std::unique_ptr<NRUEContext[]> loadUEContextState(const std::string& fileName) const = 0;
};

template <typename Archive>
void serialize(Archive& ar, NRUEContext& context, const unsigned int version) {
    ar & BOOST_SERIALIZATION_NVP(context.rnti)
        & BOOST_SERIALIZATION_NVP(context.nrUEInfoTag)
        & BOOST_SERIALIZATION_NVP(context.srsMeasurementIndicator)
        & BOOST_SERIALIZATION_NVP(context.srsMeasurements);
}

class XMLMoSTState : public MoSTState {
public:
    std::unique_ptr<NRUEContext[]> loadUEContextState(const std::string& fileName) const override {
        std::ifstream ifs(fileName);
        if (!ifs.is_open()) {
            throw std::runtime_error("Failed to open file");
        }

        boost::archive::xml_iarchive ia(ifs);
        unsigned int version;
        ia >> BOOST_SERIALIZATION_NVP(version);

        if (version != 1) {
            throw std::runtime_error("Incompatible file version");
        }

        unsigned int numContexts;
        ia >> BOOST_SERIALIZATION_NVP(numContexts);

        auto contexts = std::make_unique<NRUEContext[]>(numContexts);
        ia.for_each_with<NRUEContext>(contexts.get(), &serialize<boost::archive::xml_iarchive>);

        return contexts;
    }
};

class TextMoSTState : public MoSTState {
public:
    std::unique_ptr<NRUEContext[]> loadUEContextState(const std::string& fileName) const override {
        std::ifstream ifs(fileName);
        if (!ifs.is_open()) {
            throw std::runtime_error("Failed to open file");
        }

        boost::archive::text_iarchive ia(ifs);
        ia >> BOOST_SERIALIZATION_NVP(version);

        unsigned int numContexts;
        ia >> BOOST_SERIALIZATION_NVP(numContexts);

        auto contexts = std::make_unique<NRUEContext[]>(numContexts);
        ia.for_each_with<NRUEContext>(contexts.get(), &serialize<boost::archive::text_iarchive>);

        return contexts;
    }
};

class MoSTStateManager {
public:
    static std::unique_ptr<MoSTState> createMostState(const std::string& format) {
        if (format == "xml") {
            return std::make_unique<XMLMoSTState>();
        } else if (format == "text") {
            return std::make_unique<TextMoSTState>();
        } else {
            throw std::runtime_error("Unsupported file format");
        }
    }
};

std::unique_ptr<NRUEContext[]> loadUEContextState(const std::string& fileName, const std::string& format) {
    auto mostState = MoSTStateManager::createMostState(format);
    return mostState->loadUEContextState(fileName);
}
