#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} Node;

static sem_t list_mutex = SEM_INITIALIZER(0);
static Node* head = NULL;
static size_t size = 0;
static const size_t MAX_SIZE = 1024;

void append(const NFAPI_CRC_INDICATION_PDU_T* data) {
    if (size == MAX_SIZE) return; // List is full, cannot append

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return; // Memory allocation failure

    new_node->data = *data;
    new_node->next = NULL;

    sem_wait(&list_mutex); // Lock the list for thread safety

    if (head == NULL) {
        head = new_node;
    } else {
        Node* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    size++;
    sem_post(&list_mutex); // Unlock the list
}

void clear() {
    sem_wait(&list_mutex); // Lock the list for thread safety

    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    size = 0;
    head = NULL;
    sem_post(&list_mutex); // Unlock the list
}
