static void listManagerInit(ListManager* manager, size_t capacity) {
    manager->capacity = capacity;
    manager->count = 0;
    manager->nodes = malloc(sizeof(ListNode*) * manager->capacity);
    memset(manager->nodes, 0, sizeof(ListNode*) * manager->capacity);
    pthread_mutex_init(&manager->lock, NULL);
}

static void listManagerDestroy(ListManager* manager) {
    for (size_t i = 0; i < manager->capacity; ++i) {
        ListNode *node = manager->nodes[i];
        if (node != NULL) {
            free(node);
        }
    }
    free(manager->nodes);
    pthread_mutex_destroy(&manager->lock);
}

ListManager* listManagerCreate() {
    ListManager* manager = malloc(sizeof(ListManager));
    if (manager == NULL) {
        return NULL;
    }
    listManagerInit(manager, 16);
    return manager;
}

bool listManagerAdd(ListManager* manager, const NFAPI_CRC_INDICATION_PDU_T* data) {
    if (manager->count == manager->capacity) {
        size_t newCapacity = manager->capacity * 2;
        ListNode **newNodes = realloc(manager->nodes, sizeof(ListNode*) * newCapacity);
        if (newNodes == NULL) {
            return false;
        }
        manager->nodes = newNodes;
        memset(newNodes + manager->capacity, 0, sizeof(ListNode*) * (newCapacity - manager->capacity));
        manager->capacity = newCapacity;
    }

    size_t index = 0;
    for (; index < manager->count; ++index) {
        ListNode* node = manager->nodes[index];
        if (node == NULL || node->data.rnti != data->rnti) {
            break;
        }
    }

    if (index == manager->count) {
        ListNode *newNode = malloc(sizeof(ListNode));
        if (newNode == NULL) {
            return false;
        }
        listNodeInit(newNode, data);
        for (size_t i = manager->count; i > index; --i) {
            manager->nodes[i] = manager->nodes[i - 1];
        }
        manager->nodes[index] = newNode;
        ++manager->count;
    } else {
        pthread_mutex_lock(&manager->nodes[index]->mutex);
        memcpy(&manager->nodes[index]->data, data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pthread_mutex_unlock(&manager->nodes[index]->mutex);
    }
    return true;
}

bool listManagerUpdate(ListManager* manager, size_t index, const NFAPI_CRC_INDICATION_PDU_T* data) {
    if (index >= manager->count) {
        return false;
    }

    pthread_mutex_lock(&manager->lock);
    if (index < manager->count && manager->nodes[index] != NULL) {
        memcpy(&manager->nodes[index]->data, data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pthread_mutex_unlock(&manager->lock);
        return true;
    }
    pthread_mutex_unlock(&manager->lock);
    return false;
}

void listManagerClear(ListManager* manager) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        ListNode *node = manager->nodes[i];
        if (node != NULL) {
            free(node);
            manager->nodes[i] = NULL;
        }
    }
    memset(manager->nodes, 0, sizeof(ListNode*) * manager->capacity);
    manager->count = 0;
    pthread_mutex_unlock(&manager->lock);
}

size_t listManagerGetCount(const ListManager* manager) {
    return manager->count;
}
