// Validate RNTIs for duplicates before adding a new element to the array
void validate_rntis(NFAPI_CRC_INDICATION_PDU_T* arr, size_t index, NFAPI_CRC_INDICATION_PDU_T newElement) {
    if (index != 0) {
        for (size_t i = 0; i < index; ++i) {
