// Thread-safe dynamic array of NFAPI_CRC_INDICATION_PDU_T structures
void* safe_array(size_t* size) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    void** arr = malloc(*size * sizeof(void*));

    for (size_t i = 0; i < *size; ++i) {
        arr[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    return &mutex;
}

// Add a new element to the array, ensuring thread safety
void add_element(void* mutex, NFAPI_CRC_INDICATION_PDU_T* arr, size_t* size, NFAPI_CRC_INDICATION_PDU_T newElement) {
    pthread_mutex_lock(mutex);

    validate_rntis(arr, *size, newElement);

    (*size)++;
    if ((*size) >= MAX_ELEMENTS) {
        printf("Maximum array size reached.\n");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T* newArr = realloc(arr, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (*size));
    if (!newArr) {
        printf("Memory allocation failed.\n");
        return;
    }
    arr = newArr;

    (*arr + (*size - 1))->rxTag = newElement.rxTag;
    (*arr + (*size - 1))->rnti = newElement.rnti;
    (*arr + (*size - 1))->crcIndication.crcFlag = rand() % 2;

    pthread_mutex_unlock(mutex);
}

// Deallocate memory for the array and its elements
void free_safe_array(void* mutex, size_t size) {
    pthread_mutex_lock(mutex);

    if (size > 0) {
        for (size_t i = 0; i < size; ++i) {
            free((*((NFAPI_CRC_INDICATION_PDU_T**)mutex + i)));
        }
        free(*mutex);
    }

    pthread_mutex_unlock(mutex);
}
