#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    time_t last_accessed;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct lru_queue {
    pthread_mutex_t mutex;
    size_t max_size;
    size_t count;
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t head;
    size_t tail;
} LRUQueue;

LRUQueue* lru_queue_init(size_t max_size) {
    LRUQueue* queue = malloc(sizeof(LRUQueue));
    if (!queue) return NULL;
    queue->max_size = max_size;
    queue->count = 0;
    queue->data = calloc(max_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!queue->data) {
        free(queue);
        return NULL;
    }
    pthread_mutex_init(&queue->mutex, NULL);
    queue->head = queue->tail = 0;
    return queue;
}

void lru_queue_push(LRUQueue* queue, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&queue->mutex);
    if (queue->count == queue->max_size) {
        size_t oldest = queue->head;
        oldest = (oldest + 1) % queue->max_size;
        memmove(queue->data + (queue->head + 1), queue->data + oldest,
                (queue->tail - oldest) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        queue->count--;
    }
    queue->data[queue->tail] = data;
    queue->tail = (queue->tail + 1) % queue->max_size;
    queue->data[queue->tail].last_accessed = time(NULL);
    pthread_mutex_unlock(&queue->mutex);
}

NFAPI_CRC_INDICATION_PDU_T lru_queue_pop(LRUQueue* queue) {
    NFAPI_CRC_INDICATION_PDU_T ret;
    pthread_mutex_lock(&queue->mutex);
    if (queue->count == 0) {
        ret.rx_ue_information_tag = {};
        ret.rnti = {};
        ret.crc_indication_rel8_tag.CRCFLAG = rand() % 2;
    } else {
        ret = queue->data[queue->head];
        memmove(queue->data, queue->data + 1,
                (queue->tail - queue->head) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        queue->count--;
        queue->head = (queue->head + 1) % queue->max_size;
    }
    pthread_mutex_unlock(&queue->mutex);
    return ret;
}
```

This code creates a thread-safe LRU queue using `pthread_mutex_t` to lock the data structure during access. The function `lru_queue_init` initializes the queue, while `lru_queue_push` and `lru_queue_pop` add and remove elements from the queue respectively.

The `last_accessed` field in the custom structure helps keep track of when each element was last accessed to implement the LRU eviction policy. The head and tail pointers, along with a simple ring buffer approach, allow for efficient insertion and removal of elements from the queue.

To minimize false sharing and maximize data locality, it's important that the structures are aligned properly on memory boundaries. This can be achieved using `__attribute__((aligned(CACHE_LINE_SIZE)))` where `CACHE_LINE_SIZE` is the size of a cache line for your target architecture.

To optimize performance under high-frequency update conditions, consider profiling and fine-tuning this implementation based on your specific system requirements. Additionally, ensure that the queue's maximum size is chosen carefully to balance memory usage and cache efficiency while maintaining consistent performance across different system configurations."]

