    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

EVP_CIPHER *processAndEncryptNfaPduList(Node** list, const char* encryptionMode) {
    EVP_CIPHER *cipher = NULL;
    if (strcmp(encryptionMode, "NULL") == 0) {
        // Null encryption mode - no actual encryption
        cipher = EVP_des_ecb();
    } else if (strcmp(encryptionMode, "ECB") == 0) {
        cipher = EVP_des_ecb();
    } else if (strcmp(encryptionMode, "EDE") == 0) {
        cipher = EVP_des_ede();
    } else if (strcmp(encryptionMode, "EDE3") == 0) {
        cipher = EVP_des_ede3();
    } else if (strcmp(encryptionMode, "CFB") == 0) {
        cipher = EVP_cipher_ CFG_cfb128(&EVP_cfb_des_ede3(), NULL);
    }

    Node* currentNode = *list;
    Node* newNode = NULL;
    Node** lastNodePtr = list; // Pointer to the previous node in the list

    pthread_mutex_t listMutex = PTHREAD_MUTEX_INITIALIZER; // Mutex for list synchronization
    sem_t keyAccessSemaphore = SEM_INITIALIZE(1); // Semaphore for key access control

    while (currentNode != NULL) {
        sem_wait(&keyAccessSemaphore); // Wait for key access to avoid race conditions
        const EVP_KEY* key = getKeyFromHSM(); // Dynamically load encryption key from HSM
        sem_post(&keyAccessSemaphore);

        if (cipher->type != EVP_CIPHER_id()) {
            // Unsupported cipher mode
            freeKey(key);
            continue;
        }

        uint8_t iv[EVP_CIPHER_block_size(cipher)];
        rand_bytes(iv, sizeof(iv));

        size_t encryptedLen = 0;
        uint8_t* encryptedData = NULL;

        EVP_CIPHER_CTX cipherCtx;
        EVP_CIPHER_init(&cipherCtx, cipher, key, iv, 1);

        if (EVP_CIPHER_CTX_ctrl(&cipherCtx, EVP_CTRL_CHAIN_MODE_SET, 0) <= 0) {
            // Error initializing encryption context
            EVP_CIPHER_free_ctx(&cipherCtx);
            free(key);
            continue;
        }

        encryptedData = malloc(currentNode->data.CRC_INDICATION.length + sizeof(iv));
        if (encryptedData == NULL) {
            // Out-of-memory error
            EVP_CIPHER_free_ctx(&cipherCtx);
            freeKey(key);
            continue;
        }

        memcpy(encryptedData, iv, sizeof(iv));

        size_t remainingLen = currentNode->data.CRC_INDICATION.length;
        while (remainingLen > 0) {
            size_t chunkSize = EVP_CIPHER_CTX_get_output_length(&cipherCtx);
            if (chunkSize > remainingLen)
                chunkSize = remainingLen;

            EVP_EncryptUpdate(&cipherCtx, encryptedData + sizeof(iv), &remainingLen, currentNode->data.CRC_INDICATION.value, chunkSize);
        }

        encryptedLen = sizeof(iv) + remainingLen;

        EVP_CIPHER_CTX_cleanup(&cipherCtx);
        freeKey(key);

        if (currentNode == *list) {
            // First node in the list
            Node* newFirstNode = malloc(sizeof(Node));
            if (newFirstNode == NULL) {
                // Out-of-memory error
                free(encryptedData);
                continue;
            }

            newFirstNode->data = currentNode->data;
            newFirstNode->next = currentNode->next;
            *list = newFirstNode;
            currentNode = newFirstNode->next;
        } else {
            // Middle or last node in the list
            lastNodePtr = &currentNode->next;
            currentNode = currentNode->next;
        }

        if (encryptedLen > 0) {
            (*lastNodePtr) = malloc(sizeof(Node));
            if ((*lastNodePtr) == NULL) {
                // Out-of-memory error
                free(encryptedData);
                continue;
            }

            memcpy((*lastNodePtr)->data.CRC_INDICATION.value, encryptedData + sizeof(iv), encryptedLen - sizeof(iv));
            (*lastNodePtr)->data.CRC_INDICATION.length = encryptedLen - sizeof(iv);
            (*lastNodePtr)->next = NULL;
            lastNodePtr = &((*lastNodePtr)->next);
        }
    }

    return cipher;
}
