#include <pthread.h>
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <time.h>
#include <atomic>

// Define the structure NFAPI_RRC_MSG_PDU_T
struct NFAPI_RRC_MSG_PDU_T {
    uint16_t RX_CSI_REPORT_TAG;
    uint16_t PCI;
    float RSRQ;
    time_t timestamp;
};

// Define a wrapper around std::atomic for compatibility with C++11 and below
#ifndef STD_ATOMIC_H
#define STD_ATOMIC_H
#include <atomic>
template<typename T> using Atomic = std::atomic<T>;
#endif

// Define the list class with dynamic resizing capabilities
class RRCList {
private:
    struct NFAPI_RRC_MSG_PDU_T* data;
    size_t capacity;
    size_t length;
    Atomic<size_t> readIndex;
    Atomic<size_t> writeIndex;
    pthread_mutex_t mutex;

public:
    RRCList(size_t initialCapacity = 1024) : data(new NFAPI_RRC_MSG_PDU_T[initialCapacity]), capacity(initialCapacity), length(0), readIndex(0), writeIndex(0), mutex(PTHREAD_MUTEX_INITIALIZER) {}

    ~RRCList() { delete[] data; }

    bool push(const struct NFAPI_RRC_MSG_PDU_T& item);

    const struct NFAPI_RRC_MSG_PDU_T* get();

    void pruneOldEntries();
};

bool RRCList::push(const struct NFAPI_RRC_MSG_PDU_T& item) {
    pthread_mutex_lock(&mutex);

    // Check if the list is full and resize if necessary
    if (length == capacity) {
        size_t newCapacity = length ? 2 * length : 1024;
        NFAPI_RRC_MSG_PDU_T* newData = new NFAPI_RRC_MSG_PDU_T[newCapacity];
        memcpy(newData, data, sizeof(NFAPI_RRC_MSG_PDU_T) * length);
        delete[] data;
        data = newData;
        capacity = newCapacity;
    }

    // Increment the write index and store the item
    writeIndex++;
    data[writeIndex % capacity] = item;

    pthread_mutex_unlock(&mutex);
    return true;
}

const struct NFAPI_RRC_MSG_PDU_T* RRCList::get() {
    pthread_mutex_lock(&mutex);

    size_t readIndexVal = readIndex.load();
    if (readIndexVal == writeIndex) {
        pthread_mutex_unlock(&mutex);
        return nullptr;
    }

    const struct NFAPI_RRC_MSG_PDU_T* item = &data[readIndexVal % capacity];
    readIndex++;

    pthread_mutex_unlock(&mutex);
    return item;
}

void RRCList::pruneOldEntries() {
    time_t currentTime = time(nullptr);
    pthread_mutex_lock(&mutex);

    for (size_t i = readIndex.load(); i < writeIndex; i = (i + 1) % capacity) {
        const struct NFAPI_RRC_MSG_PDU_T* item = &data[i];
        if (difftime(currentTime, item->timestamp) > 60) { // Adjust the threshold as needed
            memmove(&data[i], &data[(i + 1) % capacity], sizeof(NFAPI_RRC_MSG_PDU_T));
            length--;
        }
    }

    pthread_mutex_unlock(&mutex);
}
```

To handle concurrent access from multiple threads, use a `pthread_mutex_t` lock to synchronize access to the list. The `push()` method checks if the list is full and resizes it if necessary using a new data buffer. The get operation retrieves an item from the list while ensuring no item is removed concurrently.

The provided code demonstrates basic memory management, dynamic resizing, and thread synchronization to manage the list. You may further optimize this code by implementing additional mechanisms such as cache locality improvements, thread contention reduction techniques, or reducing the cost of frequent I/O operations based on your specific requirements and system constraints.']

