    manager->offsets = (long*) calloc(capacity, sizeof(long));
    manager->keys = (int*) calloc(capacity, sizeof(int));
    if (!manager->offsets || !manager->keys) return STATUS_FAILURE;
    manager->length = 0;
    return STATUS_SUCCESS;
}

