int generate_unique_key(ElementManager* manager) {
    int key;
    do {
        key = rand() % MAX_INT_VALUE;
    } while (manager->unique_keys.count(key));
    return key;
}

Status assign_keys_and_offsets(ElementManager* manager, size_t element_count) {
    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < element_count; ++i) {
        int key = generate_unique_key(manager);
        int conflict = manager->key_conflicts.count(key);
        if (!conflict) {
            manager->keys[manager->length] = key;
            manager->offsets[manager->length] = rand() % MAX_OFFSET_VALUE;
            ++manager->length;
        } else {
            manager->key_conflicts[key]++;
        }
    }

    pthread_mutex_unlock(&manager->mutex);

    // Resolve conflicts by retrying with a new key if necessary
    for (auto it = manager->key_conflicts.begin(); it != manager->key_conflicts.end(); ) {
        int key = it->first;
        int count = it->second;
        if (count > 1) {
            it->second--;
            continue;
        }
        for (size_t i = 0; i < element_count; ++i) {
            if (manager->keys[i] == key) {
                int new_key = generate_unique_key(manager);
                manager->keys[i] = new_key;
                it = manager->key_conflicts.erase(key);
                break;
            }
        }
    }

    return STATUS_SUCCESS;
}

Status update_html_elements(ElementManager* manager, size_t element_count) {
    // Implement the logic to update HTML elements based on the assigned keys and offsets
    // ...
}

Status manage_memory(ElementManager* manager) {
    if (manager->length == manager->capacity) {
        long* temp_offsets = (long*) realloc(manager->offsets, 2 * manager->capacity * sizeof(long));
        int* temp_keys = (int*) realloc(manager->keys, 2 * manager->capacity * sizeof(int));

        if (!temp_offsets || !temp_keys) return STATUS_FAILURE;

        manager->offsets = temp_offsets;
        manager->keys = temp_keys;
        manager->capacity *= 2;
    }

    return STATUS_SUCCESS;
}
