    gsl_rng_set(global_rng, seed); // Initialize the global random number generator

    std::unordered_map<uint32_t, bool> used_rx_ue_information_tags; // Track used RX_UE_INFORMATION_TAG values in the list
    std::unordered_map<uint32_t, bool> used_rntis; // Track used RNTI values in the list

    auto create_pdu = [&](gsl_rng* rng) -> NFAPI_CRC_INDICATION_PDU_UPTR {
        auto pdu = std::make_unique<NFAPI_CRC_INDICATION_PDU_T>();
        pdu->index = list.size();
        pdu->rng = rng; // Use the current random number generator for CRCFLAG

        uint32_t rx_ue_information_tag = 0;
        while (used_rx_ue_information_tags.count(rx_ue_information_tag)) {
            ++rx_ue_information_tag;
        }
        used_rx_ue_information_tags[rx_ue_information_tag] = true;
        pdu->rx_ue_information_tag = rx_ue_information_tag;

        uint32_t rnti = 0;
        while (used_rntis.count(rnti)) {
            ++rnti;
        }
        used_rntis[rnti] = true;
        pdu->rnti = rnti;

        uint32_t crcflag = gsl_rng_uniform_int(pdu->rng, 1 << CRCIFLAG_BIT_LENGTH);
        pdu->crc_indication_rel8_tag.crcflag = crcflag;

        return pdu;
    };

    auto create_and_notify = [&](gsl_rng* rng, uint32_t target_rnti) {
        auto pdu = create_pdu(rng);
        if (pdu->rnti == target_rnti) {
            crc_indication_callback(pdu->rnti, nullptr);
        }
        mutex.lock();
        list.push_back(std::move(pdu));
        mutex.unlock();
    };

    std::vector<std::thread> threads;
    for (uint32_t i = 0; i < max_concurrency; ++i) {
        threads.emplace_back([&, i]() { create_and_notify(global_rng, i); });
    }
    for (auto& thread : threads) {
        thread.join();
    }
}

int main() {
    gsl_rng *global_rng = gsl_rng_alloc(gsl_rng_mt19937); // Use the Mersenne Twister engine for fast performance and good quality random numbers

    uint32_t N = 10;
    uint64_t seed = 0;
    uint32_t max_concurrency = std::thread::hardware_concurrency(); // Use the number of hardware threads available in the system for optimal parallelism

    NFAPI_CRC_INDICATION_PDU_MUTEX mutex;
    NFAPI_CRC_INDICATION_PDU_LIST list;

    create_NFAPI_CRC_INDICATION_PDU_LIST(N, seed, max_concurrency, mutex, list, global_rng);

    gsl_rng_free(global_rng); // Free the random number generator when done

    return 0;
}
