    if (!file) {
        perror("Error opening file");
        return 1;
    }

    struct stat st;
    if (stat(path, &st) == -1) {
        perror("Error checking file size");
        fclose(file);
        return 2;
    }

    json_t *root = json_loads_file(path, 0, NULL);
    if (!root) {
        fprintf(stderr, "Error parsing JSON\n");
        fclose(file);
        return 3;
    }

    const char *schema[] = {"object", "[*]", "string", "*", "number", "*", "boolean", "*"};
    if (!json_is_valid(root, json_schemas, countof(schema), schema)) {
        fprintf(stderr, "Invalid configuration format\n");
        json_decref(root);
        fclose(file);
        return 4;
