        if (!json_is_number(value_elem)) {
            fprintf(stderr, "Invalid 'value' field\n");
            continue;
        }

        int value = json_integer_value(value_elem);
        bool status = json_boolean_value(json_object_get(item, "status"));

        key = strdup(json_string_value(json_object_get(item, "key")));

        ConfigRecord *record = malloc(sizeof(ConfigRecord));
        record->key = key;
        record->value = value;
        record->status = status;

        records_list = realloc(records_list, sizeof(ConfigRecord) * (num_records + 1));
        records_list[num_records++] = record;
    }

    json_decref(root);
    fclose(file);

    *count = num_records;
    *records = malloc(num_records * sizeof(ConfigRecord*));
    memcpy(*records, records_list, num_records * sizeof(ConfigRecord*));

    // Set integer values to a random number within a specified range
    srand(time(NULL));
    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i].value = rand() % MAX_RANGE + MIN_RANGE;
    }

    return 0;
}
