    int activityLevel;
} NetworkMetric;

typedef struct {
    NetworkMetric* metrics;
    size_t count;
} AggregatedMetrics;

void initNetworkMetric(NetworkMetric* networkMetric, int sessionID, time_t timestamp, int activityLevel) {
    networkMetric->sessionID = sessionID;
    networkMetric->timestamp = timestamp;
    networkMetric->activityLevel = activityLevel;
}

AggregatedMetrics handleAndAggregateNetworkMetrics(size_t intervalSeconds, NetworkMetric* packet) {
    static AggregatedMetrics aggregatedMetrics = {NULL, 0};
    time_t currentTime = time(NULL);
    time_t prevTime = currentTime - (intervalSeconds * SECS_PER_MIN);

    if (!aggregatedMetrics.metrics) {
        aggregatedMetrics.metrics = malloc(sizeof(NetworkMetric));
        initNetworkMetric(&aggregatedMetrics.metrics[0], packet->sessionID, packet->timestamp, packet->activityLevel);
        aggregatedMetrics.count = 1;
    } else if (packet->timestamp >= prevTime && packet->timestamp < currentTime) {
        NetworkMetric* lastEntry = &aggregatedMetrics.metrics[aggregatedMetrics.count - 1];
        if ((currentTime - lastEntry->timestamp) > (intervalSeconds * SECS_PER_MIN)) {
            aggregatedMetrics.metrics = realloc(aggregatedMetrics.metrics, (aggregatedMetrics.count + 1) * sizeof(NetworkMetric));
            initNetworkMetric(&aggregatedMetrics.metrics[aggregatedMetrics.count], packet->sessionID, packet->timestamp, packet->activityLevel);
            aggregatedMetrics.count++;
        } else {
            lastEntry->activityLevel += packet->activityLevel;
        }
    }

    return aggregatedMetrics;
}
