['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct Record {
    int value;
} Record;

struct MemoryManager {
    long *offsets;
    int *keys;
    Record *records;
    size_t capacity;
    size_t used;
    pthread_mutex_t mutex;
};

void init_memory_manager(struct MemoryManager *mm, size_t max_size) {
    mm->offsets = NULL;
    mm->keys = NULL;
    mm->records = NULL;
    mm->capacity = 0;
    mm->used = 0;
    pthread_mutex_init(&mm->mutex, NULL);
}

void reset_memory_manager(struct MemoryManager *mm) {
    if (mm->offsets != NULL) free(mm->offsets);
    if (mm->keys != NULL) free(mm->keys);
    if (mm->records != NULL) free(mm->records);
    mm->capacity = 0;
    mm->used = 0;
}

int find_free_key(struct MemoryManager *mm) {
    int key, i;

    for (i = 0; i < mm->capacity; ++i) {
        if (mm->keys[i] == 0) {
            key = i;
            break;
        }
    }

    if (i == mm->capacity) { // No free keys, resize array
        size_t new_capacity = mm->capacity * 2;
        int *tmp_keys = realloc(mm->keys, new_capacity * sizeof(int));
        long *tmp_offsets = realloc(mm->offsets, new_capacity * sizeof(long));
        Record *tmp_records = realloc(mm->records, new_capacity * sizeof(Record));

        if (!tmp_keys || !tmp_offsets || !tmp_records) { // Failed to resize, return error
            perror("Reallocation failed");
            reset_memory_manager(mm);
            return -1;
        }

        mm->keys = tmp_keys;
        mm->offsets = tmp_offsets;
        mm->records = tmp_records;
        mm->capacity = new_capacity;
    }

    return key;
}

int allocate_record(struct MemoryManager *mm, int key) {
    if (key >= mm->capacity) return -1; // Key out of bounds

    pthread_mutex_lock(&mm->mutex);

    while (mm->keys[key] != 0 && mm->offsets[key] + 1 < mm->keys[key]) {
        // Key already in use with a smaller offset, retry
        int new_key = find_free_key(mm);
        if (new_key == -1) { // Failed to find free key, return error
            perror("Failed to allocate record");
            pthread_mutex_unlock(&mm->mutex);
            return -1;
        }

        mm->keys[key] = 0;
        mm->keys[new_key] = mm->keys[key];
        mm->offsets[new_key] = mm->offsets[key] + 1;
        mm->records[new_key].value = rand() % (mm->keys[key] - mm->offsets[new_key] + 1) + mm->offsets[new_key];
        key = new_key;
    }

    if (mm->keys[key] == 0) { // Key not in use, allocate record
        mm->keys[key] = mm->records[key].value = rand() % (KEY_MAX - OFFSET_MIN + 1) + OFFSET_MIN;
    }

    pthread_mutex_unlock(&mm->mutex);
    return key;
}

void free_record(struct MemoryManager *mm, int key) {
    pthread_mutex_lock(&mm->mutex);

    if (mm->keys[key] != 0 && mm->offsets[key] > 0) { // Valid key and non-zero offset
        mm->keys[key] = 0;
        --mm->used;
    }

    pthread_mutex_unlock(&mm->mutex);
}

void check_consistency(struct MemoryManager *mm) {
    long total_offsets = 0, total_keys = 0;
    int i;

    pthread_mutex_lock(&mm->mutex);

    for (i = 0; i < mm->capacity; ++i) {
        if (mm->keys[i] > 0) {
            total_offsets += mm->offsets[i];
            total_keys += mm->keys[i];
        }
    }

    pthread_mutex_unlock(&mm->mutex);

    if (total_offsets != total_keys) { // Inconsistency detected, free memory and exit
        fprintf(stderr, "Inconsistent data: Total offsets (%ld) do not match total keys (%d)\n", total_offsets, total_keys);
        reset_memory_manager(mm);
        exit(EXIT_FAILURE);
    }
}
```

This code defines a `struct MemoryManager` that manages dynamically allocated memory for three arrays: offsets (long), keys (int), and records (struct Record). The function `init_memory_manager` initializes the manager with no allocated memory, while `reset_memory_manager` frees all previously allocated memory.

The `find_free_key` function finds a free key in the keys array or resizes it if necessary. The `allocate_record` function allocates a new record with a unique key and ensures that the sum of offsets does not exceed the corresponding key value. If a duplicate key is found, it retries until a unique key is found.

The `free_record` function deallocates a specific record given its key, and the `check_consistency` function checks if the sum of all offset values matches the sum of their corresponding keys. If not, it prints an error message, frees all memory, and exits gracefully.

The code uses pthread mutexes to ensure thread safety when accessing the MemoryManager's data structures concurrently. Additionally, the MemoryManager is designed to handle varying data sizes and input ranges across different environments.']

