        lock_guard<mutex> lock(mtx);
        if (concurrentFramesBuffer.size() < 100) {
            frames.push_back(frame);
            concurrentFramesBuffer.push_back(1);
        }
    }

    std::shared_ptr<LTE_PHY_RX_FRAME_INFO_T> getFrame() {
        lock_guard<mutex> lock(mtx);
        if (!concurrentFramesBuffer.empty()) {
            int index = concurrentFramesBuffer.front();
            concurrentFramesBuffer.pop_front();
            return frames.begin()->get();
            frames.erase(frames.begin());
            concurrentFramesBuffer.push_back(0);
