[' Here is an implementation of the required C function using dynamically-allocated memory, error handling, and robust data management:

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>

typedef struct {
    uint16_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    uint32_t RX_UE_INFORMATION_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct listNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct listNode *next;
} listNode_t;

listNode_t* create_node(const NFAPI_CRC_INDICATION_PDU_T* data) {
    listNode_t* node = (listNode_t*) malloc(sizeof(listNode_t));
    if (!node) return NULL;
    node->data = *data;
    node->next = NULL;
    return node;
}

bool is_valid_RNTI(uint16_t RNTI) {
    return (RNTI >= 1 && RNTI <= 65535);
}

listNode_t** create_list() {
    listNode_t **head = (listNode_t**) malloc(sizeof(listNode_t*));
    if (!head) return NULL;
    *head = NULL;
    return head;
}

bool add_to_list(listNode_t** head, const NFAPI_CRC_INDICATION_PDU_T* data) {
    listNode_t* current = *head;
    listNode_t* new_node = create_node(data);
    if (!new_node || !is_valid_RNTI(data->RNTI)) return false;

    if (*head == NULL) {
        *head = new_node;
        return true;
    }

    while (current != NULL && current->next != NULL) {
        if (current->next->data.RNTI == data->RNTI) return false;
        current = current->next;
    }

    if (current == NULL || current->next == NULL) {
        current->next = new_node;
        return true;
    }
    return false;
}

void free_list(listNode_t** head) {
