// Implement a class loader mechanism using a map for dynamic inclusion of classes and functions
class ClassLoader {
public:
    template<typename T>
    T* loadClass(const std::string& className) {
        auto it = loadedClasses.find(className);
        if (it != loadedClasses.end())
            return static_cast<T*>(it->second.get()); // Smart pointer cast and dereference

        // Assume the class has a static factory method to create an instance
        T* instance = new T();
        std::unique_ptr<T> classInstance(instance);
        loadedClasses[className] = std::move(classInstance);
        return instance;
    }

private:
    std::map<std::string, std::unique_ptr<void>> loadedClasses;
};

// Function to create and populate the CRC indication array with valid data
void createCRCIndicationArray(ClassLoader& loader, int size, NFAPI_CRC_INDICATION_PDU_T*& crcArray) {
    // Allocate memory for offsets and keys arrays
    std::vector<long> offsets(size);
    std::vector<int> keys(size);

    // Allocate memory for the record array
    std::vector<record> records(size);

    // Generate random values for CRC indications, offsets, and keys arrays
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, size-1);

    std::mutex mtx;
    std::map<unsigned int, bool> rntiMap; // Store duplicates RNTI values for validation

    std::vector<std::future<void>> tasks; // To store concurrent tasks

    auto createTask = [&](int start, int end) {
        for (int i = start; i < end; ++i) {
            crcArray[i].tag = loader.loadClass<RX_UE_INFORMATION_TAG>("RX_UE_INFORMATION_TAG")->generateTag();
            crcArray[i].rnti = dis(gen); // Generate a random RNTI within the specified range
            if (rntiMap.find(crcArray[i].rnti) != rntiMap.end()) {
                std::cerr << "Error: Duplicate RNTI value found!" << std::endl;
                exit(1);
            }
            rntiMap[crcArray[i].rnti] = true;
            crcArray[i].crc_indication_tag = loader.loadClass<CRC_INDICATION_REL8_TAG>("CRC_INDICATION_REL8_TAG")->generateTag();
            crcArray[i].crcflag = dis(gen) % 2 == 0; // Set CRC flag randomly

            offsets[i] = i;
            keys[i] = dis(gen);
        }
    };

    for (int chunkSize = size / 10 + 1; chunkSize > 0; chunkSize -= 8) {
        tasks.push_back(std::async(std::launch::async, createTask, 0, std::min(chunkSize, size)));
    }

    for (auto& task : tasks)
        task.wait();
}

// Implement a configuration class to read and validate settings from an INI-like file
class Config {
public:
    Config(const std::string& filename) {
        loadConfig(filename);
    }

private:
    void loadConfig(const std::string& filename) {
        std::ifstream infile(filename);
        if (!infile.is_open()) {
            std::cerr << "Error: Could not open configuration file!" << std::endl;
            exit(1);
        }

        std::string line;
        while (std::getline(infile, line)) {
            std::istringstream ss(line);
            if (ss >> key) { // Extract the key from the current line
                if (!ss) continue;

                if (key == "size") {
                    if (!(ss >> value)) {
                        std::cerr << "Error: Invalid configuration - missing or malformed setting!" << std::endl;
                        exit(1);
                    }
                    size_ = static_cast<int>(std::stoi(value));
                }
            }
        }

        if (size_ <= 0) {
            std::cerr << "Error: Invalid configuration - 'size' setting must be greater than zero!" << std::endl;
            exit(1);
        }
    }

    std::string key, value, filename;
    int size_;
};

