// Add an element to the dynamic array, enforcing RNTI uniqueness and checking for array overflow
bool add_element(DynamicArray* da, const NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&da->mutex);

    size_t i;
    for (i = 0; i < da->length; ++i) {
        if (da->elements[i].RNTI == element->RNTI) {
            pthread_mutex_unlock(&da->mutex);
            return false;
