    if (da->length >= da->capacity) {
        pthread_mutex_unlock(&da->mutex);
        return false;
    }

    memcpy(&(da->elements[da->length]), element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    ++(da->length);

    pthread_mutex_unlock(&da->mutex);
    return true;
}

// Retrieve an element from the dynamic array by its index
