    if (index >= da->length) {
        return NULL;
    }

    pthread_mutex_lock(&da->mutex);
    const NFAPI_CRC_INDICATION_PDU_T* element = &(da->elements[index]);
    pthread_mutex_unlock(&da->mutex);
    return element;
}

