            memcpy(&(da->elements[i]), new_element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pthread_mutex_unlock(&da->mutex);
            return true;
        }
    }

    pthread_mutex_unlock(&da->mutex);
    return false;
