enum LoadResult {
    LOAD_SUCCESS,
    FILE_NOT_FOUND,
    INVALID_FILE_FORMAT,
    MEMORY_ALLOCATION_FAILURE,
    STRING_LENGTH_EXCEEDED,
    INTEGER_OUT_OF_BOUNDS,
