enum LoadResult loadBundle(const char *filePath, size_t *numRecords, enum LoadResult *statusCode) {
    FILE *file = fopen(filePath, "r");
    if (!file) return FILE_NOT_FOUND;

    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    rewind(file);

    Record *records = malloc((size_t)(fileSize / sizeof(Record)) * (sizeof(Record) + MAX_RECORD_SIZE)); // assuming each record fits in a MAX_RECORD_SIZE buffer and padding is handled by the union data field
    if (!records) return MEMORY_ALLOCATION_FAILURE;

    size_t numParsedRecords = 0;
    Record currentRecord;
    while (fread(&currentRecord, sizeof(Record), 1, file)) {
