                currentRecord.data.integer = rand() % MAX_INTEGER_RANGE;
                break;
            case STRING_RECORD:
                if (currentRecord.string_length_limit > MAX_STRING_LIMIT) return STRING_LENGTH_EXCEEDED;
                currentRecord.data.string = malloc(currentRecord.string_length_limit + 1); // plus one for the null terminator
                if (!currentRecord.data.string) return MEMORY_ALLOCATION_FAILURE;
                fread(currentRecord.data.string, currentRecord.string_length_limit, 1, file);
                // Perform further validation on string data here if needed
                break;
            case BOOLEAN_RECORD:
                currentRecord.data.boolean = rand() % 2 == 0;
                break;
            default:
                return INVALID_FILE_FORMAT;
        }

        // Set the record in the array and increment the number of parsed records
        records[numParsedRecords++] = currentRecord;
    }

    fclose(file);
    *numRecords = numParsedRecords;
    *statusCode = LOAD_SUCCESS;
    return LOAD_SUCCESS;
}
```

