#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <resolv.h>
#include <pthread.h>

#define MAX_RNTIS 1024
#define CRCFLAG_LIMIT 32
#define TIMEOUT 5 // seconds
#define CONFIG_FILE "config.txt"

struct RNTI {
    uint32_t rnti;
    struct sockaddr_in addr;
};

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU;

void *resolve_ip(const char *hostname, struct hostname_data *data) {
    struct addrinfo hints, *res;
    int rc;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;       // IPv4 only
    hints.ai_socktype = SOCK_STREAM; // TCP stream sockets

    rc = getaddrinfo(hostname, NULL, &hints, &res);
    if (rc != 0) {
        perror("getaddrinfo");
        return NULL;
    }

    struct hostname_data *new_data = realloc(data, sizeof(struct hostname_data) + res->ai_addrlen);
    memcpy(new_data->hostname, hostname, strlen(hostname)+1);
    new_data->addr_size = res->ai_addrlen;
    memcpy(&new_data->addr, res->ai_addr, res->ai_addrlen);
    freeaddrinfo(res);

    return new_data;
}

int construct_pdu_list(NFAPI_CRC_INDICATION_PDU **pdus, int N, const char *config_file) {
    FILE *fp = fopen(config_file, "r");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    struct hostname_data hosts[MAX_RNTIS];
    int num_hosts = 0;

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *token = strtok(line, " ");
        if (!token) continue; // empty line or comment

        struct hostname_data *host = &hosts[num_hosts++];
        host->addr.sin_len = 0;
        host->addr_size = 0;
        strncpy(host->hostname, token, sizeof(host->hostname));

        if (num_hosts >= MAX_RNTIS) break;
        token = strtok(NULL, " ");
        if (!token) break;

        host = &hosts[num_hosts++];
        if (num_hosts >= MAX_RNTIS) break;
        host->addr.sin_port = htons(53); // DNS default port

        // resolve IP addresses concurrently to save time
        pthread_t threads[num_hosts];
        for (int i = 0; i < num_hosts; ++i) {
            pthread_create(&threads[i], NULL, &resolve_ip, hosts[i].hostname, &hosts[i]);
        }
        for (int i = 0; i < num_hosts; ++i) {
            pthread_join(threads[i], NULL);
        }
    }
    fclose(fp);

    if (num_hosts == 0) return -1; // no valid hosts found in the config file

    NFAPI_CRC_INDICATION_PDU *pdus_arr = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU));
    if (!pdus_arr) return -1;

    // generate random CRCFLAGS within the limit
    for (int i = 0; i < N && i < num_hosts; ++i) {
        pdus_arr[i].tag.present = RX_UE_INFORMATION_TAG_PRSNT_RX_UE_ID;
        pdus_arr[i].tag.u.ueId.ueIdentityType = UE_IDENTITY_TYPE_RNTI;
        pdus_arr[i].tag.u.ueId.rnti = hosts[i].rnti;

        pdus_arr[i].crc_indication.present = CRC_INDICATION_REL8_TAG_PRSNT_CRCFLAG;
        pdus_arr[i].crc_indication.u.crcFlag = rand() % (CRCFLAG_LIMIT + 1);

        memcpy(&pdus_arr[i].rnti.addr, &hosts[i].addr, hosts[i].addr_size);
    }

    *pdus = pdus_arr;
    return num_hosts;
}
```

