#include <iostream>
#include <unordered_map>
#include <vector>
#include <thread>
#include <mutex>
#include <atomic>
#include <memory>
#include <functional>

class Record {
public:
    int id;
    int value;
    Record(int id, int value) : id(id), value(value) {}
};

class ConcurrentDynamicCollection {
private:
    std::unordered_map<int, std::unique_ptr<Record>> records;
    static constexpr float LOAD_FACTOR = 0.75f;
    std::mutex mtx;
    std::atomic_uint max_memory_usage{0};
    size_t num_records{0};

public:
    void insert(const Record& record) {
        std::unique_lock<std::mutex> lock(mtx);
        auto it = records.find(record.id);
        if (it != records.end()) {
            // Handle duplicate key insertion
            return;
        }
        if ((max_memory_usage + sizeof(Record)) > max_memory_limit) {
            resize();
        }
        records[record.id] = std::make_unique<Record>(record);
        ++num_records;
    }

    bool remove(int id) {
        std::unique_lock<std::mutex> lock(mtx);
        auto it = records.find(id);
        if (it == records.end()) {
            return false;
        }
        records.erase(it);
        --num_records;
        return true;
    }

    void resize() {
        // Resize strategy goes here, such as multiplicative increment or power of 2 increase
    }

    std::vector<Record> getBatch(size_t size) {
        std::unique_lock<std::mutex> lock(mtx);
        auto begin = records.begin();
        auto end = records.end();
        std::advance(begin, num_records - size);

        std::vector<Record> batch(begin, end);
        for (auto& record : batch) {
            records.erase(record.id);
        }
        --num_records;
        return batch;
    }
};

void threadedInsert(ConcurrentDynamicCollection& collection, size_t num_records, int batch_size) {
    std::vector<Record> records;
    for (size_t i = 0; i < num_records; ++i) {
        records.push_back(Record(i, i * 10));
    }

    auto start = std::chrono::high_resolution_clock::now();
    for (size_t i = 0; i < num_records / batch_size; ++i) {
        collection.insert(records[i * batch_size]);
    }
    auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::high_resolution_clock::now() - start);
    std::cout << "Insertion time: " << duration.count() << " ms" << std::endl;
}

void threadedDelete(ConcurrentDynamicCollection& collection, size_t num_records) {
    std::vector<int> ids;
    for (size_t i = 0; i < num_records; ++i) {
        ids.push_back(i);
    }

    auto start = std::chrono::high_resolution_clock::now();
    std::for_each(ids.begin(), ids.end(), [&collection](int id) { collection.remove(id); });
    auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::high_resolution_clock::now() - start);
    std::cout << "Deletion time: " << duration.count() << " ms" << std::endl;
}

int main() {
    ConcurrentDynamicCollection collection;
    constexpr size_t max_memory_limit = 100 * 1024 * 1024; // 100MB
    threadedInsert(collection, 1000000, 1000);
    threadedDelete(collection, 500000);
    return 0;
}
```

