    long offset;
    int value;
} record;

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_RECORDS 1000
#define MAX_KEYS 1000
#define BUFFER_SIZE 256

int memory_manager(NFAPI_CRC_INDICATION_PDU_T** pdu, record* records, long* offsets, int* keys, int num_records) {
    *pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_records * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*pdu) return -1; // Memory allocation failed

    records = (record*)realloc(records, num_records * sizeof(record));
    if (!records) {
        free(*pdu);
        return -1; // Memory allocation failed
    }

    offsets = (long*)calloc(MAX_RECORDS, sizeof(long));
    if (!offsets) {
        free(*pdu);
        free(records);
        return -1; // Memory allocation failed
    }

    keys = (int*)calloc(MAX_KEYS, sizeof(int));
    if (!keys) {
        free(*pdu);
        free(records);
        free(offsets);
        return -1; // Memory allocation failed
    }

    for (int i = 0; i < num_records; ++i) {
        records[i].value = rand() % 100; // Random number within range [0, 99]
        generate_random(&records[i], sizeof(record), i); // External library for random number generation
        keys[records[i].key] = records[i].key; // Ensure uniqueness of keys
        offsets[i] = i; // Initialize offsets array
    }

    int j = 0;
    for (int i = 0; i < num_records; ++i) {
        if (!keys[i]) { // Find empty key slot
            records[offsets[j]].key = i; // Assign key to record
            keys[i] = j; // Update corresponding key in keys array
            offsets[j++] = offsets[i]; // Move record to new position
        }
    }

    for (int i = 0; i < num_records; ++i) {
        (*pdu)[offsets[i]].RX_UE_INFORMATION_TAG = rand() % 65536;
        (*pdu)[offsets[i]].RNTI = rand() % 100000 + 1;
        (*pdu)[offsets[i]].CRC_INDICATION_REL8_TAG = rand() % 256;
        (*pdu)[offsets[i]].CRCFLAG = (rand() % 2) == 0;
    }

    char hostname[BUFFER_SIZE]; // DNS resolution component
    struct hostent *he;

    gethostname(hostname, BUFFER_SIZE);
    he = gethostbyname(hostname);
    if (!he) return -1; // DNS resolution failed

    u_char ip[4]; // IP address storage
    memcpy(ip, he->h_addr, sizeof(struct in_addr));

    return 0; // Success
}
