    if (!q) return NULL;

    q->capacity = THREAD_SAFE_QUEUE_INITIAL_CAPACITY;
    q->head = q->tail = 0;
    q->data = calloc(q->capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!q->data) {
        free(q);
        return NULL;
    }

    pthread_mutex_init(&q->mutex, NULL);
    pthread_cond_init(&q->full, NULL);
    pthread_cond_init(&q->empty, NULL);

    return q;
