void enqueue(thread_safe_queue_t* q, NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&q->mutex);

    while (q->head == ((q->tail + 1) % q->capacity)) { // Queue is full
        if (pthread_wait_for_notify(&q->cond[0], &q->mutex, INT32_MAX) != 0) {
            pthread_mutex_unlock(&q->mutex);
            return; // Exit on error or interruption
        }
    }

    q->data[(q->head)] = *data;
    q->head = (q->head + 1) % q->capacity;

    if (pthread_cond_signal(&q->empty) != 0) {
        pthread_mutex_unlock(&q->mutex);
        return; // Exit on error or interruption
    }

    pthread_mutex_unlock(&q->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* dequeue(thread_safe_queue_t* q) {
    NFAPI_CRC_INDICATION_PDU_T* data = NULL;
    pthread_mutex_lock(&q->mutex);

    while (q->head == q->tail) { // Queue is empty
        if (pthread_wait_for_notify(&q->cond[1], &q->mutex, INT32_MAX) != 0) {
            pthread_mutex_unlock(&q->mutex);
            return NULL; // Exit on error or interruption
        }
    }

    data = &(q->data[(q->tail)]);
    q->tail = (q->tail + 1) % q->capacity;

    if (pthread_cond_signal(&q->full) != 0) {
        pthread_mutex_unlock(&q->mutex);
        return NULL; // Exit on error or interruption
    }

    pthread_mutex_unlock(&q->mutex);

    return data;
}
