    if (!array) return NULL;

    array->data = calloc(capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->data) {
        free(array);
        return NULL;
    }

    array->capacity = capacity;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

bool add_to_array(Array* array, const NFAPI_CRC_INDICATION_PDU_T* value) {
