#include <pthread.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} Node;

struct queue {
    Node *head;
    Node *tail;
    size_t size;
    pthread_mutex_t lock;
};

static inline void check_alignment(const void* ptr) {
    if (((size_t)ptr & 0x7) != 0) {
        fprintf(stderr, "Memory alignment issue: %p\n", ptr);
    }
}

static struct queue* create_queue() {
    struct queue *q = malloc(sizeof(*q));
    check_alignment(q);
    q->head = NULL;
    q->tail = NULL;
    q->size = 0;
    pthread_mutex_init(&q->lock, NULL);
    return q;
}

static void destroy_queue(struct queue* q) {
    while (!pthread_mutex_trylock(&q->lock)) {
        pthread_mutex_unlock(&q->lock);
        sleep(1);
    }
    Node *current = q->head;
    while (current != NULL) {
        Node *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&q->lock);
    free(q);
}

static void enqueue(struct queue* q, NFAPI_CRC_INDICATION_PDU_T data) {
    Node *node = malloc(sizeof(*node));
    check_alignment(node);
    node->data = data;
    node->next = NULL;

    while (!pthread_mutex_trylock(&q->lock)) {
        pthread_mutex_unlock(&q->lock);
        sleep(1);
    }

    if (q->head == NULL) {
        q->head = node;
        q->tail = node;
    } else {
        q->tail->next = node;
        q->tail = node;
    }
    q->size++;
    pthread_mutex_unlock(&q->lock);
}

static NFAPI_CRC_INDICATION_PDU_T dequeue(struct queue* q) {
    if (pthread_mutex_trylock(&q->lock)) {
        pthread_mutex_unlock(&q->lock);
        return (NFAPI_CRC_INDICATION_PDU_T){0, 0, 0, false};
    }

    Node *current = q->head;
    if (current == NULL) {
        pthread_mutex_unlock(&q->lock);
        return (NFAPI_CRC_INDICATION_PDU_T){0, 0, 0, false};
    }

    NFAPI_CRC_INDICATION_PDU_T data = current->data;
    q->head = current->next;
    free(current);
    q->size--;
    pthread_mutex_unlock(&q->lock);

    return data;
}

static void manage_array(struct queue* queue, size_t max_size) {
    NFAPI_CRC_INDICATION_PDU_T data;
    while (queue->size < max_size / 2 && rand() % 10 == 0) {
        data.RX_UE_INFORMATION_TAG = rand();
        data.RNTI = rand();
        data.CRC_INDICATION_REL8_TAG = rand();
        data.CRCFLAG = rand() & 1;
        enqueue(queue, data);
    }

    while ((size_t)dequeue(queue).RX_UE_INFORMATION_TAG < max_size) {}
}

static void check_array_health(struct queue* queue, time_t interval) {
    if (interval == 0) return;
    struct timespec ts = {.tv_sec = interval, .tv_nsec = 0};

    while (true) {
        nanosleep(&ts, NULL);

        Node *current = queue->head;
        while (current != NULL) {
            if (!current->data.CRCFLAG || current->data.RX_UE_INFORMATION_TAG >= max_size) {
                Node *next = current->next;
                free(current);
                current = next;
                queue->size--;
            } else {
                current = current->next;
            }
        }
    }
}
