#define UDP_PACKET_INFO_T struct _udp_packet_info UDP_PACKET_INFO
UDP_PACKET_INFO {
    in_port_t UDP_PORT;
    struct in_addr SOURCE_IP;
    struct in_addr DESTINATION_IP;
    time_t TIMESTAMP;
};

#define LIST_GROWTH_FACTOR 2

UDP_PACKET_INFO_T* dynamic_udp_packet_list_init(size_t initial_size) {
    UDP_PACKET_INFO_T *packets = malloc(initial_size * sizeof(UDP_PACKET_INFO_T));
    if (!packets) {
        perror("malloc");
        return NULL;
    }

    pthread_mutex_t *mutexes = calloc(initial_size, sizeof(pthread_mutex_t));
    if (!mutexes) {
        free(packets);
        perror("calloc");
        return NULL;
    }

    size_t capacity = initial_size;
    size_t head = 0;
    size_t tail = 0;

    pthread_mutex_init(&tail_mutex, NULL);

    UDP_PACKET_INFO_T* resizable_list = (UDP_PACKET_INFO_T*)malloc(sizeof(UDP_PACKET_INFO_T*) * capacity);
    if (!resizable_list) {
        free(packets);
        free(mutexes);
        perror("malloc");
        return NULL;
    }

    resizable_list[tail] = packets + tail;

    return new_dynamic_udp_packet_list(resizable_list, capacity, mutexes, &head, &tail, &tail_mutex);
}

UDP_PACKET_INFO_T* new_dynamic_udp_packet_list(UDP_PACKET_INFO_T** list, size_t capacity, pthread_mutex_t* mutexes, size_t* head, size_t* tail, pthread_mutex_t* tail_mutex) {
    UDP_PACKET_INFO_T* resizable_list = (UDP_PACKET_INFO_T*)malloc(sizeof(UDP_PACKET_INFO_T*) * capacity);
    if (!resizable_list) {
        free(list[*tail]);
        free(mutexes);
        perror("malloc");
        return NULL;
    }

    resizable_list[*tail] = (UDP_PACKET_INFO_T*)realloc((void*)list[*tail], capacity * sizeof(UDP_PACKET_INFO_T));
    if (!resizable_list[*tail]) {
        free(resizable_list);
        free(mutexes);
        perror("realloc");
        return NULL;
    }

    *list = resizable_list;

    pthread_mutex_init(&head_mutex, NULL);

    return list;
}

void dynamic_udp_packet_list_push(UDP_PACKET_INFO_T* list, UDP_PACKET_INFO_T packet) {
    pthread_mutex_lock(&tail_mutex);

    while ((((size_t)(*tail + 1)) % capacity) == *head) {
        // list is full, resize it
        resize_dynamic_udp_packet_list(list, (*tail + 1));
    }

    UDP_PACKET_INFO_T* next = (UDP_PACKET_INFO_T*)((size_t)list[*tail] + sizeof(UDP_PACKET_INFO_T));

    pthread_mutex_lock(&head_mutex);
    if (*head == *tail) {
        // list is empty, update head
        *head = *tail;
    }

    packet.TIMESTAMP = time(NULL);

    memcpy(next, &packet, sizeof(UDP_PACKET_INFO_T));

    pthread_mutex_lock(&mutexes[*tail]);
    (*tail)++;
    pthread_mutex_unlock(&mutexes[*tail - 1]);

    pthread_mutex_unlock(&head_mutex);
    pthread_mutex_unlock(&tail_mutex);
}

void resize_dynamic_udp_packet_list(UDP_PACKET_INFO_T** list, size_t new_capacity) {
    UDP_PACKET_INFO_T* temp_list = malloc((new_capacity + 1) * sizeof(UDP_PACKET_INFO_T));
    if (!temp_list) {
        perror("malloc");
        return;
    }

    memcpy(temp_list, list[0], (*head - *tail) * sizeof(UDP_PACKET_INFO_T));

    size_t increment = (new_capacity - capacity + 1) / LIST_GROWTH_FACTOR;
    for (size_t i = *tail; i < *head + increment; ++i) {
        memcpy((UDP_PACKET_INFO_T*)&temp_list[i], list[i % capacity], sizeof(UDP_PACKET_INFO_T));
    }

    free(list[0]);
    size_t *new_head = (size_t*)realloc(list, new_capacity * sizeof(UDP_PACKET_INFO_T*));
    if (!new_head) {
        perror("realloc");
        free(temp_list);
        return;
    }

    size_t *new_tail = (size_t*)realloc((void*)&(*tail), sizeof(size_t));
    if (!new_tail) {
        perror("realloc");
        free(temp_list);
        free(new_head);
        return;
    }

    *list = new_head;
    *tail = *new_tail + increment;

    pthread_mutex_init(&head_mutex, NULL);
    for (size_t i = *tail; i < *tail + increment; ++i) {
        pthread_mutex_init(&((*list)[i / capacity]->mutex, NULL);
    }
}
```

