            list->entries[i].timestamp == list->entries[i + 1].timestamp) {
            memmove(&list->entries[i], &list->entries[i + 1], (list->size - i - 1) * sizeof(DataEntry));
            --list->size;
            i--;
        }
    }
}

int compare(const void* a, const void* b) {
