static pthread_mutex_t cache_mutex = PTHREAD_MUTEX_INITIALIZER;
static void* cache = NULL;

int convertAndPopulateNFAPCrcIndications(const char *filename, const char *output_directory, int N, int performance_threshold_kbps, int memory_usage_mb, int enable_caching) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        LOG_ERROR("Failed to open input file.");
        return 1;
    }

    size_t data_size = 0;
    NFAPI_CRC_INDICATION_PDU_T *pdus = calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        LOG_ERROR("Failed to allocate memory for PDU structures.");
        fclose(file);
        return 1;
    }

    size_t processed = 0;
    clock_t start, end;
    double elapsed_time;

    while (processed < N && !feof(file)) {
        if (!fread(&data_size, sizeof(size_t), 1, file) || data_size > memory_usage_mb * (1024 * 1024)) {
            LOG_ERROR("Invalid or oversized data encountered.");
            break;
        }

        start = clock();
        if (!enable_caching || !(processed + data_size <= processed + sizeof(cache))) {
            if (data_size > 0) {
                void *tmp_buffer = mmap(NULL, data_size, PROT_READ, MAP_PRIVATE, fileno(file), 0);
                if (!tmp_buffer) {
                    LOG_ERROR("Mmap failed.");
                    break;
                }
                memcpy(&pdus[processed], tmp_buffer, data_size);
                munmap(tmp_buffer, data_size);
            }
        } else {
            pthread_mutex_lock(&cache_mutex);
            memcpy(&pdus[processed], cache + (processed - sizeof(cache)), data_size);
            processed += data_size;
            pthread_mutex_unlock(&cache_mutex);
        }

        end = clock();
        elapsed_time = (double)(end - start) / CLOCKS_PER_SEC * 1000.0;
        if (elapsed_time > performance_threshold_kbps * 8) { // Convert to kilobytes by multiplying with 8, since there are 8 bits in a byte
            if (enable_caching) {
                pthread_mutex_lock(&cache_mutex);
                memcpy(cache + (processed - sizeof(cache)), &pdus[processed], data_size);
                processed += data_size;
                pthread_mutex_unlock(&cache_mutex);
            }
        } else {
            processed += data_size;
        }
    }

    fclose(file);

    if (processed != N) {
        free(pdus);
        return 1;
    }

    // Invoke the third-party tool to convert the data into a PDF file
    int ret = third_party_tool(output_directory, pdus, N);

    free(pdus);
    if (cache) munmap(cache, sizeof(cache) + processed * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    return ret;
}
