```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

const int MAX_N = 10000; // Maximum size for performance reasons

int allocate_and_initialize_crc_indications(NFAPI_CRC_INDICATION_PDU_T **array, int N) {
    if (N <= 0 || N > MAX_N) return 0;

    *array = (NFAPI_CRC_INDICATION_PDU_T*) malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*array == NULL) return 0;

    int count = 0;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    for (int i = 0; i < N && count < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *element = &((*array)[count]);
        element->tag.rnti = i; // Using tag.rnti for simplicity
        element->rnti = i + 1; // Unique RNTI values start from 1
        element->crc_indication.crcflag = rand() % 2;

        pthread_mutex_lock(&mutex);
        bool unique = true;
        for (int j = 0; j < count && unique; ++j) {
            if ((*array)[j].rnti == element->rnti) {
                unique = false;
            }
        }
        pthread_mutex_unlock(&mutex);

        if (unique) {
            ++count;
        }
    }

    return count;
}
