```cpp
#include <iostream>
#include <vector>
#include <algorithm>
#include <memory>
#include <stdexcept>

struct Record {
    long offset;
    int key;
    bool active;
};

std::unique_ptr<Record[]> createRecords(size_t size, size_t keyLimit) {
    if (size <= 0 || keyLimit <= 0) {
        throw std::invalid_argument("Array size or key limit must be greater than zero.");
    }

    std::unique_ptr<Record[]> records(new Record[size]);
    auto keys = std::iota(std::begin(records->key), std::end(records->key), 1);
    std::sort(keys, keys + size);

    int usedKeys = 0;
    for (auto& rec : records) {
        if (usedKeys + rec.key <= keyLimit) {
            usedKeys += rec.key;
        } else {
            rec.key = -1; // Skipping record
        }
        rec.active = false;
    }

    for (size_t i = 0; i < size && std::find(records, records + size, -1) == records + size; ++i) {
        records[i].active = true;
    }

    return records;
}

struct DataStructures {
    std::unique_ptr<long[]> offsets;
    std::unique_ptr<int[]> keys;
    std::unique_ptr<Record[]> records;
};

DataStructures createDataStructures(size_t offsetSize, size_t keySize) {
    if (offsetSize <= 0 || keySize <= 0) {
        throw std::invalid_argument("Array sizes must be greater than zero.");
    }

    auto offsets = std::make_unique<long[]>(offsetSize);
    auto keys = std::make_unique<int[]>(keySize);

    DataStructures dataStructures;
    dataStructures.offsets = offsets;
    dataStructures.keys = keys;
    dataStructures.records = createRecords(offsetSize, keySize);

    return dataStructures;
}
