    pthread_mutex_t mutex;
    sem_t not_empty;
    LTE_PHY_RX_FRAME_INFO_T* list;
    size_t size;
    size_t capacity;
};

void init_dynamic_list(struct dynamic_list* list, size_t capacity) {
    pthread_mutex_init(&list->mutex, NULL);
    sem_init(&list->not_empty, 0, 0);
    list->list = malloc(capacity * sizeof(LTE_PHY_RX_FRAME_INFO_T));
    list->size = 0;
    list->capacity = capacity;
}

void destroy_dynamic_list(struct dynamic_list* list) {
    free(list->list);
    pthread_mutex_destroy(&list->mutex);
}

bool is_empty(const struct dynamic_list* list) {
    return sem_trywait(&list->not_empty);
}

void enqueue(struct dynamic_list* list, LTE_PHY_RX_FRAME_INFO_T item) {
    pthread_mutex_lock(&list->mutex);

    if (list->size >= list->capacity) {
        // Handle the situation when list is full. For example: resize the array, or use a different data structure that can grow dynamically.
    }

    list->list[list->size] = item;
    list->size++;

    sem_post(&list->not_empty);

    pthread_mutex_unlock(&list->mutex);
}

void dequeue(struct dynamic_list* list, LTE_PHY_RX_FRAME_INFO_T* out) {
    pthread_mutex_lock(&list->mutex);

    while (list->size == 0) {
        // If the list is empty and there's no need to block, you can use sem_trywait() for faster performance.
        if (!sem_wait(&list->not_empty)) break;
    }

    *out = list->list[0];

    memmove(list->list, list->list + 1, sizeof(LTE_PHY_RX_FRAME_INFO_T) * (list->size - 1));
    list->size--;

    pthread_mutex_unlock(&list->mutex);
}

