    pthread_mutex_lock(&list->mutex);

    if (index >= list->size) {
        // Handle the situation when the index is out of range. For example: throw an exception or return an error code.
    }

    list->list[index] = item;

    pthread_mutex_unlock(&list->mutex);
}

