#include <stdbool.h>

typedef struct {
    unsigned char* data;
    size_t length;
    // Additional fields if needed
} LTE_PHY_RX_FRAME_INFO_T;

typedef struct node {
    LTE_PHY_RX_FRAME_INFO_T frame;
    struct node* next;
    pthread_mutex_t lock;
} Node;

Node* head = NULL;
pthread_mutex_t list_lock;

void init_list() {
    pthread_mutex_init(&list_lock, NULL);
}

void push(LTE_PHY_RX_FRAME_INFO_T frame) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return;

    new_node->frame = frame;
    new_node->next = NULL;
    pthread_mutex_init(&new_node->lock, NULL);

    pthread_mutex_lock(&list_lock);
    if (head == NULL) {
        head = new_node;
    } else {
        Node* temp = head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }
    pthread_mutex_unlock(&list_lock);
}

void pop(LTE_PHY_RX_FRAME_INFO_T* frame) {
    Node* temp = head;
    if (temp == NULL) return;

    pthread_mutex_lock(&list_lock);
    *frame = temp->frame;
    Node* to_free = temp;
    head = temp->next;
    free(to_free);
    pthread_mutex_unlock(&list_lock);
}

void update(size_t index, LTE_PHY_RX_FRAME_INFO_T updated_frame) {
    Node* temp = head;
    size_t i = 0;

    pthread_mutex_lock(&list_lock);
    while (temp != NULL && i < index) {
        temp = temp->next;
        i++;
    }

    if (temp == NULL) {
        pthread_mutex_unlock(&list_lock);
        return; // Error: Index out of range
    }

    pthread_mutex_lock(&temp->lock);
    temp->frame = updated_frame;
    pthread_mutex_unlock(&temp->lock);
    pthread_mutex_unlock(&list_lock);
}

void log(const char* message) {
    // Implement logging mechanism here, for example:
    FILE *file = fopen("log.txt", "a");
    if (file != NULL) {
        fprintf(file, "%s\n", message);
        fclose(file);
    }
}
