    int* keys = malloc(*key_size * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Error allocating memory for key array\n");
        free(offsets);
        return -3;
    }

    Record** records_arr = malloc(*key_size * sizeof(Record*));
    if (!records_arr) {
        fprintf(stderr, "Error allocating memory for record pointers array\n");
        free(offsets);
        free(keys);
        return -4;
    }

    for (size_t i = 0; i < *key_size; ++i) {
        if (i >= *key_size) {
            fprintf(stderr, "Error: Index out of bounds in key array\n");
            free(offsets);
            free(keys);
            free(records_arr);
            return -5;
        }

        Record* record = malloc(sizeof(Record));
        if (!record) {
            fprintf(stderr, "Error allocating memory for record\n");
            for (size_t j = 0; j < i; ++j) {
                free(records_arr[j]); // Free previously allocated records
            }
            free(offsets);
            free(keys);
            free(records_arr);
            return -6;
        }

        record->offset = &offsets[i];
        record->key = keys[i];
        records_arr[i] = record;
    }

    *records = records_arr;
    return 0; // Success
}
