struct MemoryPool {
    std::vector<char> buffer;
    size_t blockSize;

    void* allocate(size_t n) {
        if (n > buffer.size())
            throw std::runtime_error("Memory pool exhausted");
        void* ptr = buffer.data() + buffer.size() - n;
        buffer.resize(buffer.size() + blockSize - n);
        return ptr;
    }

    void deallocate(void* ptr) {
