    private static final TimeUnit TIMEOUT_UNIT = TimeUnit.MILLISECONDS;

    public double calculateAverageHumidity(WeatherData weatherData, Duration timePeriod) throws InterruptedException {
        if (weatherData == null || timePeriod == null) {
            throw new IllegalArgumentException("Invalid input parameters");
        }

        long startTime = System.currentTimeMillis();
        long endTime = startTime + TimeUnit.MILLISECONDS.toMillis(timePeriod.toMillis());
        int count = 0;
        double totalHumidity = 0.0;

        while (System.currentTimeMillis() < endTime) {
            weatherData.fetchWeatherData();
            if (weatherData.getTemperatures().isEmpty() || weatherData.getHumidities().isEmpty()) {
                continue;
            }

            totalHumidity += weatherData.getHumidities().stream().mapToDouble(d -> d).sum();
            count++;
        }

        if (count == 0) {
            throw new IllegalStateException("No valid data retrieved within the specified time period");
        }

        return totalHumidity / count;
    }
}
