            break;
        } else {
            ++retries;
            usleep(RETRY_SLEEP_TIME); // Adjust this value according to your needs.
        }
    }

    if (retries >= NUM_RETRIES) {
        fprintf(stderr, "Error: Failed to generate PDF after %d retries.\n", NUM_RETRIES);
        munmap(allocatedBuffers, totalAllocatedBytes);
        free(allocatedBuffersCount);
        fclose(config);
        fclose(log);
        return 1;
    }

    munmap(allocatedBuffers, totalAllocatedBytes);
    free(allocatedBuffersCount);
