void init_list(struct list_head* list, int size) {
    if (size <= 0 || size > 10000) {
        printf("Invalid list size.\n");
        return;
    }

    pthread_mutex_init(&list->mutex, NULL);
    list->head = malloc(sizeof(struct list_node) * size);
    for (int i = 0; i < size; ++i) {
        list->head[i].next = &list->head[(i + 1) % size];
        list->data.RX_UE_INFORMATION_TAG = i;
        list->data.RNTI = i + size;
        list->data.CRC_INDICATION_REL8_TAG = (rand() & 0xFFFF);
        list->data.CRCFLAG = rand() % 2 == 0 ? true : false;
    }
    list->head[size - 1].next = list->head;
    list->size = size;
}

