    while (current->next != list->head && current->next->data.RX_UE_INFORMATION_TAG < data->RX_UE_INFORMATION_TAG) {
        current = current->next;
    }

    struct list_node* new_node = malloc(sizeof(struct list_node));
    new_node->data = *data;
    new_node->next = current->next;
