        sscanf(line, "%d %d %d %s", &data[i].RX_UE_INFORMATION_TAG, &data[i].RNTI, &data[i].CRC_INDICATION_REL8_TAG, data[i].CRCFLAG ? line + strlen(data[i].CRCFLAG) : NULL);
    }
}

NFAPI_CRC_INDICATION_PDU_T* create_structures() {
    NFAPI_CRC_INDICATION_PDU_T* structures = (NFAPI_CRC_INDICATION_PDU_T*)calloc(NUM_STRUCTURES, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!structures) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
