#define GROW_FACTOR 2

typedef struct {
    uint16_t rnti;
    // Other fields for NFAPI_CRC_INDICATION_PDU_T structure
} element_t;

struct array_data {
    element_t **array;
    size_t capacity, size;
    pthread_mutex_t mutex;
};

void init_array_data(struct array_data *data) {
    data->capacity = 0;
    data->size = 0;
    data->array = NULL;
    pthread_mutex_init(&data->mutex, NULL);
}

void free_array_data(struct array_data *data) {
    if (!data->array) return;
    for (size_t i = 0; i < data->capacity; ++i) {
        free(data->array[i]);
    }
    free(data->array);
    pthread_mutex_destroy(&data->mutex);
}

void grow_array(struct array_data *data) {
    if (data->capacity == 0) data->capacity = GROW_FACTOR;
    element_t **new_array = realloc(data->array, data->capacity * sizeof(element_t*));
    if (!new_array) {
        fprintf(stderr, "Failed to allocate memory for new array\n");
        free_array_data(data);
        exit(EXIT_FAILURE);
    }
    data->array = new_array;
    data->capacity *= GROW_FACTOR;
}

bool add_element(struct array_data *data, const element_t *elem) {
    pthread_mutex_lock(&data->mutex);
    for (size_t i = 0; i < data->size; ++i) {
        if (data->array[i]->rnti == elem->rnti) {
            printf("Duplicate RNTI entry: %u\n", elem->rnti);
            pthread_mutex_unlock(&data->mutex);
            return false;
        }
    }

    if (data->size >= data->capacity) grow_array(data);

    data->array[data->size] = malloc(sizeof(element_t));
    if (!data->array[data->size]) {
        fprintf(stderr, "Failed to allocate memory for new element\n");
        pthread_mutex_unlock(&data->mutex);
        return false;
    }
    *data->array[data->size] = *elem;
    data->size++;

    pthread_mutex_unlock(&data->mutex);
    return true;
}

element_t* find_element(const struct array_data *data, uint16_t rnti) {
    pthread_mutex_lock(&data->mutex);
    for (size_t i = 0; i < data->size; ++i) {
        if (data->array[i]->rnti == rnti) {
            pthread_mutex_unlock(&data->mutex);
            return data->array[i];
        }
    }
    pthread_mutex_unlock(&data->mutex);
    return NULL;
}

bool remove_element(struct array_data *data, uint16_t rnti) {
    element_t* found = find_element(data, rnti);
    if (!found) return false;

    pthread_mutex_lock(&data->mutex);
    for (size_t i = data->size - 1; i > 0; --i) {
        data->array[i] = data->array[i - 1];
    }
    free(data->array[data->size - 1]);
    data->size--;
    pthread_mutex_unlock(&data->mutex);

    return true;
}

void update_crc_rate(struct array_data *data, float crc_error_rate) {
    // Implement logic for updating CRC error rate based on external data source
    // For simplicity, only updating a single flag per element
    pthread_mutex_lock(&data->mutex);
    for (size_t i = 0; i < data->size; ++i) {
        if (data->array[i]->crc_error) continue;
        data->array[i]->crc_error = rand() < crc_error_rate * RAND_MAX;
    }
    pthread_mutex_unlock(&data->mutex);
}
