#include <unistd.h>

#define MAX_INITIAL_ELEMENTS 1000
#define MAX_ELEMENTS 10000
#define BUFFER_SIZE 4096
#define EXPONENTIAL_BACKOFF_FACTOR 2

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T data;
    pthread_mutex_t mutex;
} PoolElement;

struct MemoryPool {
    PoolElement *elements;
    size_t used;
    size_t capacity;
};

void init_memory_pool(struct MemoryPool *pool) {
    pool->elements = mmap(NULL, MAX_INITIAL_ELEMENTS * sizeof(PoolElement), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);
    if (pool->elements == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }

    pool->used = 0;
    pool->capacity = MAX_INITIAL_ELEMENTS;
    for (size_t i = 0; i < pool->capacity; ++i) {
        pthread_mutex_init(&pool->elements[i].mutex, NULL);
        pool->elements[i].data.RNTI = i + 1;
        pool->elements[i].data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }
}

struct MemoryPool mem_pool;
pthread_mutex_t mem_pool_mutex = PTHREAD_MUTEX_INITIALIZER;

void *get_element(struct MemoryPool *pool) {
    pthread_mutex_lock(&mem_pool_mutex);
    if (pool->used < pool->capacity) {
        void *elem = &pool->elements[pool->used];
        ++pool->used;
        pthread_mutex_unlock(&mem_pool_mutex);
        return elem;
    } else {
        pthread_mutex_unlock(&mem_pool_mutex);

        PoolElement *new_elems = realloc(pool->elements, (pool->capacity + (MAX_ELEMENTS - pool->capacity) / 2) * sizeof(PoolElement));
        if (!new_elems) {
            perror("realloc failed");
            exit(EXIT_FAILURE);
        }

        pool->elements = new_elems;
        pool->capacity += (MAX_ELEMENTS - pool->capacity) / 2;

        for (size_t i = pool->used; i < pool->capacity; ++i) {
            pthread_mutex_init(&pool->elements[i].mutex, NULL);
            pool->elements[i].data.RNTI = i + 1;
            pool->elements[i].data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
        }

        pthread_mutex_lock(&mem_pool_mutex);
        void *elem = &pool->elements[pool->used - 1];
        ++pool->used;
        pthread_mutex_unlock(&mem_pool_mutex);

        return elem;
    }
}

void put_element(struct MemoryPool *pool, void *elem) {
    pthread_mutex_lock(&((PoolElement*)elem)->mutex);
    memset(((PoolElement*)elem), 0, sizeof(PoolElement));
    pthread_mutex_unlock(&mem_pool_mutex);
}

