using UserAccountMap = boost::container::flat_map<std::string, UserAccount>;

class NIC {
private:
    boost::lockfree::spsc_queue<std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>> dataQueue;
    UserAccountMap userAccounts;
    std::ofstream logFile;

public:
    NIC() : logFile(boost::filesystem::path("nic_log.txt")) {}

    void enqueue(std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T> data) {
        dataQueue.push(data);
        logDataOperation("Enqueued", data->rnti);
    }

    bool dequeueAndProcess(NFAPI_CRC_INDICATION_PDU_T& data) {
        if (auto ptr = dataQueue.pop(); ptr) {
            data = *ptr;
            logDataOperation("Dequeued", data.rnti);
            return true;
        }
        return false;
    }

    UserAccount* getUser(const std::string& rnti) {
        auto it = userAccounts.find(rnti);
        if (it != userAccounts.end())
            return &it->second;
        return nullptr;
    }

    void addUser(const UserAccount& user) {
        if (userAccounts.emplace(user.id, user).second)
            logUserOperation("Added", user.id);
    }

    bool updateUser(const UserAccount& user) {
        auto it = userAccounts.find(user.id);
        if (it != userAccounts.end()) {
            it->second = user;
            logUserOperation("Updated", user.id);
            return true;
        }
        return false;
    }

    bool removeUser(const std::string& id) {
        auto it = userAccounts.find(id);
        if (it != userAccounts.end()) {
            userAccounts.erase(it);
            logUserOperation("Deleted", id);
            return true;
        }
        return false;
    }

private:
    void logDataOperation(const std::string& operation, uint32_t rnti) {
        logFile << "[" << boost::asio::chrono_clock::now().time_since_epoch().count()
                << "] Data: " << operation << ", RNTI: " << rnti << std::endl;
    }

    void logUserOperation(const std::string& operation, const std::string& id) {
        logFile << "[" << boost::asio::chrono_clock::now().time_since_epoch().count()
                << "] User: " << operation << ", ID: " << id << std::endl;
    }
};
