typedef struct {
    double signal_strength;
    time_t timestamp;
    pthread_mutex_t lock;
} lte_report;

typedef struct list_node {
    struct list_node *next;
    struct list_data data;
} list_node;

typedef struct list_data {
    list_node* head;
    size_t size;
    size_t capacity;
} list_data;

list_data* create_list() {
    list_data* list = malloc(sizeof(list_data));
    list->head = NULL;
    list->size = 0;
    list->capacity = 4;
    return list;
}

void resize_list(list_data* list) {
    if (list->capacity == 0) {
        list->capacity = 4;
        return;
    }
    size_t new_capacity = list->capacity * 2;
    list_node** old_nodes = realloc(list->head, new_capacity * sizeof(list_node));
    if (!old_nodes) {
        perror("realloc failed");
        return;
    }
    list->head = old_nodes;
    list->capacity = new_capacity;
}

void push_back(list_data* list, lte_report report) {
    if (list->size == list->capacity) resize_list(list);
    list_node *new_node = &list->head[list->size++];
    new_node->data = report;
    new_node->next = NULL;
    if (list->size == 1) list->head = new_node;
    else {
        list_node* current = list->head;
        while (current->next != NULL) current = current->next;
        current->next = new_node;
    }
}

lte_report* find_by_strength(list_data* list, double threshold) {
    if (list->size == 0) return NULL;
    list_node* current = list->head;
    while (current != NULL && current->data.signal_strength < threshold) current = current->next;
    return &current->data;
}

