NFAPI_CRC_INDICATION_PDU_T* create_list(unsigned int n, unsigned int seed) {
    start_time = clock(); // Start logging timer
    srand(seed); // Set random seed

    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pdu_list) {
        log("Error: Failed to allocate memory");
        throw std::runtime_error("Memory allocation failed");
    }

    unsigned int unique_rntis = 0;
    for (unsigned int i = 0; i < n && unique_rntis < MAX_RNTIS; ++i) {
        uint16_t rnti = rand() % MAX_RNTIS; // Generate RNTI within the valid range

        if (used_rntis.find(rnti) != used_rntis.end()) { // If RNTI is already in use, try another one
            continue;
        }

        pdu_list[i].rx_ue_information_tag = rand();
        pdu_list[i].rnti = rnti;
        pdu_list[i].crc_indication_rel8_tag = rand();
        pdu_list[i].crcflag = (rand() % 2) == 0; // Set CRCFLAG randomly

        used_rntis.insert(rnti); // Mark the RNTI as used
        ++unique_rntis; // Increment total unique RNTIs used counter
    }

    if (i < n && unique_rntis == MAX_RNTIS) {
        log("Warning: Reached maximum number of available RNTIs");
    }

    return pdu_list;
}
