bool is_unique_ue_id(uint32_t ue_id) {
    if (num_elements == 0 || head->data.UE_ID != ue_id)
        return true;

    Node* current = head;
    do {
        if (current->next && current->next->data.UE_ID == ue_id)
            return false;
        current = current->next;
    } while (current != head);

    return true;
}

NFAPI_MESSAGE_PDU_T* allocate_ue_context(uint32_t ue_id) {
    if (!is_unique_ue_id(ue_id)) {
        fprintf(stderr, "Warning: Trying to create a UE context with an existing ID. Skipping.\n");
        return NULL;
    }

    NFAPI_MESSAGE_PDU_T* ue = (NFAPI_MESSAGE_PDU_T*)malloc(sizeof(NFAPI_MESSAGE_PDU_T));
