        free(ue);
        return NULL;
    }

    ue->num_meas_reports = 0;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Error: Failed to allocate memory for new Node.\n");
        free(ue->meas_reports);
        free(ue);
        return NULL;
    }

    new_node->data = *ue;
    new_node->next = head;

    if (head != NULL)
        head->prev = new_node;

    head = new_node;

    ++num_elements;
    printf("Created UE context with ID: %d\n", ue->UE_ID);

    return ue;
}

void deallocate() {
    if (head == NULL)
        return;

    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current->data.meas_reports);
        free(current);
        current = next;
    }

    head = NULL;
    num_elements = 0;
}
