} RRC_MSG;

typedef struct dl_rrc {
    RRC_MSG **messages;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    sem_t not_full;
    sem_t not_empty;
    int *version_cache;
    int cache_size;
    int cache_index;
