    msg->rrc_version = rrc_version;
    msg->message_length = 0;
    msg->message_content = NULL;
    sem_init(&msg->lock, 0, 1);
}

DL_RRC *create_dl_rrc(size_t capacity) {
    DL_RRC *dl_rrc = mmap(NULL, sizeof(DL_RRC), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    pthread_mutex_init(&dl_rrc->mutex, NULL);
    sem_init(&dl_rrc->not_full, 0, capacity);
    sem_init(&dl_rrc->not_empty, 0, 0);
    dl_rrc->messages = calloc(capacity, sizeof(RRC_MSG *));
    for (size_t i = 0; i < capacity; ++i) {
        init_rrc_msg(&dl_rrc->messages[i], -1);
    }
    dl_rrc->capacity = capacity;
    dl_rrc->count = 0;
    return dl_rrc;
}

void free_dl_rrc(DL_RRC *dl_rrc) {
    for (size_t i = 0; i < dl_rrc->capacity; ++i) {
        if (dl_rrc->messages[i]->message_content) {
            free(dl_rrc->messages[i]->message_content);
        }
        sem_destroy(&dl_rrc->messages[i]->lock);
    }
    free(dl_rrc->messages);
    munmap(dl_rrc, sizeof(DL_RRC));
}

int get_rrc_version() {
    // Implement cache strategy and error recovery mechanisms here.
    return dl_rrc->version_cache[dl_rrc->cache_index];
}

void insert_rrc_msg(DL_RRC *dl_rrc, RRC_MSG *msg) {
    sem_wait(&dl_rrc->not_full);
    pthread_mutex_lock(&dl_rrc->mutex);
    for (size_t i = 0; i < dl_rrc->capacity; ++i) {
        if (dl_rrc->messages[i]->message_content == NULL) {
            dl_rrc->messages[i] = msg;
            dl_rrc->count++;
            sem_post(&dl_rrc->not_empty);
            pthread_mutex_unlock(&dl_rrc->mutex);
            return;
        }
    }
    pthread_mutex_unlock(&dl_rrc->mutex);
}

RRC_MSG* retrieve_rrc_msg(DL_RRC *dl_rrc, int index) {
    RRC_MSG *msg = NULL;
    sem_wait(&dl_rrc->not_empty);
    pthread_mutex_lock(&dl_rrc->mutex);
    msg = dl_rrc->messages[index];
    dl_rrc->messages[index] = dl_rrc->messages[dl_rrc->capacity - 1];
    if (msg->message_content) {
        memmove(dl_rrc->messages[dl_rrc->capacity - 1], msg, sizeof(RRC_MSG));
    }
    dl_rrc->count--;
    sem_post(&dl_rrc->not_full);
    pthread_mutex_unlock(&dl_rrc->mutex);
    return msg;
}
