```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct NetworkInterface {
    char name[32];
    double packetLossRate;
    double throughput;
    double latency;
} NetworkInterface;

typedef struct HashNode {
    NetworkInterface data;
    struct HashNode *next;
} HashNode;

#define HASH_SIZE 10007 // Prime number for good hash distribution
unsigned int hashFunction(const char* key) {
    unsigned long hash = 5381;
    int c;
    while ((c = *key++))
        hash = hash * 33 + c;
    return hash % HASH_SIZE;
}

void addNetworkInterface(HashNode** table, NetworkInterface* interface) {
    unsigned int index = hashFunction(interface->name);
    HashNode* current = table[index];

    if (!current) {
        current = malloc(sizeof(HashNode));
        memcpy(current, interface, sizeof(NetworkInterface));
        current->next = NULL;
        table[index] = current;
    } else {
        HashNode* newNode = malloc(sizeof(HashNode));
        memcpy(newNode, interface, sizeof(NetworkInterface));
        newNode->next = current;

        while (current->next)
            current = current->next;

        current->next = newNode;
    }
}

void sortNetworkInterfacesByThroughput(HashNode** table, int size) {
    NetworkInterface tmp[size];

    for (int i = 0; i < HASH_SIZE; ++i) {
        if (!table[i]) continue;

        HashNode* current = table[i];
        int index = 0;

        while (current) {
            tmp[index++] = current->data;
            current = current->next;
        }

        qsort(tmp, index, sizeof(NetworkInterface), compareByThroughput);

        int j = 0;
        for (int i = 0; i < HASH_SIZE; ++i) {
            if (!table[i]) continue;

            HashNode* current = table[i];
            while (current) {
                NetworkInterface& data = current->data;
                if (j >= index) {
                    table[i] = current;
                    break;
                }
                current->data = tmp[j++];
                current = current->next;
            }
        }
    }
}

int compareByThroughput(const void *a, const void *b) {
    return ((NetworkInterface*)b)->throughput - ((NetworkInterface*)a)->throughput;
}

// Assuming getNetworkStats returns the interface stats in an array of type NetworkInterface
void updateStatistics(NetworkInterface* interfaces[], int size, void (*getNetworkStats)(NetworkInterface[])) {
    for (int i = 0; i < size; ++i) {
        NetworkInterface* currInterface = &interfaces[i];
        getNetworkStats([currInterface]);
    }
}

void manageNetworkStatistics(HashNode** table, int* size, void (*getNetworkStats)(NetworkInterface[])) {
    clock_t prevUpdate = clock();
    clock_t current;
    double elapsedTime;

    *size = 0;

    while (1) {
        current = clock();
        elapsedTime = (double)(current - prevUpdate) / CLOCKS_PER_SEC;

        if (elapsedTime >= 5.0) // Update every 5 seconds
        {
            updateStatistics(table, *size, getNetworkStats);
            sortNetworkInterfacesByThroughput(table, *size);

            prevUpdate = current;
        }
    }
}
