    public RandomValueGenerator(int minValue, int maxValue)
    {
        Min = minValue;
        Max = maxValue;
    }

    public int Min
    {
        get { return min; }
        set { if (value < int.MinValue || value > int.MaxValue) throw new ArgumentOutOfRangeException(nameof(min), value, "The minimum value must be within the valid range."); min = value; }
