[" Here's an outline for a multi-threaded C library module that manages a dynamic array of custom message objects. The code provided below is a skeleton implementation that addresses the given constraints.

```c
#include <pthread.h>
#include <stdbool.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int user_id;
    time_t timestamp;
    enum { LOW, MEDIUM, HIGH } priority;
} Message;

typedef struct MessageQueue Node;
struct MessageQueue {
    Node *head;
    Node *tail;
    unsigned int capacity;
    unsigned int size;
    pthread_mutex_t lock;
};

Node* create_node(const Message *msg) {
    Node *node = malloc(sizeof(Node));
    node->data = msg;
    node->next = NULL;
    return node;
}

void enqueue(Node **head, Node **tail, const Message *msg) {
    Node *new_node = create_node(msg);
    pthread_mutex_lock(&(*head)->lock);
    if (*head == NULL) {
        *head = new_node;
        *tail = *head;
    } else {
        (*tail)->next = new_node;
        *tail = new_node;
    }
    pthread_mutex_unlock(&(*head)->lock);
}

Message* dequeue(Node **head) {
    if (*head == NULL) return NULL;
    Message *data = (*head)->data;
    Node *temp = *head;
    *head = (*head)->next;
    free(temp);
    return data;
}

void init_queue(MessageQueue *q, unsigned int capacity) {
    q->head = NULL;
    q->tail = NULL;
    q->capacity = capacity;
    q->size = 0;
    pthread_mutex_init(&q->lock, NULL);
}

void destroy_queue(MessageQueue *q) {
    while (q->head != NULL) dequeue(&q->head);
    pthread_mutex_destroy(&q->lock);
}

// Implement add_message(), remove_old_messages(), update_priority(), and other functions as per your requirements.
```

