    uint8_t payload[0];  // Variable-length MAC_PAYLOAD_T
} MAC_PDU_T;

typedef struct deque_node {
    MAC_PDU_T *data;
    struct deque_node *prev, *next;
} DEQUE_NODE;

// Function prototypes
void mac_pdu_queue_init(MAC_PDU_QUEUE_T *, size_t max_size);
int mac_pdu_queue_add(MAC_PDU_QUEUE_T *, MAC_PDU_T *);
int mac_pdu_queue_remove_at(MAC_PDU_QUEUE_T *, size_t index);
void mac_pdu_queue_iterate(MAC_PDU_QUEUE_T *, void(*process)(MAC_PDU_T *));
size_t mac_pdu_queue_length(const MAC_PDU_QUEUE_T *);

// Global variables and functions
extern CONFIG_MANAGER_T config;  // External configuration manager instance

void log_pdu(const MAC_PDU_T *pdu) {
    printf("Logging PDU: count=%zu, payload_size=%zu\n", mac_pdu_queue_length(&pdu->queue), sizeof(pdu->payload));
}

struct {
    DEQUE_NODE head;
    DEQUE_NODE tail;
    size_t max_size;
    size_t current_size;
} mac_pdu_queue;

void mac_pdu_queue_init(MAC_PDU_QUEUE_T *q, size_t max_size) {
    memset(q, 0, sizeof(*q));
    q->max_size = max_size;
}

int mac_pdu_queue_add(MAC_PDU_QUEUE_T *q, MAC_PDU_T *pdu) {
    if (q->current_size == q->max_size) {
        // Handle out-of-memory gracefully
        if (config.reallocation_policy == CONFIG_REALLOCATION_POLICY_RESIZE) {
            // Resize the array and repeat the add operation
            size_t new_max_size = q->max_size * 2;
            mac_pdu_queue_resize(q, new_max_size);
        } else if (config.reallocation_policy == CONFIG_REALLOCATION_POLICY_DROP) {
            // Drop the new PDU to avoid reallocation overhead
            return 1;
        }
    }

    DEQUE_NODE *node = malloc(sizeof(DEQUE_NODE));
    if (!node) {
        fprintf(stderr, "Out of memory!\n");
        return 0;
    }

    node->data = pdu;
    node->prev = &mac_pdu_queue.head;
    node->next = NULL;

    mac_pdu_queue.head.next = node;
    if (mac_pdu_queue.tail.prev) {
        mac_pdu_queue.tail.prev->next = node;
        mac_pdu_queue.tail = *node;
    } else {
        mac_pdu_queue.tail = *node;
    }

    ++q->current_size;
    log_pdu(pdu);
    return 1;
}

int mac_pdu_queue_remove_at(MAC_PDU_QUEUE_T *q, size_t index) {
    if (index >= q->current_size || !q->current_size)
        return 0;

    DEQUE_NODE *node = &mac_pdu_queue.head;
    for (size_t i = 0; i < index; ++i) {
        node = node->next;
        if (!node)
            return 0; // Index out of range
    }

    DEQUE_NODE *prev_node = node->prev;
    MAC_PDU_T *pdu = node->data;

    free(node);

    prev_node->next = node->next;
    if (node->next) {
        node->next->prev = prev_node;
        if (!mac_pdu_queue.tail.prev) {
            mac_pdu_queue.tail = *node->next;
        }
    } else {
        mac_pdu_queue.tail = *prev_node;
    }

    --q->current_size;
    log_pdu(pdu);
    return 1;
}

void mac_pdu_queue_iterate(MAC_PDU_QUEUE_T *q, void(*process)(MAC_PDU_T *)) {
    DEQUE_NODE *node = &mac_pdu_queue.head;
    for (size_t i = 0; i < q->current_size; ++i) {
        process(node->data);
        node = node->next;
    }
}

size_t mac_pdu_queue_length(const MAC_PDU_QUEUE_T *q) {
    return q->current_size;
}

void mac_pdu_queue_resize(MAC_PDU_QUEUE_T *q, size_t new_max_size) {
    if (new_max_size < q->current_size) {
        fprintf(stderr, "New max size is smaller than the current size!\n");
        return;
    }

    DEQUE_NODE **nodes = malloc(sizeof(DEQUE_NODE) * new_max_size);
    if (!nodes) {
        fprintf(stderr, "Out of memory while resizing!\n");
        return;
    }

    size_t i = 0;
    DEQUE_NODE *node = &mac_pdu_queue.head;
    for (; node && i < q->current_size; ++i, node = node->next) {
        nodes[i] = node;
    }

    free(mac_pdu_queue.head.next);
    mac_pdu_queue.head.next = nodes;
    mac_pdu_queue.max_size = new_max_size;
}
