#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <atomic>
#include <new>

const size_t MAX_MEMORY = 1000000; // Maximum memory limit (in bytes)

struct Record {
    std::atomic<int> key;
    atomic<long> offset;
};

class RingBuffer {
public:
    RingBuffer(size_t capacity) : data_(nullptr), size_(0), capacity_(capacity), freeHead_(0), freeTail_(0), lock_() {}

    ~RingBuffer() {
        if (data_) {
            delete[] data_;
        }
    }

    void resize(size_t newCapacity) {
        if (newCapacity > MAX_MEMORY || newCapacity <= capacity_) {
            return;
        }

        auto temp = static_cast<Record*>(realloc(data_, newCapacity * sizeof(Record)));
        if (!temp) {
            throw std::bad_alloc();
        }

        data_ = temp;
        capacity_ = newCapacity;
    }

    bool push(const Record& record) {
        if (size_ >= capacity_) {
            resize(capacity_ * 2);
        }

        auto index = (freeHead_ + size_) % capacity_;

        std::unique_lock<std::mutex> lock(lock_);
        while ((data_[index].offset.load() != freeTail_) || size_ >= capacity_) {
            lock.wait();
        }

        data_[index] = record;
        size_++;
        freeTail_ = (freeHead_ + size_) % capacity_;
        return true;
    }

    Record pop() {
        if (!size_) {
            throw std::out_of_range("Empty ring buffer");
        }

        auto index = freeTail_;
        auto result = data_[index];

        std::unique_lock<std::mutex> lock(lock_);
        while (data_[index].offset.load() != index) {
            lock.wait();
        }

        size_--;
        if ((freeHead_ == freeTail_) && (size_ > 0)) {
            freeHead_ = index + 1;
            freeTail_ = index;
        } else if (freeHead_ == capacity_) {
            freeHead_ = 0;
        }

        return result;
    }

private:
    Record* data_;
    size_t size_, capacity_;
    long freeHead_, freeTail_;
    std::mutex lock_;
};

