        memoryPool[i].RNTI = 0;
        memoryPool[i].CRC_INDICATION_REL8_TAG = 0;
        memoryPool[i].CRCFLAG = false;
    }

    freeIndex = 0;
}

// Function to create and populate a linked list of NFAPI_CRC_INDICATION_PDU_T structures
void createAndPopulateList(NFAPI_CRC_INDICATION_PDU_T **head, size_t size) {
    pthread_mutex_lock(&memLock);

    // Allocate enough elements from the memory pool to populate the list
    size_t allocatedSize = size < freeIndex ? size : freeIndex;
    NFAPI_CRC_INDICATION_PDU_T **newList = malloc(allocatedSize * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    // Populate the list with elements from the memory pool
    for (size_t i = 0; i < allocatedSize; ++i) {
        (*newList + i) = &memoryPool[freeIndex++];

        // Set random values for each struct in the list
        (**(newList + i)).RX_UE_INFORMATION_TAG = rand();
        (**(newList + i)).RNTI = rand() % 0xFFFF;
        (**(newList + i)).CRC_INDICATION_REL8_TAG = rand();
        (**(newList + i)).CRCFLAG = generateRandomCRCFlag();
    }

    pthread_mutex_unlock(&memLock);

    // Connect the populated elements in the list to form a circular linked list
    if (allocatedSize > 1) {
        (*(newList + allocatedSize - 1))->next = *head;
        *head = newList[0];
    }
}

// Custom memory deallocation function to minimize fragmentation
