    NFAPI_CRC_INDICATION_PDU_T *curNode = *list;
    while (curNode != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *nextNode = curNode->next;
        free(curNode);
        curNode = nextNode;
    }
