    for (int i = 0; i < num_frames; ++i) {
        free((frames[i])->symbols);
        free(frames[i]);
    }
    free(frames);
    pthread_mutex_destroy(&frames_lock[0]);
    sem_destroy(&frames_semaphore);
}

PHY_FRAME_T* frame_new() {
    if (num_frames >= MAX_FRAMES) return NULL;

    pthread_mutex_lock(&frames_lock[num_frames % LOCK_COUNT]);
    PHY_FRAME_T* new_frame = malloc(sizeof(PHY_FRAME_T));
    if (!new_frame) {
        pthread_mutex_unlock(&frames_lock[num_frames % LOCK_COUNT]);
        return NULL;
    }
    new_frame->frame_type = TYPE_A; // Default frame type (set according to user input later)
    new_frame->tx_power_level = 0;
    new_frame->symbols = calloc(1, SYMBOL_ALIGNMENT);
    if (!new_frame->symbols) {
        free(new_frame);
        pthread_mutex_unlock(&frames_lock[num_frames % LOCK_COUNT]);
        return NULL;
    }

    align_memory(&(new_frame->symbols), SYMBOL_ALIGNMENT);

    frames[num_frames++] = new_frame;
    sem_post(&frames_semaphore);
    pthread_mutex_unlock(&frames_lock[num_frames % LOCK_COUNT]);

    return new_frame;
}

void frame_push_symbol(PHY_FRAME_T* frame, const struct PHY_SYMBOL_T* symbol) {
    void** symbols = &((void**)frame->symbols);
    size_t alignment = SYMBOL_ALIGNMENT;

    if (!frame || !symbol) return;

    pthread_mutex_lock(&frames_lock[num_frames % LOCK_COUNT]);

    while (*symbols + alignment != frames[num_frames]->symbols) {
        sem_wait(&frames_semaphore);
    }

    // Process the symbol here (replace with actual API call)
    process_frame(frame);

    // Store the symbol and update the pointer
    memcpy(*symbols, symbol, sizeof(struct PHY_SYMBOL_T));
    (*symbols) = ((char*)*symbols + SYMBOL_ALIGNMENT);

    pthread_mutex_unlock(&frames_lock[num_frames % LOCK_COUNT]);
}
