    pthread_mutex_lock(&cm->list_lock);
    if (gsl_list_length(cm->connections) == 0)
        gsl_list_init(cm->connections);

    gsl_list_push(cm->connections, &record);
    cm->num_connections++;
    pthread_mutex_unlock(&cm->list_lock);
}

void remove_connection(ConnectionManager* cm, size_t connection_id) {
    pthread_mutex_lock(&cm->list_lock);
    gsl_list* current = cm->connections;
    while (current != NULL && gsl_list_length(current) > 0) {
        ConnectionRecord* record = gsl_list_data(current);
        if (record->id == connection_id) {
            gsl_list* next = gsl_list_next(current);
            gsl_list_remove(cm->connections, current);
            free(current);
            cm->num_connections--;
            pthread_mutex_unlock(&cm->list_lock);

            free(record);
            return;
