typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_tag;
    uint32_t crcflags; // Randomly set CRCFLAGS
    time_t timestamp;
    int weight; // User-defined structure's weight
} NFAPI_CRC_INDICATION_PDU_T;

struct FilterData {
    std::queue<NFAPI_CRC_INDICATION_PDU_T> queue;
    std::map<uint32_t, int> transaction_weights;
    time_t last_processed;
    int max_load;
};

FilterData* create_filter(int max_load) {
    FilterData* data = (FilterData*)malloc(sizeof(FilterData));
    data->last_processed = 0;
    data->max_load = max_load;
    return data;
}

void enqueue(FilterData* filter, NFAPI_CRCI_INDICATION_PDU_T pdu) {
    filter->queue.push(pdu);
}

void process(FilterData* filter, std::function<int(NFAPI_CRCI_INDICATION_PDU_T&)> processor) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    struct timespec deadline;
    clock_gettime(CLOCK_REALTIME, &deadline);
    deadline.tv_sec += 0.010; // Process in 10 milliseconds

    while (true) {
        pthread_mutex_lock(&lock);

        if (filter->queue.empty() || filter->queue.size() > filter->max_load) {
            pthread_mutex_unlock(&lock);
            usleep(1000); // Sleep until the next iteration
            continue;
        }

        NFAPI_CRCI_INDICATION_PDU_T pdu = filter->queue.front();
        filter->queue.pop();
        pthread_mutex_unlock(&lock);

        if (processor(pdu)) {
            filter->transaction_weights[pdu.rnti] += pdu.weight;
        }

        filter->last_processed = time(NULL);
    }
}

void destroy_filter(FilterData* filter) {
    free(filter);
}

int find_max_weight(std::map<uint32_t, int>& transaction_weights, uint32_t current_time) {
    int max_weight = 0;
    uint32_t max_rnti = 0;

    for (auto it = transaction_weights.begin(); it != transaction_weights.end(); ++it) {
        if (current_time - it->second > 3) {
            transaction_weights.erase(it);
            continue;
        }

        if (it->second > max_weight) {
            max_weight = it->second;
            max_rnti = it->first;
        }
    }

    return max_rnti;
}

NFAPI_CRCI_INDICATION_PDU_T filter(FilterData* filter, int num_structures) {
    process(filter, [&](NFAPI_CRCI_INDICATION_PDU_T pdu) {
        if (filter->queue.size() < num_structures) return false;
        return true;
    });

    std::map<uint32_t, int> transaction_weights = filter->transaction_weights;
    uint32_t max_rnti = find_max_weight(transaction_weights, filter->last_processed);
    int max_weight = 0;

    for (auto it = transaction_weights.begin(); it != transaction_weights.end(); ++it) {
        if (it->first == max_rnti) {
            max_weight += it->second;
        }
    }

    return filter->queue.front();
}
```

