    if (num_profiles <= 0 || up >= user_profiles + max_profiles || role < min_role || role > max_role) return;

    sem_wait(&up->roles_mutex);

    // Implement external service updates and validation here

    up->roles = realloc(up->roles, (++up->num_roles) * sizeof(int));
    if (!up->roles) {
        perror("Memory allocation failed");
        sem_post(&up->roles_mutex);
        return;
    }

    up->roles[up->num_roles-1] = role;

    sem_post(&up->roles_mutex);
}

void remove_role(UserProfile* up, int role) {
    if (num_profiles <= 0 || up >= user_profiles + max_profiles || role < min_role || role > max_role) return;

    sem_wait(&up->roles_mutex);

    // Implement external service updates and validation here

    for (int i = 0; i < up->num_roles; ++i) {
        if (up->roles[i] == role) {
            memmove(up->roles + i, up->roles + i+1, (up->num_roles-i-1)*sizeof(int));
            --up->num_rooles;
            break;
        }
    }

    sem_post(&up->roles_mutex);
}

