Record records[MAX_RECORDS];
pthread_mutex_t records_lock = PTHREAD_MUTEX_INITIALIZER;

int rand_in_range(int min, int max) {
    return (rand() % ((max - min + 1)));
}

void update_records() {
    pthread_mutex_lock(&records_lock);
    for (size_t i = 0; i < MAX_RECORDS - 1; ++i) {
        int current_value = records[i].value;
        while (current_value == records[i + 1].value) {
            current_value = rand_in_range(MIN_VALUE, MAX_VALUE);
        }
        records[i].value = current_value;
        records[i].last_updated = time(NULL);
    }
    pthread_mutex_unlock(&records_lock);
}

int get_network_metric() {
    update_records();
    pthread_mutex_lock(&records_lock);
    int metric = records[rand() % MAX_RECORDS].value;
    pthread_mutex_unlock(&records_lock);
    return metric;
}

int resolve_hostname(const char *hostname) {
    struct hostent *hostinfo;
    struct in_addr **addr_list;
    int i;

    hostinfo = gethostbyname(hostname);
    if (hostinfo == NULL) {
        return -1;
    }
    addr_list = (struct in_addr **)hostinfo->h_addr_list;

    for (i = 0; addr_list[i] != NULL; ++i) {
        // DNS resolution successful, store IP address and return.
        char ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, addr_list[i], ip, sizeof(ip));
        free(hostinfo->h_addr);
        hostinfo->h_addr = strdup(ip);
    }

    // Timeout occurred, clean up and return error.
    free(hostinfo->h_addr);
    return -2;
}

char *get_api_data(int metric) {
    // Implement API call logic here, considering the need for a valid metric value.
    // ...

    static char api_response[1024];
    snprintf(api_response, sizeof(api_response), "API response: metric=%d", metric);
    return strdup(api_response);
}

char *get_ip_and_data(const char *hostname) {
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    int result = resolve_hostname(hostname);
    if (result < 0) {
        return NULL;
    }

    char *api_data = get_api_data(get_network_metric());
    if (api_data == NULL) {
        // API call failed, clean up and return error.
        free(hostinfo->h_addr);
        return NULL;
    }

    clock_gettime(CLOCK_MONOTONIC, &end);
    long elapsed = (end.tv_sec - start.tv_sec) * 1000 + (end.tv_nsec - start.tv_nsec) / 1000000;
    if (elapsed > TIMEOUT) {
        // Total request time exceeded, clean up and return error.
        free(api_data);
        free(hostinfo->h_addr);
        return NULL;
    }

    char *ip = strdup(hostinfo->h_addr);
    char *response = malloc(strlen(ip) + strlen(api_data) + 2);
    snprintf(response, sizeof(response), "%s %s", ip, api_data);
    return response;
}
