    pthread_mutex_t mutex;
    struct node *next;
} node_t;

typedef struct {
    int capacity;
    int size;
    node_t *head;
    pthread_cond_t notEmpty;
    pthread_mutex_t listMutex;
} dynamicList_t;

void initDynamicList(dynamicList_t* list) {
    list->capacity = 1024;
    list->size = 0;
    list->head = NULL;
    pthread_cond_init(&list->notEmpty, NULL);
    pthread_mutex_init(&list->listMutex, NULL);
}

void deleteDynamicList(dynamicList_t* list) {
    node_t *current = list->head;
    node_t *nextNode;

    while (current != NULL) {
        nextNode = current->next;
        free(current);
        current = nextNode;
    }

    pthread_cond_destroy(&list->notEmpty);
    pthread_mutex_destroy(&list->listMutex);
}

node_t* createNode() {
    node_t *newNode = (node_t*) malloc(sizeof(node_t));
    if (!newNode) {
        fprintf(stderr, "Out of memory\n");
        return NULL;
    }
    pthread_mutex_init(&newNode->mutex, NULL);
    newNode->next = NULL;
    return newNode;
}

void pushBack(dynamicList_t* list, LTE_PHY_RX_FRAME_INFO_T frame) {
    pthread_mutex_lock(&list->listMutex);
    node_t *newNode = createNode();
    if (!newNode) {
        pthread_mutex_unlock(&list->listMutex);
        return;
    }

    newNode->frame = frame;

    if (list->size == list->capacity) {
        resizeList(list);
    }

    node_t *current = list->head;
    if (!current) {
        list->head = newNode;
    } else {
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }
    ++list->size;
    pthread_mutex_unlock(&list->listMutex);
    pthread_cond_signal(&list->notEmpty);
}

LTE_PHY_RX_FRAME_INFO_T popFront(dynamicList_t* list) {
    LTE_PHY_RX_FRAME_INFO_T frame;
    node_t *nodeToRemove = NULL;

    pthread_mutex_lock(&list->listMutex);
    if (list->size == 0) {
        pthread_cond_wait(&list->notEmpty, &list->listMutex);
    }

    nodeToRemove = list->head;
    if (!nodeToRemove) {
        pthread_mutex_unlock(&list->listMutex);
        return (LTE_PHY_RX_FRAME_INFO_T) {0};
    }

    frame = nodeToRemove->frame;
    list->head = nodeToRemove->next;
    free(nodeToRemove);
    --list->size;
    pthread_mutex_unlock(&list->listMutex);

    return frame;
}

void resizeList(dynamicList_t* list) {
    int newCapacity = list->capacity * 2;
    node_t **nodes = realloc(list->head, sizeof(node_t*) * newCapacity);

    if (!nodes) {
        fprintf(stderr, "Out of memory\n");
        return;
    }

    list->capacity = newCapacity;
    for (int i = list->size; i < newCapacity; ++i) {
        nodes[i] = NULL;
    }

    node_t *current = list->head;
    node_t *nextNode;
    int k = 0;
    while (current != NULL) {
        nextNode = current->next;
        current->next = nodes[k];
        nodes[k] = current;
        ++k;
        current = nextNode;
    }
}
