#define MAX_CAPACITY 1024
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
size_t active_count = 0;
size_t capacity = 0;
NFAPI_CRC_INDICATION_PDU_T *data = NULL;

void init_data() {
    if (capacity) free(data);
    capacity = MAX_CAPACITY;
    data = calloc(capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

NFAPI_CRC_INDICATION_PDU_T* get_structure() {
    pthread_mutex_lock(&mutex);
    if (active_count >= capacity) init_data();
    NFAPI_CRC_INDICATION_PDU_T *res = &data[active_count++];
    res->rx_ue_information_tag.tag = 0x1234;
    res->rnti = rand() % 65536;
    res->crc_indication_rel8_tag.crcflag = (rand() % 2) ? 1 : 0;
    res->creation_time = time(NULL);
    pthread_mutex_unlock(&mutex);
    return res;
}

void clean_data() {
    time_t current_time = time(NULL);
    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < active_count; ++i) {
        if ((current_time - data[i].creation_time) > 60) { // Age threshold is 60 seconds
            free(data + i);
            memmove(data + i, data + i + 1, --active_count - i);
        }
    }
    pthread_mutex_unlock(&mutex);
}
