    for (size_t i = n; i < m + n; ++i) {
        pthread_t thread;
        pthread_create(&thread, NULL, manager, (void*)&sem_m);
    }
}

PoolNode* pool_acquire() {
    sem_wait(&pool_mutex);
    PoolNode *node = head;
    if (!head) {
        sem_post(&pool_mutex);
        return NULL;
    }

    head = node->next;
    if (head == NULL) tail = NULL;
    sem_post(&pool_mutex);

    sem_wait(node->data.timestamp); // Lock the structure for further manipulation

    num_allocations++;

    return node;
}

void pool_release(PoolNode* node) {
    if (num_allocations > eviction_counter + 1000) {
        sem_wait(&pool_mutex);
        eviction_counter += num_allocations - 1;
        num_allocations = eviction_counter;
        sem_post(&pool_mutex);
    }

    sem_post(node->data.timestamp); // Unlock the structure for use by others
}

void* manager(void* arg) {
    sem_t *sem = (sem_t *)arg;
    while (1) {
        sem_wait(sem);

        pool_Node* node = pool_acquire();
        if (!node) continue;

        // Process the structure here...

        pool_release(node);
    }
    return NULL;
}

