// Custom memory pool allocator class
class MemPoolAllocator {
public:
    MemPoolAllocator(size_t blockSize, size_t numBlocks) : _blockSize(blockSize), _numBlocks(numBlocks) {}

    void* allocate(std::size_t n) {
        if (n > _numBlocks * _blockSize)
            throw std::bad_alloc();

        auto start = _memory.data();
        auto end = start + (_numBlocks * _blockSize);
        auto result = start;

        // Align memory block address
        if (std::align(_alignment, n, result, end - result))
            return result;
        else
            throw std::bad_alloc();
    }

    void deallocate(void* p, std::size_t) {
        // Free memory back to the pool
    }

private:
    size_t _blockSize;
    size_t _numBlocks;
    std::vector<char> _memory;
    static constexpr std::size_t _alignment = 64;
};

// LTE UE Context structure
struct LTEUEContext {
    uint32_t UE_ID;
    enum RRC_STATE RRC_State;
    uint16_t S1AP_MESSAGE_TAG;
};

std::mutex _contextPoolMutex;
std::vector<LTEUEContext*, MemPoolAllocator> _contextPool;

// Initialize LTE UE context pool function
void initLTEUCONTEXTPOOL(unsigned int maxConcurrentContexts) {
    if (maxConcurrentContexts > PLATFORM_MAX_NUM_CONCURRENT_CONTEXTS) {
        std::cerr << "Error: Maximum number of concurrent contexts exceeded the platform limit." << std::endl;
        return;
    }

    _contextPool.resize(maxConcurrentContexts, nullptr);
    MemPoolAllocator allocator(_contextPool[0].sizeof(), maxConcurrentContexts);
    for (auto& context : _contextPool) {
        try {
            context = static_cast<LTEUEContext*>(allocator.allocate(sizeof(LTEUEContext)));
            new (context) LTEUEContext(); // Construct in-place
        } catch (const std::bad_alloc&) {
            std::cerr << "Error: Failed to allocate memory for context." << std::endl;
            return;
        }
    }
}

// Get an LTE UE context from the pool
LTEUEContext* getLTEUCONTEXT() {
    std::unique_lock<std::mutex> lock(_contextPoolMutex);

    for (auto i = 0u; i < _contextPool.size(); ++i) {
        if (_contextPool[i] == nullptr) {
            lock.unlock();
            return _contextPool[i];
        }
    }

    // No available context found, log and return a null pointer
    std::cerr << "Error: All LTE UE contexts are in use." << std::endl;
    return nullptr;
}

// Return an LTE UE context to the pool
void freeLTEUCONTEXT(LTEUEContext* context) {
    std::unique_lock<std::mutex> lock(_contextPoolMutex);
    if (context == nullptr)
        return;

    context->~LTEUEContext(); // Destroy in-place
    _contextPoolAllocator.deallocate(context, sizeof(LTEUEContext));
    _contextPool[i] = nullptr;
}
