CellularEvent* create_linked_list(int size) {
    CellularEvent *head = NULL, *current = NULL, *new_event;

    srand(time(NULL));
    for (int i = 0; i < size; ++i) {
        new_event = create_cellular_event();
        if (!head) {
            head = current = new_event;
        } else {
            current->next = new_event;
            current = new_event;
        }
    }

    CellularEvent* temp = head;
    for (int i = 0; i < size - 1; ++i) {
        if (temp->session_id == current->session_id) {
            free(current);
            current = temp->next;
            --size;
        }
        temp = temp->next;
    }

    return head;
}
