```cpp
#include <iostream>
#include <chrono>
#include <deque>
#include <unordered_map>
#include <functional>
#include <mutex>

struct NetworkTransaction {
    int TransactionID;
    std::string RequestType;
    int ResponseCode;
    std::int64_t Timestamp;
};

class DoublyLinkedList {
private:
    struct Node {
        NetworkTransaction data;
        Node* prev;
        Node* next;
        Node(const NetworkTransaction& transaction, Node* prev = nullptr, Node* next = nullptr)
            : data(transaction), prev(prev), next(next) {}
    };

    std::deque<Node> transactions_;
    std::unordered_map<int, Node*> id_map_;
    mutable std::mutex mtx;

public:
    DoublyLinkedList() = default;

    void insert(const NetworkTransaction& transaction) {
        std::unique_lock<std::mutex> lock(mtx);

        auto it = id_map_.find(transaction.TransactionID);
        if (it != id_map_.end()) {
            // Duplicate ID, do not insert
            return;
        }

        Node* newNode = new Node(transaction);
        transactions_.push_back(*newNode);
        id_map_[transaction.TransactionID] = newNode;
    }

    std::vector<NetworkTransaction> filter(const std::string& requestTypeStart, const std::string& requestTypeEnd) {
        std::vector<NetworkTransaction> result;
        std::unique_lock<std::mutex> lock(mtx);

        for (auto it = transactions_.begin(); it != transactions_.end(); ++it) {
            if ((requestTypeStart.empty() || requestTypeStart <= it->data.RequestType) &&
                (requestTypeEnd.empty() || requestTypeEnd >= it->data.RequestType)) {
                result.push_back(it->data);
            }
        }
        return result;
    }

    std::vector<NetworkTransaction> sortByTimestampAscending() {
        std::vector<NetworkTransaction> result;
        std::unique_lock<std::mutex> lock(mtx);

        for (auto it = transactions_.begin(); it != transactions_.end(); ++it) {
            result.push_back(it->data);
        }
        std::sort(result.begin(), result.end(), [](const NetworkTransaction& a, const NetworkTransaction& b) -> bool {
            return a.Timestamp < b.Timestamp;
        });
        return result;
    }
};
```

This implementation uses a `std::deque` for the doubly linked list and an unordered map to store transactions based on their unique IDs, ensuring no duplicates are stored. The function `insert()` checks for duplicate entries efficiently using the unordered map.

The filtering functionality is provided by the `filter()` method, which accepts a range of RequestTypes as arguments and returns a vector containing only the transactions within that range.

The sorting by Timestamp in ascending order is done by the `sortByTimestampAscending()` method.

The function is designed to minimize blocking operations and ensure thread safety with the use of a mutex. The unordered map also reduces the overhead of searching for duplicate transactions, improving performance under high load.

To handle up to 1 million transactions without significant degradation in performance, you may want to consider using a more efficient data structure like a hash table or red-black tree if your standard library provides an implementation. Additionally, optimizing memory management and minimizing function call overhead can further improve performance.']

