#include <pthread.h>
#include <stdlib.h>
#include <sys/mman.h>
#include <time.h>
#include <semaphore.h>
#include <stdbool.h>
#include <func_monitoring_service.h> // External monitoring service interface

typedef struct {
    size_t id;
    time_t last_active;
    uint64_t bandwidth_usage;
} ConnectionState;

typedef struct Node {
    ConnectionState cs;
    struct Node* next;
} Node;

struct Collection {
    Node* head;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
    sem_t resize_sem; // Semaphore for collection resizing
};

void init_collection(struct Collection* col, size_t initial_capacity) {
    col->head = NULL;
    col->size = 0;
    col->capacity = initial_capacity;
    pthread_mutex_init(&col->lock, NULL);
    sem_init(&col->resize_sem, 0, col->capacity);
}

Node* create_node(ConnectionState cs) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->cs = cs;
    new_node->next = NULL;
    return new_node;
}

void push_back(struct Collection* col, Node* node) {
    pthread_mutex_lock(&col->lock);
    if (col->size == col->capacity) {
        sem_wait(&col->resize_sem);
    }

    Node* current = col->head;
    if (!current) {
        col->head = node;
    } else {
        while (current->next) {
            current = current->next;
        }
        current->next = node;
    }
    col->size++;
    pthread_mutex_unlock(&col->lock);
}

ConnectionState pop_front(struct Collection* col) {
    ConnectionState cs;
    pthread_mutex_lock(&col->lock);
    if (!col->head) {
        pthread_mutex_unlock(&col->lock);
        return (ConnectionState){0, 0, 0};
    }
    Node* temp = col->head;
    cs = temp->cs;
    col->head = temp->next;
    free(temp);
    col->size--;
    pthread_mutex_unlock(&col->lock);
    return cs;
}

void check_and_add(struct Collection* col, ConnectionState new_connection) {
    if (func_monitoring_service_validate(new_connection)) {
        Node* node = create_node(new_connection);
        if (node) push_back(col, node);
    }
}
```

