// D doubly-linked list node structure
struct Node {
    UserActivity activity;
    struct Node *prev, *next;
};

// Mutex to ensure thread-safety
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
// List head and tail pointers
struct Node *head, *tail;

void add_to_list(UserActivity activity) {
    struct Node *new_node = malloc(sizeof(struct Node));
    new_node->activity = activity;
    pthread_mutex_lock(&list_mutex);
    if (!head) {
        head = new_node;
        tail = new_node;
    } else {
        new_node->prev = tail;
        new_node->next = head;
        tail->next = new_node;
        head->prev = new_node;
        tail = new_node;
    }
    pthread_mutex_unlock(&list_mutex);
}

bool find_activity(int userId, char* pageUrl, char* sessionId) {
    bool found = false;
    struct Node *current = head;

    while (current != NULL && !found) {
        if (current->activity.UserId == userId
            && strcmp(current->activity.PageUrl, pageUrl) == 0
            && strcmp(current->activity.SessionId, sessionId) == 0) {
            found = true;
        }
        current = current->next;
    }

    return found;
}

// Process function that is called asynchronously from diverse client sources
void process_data(UserActivity activity) {
    if (!find_activity(activity.UserId, activity.PageUrl, activity.SessionId)) {
        add_to_list(activity);
    }
}
