// Custom Memory Pool
typedef struct MemPool_Tag {
    void* start;
    void* end;
    size_t allocatedSize;
    size_t usedSize;
} MemPool;

void initMemPool(MemPool* pool, void* base, size_t size) {
    pool->start = base;
    pool->end = (char*)base + size;
    pool->allocatedSize = size;
    pool->usedSize = 0;
}

void* allocate(MemPool* pool, size_t size) {
    if (pool->usedSize + size > pool->allocatedSize) {
        fprintf(stderr, "Out of memory!\n");
        return NULL;
    }

    void* result = (char*)pool->start + pool->usedSize;
    pool->usedSize += size;
    return result;
}

void freeMemPool(MemPool* pool) {
    if (pool->start != NULL && pool->usedSize > 0) {
        free((char*)pool->start);
        pool->usedSize = 0;
    }
}

