ListNode* createListNode(NFAPI_CRC_INDICATION_PDU* data) {
    ListNode* node = (ListNode*)allocate(1, sizeof(ListNode));
    if (!node) return NULL;

    node->data = data;
    node->next = NULL;

    return node;
}

void appendNode(MemPool* pool, ListNode** head, ListNode* node) {
    if (!head || !node) return;

    if (*head == NULL) {
        *head = node;
    } else {
        ListNode* current = *head;
        while (current->next != NULL) current = current->next;
        current->next = node;
    }
}

void removeNodeByRNTI(MemPool* pool, ListNode** head, RNTI rnti) {
    if (!head || !*head) return;

    ListNode *current = *head, *prev = NULL;
    while (current != NULL) {
        if (current->data->rnti == rnti) {
            if (prev == NULL) {
                *head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }
}

void iterateList(const ListNode* head, void(*process)(const NFAPI_CRC_INDICATION_PDU*)) {
    if (!head || !process) return;

    const ListNode *current = head;
    while (current != NULL) {
        process(current->data);
        current = current->next;
    }
