typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    uint32_t RNTI;
    CRC_INDICATION_REL8_TAG crcTag;
    uint16_t CRCFLAG;
    struct _NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

static pthread_mutex_t listMutex = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_CRC_INDICATION_PDU_T *head = NULL, *tail = NULL;
static unsigned int capacity = 0;
static unsigned int numElements = 0;
static unsigned int maxCRCFlag = 100;

// Custom LCG for CRCFLAG generation
unsigned int customLCG(unsigned int seed) {
    static const unsigned long a = 16807;
    static const unsigned long c = 0x0000ffff;
    unsigned long value = (seed * a + c) & c;
    return (value >> 16) % maxCRCFlag;
}

int addElement(NFAPI_CRC_INDICATION_PDU_T **headRef, NFAPI_CRC_INDICATION_PDU_T *newNode) {
    if (!*headRef) {
        *headRef = newNode;
        tail = *headRef;
    } else {
        tail->next = newNode;
        tail = newNode;
    }
    numElements++;
    return 0;
}

void printList() {
    pthread_mutex_lock(&listMutex);
    printf("Element count: %d\n", numElements);
    printf("CRC Flag Usage Statistics:\n");
    unsigned int minCRCFlag = maxCRCFlag, uniqueCRCFlags = 0;
    for (NFAPI_CRC_INDICATION_PDU_T *curNode = *head; curNode != NULL; curNode = curNode->next) {
        printf("Tag: %d RNTI: %u CRC Flag: %u\n", curNode->tag, curNode->RNTI, curNode->CRCFLAG);
        if (curNode->CRCFLAG < minCRCFlag) minCRCFlag = curNode->CRCFLAG;
        if (curNode->CRCFLAG != uniqueCRCFlags++) continue; // optimization for duplicate CRC flags
        printf("Duplicate CRC Flag found: %u\n", curNode->CRCFLAG);
    }
    printf("Minimum CRC Flag: %d\n", minCRCFlag);
    pthread_mutex_unlock(&listMutex);
}

int initializeList(unsigned int seed) {
    if (seed <= 0) return -1; // invalid seed value

    capacity = 50000;
    NFAPI_CRC_INDICATION_PDU_T *elements = malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!elements) return -2; // failed to allocate memory

    for (unsigned int i = 0; i < capacity; ++i) {
        elements[i].CRCFLAG = customLCG(seed);
        if (elements[i].CRCFLAG >= maxCRCFlag) {
            free(elements); // free previously allocated memory
            return -3; // CRC flag out of range
        }
    }

    head = elements;
    tail = &elements[capacity - 1];
    numElements = capacity;
    return 0;
}

// Implement the required functions for concurrency handling, error handling, and other optimizations as needed.
