    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    bool crcflag;
    struct _NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct _DYNAMIC_LIST {
    int size;
    int capacity;
    NFAPI_CRC_INDICATION_PDU_T* head;
    pthread_mutex_t mutex;
} DYNAMIC_LIST;

DYNAMIC_LIST* dynamic_list_create() {
    DYNAMIC_LIST* list = (DYNAMIC_LIST*)malloc(sizeof(DYNAMIC_LIST));
    list->size = 0;
    list->capacity = 10000;
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void dynamic_list_destroy(DYNAMIC_LIST* list) {
    if (!list) return;
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

bool dynamic_list_insert(DYNAMIC_LIST* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    if (list->size >= list->capacity) {
        int newCapacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T** newHead = (NFAPI_CRC_INDICATION_PDU_T**)realloc(list->head, sizeof(NFAPI_CRC_INDICATION_PDU_T) * newCapacity);
        if (!newHead) return false;
        list->head = newHead;
        list->capacity = newCapacity;
    }

    pthread_mutex_lock(&list->mutex);

    data->next = list->head;
    list->head = data;
    list->size++;

    pthread_mutex_unlock(&list->mutex);

    return true;
}

bool dynamic_list_remove(DYNAMIC_LIST* list, uint32_t rnti) {
    if (list->size <= 0) return false;

    NFAPI_CRC_INDICATION_PDU_T *current = list->head, *prev = NULL;

    pthread_mutex_lock(&list->mutex);

    while (current != NULL && current->rnti != rnti) {
        prev = current;
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->mutex);
        return false;
    }

    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    list->size--;
    pthread_mutex_unlock(&list->mutex);

    return true;
}

void dynamic_list_iterate(DYNAMIC_LIST* list) {
    pthread_mutex_lock(&list->mutex);

    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current != NULL) {
        printf("tag: %u, rnti: %u, crc_indication: %u, crcflag: %d\n", current->tag, current->rnti, current->crc_indication, current->crcflag);
        current = current->next;
    }

    pthread_mutex_unlock(&list->mutex);
}

void* periodic_update(DYNAMIC_LIST* list) {
    while (true) {
        // Fetch data from external sources and create NFAPI_CRC_INDICATION_PDU_T structures...

        NFAPI_CRC_INDICATION_PDU_T* newData = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        // Set the properties of the newData struct...

        dynamic_list_insert(list, newData);

        sleep(1);
    }
}

int main() {
    DYNAMIC_LIST* list = dynamic_list_create();
    pthread_t thread;

    // Start periodic updates in a separate thread...
    pthread_create(&thread, NULL, periodic_update, list);

    // Perform other tasks here...

    while (true) {
        // Handle potential network latency or service outages gracefully...

        dynamic_list_iterate(list);
    }

    pthread_join(thread, NULL);
    dynamic_list_destroy(list);
}
