typedef struct _UE_ID_CACHE {
    uint16_t RNTI;
    struct _UE_ID_CACHE* next;
} UE_ID_CACHE;

int generate_crc_indication_pdu_list(NFAPI_CRC_INDICATION_PDU_T** list, size_t max_elements) {
    if (!list || max_elements <= 0) return -1;

    *list = NULL;
    UE_ID_CACHE* ue_id_cache_head = NULL;
    UE_ID_CACHE* ue_id_cache_tail = NULL;

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (size_t i = 0; i < max_elements && !pthread_mutex_trylock(&mutex); ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) break;

        pthread_mutex_lock(&mutex);
        pdu->RX_UE_INFORMATION_TAG = i + 1;
        pdu->RNTI = generate_unique_rnti(ue_id_cache_head, &mutex);
        pdu->CRC_INDICATION_REL8_TAG = rand() % 2;
        pdu->CRFLAG = (pdu->CRC_INDICATION_REL8_TAG == 1) ? true : false;
        pthread_mutex_unlock(&mutex);

        pdu->next = *list;
        *list = pdu;
    }

    return i;
}

uint16_t generate_unique_rnti(UE_ID_CACHE* ue_id_cache_head, pthread_mutex_t* mutex) {
    UE_ID_CACHE* current = ue_id_cache_head;
    uint16_t rnti = 0;

    while (current != NULL) {
        rnti++;
        current = current->next;
    }

    pthread_mutex_lock(mutex);
    UE_ID_CACHE* new_ue_id_cache = (UE_ID_CACHE*)malloc(sizeof(UE_ID_CACHE));
    if (!new_ue_id_cache) {
        pthread_mutex_unlock(mutex);
        return rnti;
    }

    new_ue_id_cache->RNTI = rnti;
    new_ue_id_cache->next = ue_id_cache_head;
    ue_id_cache_head = new_ue_id_cache;

    pthread_mutex_unlock(mutex);
    return rnti;
}
