    struct list_node *next;
} list_node_t;

// Lock for thread safety
pthread_mutex_t lock;

void init_list() {
    // Initialize list with a preallocated capacity of 10,000 elements
    size_t capacity = 10000;
    list_node_t *head = mmap(NULL, capacity * sizeof(list_node_t), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (head == MAP_FAILED) {
        // Handle memory allocation failure
    }
    head->next = NULL;
}

size_t num_unique_rtnis() {
    size_t unique_count = 0;
    list_node_t *current = head->next;
    while (current != NULL) {
        bool found_duplicate = false;
        list_node_t *search = current;
        do {
            if (search->data.rnti == current->data.rnti) {
                found_duplicate = true;
                break;
            }
            search = search->next;
        } while (search != current);
        if (!found_duplicate) {
            unique_count++;
        }
        current = current->next;
    }
    return unique_count;
}

void add_element(const NFAPI_CRCI_PDU_T *pdu) {
    pthread_mutex_lock(&lock);

    // Batch processing: add up to 1000 elements at a time
    list_node_t *batch_start = head->next;
    size_t batch_count = 0;

    while (batch_count < 1000 && batch_start != NULL) {
        if (batch_start->data.rnti == pdu->rnti) {
            // Update CRCFLAG for the existing element
            batch_start->data.crc_indication.crcflag = !batch_start->data.crc_indication.crcflag;
        } else {
            // Add a new element to the batch
            list_node_t *new_node = (list_node_t *)malloc(sizeof(list_node_t));
            if (new_node == NULL) {
                // Handle memory allocation failure
            }
            new_node->data = *pdu;
            new_node->next = batch_start;

            batch_start = new_node;
        }

        batch_count++;
        batch_start = batch_start->next;
    }

    if (batch_count > 0) {
        // Compact the list if it exceeds 80% of its allocated capacity
        if ((head->next - batch_start) * sizeof(list_node_t) >= 0.8 * mmap_size()) {
            compact_list();
        }
    }

    pthread_mutex_unlock(&lock);
}

void remove_element_by_rnti(RNTI rnti) {
    pthread_mutex_lock(&lock);

    list_node_t *current = head->next;
    list_node_t *prev = NULL;

    while (current != NULL && current->data.rnti == rnti) {
        if (prev == NULL) {
            head->next = current->next;
        } else {
            prev->next = current->next;
        }
        free(current);
        current = prev->next;
    }

    pthread_mutex_unlock(&lock);
}

