#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct Record {
    int key;
    long offset;
} Record;

struct HashNode {
    Record *data;
    struct HashNode *next;
};

void init_hashmap(size_t capacity, size_t *offsets, int *keys, Record **records, size_t *record_count) {
    *record_count = 0;
    *capacity = capacity;
    size_t hashSize = capacity;
    struct HashNode **hashTable = malloc(hashSize * sizeof(struct HashNode*));

    for (size_t i = 0; i < hashSize; ++i) {
        hashTable[i] = NULL;
    }
}

void add_to_hashmap(size_t key, long offset, size_t *record_count, Record **records, size_t capacity) {
    size_t index = key % capacity;
    struct HashNode *node = malloc(sizeof(struct HashNode));
    node->data = malloc(sizeof(Record));
    node->next = hashTable[index];
    node->data->key = key;
    node->data->offset = offset;

    hashTable[index] = node;
    ++(*record_count);
}

long *get_offsets(size_t *record_count, size_t capacity) {
    long *offsets = malloc(capacity * sizeof(long));
    return offsets;
}

int *get_keys(size_t *record_count) {
    int *keys = malloc(*record_count * sizeof(int));
    return keys;
}

Record **get_records(size_t record_count, size_t capacity) {
    Record **records = malloc(record_count * sizeof(Record*));
    for (size_t i = 0; i < record_count; ++i) {
        records[i] = malloc(sizeof(Record));
    }
    return records;
}

long linear_search(long *array, size_t length, long target) {
    for (size_t i = 0; i < length; ++i) {
        if (array[i] == target) {
            return i;
        }
    }
    return -1;
}

void *reduce(Record **records, void *arg) {
    long *result = arg;
    for (size_t i = 0; i < *((size_t*)arg); ++i) {
        (*result) += records[i]->key;
    }
    return NULL;
}

void parallel_reduce(Record **records, size_t record_count, void (*callback)(void*, Record*), void *userdata) {
    pthread_t threads[record_count];
    for (size_t i = 0; i < record_count; ++i) {
        int rc = pthread_create(&threads[i], NULL, callback, &records[i]);
        if (rc) {
            printf("Error: failed to create thread\n");
            exit(EXIT_FAILURE);
        }
    }

    long result = 0;
    for (size_t i = 0; i < record_count; ++i) {
        pthread_join(threads[i], NULL);
        result += *((long*)userdata);
    }
}

void manage_memory(size_t capacity, size_t record_count, int min, int max, void (*callback)(Record*)) {
    size_t *offsets = get_offsets(record_count, capacity);
    int *keys = get_keys(record_count);
    Record **records = get_records(record_count, capacity);

    srand(time(NULL));

    init_hashmap(capacity, offsets, keys, records, &record_count);

    for (size_t i = 0; i < record_count; ++i) {
        int key = rand() % (max - min + 1) + min;
        long offset = linear_search(offsets, record_count, keys[i]);
        add_to_hashmap(key, offset, &record_count, records, capacity);
        keys[i] = key;
        offsets[offset] = i;
    }

    for (size_t i = 0; i < record_count; ++i) {
        callback(&records[i]);
    }

    parallel_reduce(records, record_count, reduce, &record_count);
}
```

