['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <time.h>
#include <pthread.h>
#include <sys/mman.h>

#define MAX_RECORDS 1024
#define MAX_DEPTH 32
#define BUFFER_SIZE 256
#define RANDOM_RANGE 1000

typedef struct Record {
    int value;
    char buffer[BUFFER_SIZE];
    struct Record* parent;
    struct Record** children;
    pthread_mutex_t mutex;
    size_t ref_count;
} Record;

int initialize_data(Record** records, long* offsets, int* keys, char** strings) {
    if (offsets == NULL || keys == NULL || records == NULL || strings == NULL) {
        perror("Invalid input");
        return -1;
    }

    size_t total_records = sizeof(offsets) / sizeof(long);
    if (total_records > MAX_RECORDS) {
        printf("Too many records.\n");
        return -2;
    }

    for (size_t i = 0; i < total_records; ++i) {
        if (offsets[i] >= total_records || keys[i] >= MAX_DEPTH) {
            printf("Invalid offset or depth.\n");
            return -3;
        }
    }

    srand(time(NULL));
    Record* root = mmap(0, sizeof(Record), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    *records = root;

    for (size_t i = 0; i < total_records; ++i) {
        Record* record = &((Record*)aligned_alloc(64, sizeof(Record)))[offsets[i]];
        record->value = rand() % RANDOM_RANGE + 1;
        strcpy(record->buffer, "HELLO");
        record->parent = NULL;
        record->children = malloc((MAX_DEPTH - 1) * sizeof(Record*));
        for (size_t j = 0; j < MAX_DEPTH - 1; ++j) {
            record->children[j] = NULL;
        }
        pthread_mutex_init(&record->mutex, NULL);
        record->ref_count = 1;

        if (offsets[i] > 0) {
            Record* parent = &((Record*)aligned_alloc(64, sizeof(Record)))[offsets[i] - 1];
            parent->ref_count++;
            parent->children[keys[i]] = record;
            record->parent = parent;
        }
    }

    return 0;
}
```
