Node* generateAndSecurePduList(int size, uint32_t *UE_IDS, uint32_t *RNTIs, char **CRC_INDICATION_DATA, const EVP_CIPHER_CTX *encryptionKey, enum encryptionMode mode) {
    Node* head = NULL;
    Node* current = NULL;
    for(int i = 0; i < size; ++i) {
        PDU pdu = {UE_IDS[i], RNTIs[i], CRC_INDICATION_DATA[i], NULL};
        if(!head) {
            head = malloc(sizeof(Node));
            current = head;
            current->pdu = pdu;
            current->next = NULL;
        } else {
            current->next = malloc(sizeof(Node));
            current = current->next;
            current->pdu = pdu;
            current->next = NULL;
        }
        encryptPDU(&(current->pdu), encryptionKey, mode);
