            break;
        case EDE:
            // Use EDE encryption
            break;
        case EDE3:
            // Use EDE3 encryption
            break;
        case CFB:
            // Use CFB encryption
            break;
        case NONE:
            // Do not encrypt
            pdu->cipher = NULL;
            break;
        default:
            fprintf(stderr, "Invalid encryption mode\n");
            exit(EXIT_FAILURE);
    }

    EVP_CIPHER *cipher = EVP_EncryptInit(ctx);
    EVP_CIPHER_CTX *enc_ctx = EVP_CIPHER_CTX_new();
    EVP_CIPHER_CTX_copy(enc_ctx, ctx);
    char encrypted[len + EVP_MAX_IV_LENGTH];
