    if(encryptedLen == -1) {
        fprintf(stderr, "Error during encryption\n");
        exit(EXIT_FAILURE);
    }
    pdu->cipher = cipher;
    pdu->CRC_INDICATION_DATA = malloc(encryptedLen + 1);
    memcpy(pdu->CRC_INDICATION_DATA, encrypted, encryptedLen);
    pdu->CRC_INDICATION_DATA[encryptedLen] = '\0';
