typedef struct _mac_pdu_manager {
    MAC_PDU** data; // Pointer to array of MAC_PDU pointers
    size_t capacity; // Current capacity of the dynamic array
    size_t count; // Number of elements in the dynamic array
    pthread_mutex_t mutex; // Synchronization mechanism for updating the array concurrently
} MacPduManager;

MacPduManager* mac_pdu_manager_create(size_t initial_capacity) {
    MacPduManager* manager = malloc(sizeof(MacPduManager));
    if (!manager) return NULL;

    manager->capacity = initial_capacity;
    manager->count = 0;
    manager->data = calloc(initial_capacity, sizeof(MAC_PDU*));
    if (!manager->data) {
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void mac_pdu_manager_destroy(MacPduManager* manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->count; ++i) free(manager->data[i]);
    free(manager->data);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

MAC_PDU* mac_pdu_manager_get(MacPduManager* manager, size_t index) {
    if (index >= manager->count) return NULL;
    pthread_mutex_lock(&manager->mutex);
    MAC_PDU* result = manager->data[index];
    pthread_mutex_unlock(&manager->mutex);
    return result;
}

void mac_pdu_manager_update(MacPduManager* manager, size_t index, void* payload) {
    if (index >= manager->count) return;
    pthread_mutex_lock(&manager->mutex);
    MAC_PDU* pdu = manager->data[index];
