#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <semaphore.h>
#include <sys/mman.h>
#include <atomic>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU;

struct ue_info_manager {
    std::atomic<size_t> capacity;
    size_t num_entries;
    NFAPI_CRC_INDICATION_PDU* buffer;
    pthread_mutex_t mutex;
    sem_t capacity_sem;
    void (*capacity_callback)(size_t);
    void (*log_func)(const char*, ...);
};

void ue_info_manager_init(struct ue_info_manager* manager, size_t expected_entries, void (*cap_cb)(size_t), void (*log_f)(const char*, ...)) {
    manager->capacity = 0;
    manager->num_entries = 0;
    manager->buffer = nullptr;
    pthread_mutex_init(&manager->mutex, nullptr);
    sem_init(&manager->capacity_sem, 0, INT_MAX);
    manager->capacity_callback = cap_cb;
    manager->log_func = log_f;

    if (expected_entries > 0)
        manager->capacity.store(expected_entries * 2);
}

void* aligned_alloc(size_t alignment, size_t size) {
    void* result = mmap(nullptr, size + alignment - 1, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (result == MAP_FAILED)
        return nullptr;
    size_t aligned = ((size_t)result + alignment - 1) & ~(alignment - 1);
    return realloc(result, aligned - size + size);
}

bool ue_info_manager_push(struct ue_info_manager* manager, const NFAPI_CRC_INDICATION_PDU& data) {
    if (!manager->buffer) {
        // initialize buffer
        size_t capacity = manager->capacity.load();
        manager->buffer = static_cast<NFAPI_CRC_INDICATION_PDU*>(aligned_alloc(sizeof(NFAPI_CRC_INDICATION_PDU), capacity * sizeof(NFAPI_CRC_INDICATION_PDU)));
        if (!manager->buffer) {
            manager->log_func("Failed to allocate buffer for ue_info_manager", 0);
            return false;
        }
    }

    bool success = true;

    pthread_mutex_lock(&manager->mutex);
    if (manager->num_entries >= manager->capacity.load()) {
        size_t new_capacity = manager->capacity * 2;
        manager->buffer = static_cast<NFAPI_CRC_INDICATION_PDU*>(aligned_alloc(sizeof(NFAPI_CRC_INDICATION_PDU), new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU)));
        if (!manager->buffer) {
            success = false;
            manager->log_func("Failed to expand buffer for ue_info_manager", 0);
        } else {
            if (manager->capacity_callback)
                manager->capacity_callback(new_capacity);
            manager->capacity.store(new_capacity);
        }
    }

    if (success) {
        manager->buffer[manager->num_entries] = data;
        manager->num_entries++;
    }

    pthread_mutex_unlock(&manager->mutex);

    return success;
}
```

This code defines a `ue_info_manager` struct that manages an array of `NFAPI_CRC_INDICATION_PDU_T` structures. The manager initializes with a given expected number of entries and provides a method `ue_info_manager_push()` to add new elements. The function uses a lock-free data structure (array) to minimize contention and ensure efficient performance in high-concurrency scenarios, while also handling memory allocation failures gracefully.

The manager integrates with an external logging framework to log relevant events, ensuring consistency and reliability across different components of the system. It handles unexpected input gracefully by returning false when it encounters invalid RNTI values or malformed `RX_UE_INFORMATION_TAG` instances.

To minimize memory fragmentation and reduce cache misses, the code uses aligned allocation for both buffer initialization and expansion. The function also provides a capacity callback to dynamically adjust its capacity based on the expected number of entries, allowing the system to scale efficiently as the number of entries grows.']

