#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    int RNTI;
    CRC_INDICATION_REL8_TAG crcIndication;
} NFAPI_CRC_INDICATION_PDU;

typedef void (*PF_PROCESS_ELEMENT)(NFAPI_CRC_INDICATION_PDU *data);

void create_and_populate_list(size_t max_size, PF_PROCESS_ELEMENT process_callback, int rnti_filter) {
    NFAPI_CRC_INDICATION_PDU **head = (NFAPI_CRC_INDICATION_PDU**) malloc(max_size * sizeof(NFAPI_CRC_INDICATION_PDU*));
    if (!head) {
        printf("Memory allocation failed\n");
        return;
    }

    size_t current_size = 0;
    for (size_t i = 0; i < max_size; ++i) {
        NFAPI_CRC_INDICATION_PDU *data = (NFAPI_CRC_INDICATION_PDU*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
        if (!data) {
            printf("Memory allocation failed\n");
            break;
        }

        data->tag.presenceFlag = true;
        data->tag.tagValue = RX_UE_INFORMATION_TAG_CRC_INDICATION_REL8;
        data->RNTI = i + 1;
        data->crcIndication.crcFlag = rand() % 2;

        if (current_size > 0 && i - current_size >= max_size / 2) {
            size_t j = 0;
            for (; j < current_size - 1; ++j)
                head[j] = head[j + 1];
            free(head[current_size - 1]);
            current_size--;
        }

        if (rnti_filter && data->RNTI != rnti_filter) {
            free(data);
            continue;
        }

        head[current_size++] = data;
    }

    for (size_t i = 0; i < current_size; ++i) {
        if (process_callback)
            process_callback(&head[i][0]);
    }
}
```

