    NR_CQI_REPORT_PDU_T data;
    struct list_node *next;
};

// Thread-local head and tail pointers
thread_local struct list_node _list_head[2];
thread_local struct list_node _list_tail[2];

// Atomic counters for the number of elements in each thread's list
__atomic_uint count = 0;

// Macro to align a pointer to a cache line boundary
#define ALIGN(ptr) (((ptr)+63)&~63)

void insert_at_head(NR_CQI_REPORT_PDU_T data) {
    struct list_node *node = (struct list_node *)ALIGN(malloc(sizeof(struct list_node)));
    node->data = data;
    node->next = _list_head[__sync_val_compare_and_swap(&(_list_head[0]), &(_list_head[1]), node)];
    __atomic_fetch_add(&count, 1);
}

void insert_at_tail(NR_CQI_REPORT_PDU_T data) {
    struct list_node *node = (struct list_node *)ALIGN(malloc(sizeof(struct list_node)));
    node->data = data;
    node->next = NULL;

    node->next = _list_tail[__sync_val_compare_and_swap(&(_list_tail[0]), &(_list_tail[1]), node)];
    if (_list_head[0]) { // List is non-empty
        _list_tail[0]->next = node;
        _list_tail[0] = node;
    } else { // Initialize list with the new node
        _list_head[0] = node;
        _list_tail[0] = node;
    }

    __atomic_fetch_add(&count, 1);
}

void insert_in_middle(NR_CQI_REPORT_PDU_T data) {
