void delete_from_head() {
    if (_list_head[0]) {
        struct list_node *temp = _list_head[0];
        _list_head[0] = temp->next;
        free(temp);
        __atomic_fetch_sub(&count, 1);
    }
}

void delete_from_tail() {
    if (_list_head[0]) { // List is non-empty
        struct list_node *current = _list_head[0];
        while (current->next != NULL) current = current->next;
        current->next = NULL;
        free(current);
        _list_tail[0] = _list_head[0];
        __atomic_fetch_sub(&count, 1);
    }
}

void delete_from_index(size_t index) {
    if (index >= count || index < 0) return; // Invalid index

    struct list_node *current = _list_head[0];
    size_t i = 0;
    while (i++ < index && current != NULL) current = current->next;

    if (current == NULL) return; // Element not found

    struct list_node *temp = current;
    temp->next = current->next;
    free(temp);
    __atomic_fetch_sub(&count, 1);
}

void traverse() {
    struct list_node *current = _list_head[0];
    while (current != NULL) {
        // Process each element in the list
        current = current->next;
    }
}
