// Define the structure NFAPI_L1_API_RACH_CONFIG
typedef struct {
    uint8_t cell_id;
    uint8_t cyclic_shift;
    // Add more fields as needed...
} NFAPI_L1_API_RACH_CONFIG;

// Function to initialize the array of structures
NFAPI_L1_API_RACH_CONFIG* init_config_array(size_t N, uint32_t seed) {
    size_t aligned_N = align(N, sizeof(NFAPI_L1_API_RACH_CONFIG)); // Ensure proper alignment for optimal access times
    NFAPI_L1_API_RACH_CONFIG* configs = (NFAPI_L1_API_RACH_CONFIG*)posix_memalign(NULL, alignof(NFAPI_L1_API_RACH_CONFIG), aligned_N * sizeof(NFAPI_L1_API_RACH_CONFIG));
    if (!configs) { // Handle memory allocation failures
        perror("Memory allocation failed");
        return NULL;
    }

    srand(seed); // Set seed for random number generation

    time_t rawtime;
    struct tm* timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("Initializing config array at: %s\n", timestamp);

    for (size_t i = 0; i < aligned_N; ++i) {
        size_t cell_id = (size_t)i;
        NFAPI_L1_API_RACH_CONFIG* config = &configs[i];

        // Populate with unique cell ID and random cyclic shift within allowed range
        config->cell_id = cell_id;
        config->cyclic_shift = rand() % MAX_CYCLIC_SHIFT; // Adjust the MAX_CYCLIC_SHIFT constant as needed for your application

        printf("Config %lu: Cell ID=%u, Cyclic Shift=%u\n", i + 1, config->cell_id, config->cyclic_shift);
    }

    return configs;
}

// Helper function to ensure proper alignment of memory
size_t align(size_t size, size_t alignment) {
    if (alignment > size)
        return size;
    return ((size + alignment - 1) / alignment) * alignment;
}
