static pthread_mutex_t resource_mutex = PTHREAD_MUTEX_INITIALIZER;
static size_t memory_budget = max_memory;
static size_t num_structures = 0;
static NFAPI_CRC_INDICATION_PDU_T *structures;

void log(const char *message) {
    // Implement logging mechanism here, e.g., writing to a file or sending messages to a log server
}

int allocate_structures() {
    if (num_structures >= NUM_STRUCTURES || memory_budget < sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_structures) {
        // Resource exhaustion or exceeding the memory budget, log an error and return failure
        log("Resource Exhaustion: Failed to allocate structures");
        return 0;
    }

    pthread_mutex_lock(&resource_mutex);
    if (num_structures >= NUM_STRUCTURES || memory_budget < sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_structures + sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        // Attempting to exceed the memory budget while holding the mutex, log an error and return failure
        log("Mutex Locked: Failed to allocate structures");
        pthread_mutex_unlock(&resource_mutex);
        return 0;
    }

    structures = realloc(structures, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (num_structures + 1));
    if (!structures) {
        // Failed to dynamically allocate memory, log an error and return failure
        log("Failed to allocate structures");
        pthread_mutex_unlock(&resource_mutex);
        return 0;
    }

    num_structures++;
    pthread_mutex_unlock(&resource_mutex);

