typedef struct {
    int TX_POWER_LEVEL;
    int RECEIVED_SIGNAL_STRENGTH;
    int FRAME_TYPE;
} PHY_FRAME_STATS;

int allocate_phy_frame_stats(size_t N, size_t* total, PHY_FRAME_STATS** data, void(*external_data)(PHY_FRAME_STATS*)) {
    PHY_FRAME_STATS* stats = NULL;
    size_t current_size = N;
    bool consecutive_same_type = false;
    *total = 0;

    if (!(stats = malloc(current_size * sizeof(PHY_FRAME_STATS)))) {
        fprintf(stderr, "Error: Allocation failed for initial size.\n");
        return 0;
    }

    for (size_t i = 0; i < current_size - 1; ++i) {
        if ((i == 0 || stats[i].FRAME_TYPE != stats[i + 1].FRAME_TYPE) && !consecutive_same_type) {
            consecutive_same_type = false;
        } else if (consecutive_same_type) {
            size_t new_size = current_size * 2;
            PHY_FRAME_STATS* temp = realloc(stats, new_size * sizeof(PHY_FRAME_STATS));

            if (!temp) {
                fprintf(stderr, "Error: Allocation failed during resizing.\n");
                free(stats);
                return 0;
            }

            stats = temp;
            current_size = new_size;
        }

        (*external_data)(&stats[i]); // Integrate external data source
        ++(*total);
        consecutive_same_type = (stats[i].FRAME_TYPE == stats[i + 1].FRAME_TYPE);
    }

    if(consecutive_same_type) {
        fprintf(stderr, "Error: Two consecutive structures have the same FRAME_TYPE.\n");
        free(stats);
        return 0;
    }

    *data = stats;
    return *total;
}
