use std::fs::File;
use std::io::{BufRead, BufReader};
use std::os::unix::prelude::ExitStatusExt;
use std::process::Command;
use std::sync::Lazy;
use std::time::{Instant, Duration};
use rustc_driver::{run, catch_with_exit_code};

static ICEHOOK: Lazy<Option<Box<dyn FnMut(String) + Send>> = Lazy::new(|| {
    // Initialize your custom logging hook here
    None
});

fn compile_and_measure(source: &str) -> Result<(), Box<dyn std::error::Error>> {
    let start = Instant::now();
    let mut command = Command::new("rustc");

    // Add custom logging hook and other options here
    command.arg("-").stdin(std::process::Stdio::from_ref(&mut BufReader::new(source.as_bytes())))
        .output_mut(|out, err, _| {
            ICEHOOK.with(|h| h.as_ref().map(|f| f(*out)));
            out.close();
        })
        .spawn()?;

    let exit_code = catch_with_exit_code(move || command.wait())?;

    let time_taken = start.elapsed();
    println!("Compilation took {} seconds", time_taken.as_secs_f64());

    // Calculate resident set size before and after compilation
    let mem_usage = |cmd: &Command| {
        let mut pre_resident_set_size = 0;
        unsafe { libc::mallopt(0, -1) };
        let pre = libc::mallctl("MALLSTAT", std::ptr::null_mut(), &mut pre_resident_set_size as *mut _, sizeof(pre_resident_set_size));
        if pre != 0 {
            unsafe { libc::perror("mallctl"); }
            return;
        }

        let status = cmd.get_status().unwrap();
        let post = status.used_memory() as u64;
        println!("Resident set size before compilation: {}", pre_resident_set_size);
        println!("Resident set size after compilation: {}", post);
    };

    mem_usage(&command);

    if exit_code.success() {
        Ok(())
    } else {
        early_error(format!("Rust compiler failed with exit code {}", exit_code));
        Err("Compilation failure")
    }
}
