    structures = calloc(MAX_STRUCTURES, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!structures) {
        perror("Calloc failed");
        exit(1);
    }

    num_structures = MAX_STRUCTURES;
}

void deinit_structures() {
