    free(structures);
    structures = NULL;
    num_structures = 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_structure() {
    pthread_mutex_lock(&structures_mutex);
    if (num_structures == 0) {
        init_structures();
    }

    NFAPI_CRC_INDICATION_PDU_T *structure = &structures[--num_structures];
    structure->tag = num_structures;
    structure->rnti = rand() % RNTI_RANGE;
    structure->crc_indication_tag.value = (rand() % 256) + ((rand() % 256) << 8);
    structure->crcflag = (rand() % 2) == 0 ? true : false;

    pthread_mutex_unlock(&structures_mutex);
    return structure;
}

void reinitialize_structures() {
    if (num_structures > 0) deinit_structures();
    init_structures();
}

