    *indications = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*indications == NULL)
        return -2; // Failed to allocate memory

    for (size_t i = 0; i < N; ++i) {
        pthread_mutex_lock(&mutex);
        RFAPI_UE_INFORMATION_TAG ue_info = get_ue_information();
        if (!ue_info.tag_present) {
