    (*env)->CallVoidMethod(env, channelObject, connectMethod, socketAddress);

    // Connection handling and data transfer logic goes here (not provided)

    // Call the Java method to disconnect from the remote server
    disconnectMethod = (*env)->GetMethodID(env, channelClass, "disconnect", "()V");
    if (disconnectMethod == NULL) {
        return; // Method not found
    }
    (*env)->CallVoidMethod(env, channelObject, disconnectMethod);
}

void connectionErrorHandler(JNIEnv *env, jobject channelObject, jint errorCode) {
    jclass exceptionClass = (*env)->FindClass(env, "java/lang/Exception");
    jmethodID constructor = (*env)->GetMethodID(env, exceptionClass, "<init>", "(Ljava/lang/String;)V");
    jstring errorMessage = (*env)->NewStringUTF(env, "Connection error: " + errorCode);

    jobject exceptionObject = (*env)->NewObject(env, exceptionClass, constructor, errorMessage);
    jclass runtimeExceptionClass = (*env)->FindClass(env, "java/lang/RuntimeException");
    jmethodID throwMethod = (*env)->GetStaticMethodID(env, runtimeExceptionClass, "throw", "(Ljava/lang/Throwable;)V");
    (*env)->CallStaticVoidMethod(env, runtimeExceptionClass, throwMethod, exceptionObject);
}

