['```c
#include <stdio.h>
#include <time.h>
#include <pthread.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct {
    time_t timestamp;
    int id;
    double value;
    double weight;
} Transaction;

pthread_mutex_t metric_lock = PTHREAD_MUTEX_INITIALIZER;
int processed_transactions = 0;
double total_weighted_sum = 0.0;
double transactions_per_second = 0.0;
double last_update_time = 0.0;

void filter_and_process(Transaction t) {
    double current_time = time(NULL);
    if (current_time - t.timestamp > 5) return;

    double window_time = current_time - std::max(t.timestamp, last_update_time);
    if (window_time < 3) return;

    total_weighted_sum += t.value * t.weight;
    processed_transactions++;

    double frequency = processed_transactions / window_time;
    transactions_per_second = frequency > transactions_per_second ? frequency : transactions_per_second;

    if (window_time >= 3) {
        last_update_time = std::max(t.timestamp, last_update_time);
        double average_weighted_sum = total_weighted_sum / processed_transactions;
        printf("Transaction with ID %d and value %.2f has the highest weighted sum.\n", t.id, t.value * t.weight);
        printf("Average weighted sum: %.2f\n", average_weighted_sum);
        printf("Transactions per second: %.2f\n", transactions_per_second);
    }

    pthread_mutex_lock(&metric_lock);
    total_weighted_sum -= t.value * t.weight;
    processed_transactions--;
    pthread_mutex_unlock(&metric_lock);
}

void* read_transactions(void* arg) {
    int sock = *(int*)arg;
    char buffer[1024];
    Transaction transaction;

    while (true) {
        memset(&transaction, 0, sizeof(Transaction));
        ssize_t bytes_read = recv(sock, buffer, sizeof(buffer), 0);
        if (bytes_read <= 0) break;

        transaction.timestamp = time(NULL);
        memcpy(&transaction.id, buffer, sizeof(int));
        memcpy(&transaction.value, buffer + sizeof(int) + 1, sizeof(double));
        memcpy(&transaction.weight, buffer + sizeof(int) + 9, sizeof(double));

        filter_and_process(transaction);
    }

    close(sock);
    return NULL;
}

int main() {
    int server_socket = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

    bind(server_socket, (struct sockaddr*)&server_addr, sizeof(server_addr));
    listen(server_socket, 5);

    while (true) {
        int client_socket = accept(server_socket, NULL, NULL);
        pthread_t thread;
        pthread_create(&thread, NULL, read_transactions, &client_socket);
    }

    return 0;
}
```
This code sets up a simple TCP server that listens for incoming transactions on port 8080. The `read_transactions()` function handles reading the transactions from the network stream and calling the `filter_and_process()` function to filter and process them. The main function initializes the socket, binds it to an address, and begins accepting connections in a loop. Keep in mind that this is a minimal example, and you may need to modify it for your specific use case.']

