    if (*head == NULL) {
        *head = new_node;
    } else {
        new_node->next = *head;
        *head = new_node;
    }
}

NODE* get_node_at(NODE* head, size_t index) {
    if (index >= 0) {
        for (size_t i = 0; i < index && head != NULL; ++i)
            head = head->next;
    } else {
        for (size_t i = list_length(head) + index; i > 0 && head != NULL; --i)
            head = head->next;
    }
    return head;
}

size_t list_length(NODE* head) {
    size_t length = 0;
    for (NODE* current = head; current != NULL; current = current->next)
        ++length;
    return length;
}

void check_integrity(const NODE* node, const size_t index) {
    if (node == NULL || list_length(node) != index + 1) {
