    for (size_t i = 0; i < capacity; ++i)
        list[i] = NULL;
    return list;
}

void resize_list(NODE** list, size_t new_capacity) {
    NODE** new_list = mem_alloc(new_capacity * sizeof(NODE*));
    for (size_t i = 0; i < pool_capacity && i < new_capacity; ++i) {
        if (list[i] != NULL)
            new_list[i] = list[i];
    }
    pool_capacity = new_capacity;
}

void free_list(NODE** list) {
    for (size_t i = 0; i < pool_capacity; ++i)
        mem_free(list[i]);
    mem_free(list);
}

NFAPI_CRC_INDICATION_PDU* create_pdus(size_t count, size_t data_size) {
