void enqueue(List *list, NFAPI_CRCI_INDICATION_PDU_T data) {
    Node* new_node = create_node(data);
    if (!new_node) return; // out of memory error handling

    pthread_mutex_lock(&list->lock);

    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    ++(list->current_count);

    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRCI_INDICATION_PDU_T dequeue(List *list) {
    if (list->head == NULL) return (NFAPI_CRCI_INDICATION_PDU_T){0};

    pthread_mutex_lock(&list->lock);

    Node* temp = list->head;
    NFAPI_CRCI_INDICATION_PDU_T data = temp->data;
    list->head = temp->next;

    if (list->head == NULL) list->tail = NULL;
    free(temp);
    --(list->current_count);

    pthread_mutex_unlock(&list->lock);

