typedef struct MAC_CONTEXT_T {
    uint64_t rnti;
    uint16_t lcid;
    MAC_TRANSACTION_RECORD_T* transaction_record;
};

typedef struct MAC_TRANSACTION_RECORD_T {
    void* payload;
    size_t payload_size;
    // metadata fields...
};

static sem_t list_mutex;
static unsigned long long num_contexts = 0;
static const int MAX_CONTEXTS = INT_MAX / sizeof(MAC_CONTEXT_T*);
static MAC_CONTEXT_T** context_list = calloc(MAX_CONTEXTS, sizeof(MAC_CONTEXT_T*));

void init_mutex() {
    if (sem_init(&list_mutex, 0, 1) != 0) {
        fprintf(stderr, "Failed to initialize mutex: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void destroy_mutex() {
    sem_destroy(&list_mutex);
}

MAC_CONTEXT_T* create_context(uint64_t rnti, uint16_t lcid) {
    MAC_CONTEXT_T* context;

    // Critical section to ensure thread safety
    sem_wait(&list_mutex);

    if (num_contexts >= MAX_CONTEXTS) {
        fprintf(stderr, "Too many contexts. Reached limit of %d.\n", MAX_CONTEXTS);
        sem_post(&list_mutex);
        return NULL;
    }

    context = calloc(1, sizeof(MAC_CONTEXT_T));
    if (!context) {
        fprintf(stderr, "Memory allocation failure for context.\n");
        sem_post(&list_mutex);
        return NULL;
    }

    context->rnti = rnti;
    context->lcid = lcid;

    // Dynamically allocate transaction_record here
    context->transaction_record = calloc(1, sizeof(MAC_TRANSACTION_RECORD_T));
    if (!context->transaction_record) {
        fprintf(stderr, "Memory allocation failure for transaction_record.\n");
        free(context);
        sem_post(&list_mutex);
        return NULL;
    }

    num_contexts++;
    context_list[num_contexts - 1] = context;

    sem_post(&list_mutex);

    printf("Created context with RNTI: %llu, LCID: %d\n", rnti, lcid);

    return context;
}

void destroy_context(MAC_CONTEXT_T* context) {
    // Critical section to ensure thread safety
    sem_wait(&list_mutex);

    if (context == NULL || context_list == NULL || num_contexts <= 0) {
        fprintf(stderr, "Invalid context or empty list.\n");
        sem_post(&list_mutex);
        return;
    }

    for (unsigned long i = 1; i <= num_contexts; ++i) {
        if (context_list[i] == context) {
            memset(context, 0, sizeof(MAC_CONTEXT_T));
            free(context->transaction_record);
            free(context);

            // Shift the array down and free the last element, if any
            for (unsigned long j = i; j < num_contexts; ++j) {
                context_list[j - 1] = context_list[j];
            }

            context_list[num_contexts - 1] = NULL;
            num_contexts--;
            break;
        }
    }

    sem_post(&list_mutex);
}
