A simple parser could look like this:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

typedef struct {
    char *section;
    char **keys;
    int num_keys;
} INI_CONFIG;

INI_CONFIG* ini_parse(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("fopen failed");
        exit(EXIT_FAILURE);
    }

    INI_CONFIG *config = malloc(sizeof(INI_CONFIG));
    char line[1024];
    char key[1024], value[1024];

    config->section = NULL;
    config->keys = NULL;
    config->num_keys = 0;

    while (fgets(line, sizeof(line), file)) {
        if (strncmp(line, "[", 1) == 0) {
            int len = strlen(line);
            char *endptr = line + len - 1;
            while (*endptr != '\n' && endptr > line) {
                if (*endptr == ']') break;
                --endptr;
            }
            config->section = strndup(line, endptr - line);
        } else if (strncmp(line, "=", 1) != 0 || config->section == NULL) continue;

        int len = strlen(line);
        char *equals_pos = strchr(line, '=');
        if (!equals_pos) continue;

        int key_len = equals_pos - line + 1;
        char *key_start = strndup(line, key_len);
        memmove(key, key_start, key_len);
        key[key_len] = '\0';
        free(key_start);

        int value_len = len - key_len + 1;
        char *value_start = equals_pos + 1;
        memmove(value, value_start, value_len);
        value[value_len] = '\0';

        config->keys = realloc(config->keys, sizeof(char *) * (++config->num_keys));
        config->keys[config->num_keys - 1] = strdup(key);
        config->keys[config->num_keys - 1][strlen(key)] = '\0';
        config->keys[config->num_keys - 1] = strdup(value);
    }

    fclose(file);
    return config;
}
```']

