typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG cindTag;
    uint8_t crcFlag;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_STRUCTURE_SIZE (1024 * 1024) // Maximum size limit in bytes
static pthread_mutex_t memoryPoolMutex = PTHREAD_MUTEX_INITIALIZER;
static bool memoryPoolIsFull = false;
static size_t memoryPoolSize = 0;
static NFAPI_CRC_INDICATION_PDU_T* memoryPool = NULL;

int allocateAndPopulatePdus(NFAPI_CRC_INDICATION_PDU_T** pdus, size_t numPdus, const RNTI* allowedRNTIs, size_t allowedRNTIsSize) {
    if (!pdus || !numPdus) {
        return -1; // Invalid input
    }

    if (memoryPoolIsFull && numPdus > memoryPoolSize) {
        return -2; // Insufficient resources
    }

    size_t totalSize = sizeof(NFAPI_CRC_INDICATION_PDU_T) * numPdus;

    if (totalSize > MAX_STRUCTURE_SIZE || (allowedRNTIs && allowedRNTIsSize > 0 && totalSize > MAX_STRUCTURE_SIZE / allowedRNTIsSize)) {
        return -3; // Exceeded maximum size limit
    }

    NFAPI_CRC_INDICATION_PDU_T* pdusToAllocate = NULL;
    size_t allocatedCount = 0;

    pthread_mutex_lock(&memoryPoolMutex);

    if (!memoryPoolIsFull) {
        void* tempMemoryPool = realloc(memoryPool, memoryPoolSize + totalSize);
        if (!tempMemoryPool) {
            pthread_mutex_unlock(&memoryPoolMutex);
            return -2; // Insufficient resources
        }
        memoryPool = tempMemoryPool;
        memoryPoolSize += totalSize;
    } else {
        pdusToAllocate = malloc(totalSize);
        if (!pdusToAllocate) {
            pthread_mutex_unlock(&memoryPoolMutex);
            return -2; // Insufficient resources
        }
        allocatedCount = totalSize;
    }

    pthread_mutex_unlock(&memoryPoolMutex);

    for (size_t i = 0; i < numPdus; ++i) {
        pdus[i]->tag = generateTag(); // Implement generation of RX_UE_INFORMATION_TAG
        pdus[i]->rnti = (allowedRNTIs && allowedRNTIsSize > i) ? allowedRNTIs[i] : rand() % 0xFFFFFFFF; // Use provided RNTI or generate random one
        pdus[i]->cindTag = generateCindTag(); // Implement generation of CRC_INDICATION_REL8_TAG
        pdus[i]->crcFlag = rand() % 2; // Set CRCFLAG randomly
    }

    if (memoryPoolIsFull) {
        free(pdusToAllocate);
    }

    return 0;
}

// Implement functions for generating RX_UE_INFORMATION_TAG, CRC_INDICATION_REL8_TAG and logging
