#include <pthread.h>
#include <stdlib.h>
#include <stdbool.h>
#include <semaphore.h>
#include <NFAPI_MESSAGE_PDU_T.h> // Custom structure definition

typedef struct message_queue {
    NFAPI_MESSAGE_PDU_T *data;
    size_t capacity;
    size_t count;
    sem_t mutex;
    sem_t not_empty;
    sem_t not_full;
} message_queue_t;

message_queue_t *create_message_queue(size_t capacity) {
    message_queue_t *queue = malloc(sizeof(message_queue_t));
    queue->data = calloc(capacity, sizeof(NFAPI_MESSAGE_PDU_T));
    queue->capacity = capacity;
    queue->count = 0;
    sem_init(&queue->mutex, 0, 1);
    sem_init(&queue->not_empty, 0, capacity > 0 ? 1 : 0);
    sem_init(&queue->not_full, 0, capacity);
    return queue;
}

void enqueue(message_queue_t *queue, NFAPI_MESSAGE_PDU_T msg) {
    sem_wait(&queue->not_full);
    sem_wait(&queue->mutex);

    // Insert msg into the queue while minimizing fragmentation.
    // ... (Implement a suitable strategy for efficient insertion)

    queue->data[queue->count++] = msg;
    sem_post(&queue->mutex);
    sem_post(&queue->not_empty);
}

bool dequeue(message_queue_t *queue, NFAPI_MESSAGE_PDU_T *msg) {
    sem_wait(&queue->not_empty);
    sem_wait(&queue->mutex);

    // Extract msg from the queue and return it.
    // ... (Implement a suitable strategy for efficient extraction)

    *msg = queue->data[--queue->count];
    memset(&queue->data[queue->count], 0, sizeof(NFAPI_MESSAGE_PDU_T));
    sem_post(&queue->mutex);
    sem_post(&queue->not_full);

    return true;
}

void destroy_message_queue(message_queue_t *queue) {
    free(queue->data);
    free(queue);
}
```

To support concurrent read and write operations, use a semaphore for synchronizing access to the message queue. The `enqueue` function signals that the queue is not full when an element is inserted, and the `dequeue` function signals that the queue is not empty when an element is extracted. This way, consumer threads can wait for elements to become available without blocking producer threads, and vice versa.

This implementation uses dynamically allocated memory for the message queue, allowing it to handle varying loads effectively. You may want to optimize performance-critical sections by implementing efficient strategies for inserting and extracting messages while minimizing fragmentation. Additionally, consider using appropriate synchronization mechanisms and data structures to meet the objectives without introducing unnecessary overhead or bottlenecks.']

