void read_config(const char *filename) {
    int fd, ret;
    LTE_PHY_RX_FRAME_INFO_T data;

    fd = open(filename, O_RDONLY);
    if (fd < 0) {
        perror("Error opening file");
        return;
    }

    ret = read(fd, &data, sizeof(LTE_PHY_RX_FRAME_INFO_T));
    if (ret != sizeof(LTE_PHY_RX_FRAME_INFO_T)) {
        perror("Error reading file");
        close(fd);
        return;
    }

    // Handle data integrity checks here

    pthread_mutex_lock(&mutex);
    dynamic_array = realloc(dynamic_array, (num_elements + 1) * sizeof(LTE_PHY_RX_FRAME_INFO_T));
    if (!dynamic_array) {
        perror("Error allocating memory");
        close(fd);
        pthread_mutex_unlock(&mutex);
        return;
    }
    num_elements++;
    dynamic_array[num_elements - 1] = data;
    pthread_mutex_unlock(&mutex);

    close(fd);
}

void *data_source_reader(void *arg) {
    const char *filename = (const char *) arg;

    while (1) {
        read_config(filename);
        sleep(1); // Adjust this based on data source refresh rates
