} nfapi_crc_indication_pdu_t;

typedef struct memory_pool_s {
    void* memory_block;
    size_t used;
    size_t capacity;
} memory_pool_t;

memory_pool_t* create_memory_pool(size_t initial_capacity) {
    memory_pool_t *pool = malloc(sizeof(memory_pool_t));
    if (!pool) return NULL;
    pool->memory_block = malloc(initial_capacity * sizeof(nfapi_crc_indication_pdu_t));
    if (!pool->memory_block) {
        free(pool);
        return NULL;
    }
    pool->capacity = initial_capacity;
    pool->used = 0;
    return pool;
}

void destroy_memory_pool(memory_pool_t *pool) {
    if (pool && pool->memory_block) free(pool->memory_block);
    if (pool) free(pool);
}

nfapi_crc_indication_pdu_t* acquire(memory_pool_t *pool) {
    if (pool->used == pool->capacity) return NULL;
    nfapi_crc_indication_pdu_t *entry = (nfapi_crc_indication_pdu_t*)((char*)pool->memory_block + pool->used * sizeof(nfapi_crc_indication_pdu_t));
    pool->used++;
    return entry;
}

void release(memory_pool_t *pool, nfapi_crc_indication_pdu_t *entry) {
    pool->used--;
}

pthread_mutex_t data_mutex = PTHREAD_MUTEX_INITIALIZER;
static size_t allocated_count = 0;

void increment_allocated_count() {
    pthread_mutex_lock(&data_mutex);
    allocated_count++;
    pthread_mutex_unlock(&data_mutex);
}

void decrement_allocated_count(nfapi_crc_indication_pdu_t *entry) {
    if (entry->tag.length == 0 || entry->rnti.length == 0 || entry->crc_indication_tag.length == 0) return; // Skip invalid entries
    pthread_mutex_lock(&data_mutex);
    allocated_count--;
    pthread_mutex_unlock(&data_mutex);
}

void print_all(memory_pool_t *pool) {
    if (pool->used == 0) return;
    nfapi_crc_indication_pdu_t* current = pool->memory_block;
    for (size_t i = 0; i < pool->used; ++i) {
        printf("tag: %.*s, rnti: %.*s, crc_indication_tag: %.*s\n", current->tag.length, current->tag.value, current->rnti.length, current->rnti.value, current->crc_indication_tag.length, current->crc_indication_tag.value);
        current++;
    }
}

nfapi_crc_indication_pdu_t* create_data(memory_pool_t *pool) {
    nfapi_crc_indication_pdu_t* data = acquire(pool);
    if (!data) return NULL;

    data->tag.length = sizeof(RX_UE_INFORMATION_TAG) / sizeof(char);
    data->tag.value = &data->tag;
    memset(data->tag.value, 0, data->tag.length); // Set to default values

    data->rnti.length = sizeof(RNTI) / sizeof(char);
    data->rnti.value = &data->rnti;
