    data->crc_indication_tag.length = sizeof(CRC_INDICATION_REL8_TAG) / sizeof(char);
    data->crc_indication_tag.value = &data->crc_indication_tag;

    // Set a random CRCFLAG value
    *(uint32_t*)data->crc_indication_tag.value = rand();

    increment_allocated_count();
    return data;
}
