            (data[i].rnti.rntiType != VALID_RNTI.rntiType || data[i].rnti.rntiValue != VALID_RNTI.rntiValue)) {
            goto cleanup;
        }

        // Set CRC_INDICATION randomly
        data[i].crc_indication = VALID_CRCFLAG;
    }

cleanup:
    if (sem_trylock(&log_mutex) != 0) {
        perror("Semaphore lock failed");
        goto cleanup_memory;
    }

    // Log any errors or invalid entries, if any
    for (size_t i = 0; i < N; ++i) {
        if (!((data[i].rx_ue_tag.length == VALID_RX_UE_TAG.length && data[i].rx_ue_tag.tagValue == VALID_RX_UE_TAG.tagValue) &&
              (data[i].rnti.rntiType == VALID_RNTI.rntiType && data[i].rnti.rntiValue == VALID_RNTI.rntiValue))) {
