        }
    }

    sem_post(&log_mutex);

cleanup_memory:
    if (data != MAP_FAILED) {
        munmap(data, N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    return errno ? -1 : 0;
}

int main() {
