static uint32_t* theme_bitmap = NULL;
static size_t theme_bitmap_size = 0;
static char* theme_cache_root = "./theme_cache";
static png_structp theme_png = NULL;

void init_theme_dir() {
    if (!theme_cache_root || !access(theme_cache_root, F_OK)) return;
    mkdir(theme_cache_root, 0777);
}

uint32_t get_theme_index() {
    if (!theme_bitmap) {
        theme_bitmap = mmap(NULL, sizeof(uint32_t)*theme_bitmap_size, PROT_READ|PROT_WRITE, MAP_PRIVATE|MAP_ANON,-1, 0);
        memset(theme_bitmap, -1, sizeof(uint32_t)*theme_bitmap_size);
    }
    uint32_t index = -1;
    for (size_t i = 0; i < theme_bitmap_size; ++i) {
        if (theme_bitmap[i] == (uint32_t)-1) {
            index = i;
            break;
        }
    }
    return index != (uint32_t)-1 ? index : increase_theme_bitmap_size();
}

void recycle_theme_index(uint32_t index) {
    if (index >= theme_bitmap_size) return;
    theme_bitmap[index] = -1;
}

void* get_theme_data(uint32_t index) {
    char path[100];
    sprintf(path, "%s/%d.png", theme_cache_root, index);
    png_byte header[8];
    FILE *fp = fopen(path, "rb");
    if (!fp || !fread(header, 1, 8, fp) || (png_check_sig(header, 8) != 0)) {
        theme_png = png_create_read_struct(PNG_LIBPNG_VER_STRING, NULL, NULL, NULL);
        ifsetjmp(theme_png->jmpbuf, siglongjmp(theme_png->jmpbuf, 1));
        init_input_struct(theme_png, path);
        update_input_control(theme_png);
        read_png(theme_png, NULL, NULL);
        fp = fopen(path, "wb");
        write_png(theme_png, fp, PNG_TRUNCATE_OUTPUT);
        png_destroy_read_struct(&theme_png, NULL, NULL);
    }
    return fp;
}

void increase_theme_bitmap_size() {
    if (theme_bitmap_size == 0) theme_bitmap_size = 256;
    else theme_bitmap_size *= 2;
    uint32_t* new_bitmap = mmap(NULL, sizeof(uint32_t)*theme_bitmap_size, PROT_READ|PROT_WRITE, MAP_PRIVATE|MAP_ANON,-1, 0);
