struct logging_data {
    int success_count;
    int error_count;
    char log[4096];
};

void* rng(void* arg) {
    srand(((unsigned int)arg + time(NULL)));
    return NULL;
}

NFAPI_CRC_INDICATION_PDU_T* create_list(size_t max_entries, pthread_mutex_t *log_lock) {
    NFAPI_CRC_INDICATION_PDU_T *data = NULL;
    struct logging_data log_data = {0, 0};

    if (max_entries == 0 || max_entries > RAND_MAX / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        pthread_mutex_lock(log_lock);
        snprintf(log_data.log, sizeof(log_data.log), "Error: Invalid max_entries (%zu)\n", max_entries);
        pthread_mutex_unlock(log_lock);
        return NULL;
    }

    data = calloc(max_entries, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!data) {
        pthread_mutex_lock(log_lock);
        snprintf(log_data.log, sizeof(log_data.log), "Error: Memory allocation failed\n");
        pthread_mutex_unlock(log_lock);
        return NULL;
    }

    pthread_t rng_threads[max_entries];
    for (size_t i = 0; i < max_entries; ++i) {
        pthread_create(&rng_threads[i], NULL, &rng, (void*)(intptr_t)i);
    }

    for (size_t i = 0; i < max_entries; ++i) {
        pthread_join(rng_threads[i], NULL);

        data[i].RX_UE_INFORMATION_TAG = i * 1000 + 1; // Adjust tag range as needed
        data[i].RNTI = (uint16_t)((rand() % max_entries) << 3 | rand() % 8);
        data[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        data[i].CRCFLAG = rand() % 2;
    }

    pthread_mutex_lock(log_lock);
    snprintf(log_data.log, sizeof(log_data.log), "Successfully created %zu entries\n", max_entries);
    log_data.success_count += max_entries;
    pthread_mutex_unlock(log_lock);

    return data;
}

