import java.util.concurrent.TimeUnit;

public class WeatherData {
    private List<NFAPI_CRC_INDICATION_PDU_T> data = new ArrayList<>();

    // ... Other methods, constructors and fields ...

    public double calculateAverageCRCIndication(Duration timePeriod) {
        long startTime = System.currentTimeMillis();
        long endTime = startTime + TimeUnit.SECONDS.toMillis(timePeriod.getSeconds());
        int count = 0;
        double sum = 0.0;

        synchronized (this.data) { // Thread safety
            for (NFAPI_CRC_INDICATION_PDU_T indication : this.data) {
                long indicationTime = indication.timestamp;
                if (indicationTime >= startTime && indicationTime <= endTime) {
                    sum += indication.CRC_INDICATION_REL8_TAG;
                    count++;
                }
            }
        }

        if (count == 0) return -1; // Edge case: insufficient data to calculate an average CRC indication
        return sum / count;
    }
}
