    LTE_PHY_MIB_T* array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} LTE_PHY_MIB_MANAGER;

void init_manager(LTE_PHY_MIB_MANAGER* manager, size_t capacity) {
    manager->array = malloc(capacity * sizeof(LTE_PHY_MIB_T));
    manager->capacity = capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    pthread_cond_init(&manager->cond, NULL);
}

void add_entry(LTE_PHY_MIB_MANAGER* manager, const LTE_PHY_MIB_T* entry) {
    pthread_mutex_lock(&manager->lock);
    while (manager->count == manager->capacity) {
        pthread_cond_wait(&manager->cond, &manager->lock);
    }

    memcpy(manager->array + manager->count, entry, sizeof(LTE_PHY_MIB_T));
    manager->count++;
    pthread_mutex_unlock(&manager->lock);
}

void update_entry(LTE_PHY_MIB_MANAGER* manager, uint32_t id, const LTE_PHY_MIB_T* entry) {
    pthread_mutex_lock(&manager->lock);

    size_t i;
    for (i = 0; i < manager->count; ++i) {
        if (manager->array[i].id == id) {
            memcpy(&manager->array[i], entry, sizeof(LTE_PHY_MIB_T));
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

LTE_PHY_MIB_T* find_entry(const LTE_PHY_MIB_MANAGER* manager, uint32_t id) {
    pthread_mutex_lock(&manager->lock);

    size_t i;
    for (i = 0; i < manager->count; ++i) {
        if (manager->array[i].id == id) {
            LTE_PHY_MIB_T* result = malloc(sizeof(LTE_PHY_MIB_T));
            memcpy(result, &manager->array[i], sizeof(LTE_PHY_MIB_T));
            pthread_mutex_unlock(&manager->lock);
            return result;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}
