    pdu->rx_ue_information.value = 123456;
    pdu->rnti.value = 789012;
    pdu->crc_indication.crcflag = (rand() % 2) ? 1 : 0;

    log("DEBUG", "PDU allocated.");
    return pdu;
}

void free_pdu(NFAPI_CRC_INDICATION_PDU_T *pdus, size_t count) {
    if (!pdus || !count) {
        return;
    }

    free(pdus);
    log("INFO", "Freed PDUs.");
}

void allocator_free(Allocator **allocator) {
    if (!allocator || !*allocator) {
        return;
    }

    pthread_mutex_destroy(&(*allocator)->lock);
    free_pdu((*allocator)->data, (*allocator)->used_count);
