struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rxUEInfoTag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crcIndication;
};

class DynamicLinkedList {
private:
    std::list<std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>> data;
    std::unordered_map<uint32_t, uint32_t> rntiMap; // RNTI and its index in the list
    boost::circular_buffer<std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>> buffer(100); // Clear every 100 items added or after 'interval' milliseconds
    std::mutex mtx;
    unsigned int interval = 5000; // Period to clear and re-populate the list (in ms)

public:
    DynamicLinkedList(unsigned int interval) : interval(interval) {}

    void add(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T> newPdu = std::make_unique<NFAPI_CRC_INDICATION_PDU_T>(pdu);
        newPdu->rnti = generateUniqueRNTI(); // Generates a unique RNTI based on current time or other sources
        data.emplace_back(std::move(newPdu));
        rntiMap[newPdu->rnti] = static_cast<uint32_t>(data.size() - 1); // Update the RNTI to index mapping
    }

    void clear() {
        std::unique_lock<std::mutex> lock(mtx);
        data.clear();
        rntiMap.clear();
    }

    void run() {
        std::thread clearThread([this](){ while (true) { clear(); boost::this_thread::sleep_for(boost::chrono::milliseconds(interval)); } });
        for (auto& pdu : buffer) {
            add(*pdu);
        }
        clearThread.detach();
    }

    const NFAPI_CRC_INDICATION_PDU_T* findByRNTI(uint32_t rnti) const {
        auto iter = rntiMap.find(rnti);
        if (iter != rntiMap.end()) {
            return &(*data.begin()).get()[iter->second];
        }
        return nullptr;
    }

private:
    uint32_t generateUniqueRNTI() const {
        // Implement a strategy to generate unique RNTIs based on external data sources or current time
        static std::random_device rd;
        static std::mt19937 gen(rd());
        return gen() % 0xFFFFFFFF + 1; // Generates random numbers between 1 and 4.294.967.295 (UINT32_MAX-1)
    }
};
