    load_bundle_args_t* data = args;
    FILE* file = fopen(data->filename, "r");

    if (!file) {
        *data->status = -1; // error: file not found
        return NULL;
    }

    // asynchronous processing here...

    fclose(file);
    return NULL;
}

int load_bundle(const char* filename, size_t* num_records, int* status) {
    pthread_t threads[NUM_THREADS];
    load_bundle_args_t data[NUM_THREADS];
    size_t total_loaded = 0;

    for (int i = 0; i < NUM_THREADS; ++i) {
        data[i].filename = filename;
        data[i].num_records = num_records;
        data[i].status = status;
        pthread_create(&threads[i], NULL, load_from_file, &data[i]);
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
        total_loaded += *num_records;
    }

    if (*status != 0) return *status; // error occurred during loading

    // process the loaded records here...

    return total_loaded;
}

