typedef struct {
    RX_POWER_MEASUREMENT_TAG rxPower;
    RX_SIGNAL_QUALITY_TAG rxSignalQuality;
    TX_QUEUE_STATUS_TAG txQueueStatus;
    unsigned int txQueueId; // Unique ID for each structure
    unsigned int queueDepth;
} PHY_STATS_PDU_T;

unsigned int generate_unique_id(unsigned int* id_cache, size_t cache_size) {
    static unsigned int next_id = 0;
    if (next_id >= cache_size) {
        next_id = 0;
    }
    const unsigned int current_id = id_cache[next_id];
    id_cache[next_id] = next_id + 1 + current_id;
    return current_id + 1 + next_id;
}

unsigned int populate_array(PHY_STATS_PDU_T** array, size_t max_size, unsigned int* id_cache, size_t cache_size) {
    *array = (PHY_STATS_PDU_T*)calloc(max_size, sizeof(PHY_STATS_PDU_T));
    if (!*array) {
        return 0;
    }

    unsigned int allocated_count = 0;
    for (size_t i = 0; i < max_size && allocated_count < max_size; ++i) {
        const unsigned int txQueueId = generate_unique_id(id_cache, cache_size);
        PHY_STATS_PDU_T* current_entry = &(*array)[allocated_count];
        current_entry->txQueueId = txQueueId;
        current_entry->queueDepth = rand() % MAX_QUEUE_DEPTH + MIN_QUEUE_DEPTH;
        // Adjust signal strength and quality based on network conditions (not shown)
        allocated_count++;
    }

    return allocated_count;
}
