#include <list>
#include <mutex>
#include <memory>
#include <boost/circular_buffer.hpp>
#include <boost/asio/steady_timer.hpp>
#include <boost/optional.hpp>
#include <spdlog/spdlog.h>

namespace mylib {

class Config {
public:
    std::string logFileName;
    int logLevel;
};

struct RNTIBuffer {
    boost::circular_buffer<uint64_t> buffer;
    std::mutex mtx;
};

struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rxTag;
    uint64_t rnti;
    CRC_INDICATION_REL8_TAG crcIndication;
};

class DynamicList {
public:
    DynamicList(const Config& config) : log_(spdlog::get("mylib")) {
        log_->set_level(static_cast<spdlog::level::level_enum>(config.logLevel));
    }

    void addEntry(const RX_UE_INFORMATION_TAG& rxTag, const uint64_t rnti) {
        std::unique_lock<std::mutex> lock(mtx_);
        data_.emplace_back(rxTag, rnti, getCRCFlag());

        // Update RNTI buffer and handle potential delays in data retrieval using boost::asio::steady_timer
        auto it = rntiBuffer_.buffer.get_write_iterator();
        *it = rnti;
        updateRntiBuffer_(it, rnti);
    }

    const NFAPI_CRC_INDICATION_PDU_T* getRandomEntry() {
        std::unique_lock<std::mutex> lock(mtx_);
        return data_.empty() ? nullptr : &data_.front();
    }

private:
    boost::optional<CRC_FLAG> getCRCFlag() {
        // Generate a random CRC flag value
        static thread_local std::uniform_int_distribution<> distribution(0, 1);
        return distribution(generator_);
    }

    void updateRntiBuffer_(boost::circular_buffer<uint64_t>::iterator& it, const uint64_t rnti) {
        std::unique_lock<std::mutex> lock(rntiBuffer_.mtx);
        rntiBuffer_.buffer.push_back(rnti);
        boost::asio::steady_timer timer;
        timer.expires_from_now(std::chrono::seconds(10)); // Adjust delay as necessary
        timer.async_wait([it, this](boost::system::error_code ec) {
            if (!ec) {
                std::unique_lock<std::mutex> lock(rntiBuffer_.mtx);
                auto currentIt = it;
                // Rotate RNTI buffer and update iterator
                if (++currentIt == rntiBuffer_.buffer.end()) {
                    currentIt = rntiBuffer_.buffer.begin();
                }
                it = currentIt;
            } else {
                log_->error("Timer expired unexpectedly");
            }
        });
    }

    std::list<NFAPI_CRC_INDICATION_PDU_T> data_;
    std::mutex mtx_;
    RNTIBuffer rntiBuffer_;
    static std::mt19937 generator_; // Random number generator for CRC flag generation
};

std::mt19937 DynamicList::generator_{std::random_device{}()};
}  // namespace mylib
