// Initialize a log record with random values within specified ranges
void init_log_record(LogRecord* log) {
    log->seq_num = rand();
    log->status = (rand() % 2) == 0;
    log->timestamp_offset = (long)time(NULL) * rand(); // Random timestamp offset within current time
    log->log_level = rand() % 10; // Random log level between 0 and 9

