    log->message = (char*)malloc(MESSAGE_SIZE);
    if (!log->message) {
        // Critical error: Log to secondary storage and exit with error code
        printf("Fatal Error: Failed to allocate memory for message\n");
        exit(1);
    }

    // Fill the message field with random characters
    for (int i = 0; i < MESSAGE_SIZE; ++i) {
        log->message[i] = (char)(rand() % 256);
    }
}

// Function to dynamically allocate memory for a logging subsystem and initialize log entries
LogRecord* init_logging_subsystem(size_t num_entries, size_t resource_limit) {
    const int LOG_RECORD_SIZE = sizeof(LogRecord) + 256; // Size of a single log record including the message field
    LogRecord* logs = NULL;

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    size_t total_allocated = 0;
