        LogRecord* log = &logs[i];
        init_log_record(log);
        total_allocated += LOG_RECORD_SIZE;
    }

    if (total_allocated != num_entries * LOG_RECORD_SIZE) {
        // Critical error: Not enough memory allocated, log to secondary storage and exit with error code
        printf("Fatal Error: Insufficient memory for logging subsystem\n");
        exit(1);
