void* align(size_t alignment, size_t size) {
    size_t new_size = (sizeof(NFAPI_CRC_INDICATION_PDU_T) * MAX_ELEMENTS + alignment - 1);
    size_t page_size = sysconf(_SC_PAGE_SIZE);
    if ((new_size % page_size) != 0) new_size += (page_size - (new_size % page_size));
    void* ptr = malloc(new_size);
    if (!ptr) {
