struct container {
    pthread_mutex_t mutex;
    size_t capacity, count;
    NFAPI_CRC_INDICATION_PDU_T *data;
};

void init_container(struct container *container, size_t capacity) {
    container->capacity = capacity;
    container->count = 0;
    container->data = calloc(capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&container->mutex, NULL);
}

void push(struct container *container, const NFAPI_CRC_INDICATION_PDU_T *item) {
    pthread_mutex_lock(&container->mutex);

    if (container->count == container->capacity) {
        goto unlock;
    }

    memcpy(&container->data[container->count], item, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    ++container->count;

unlock:
    pthread_mutex_unlock(&container->mutex);
}

size_t pop(struct container *container, NFAPI_CRC_INDICATION_PDU_T *item) {
    pthread_mutex_lock(&container->mutex);

    if (container->count == 0) {
        goto unlock;
    }

    memcpy(item, &container->data[0], sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memmove(&container->data[0], &container->data[1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (--container->count));

unlock:
    pthread_mutex_unlock(&container->mutex);
    return container->count;
}
