typedef struct MemPool {
    size_t capacity;
    size_t size;
    NFAPI_CRC_INDICATION_PDU_T *data;
    pthread_mutex_t mutex;
} MemPool;

MemPool* create_mempool(size_t initial_capacity, size_t max_capacity) {
    MemPool *pool = malloc(sizeof(MemPool));
    pool->capacity = (initial_capacity > 0) ? initial_capacity : 16;
    pool->max_capacity = max_capacity;
    pool->size = pool->capacity;
    pool->data = mmap(NULL, pool->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (pool->data == MAP_FAILED) {
        free(pool);
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }
    pool->mutex = PTHREAD_MUTEX_INITIALIZER;
    return pool;
}

void* reallocate_mempool(MemPool *pool) {
    size_t new_capacity = (pool->size + pool->capacity) / 2 * 3; // growth factor of 1.5x, rounded up
    if (new_capacity > pool->max_capacity) {
        fprintf(stderr, "Exceeded max capacity!\n");
        free_mempool(pool);
        exit(EXIT_FAILURE);
    }
    NFAPI_CRC_INDICATION_PDU_T *new_data = mmap(NULL, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (new_data == MAP_FAILED) {
        perror("Reallocation failed");
        free_mempool(pool);
        exit(EXIT_FAILURE);
    }
    memcpy(new_data, pool->data, pool->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    munmap(pool->data, pool->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pool->data = new_data;
    pool->capacity = new_capacity;
    pool->size += new_capacity - pool->capacity;
}

void free_mempool(MemPool *pool) {
    if (pool->data != MAP_FAILED)
        munmap(pool->data, pool->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    free(pool);
}

void add_to_mempool(MemPool *pool) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->size == pool->capacity)
        reallocate_mempool(pool);
    pool->data[pool->size].crcflag = rand(); // initialize crcflag with a random value
    pool->size++;
    pthread_mutex_unlock(&pool->mutex);
}

// Usage example:
void run_example(MemPool *pool, size_t num_elements) {
