    pthread_mutex_lock(&dns_cache_lock);

    for (size_t i = 0; i < cache_size; ++i) {
        if (strcmp(dns_cache[i].hostname, hostname) == 0) {
            strncpy(ip_address, dns_cache[i].ip_address, ip_address_len);
            pthread_mutex_unlock(&dns_cache_lock);
            return ip_address;
        }
    }

    char ip_address_[256];
    if (perform_dns_lookup(hostname, ip_address_, sizeof(ip_address_))) {
        // Handle errors and log failures here.
        pthread_mutex_unlock(&dns_cache_lock);
        return NULL;
    }

    strncpy(ip_address, ip_address_, ip_address_len);
    if (cache_size >= cache_capacity) {
        DnsCacheEntry *new_cache = realloc(dns_cache, sizeof(DnsCacheEntry) * (2 * cache_capacity));
        if (!new_cache) {
            // Handle memory allocation errors here.
            pthread_mutex_unlock(&dns_cache_lock);
            return NULL;
        }
        dns_cache = new_cache;
        cache_capacity *= 2;
    }

    DnsCacheEntry *entry = &dns_cache[cache_size++];
    strncpy(entry->hostname, hostname, sizeof(entry->hostname));
    strncpy(entry->ip_address, ip_address, sizeof(entry->ip_address));
    entry->timestamp = time(NULL);

    pthread_mutex_unlock(&dns_cache_lock);
    return ip_address;
}
