typedef struct {
    AES_KEY aes_key;
    size_t session_count;
    size_t max_sessions;
    pthread_mutex_t mutex;
} CipherContext;

CipherContext* create_cipher(const char *password, size_t max_sessions) {
    SHA256_CTX sha256_ctx;
    uint8_t key[AES_BLOCK_SIZE];
    SHA256_Init(&sha256_ctx);
    SHA256_Update(&sha256_ctx, password, strlen(password));
    SHA256_Final(key, &sha256_ctx);

    AES_set_encrypt_key(key, 256, &aes_key);

    CipherContext* ctx = malloc(sizeof(CipherContext));
    ctx->aes_key = aes_key;
    ctx->max_sessions = max_sessions;
    ctx->session_count = 0;
    pthread_mutex_init(&ctx->mutex, NULL);

    return ctx;
}

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_array(size_t size, CipherContext* ctx) {
    NFAPI_CRC_INDICATION_PDU_T* array = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_lock(&ctx->mutex);
    ctx->session_count += size;
    if (ctx->session_count > ctx->max_sessions) {
        free(array);
        array = NULL;
    } else {
        for (size_t i = 0; i < size; ++i) {
            array[i].tag = generate_RX_UE_INFORMATION_TAG();
            array[i].rnti = generate_RNTI();
            array[i].crc_indication_tag = generate_CRC_INDICATION_REL8_TAG();
            array[i].crcflag = rand() % 2;
        }
    }
    pthread_mutex_unlock(&ctx->mutex);

    return array;
}

void destroy_cipher(CipherContext** ctx) {
    if (*ctx == NULL) return;

    pthread_mutex_destroy(&(*ctx)->mutex);
    free(*ctx);
    *ctx = NULL;
}

void cleanup_cipher(CipherContext* ctx) {
    if (ctx->session_count > 0 && pthread_trylock(&ctx->mutex) == 0) {
        ctx->session_count = 0;
        destroy_cipher(&ctx);
    }
}
