Node* dl_frame_queue_init() {
    Node *head = NULL, *tail = NULL;
    return (Node*)calloc(1, sizeof(Node)); // Allocate memory for the head node
}

// Function to add a new entry to the dynamic array
void enqueue(Node **head_ref, LTE_DL_FRAME_MSG *msg) {
    Node *new_node = (Node*)malloc(sizeof(Node));
    new_node->msg = msg;
    new_node->next = NULL;

    sem_init(&new_node->ready_sem, 0, 0); // Initialize semaphore

    if (*head_ref == NULL) {
        *head_ref = new_node;
        tail = *head_ref;
    } else {
        tail->next = new_node;
        tail = new_node;
    }
}

// Function to retrieve a specific entry by frame number (blocking)
LTE_DL_FRAME_MSG* dequeue(Node **head, uint32_t frame_number) {
    Node *current = *head;

