            sem_wait(&(current->msg->mutex)); // Acquire lock for accessing the structure
            LTE_DL_FRAME_MSG* msg = current->msg;
            sem_post(&(current->ready_sem)); // Signal that data is no longer available
            sem_post(&(current->msg->mutex)); // Release lock
            Node *temp = current;
            current = current->next;
            free(temp); // Free the node that contained the message, not the message itself
            return msg;
        }
        current = current->next;
    }

    // Fallback mechanism: Return a default message if data is unavailable
    static LTE_DL_FRAME_MSG default_msg;
    return &default_msg;
}

// Function to clear the dynamic array (blocking)
