        if (semaphore_timedwait(&(current->ready_sem), 1000) == -1) {
            printf("Timeout waiting for data.\n");
            break;
        }
        sem_post(&(current->msg->mutex)); // Release lock
        current = next_node;
        free(current); // Free the node containing the message
