pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t pool_cond = PTHREAD_COND_INITIALIZER;
pthread_t active_threads[MAX_CONCURRENT];
size_t current_threads = 0;
NFAPI_CRC_INDICATION_PDU_T* pool;

void* populate(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T* structure;
    pthread_mutex_lock(&pool_mutex);
    if (!current_threads && !(structure = pool)) {
        pthread_mutex_unlock(&pool_mutex);
        return NULL;
    }
    current_threads++;
    structure->rx_ue_information_tag.tag = RX_UE_INFORMATION_TAG_VALUE; // Replace with valid initialization
    structure->rnti.value = RNTI_VALUE;                                   // Replace with valid initialization
    structure->crc_indication_rel8_tag.crcflag = (rand() % 2) == 0 ? true : false;
    pthread_mutex_unlock(&pool_mutex);

    // Insert validation and logging here

    return NULL;
}

void populateCrcIndicationArray(NFAPI_CRC_INDICATION_PDU_T** array, size_t arraySize) {
    pool = *array;
    for (size_t i = 0; i < arraySize; ++i) {
        if (!pool) break;
        pthread_t thread;
        pthread_create(&thread, NULL, populate, NULL);
        active_threads[current_threads] = thread;
    }

    for (size_t i = 0; i < current_threads && current_threads < MAX_CONCURRENT;) {
        pthread_mutex_lock(&pool_mutex);
        while (current_threads == MAX_CONCURRENT || !pool) {
            pthread_cond_wait(&pool_cond, &pool_mutex);
        }
        current_threads--;
        pthread_t threadToRemove = active_threads[0];
        memmove(active_threads, active_threads + 1, sizeof(pthread_t) * (current_threads));
        pthread_join(threadToRemove, NULL);
        pthread_mutex_unlock(&pool_mutex);
    }
}
