    sem_wait(&ma->mutex);
    if (ma->size >= ma->capacity) resize_managed_array(ma);
    memcpy(ma->array[ma->size], elem, sizeof(NFAPI_CRADC_INDICATION_PDU));
    ma->size++;
    sem_post(&ma->mutex);
}

