    sem_wait(&ma->mutex);
    for (size_t i = 0; i < ma->size; ++i) {
        if (memcmp(&ma->array[i]->rnti, &rnti, sizeof(RNTI)) == 0) {
            sem_post(&ma->mutex);
            return ma->array[i];
        }
    }
    sem_post(&ma->mutex);
    return NULL;
}

void cleanup(struct managed_array* ma) {
    sem_destroy(&ma->mutex);
    for (size_t i = 0; i < ma->size; ++i) {
        free(ma->array[i]->data->buffer);
        free(ma->array[i]->data);
