typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} dynamic_list_t;

dynamic_list_t* dynamic_list_create(size_t initial_capacity) {
    dynamic_list_t* list = malloc(sizeof(dynamic_list_t));
    if (!list) {
        logging_error("Error allocating memory for dynamic list");
        return NULL;
    }

    list->data = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        logging_error("Error allocating memory for dynamic list data");
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);

    logging_info("Created dynamic list with initial capacity: %zu", initial_capacity);
    return list;
}

void dynamic_list_destroy(dynamic_list_t* list) {
    if (!list) return;

    free(list->data);
    pthread_mutex_destroy(&list->lock);
    free(list);

    logging_info("Destroyed dynamic list with %zu items", list->size);
}

void* dynamic_list_get_ptr(dynamic_list_t* list, size_t index) {
    pthread_mutex_lock(&list->lock);

    if (index >= list->size || index >= list->capacity) {
        logging_error("Index out of bounds in dynamic list");
        pthread_mutex_unlock(&list->data->lock);
        return NULL;
    }

    void* item = &list->data[index];
    pthread_mutex_unlock(&list->data->lock);
    return item;
}

size_t dynamic_list_get_size(dynamic_list_t* list) {
    pthread_mutex_lock(&list->lock);
    size_t size = list->size;
    pthread_mutex_unlock(&list->data->lock);
    return size;
}

void dynamic_list_push_back(dynamic_list_t* list, NFAPI_CRC_INDICATION_PDU_T* item) {
    if (!item || !list) return;

    pthread_mutex_lock(&list->lock);

    if (list->size >= list->capacity) {
        size_t new_capacity = (list->capacity * 2) + 1;
        NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_data) {
            logging_error("Error resizing dynamic list");
            pthread_mutex_unlock(&list->data->lock);
            return;
        }

        list->data = new_data;
        list->capacity = new_capacity;
    }

    item->CRCFLAG = rand() % 2; // Set CRCFLAG randomly
    memcpy(&list->data[list->size], item, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size++;

