typedef struct UE_CONTEXT {
    uint32_t rnti;
    uint16_t srb_count;
    sem_t srb_mutex[MAX_SRB];
    uint16_t srbs[MAX_UE][MAX_SRB];
    volatile uint32_t pdcp_sn[MAX_UE][MAX_SRB];
} UE_CONTEXT;

typedef struct DYNAMIC_LIST {
    UE_CONTEXT* ue_contexts;
    uint32_t count;
    uint32_t capacity;
    pthread_mutex_t list_mutex;
    pthread_cond_t not_full;
    sem_t not_empty;
} DYNAMIC_LIST;

DYNAMIC_LIST* create_dynamic_list() {
    DYNAMIC_LIST *list = mmap(NULL, sizeof(DYNAMIC_LIST), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    pthread_mutex_init(&list->list_mutex, NULL);
    sem_init(&list->not_empty, 0, 0);
    sem_init(&list->not_full, 0, MAX_UE);
    return list;
}

void destroy_dynamic_list(DYNAMIC_LIST* list) {
    munmap(list, sizeof(DYNAMIC_LIST));
    pthread_mutex_destroy(&list->list_mutex);
    sem_destroy(&list->not_empty);
    sem_destroy(&list->not_full);
}

UE_CONTEXT* get_ue_context(DYNAMIC_LIST* list) {
    pthread_mutex_lock(&list->list_mutex);
    while (list->count == list->capacity && sem_trywait(&list->not_full) != 0)
        pthread_cond_wait(&list->not_full, &list->list_mutex);

    UE_CONTEXT* ue = &list->ue_contexts[list->count];
    if (++list->count > list->capacity)
        sem_post(&list->not_empty);
    pthread_mutex_unlock(&list->list_mutex);

    return ue;
}

void add_srbs(UE_CONTEXT* ue, uint16_t count) {
    for (uint16_t i = 0; i < count; ++i) {
        sem_init(&ue->srb_mutex[i], 0, 1);
        ue->srbs[list->count - 1][i] = i + 1;
    }
}

UE_CONTEXT* create_ue_context(DYNAMIC_LIST* list) {
    UE_CONTEXT* ue = get_ue_context(list);
    ue->rnti = list->count;
    add_srbs(ue, NUM_SRBS_PER_UE);
    return ue;
}
