void init_dns_resolver(const char *hostname) {
    struct hostent *he;
    struct addrinfo hints, *servinfo, *p;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    int status;

    if ((status = getaddrinfo(hostname, NULL, &hints, &servinfo)) != 0) {
        herror("getaddrinfo: ", status);
        error = -1;
    }

    // Loop through all the results and connect to the first one we can
    for (p = servinfo; p != NULL; p = p->ai_next) {
        int sockfd;
        if ((sockfd = socket(p->ai_family, p->ai_socktype, p->ai_protocol)) == -1) {
            perror("socket");
            error = -1;
            continue;
        }

        if (connect(sockfd, p->ai_addr, p->ai_addrlen) == -1) {
            close(sockfd);
            perror("connect");
            error = -1;
            continue;
        }

        break; // Successfully connected. No need to try the other ones.
    }

    if (p == NULL) {
        fprintf(stderr, "Could not connect to host: %s\n", hostname);
        error = -1;
    }

    freeaddrinfo(servinfo); // Free the linked list that was passed back by getaddrinfo()
}

