    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_create(&threads[i], NULL, fetch_lte_parameters, &frame_info);
    }

    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    buffer = mmap(NULL, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fileno(stdin), 0);
    if (buffer == MAP_FAILED) {
        perror("mmap");
        error = -1;
        return NULL;
    }

    pthread_mutex_lock(&buffer_mutex);
    memcpy(buffer, &frame_info, sizeof(LTE_PHY_RX_FRAME_INFO_T));
    pthread_mutex_unlock(&buffer_mutex);

