    size_t count;
    void *frames[128]; // Adjust M as per requirements
} concurrent_frames_t;

concurrent_frames_t* init_concurrent_frames(size_t M) {
    concurrent_frames_t* frames = malloc(sizeof(concurrent_frames_t));
    if (!frames) return NULL;

    frames->count = 0;
    for (size_t i = 0; i < M; ++i) {
        frames->frames[i] = calloc(1, NFAPI_UL_RX_FRAME_PDU_T_SIZE);
        if (!frames->frames[i]) {
            free(frames);
            return NULL;
        }
    }

    pthread_mutex_init(&frames->lock, NULL);

    return frames;
}

void push_frame(concurrent_frames_t* frames, void *frame) {
    if (frames == NULL || frame == NULL) return;

    pthread_mutex_lock(&frames->lock);

    // Handle buffer overflow by overwriting the least recently used frame
    if (frames->count >= arraysize(frames->frames)) {
        free(frames->frames[frames->count % arraysize(frames->frames)]);
    }

    frames->frames[frames->count++] = frame;

    pthread_mutex_unlock(&frames->lock);
}

void* get_frame(concurrent_frames_t* frames) {
    if (frames == NULL || frames->count == 0) return NULL;

    pthread_mutex_lock(&frames->lock);

    void *frame = frames->frames[frames->count - 1];

    // Remove the frame from the array and reset its index to avoid accessing freed memory
    frames->frames[--frames->count] = NULL;

    pthread_mutex_unlock(&frames->lock);

    return frame;
}

