// Slab pool for LTE_PHY_RX_FRAME_INFO structures
struct slab_pool {
    void *memory_block;
    size_t used;
    size_t free;
};

void* slab_alloc(struct slab_pool *pool, size_t size) {
    if (pool->free == 0) return NULL;

    void *data = (char *) pool->memory_block + pool->used;
    pool->used += size;
    pool->free--;

    return data;
}

void slab_cleanup(struct slab_pool *pool) {
    if (pool->free > 0) return;

    free(pool->memory_block);
}

