            *head = node;
            node->prev = NULL;
            node->next = NULL;
        } else {
            node->prev = (*head)->prev;
            node->next = *head;
            (*head)->prev = node;
            *head = node;
        }

        list_len++;
        pthread_mutex_unlock(&lock);
    }

    // Cleanup slab pool on error or max list size reached
    if (list_len == 0) slab_cleanup(&lte_slab);
}

// Function to initialize and populate doubly linked list of NFAPI_CRC_INDICATION_PDU structures
void init_crc_list(NFAPI_CRC_INDICATION_PDU_T **head, size_t max_entries) {
