    while (list_len < max_entries && (data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU)))) {
        node = data;

        pthread_mutex_lock(&lock);

        if (list_len == 0) {
            *head = node;
            node->prev = NULL;
            node->next = NULL;
        } else {
            node->prev = (*head)->prev;
            node->next = *head;
            (*head)->prev = node;
            *head = node;
        }

        node->RX_UE_INFORMATION_TAG = 123456; // Set valid RX_UE_INFORMATION_TAG value
        node->RNTI = 987654;                   // Set valid RNTI value
        node->CRC_INDICATION_REL8_TAG.tag = 100;// Set valid CRC_INDICATION_REL8_TAG tag value
        node->CRCFLAG = true;                  // Randomly set CRCFLAG value

        list_len++;
        pthread_mutex_unlock(&lock);
    }

    // Cleanup partially allocated resources on error or max entries reached
    if (list_len == 0) {
        while (*head != NULL) {
            NFAPI_CRC_INDICATION_PDU_T *temp = *head;
            *head = (*head)->next;
            free(temp);
        }
    }
}
