#include <new>

// Define the NFAPI_CRC_INDICATION_PDU_T structure
struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rxTag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcIndication;
};

// Custom memory pool for efficient resource management
class MemoryPool {
public:
    MemoryPool(size_t initialSize) : buffer_(nullptr), capacity_(0), used_(0) {
        if (initialSize > 0) {
            allocate(initialSize);
        }
    }

    ~MemoryPool() {
        clear();
    }

    NFAPI_CRC_INDICATION_PDU_T* allocate() {
        std::lock_guard<std::mutex> lock(mutex_);
        if (used_ < capacity_) {
            NFAPI_CRC_INDICATION_PDU_T* element = buffer_ + used_;
            ++used_;
            return element;
        } else {
            expand();
            return allocate();
        }
    }

    void deallocate(NFAPI_CRC_INDICATION_PDU_T* element) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (element >= buffer_ && element < buffer_ + capacity_) {
            --used_;
            std::memcpy(element, buffer_ + used_, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        } else {
            throw std::logic_error("Invalid memory element");
        }
    }

    void clear() {
        std::lock_guard<std::mutex> lock(mutex_);
        for (size_t i = 0; i < capacity_; ++i) {
            new (buffer_ + i) NFAPI_CRC_INDICATION_PDU_T(); // Construct each element with default values
        }
        used_ = 0;
    }

private:
    void allocate(size_t numElements) {
        if (capacity_ < numElements) {
            NFAPI_CRC_INDICATION_PDU_T* newBuffer = static_cast<NFAPI_CRC_INDICATION_PDU_T*>(::operator new[](numElements * sizeof(NFAPI_CRC_INDICATION_PDU_T)));
            if (buffer_) {
                std::memcpy(newBuffer, buffer_, used_ * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                ::operator delete[](buffer_);
            }
            buffer_ = newBuffer;
            capacity_ = numElements;
        }
    }

    void expand() {
        size_t newCapacity = capacity_ * 2;
        allocate(newCapacity);
    }

    NFAPI_CRC_INDICATION_PDU_T* buffer_;
    mutable std::mutex mutex_;
    size_t capacity_;
    size_t used_;
};

// Function to dynamically allocate memory for an array of structures based on the specified number of elements `N`
NFAPI_CRC_INDICATION_PDU_T* createArray(size_t N) {
    MemoryPool memoryPool(N);
    auto data = memoryPool.allocate();
    std::default_random_engine generator;
    for (NFAPI_CRC_INDICATION_PDU_T *element = data; element < data + N; ++element) {
        element->rxTag = RX_UE_INFORMATION_TAG{}; // Set default values for rxTag
        element->rnti = RNTI{};                   // Set default values for rnti
        element->crcIndication.crcFlag = (generator() % 2 == 0) ? true : false; // Randomly set CRCFLAG
    }
    return data;
}
