#include <cstdint>
#include <new>
#include <vector>
#include <random>
#include <atomic>
#include <mutex>
#include <functional>
#include <iostream>

class NFAPI_CRC_INDICATION_PDU_T {
public:
    enum Tag : uint32_t { RX_UE_INFORMATION_TAG = 0x01, RNTI = 0x02, CRC_INDICATION_REL8_TAG = 0x04 };

    uint32_t rxiTag;
    uint64_t rnti;
    bool crcFlag;

    NFAPI_CRC_INDICATION_PDU_T() : rxiTag(RX_UE_INFORMATION_TAG), rnti(0), crcFlag(false) {}
};

class MemoryPool {
public:
    static MemoryPool& getInstance() {
        thread_local MemoryPool instance;
        return instance;
    }

    void* allocate(size_t size, size_t alignment = alignof(NFAPI_CRC_INDICATION_PDU_T)) {
        if (freeList.empty()) {
            void* memory = std::malloc(size);
            if (!memory) throw std::bad_alloc();
            freeList.emplace_back(memory, size);
        }
        void* ptr = freeList.front().first;
        freeList.pop_front();
        return ptr;
    }

    void deallocate(void* memory, size_t size) {
        auto it = std::find_if(freeList.begin(), freeList.end(),
                               [&](const auto& pair) { return pair.first == memory; });
        if (it != freeList.end()) freeList.erase(it);
        else std::cerr << "Error: Tried to deallocate invalid memory\n";
    }

private:
    MemoryPool() {}
    ~MemoryPool() {
        for (auto& pair : freeList) std::free(pair.first);
    }

    struct FreeBlock { void* ptr; size_t size; };
    std::vector<FreeBlock> freeList;
};

class Allocator {
public:
    Allocator() : nextIndex(0), numAllocated(0) {}

    NFAPI_CRC_INDICATION_PDU_T* allocate(size_t nElements) {
        if (nElements > 10000 || nElements == 0) throw std::invalid_argument("Number of elements must be between 1 and 10,000");

        NFAPI_CRC_INDICATION_PDU_T* data = nullptr;
        try {
            data = static_cast<NFAPI_CRC_INDICATION_PDU_T*>(MemoryPool::getInstance().allocate(nElements * sizeof(NFAPI_CRC_INDICATION_PDU_T)));
            std::fill(data, data + nElements, NFAPI_CRC_INDICATION_PDU_T());
        } catch (...) {
            std::cerr << "Error: Failed to allocate memory\n";
            MemoryPool::getInstance().deallocate(data, nElements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            throw;
        }

        numAllocated += nElements;
        for (size_t i = 0; i < nElements; ++i) {
            data[i].rxiTag = RX_UE_INFORMATION_TAG + nextIndex++;
            data[i].rnti = static_cast<uint64_t>(std::hash<std::thread::id>{}(std::this_thread::get_id()));
            data[i].crcFlag = (rand() % 2) == 0;
        }

        return data;
    }

    void deallocate(NFAPI_CRC_INDICATION_PDU_T* data, size_t nElements) {
        if (!data || numAllocated - nElements < 0) {
            std::cerr << "Error: Invalid memory or incorrect number of elements for deallocation\n";
            return;
        }

        MemoryPool::getInstance().deallocate(data, nElements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        numAllocated -= nElements;
    }

private:
    std::atomic<size_t> nextIndex;
    size_t numAllocated;
};

void log(const char* message) {
    static std::mutex logMutex;
    static std::function<void(const char*)> logFunction = [](const char* message) {
        // Add your logging implementation here, such as writing to a file or using a logging library
        std::cout << "[" << std::this_thread::get_id() << "] " << message << "\n";
    };

    std::lock_guard<std::mutex> lock(logMutex);
    logFunction(message);
}

NFAPI_CRC_INDICATION_PDU_T* createArray(size_t nElements) {
    Allocator allocator;
    return allocator.allocate(nElements);
}

