import os
import yaml
from abc import ABC, abstractmethod
import logging
from typing import Dict, Any, Type, Callable, Union
import concurrent.futures as cf

class WebService(ABC):
    def __init__(self, config: Dict[str, Any]):
        self._config = config

    @abstractmethod
    def validate_config(self) -> bool:
        pass

    @abstractmethod
    def initialize(self) -> None:
        pass

    @abstractmethod
    def start(self) -> None:
        pass

class ServiceRegistry:
    _services: Dict[str, Callable[[Dict[str, Any]], Type[WebService]]] = {}

    @staticmethod
    def register_factory(service_id: str, factory_func: Callable[[Dict[str, Any]], Type[WebService]]) -> None:
        ServiceRegistry._services[service_id] = factory_func

class WebServiceManager:
    def __init__(self, base_dir: str):
        self.base_dir = base_dir
        self.running_services = {}
        self.logger = logging.getLogger(__name__)

    def _read_config(self) -> Dict[str, Any] or None:
        try:
            with open(os.path.join(self.base_dir, 'config.yaml'), 'r') as f:
                config = yaml.safe_load(f)
                if not config or ('web.config' in os.listdir(self.base_dir)):
                    return None
                return config
        except FileNotFoundError:
            self.logger.error(f"Configuration file '{os.path.join(self.base_dir, 'config.yaml')}' not found.")
            return None

    def _get_service(self, service_id: str) -> Union[Type[WebService], None]:
        if service_id in ServiceRegistry._services:
            return ServiceRegistry._services[service_id]
        else:
            self.logger.error(f"Unknown service ID '{service_id}'.")
            return None

    def _start_service(self, service: Type[WebService], service_id: str) -> bool:
        try:
            service_instance = service(service._config)
            if not service_instance.validate_config():
                self.logger.error(f"Invalid configuration for service '{service_id}'.")
                return False
            service_instance.initialize()
            self.running_services[service_id] = service_instance
            service_instance.start()
            self.logger.info(f"Successfully started service '{service_id}'.")
            return True
        except Exception as e:
            self.logger.error(f"Error starting service '{service_id}': {str(e)}")
            return False

    def start(self) -> None:
        config = self._read_config()
        if not config:
            return

        executor = cf.ProcessPoolExecutor(max_workers=os.cpu_count())
        services_to_start = [executor.submit(self._get_service, service_id) for service_id in config['services']]
        successes = sum([self._start_service(*service.result()) for service in cf.as_completed(services_to_start)])
        if not successes == len(config['services']):
            self.logger.error("Failed to start some services.")

    def stop(self, service_id: str = None) -> None:
        for service in list(self.running_services.values()):
            if service_id and service_id != service.__class__.__name__:
                continue
            try:
                service.stop()
                del self.running_services[service.__class__.__name__]
                self.logger.info(f"Successfully stopped service '{service.__class__.__name__}'.")
            except Exception as e:
                self.logger.error(f"Error stopping service '{service.__class__.__name__}': {str(e)}")

    def register_service(cls: Type[WebService], service_id: str) -> None:
        ServiceRegistry.register_factory(service_id, cls)
