    int status; // 0: idle, 1: active, -1: inactive or error
    time_t last_activity;
} Connection;

#define NUM_THREADS 4
pthread_mutex_t connections_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t connections_cond = PTHREAD_COND_INITIALIZER;

static Connection* connections = NULL;
static size_t num_connections = 0;
static time_t timeout = 60; // seconds

void log(const char* message) {
