}

void add_connection(int sockfd, struct sockaddr_in addr) {
    pthread_mutex_lock(&connections_lock);
    Connection* new_conn = (Connection*)malloc(sizeof(Connection));
    if (!new_conn) {
        log("Failed to allocate memory for new connection");
        pthread_mutex_unlock(&connections_lock);
        return;
    }

    new_conn->sockfd = sockfd;
    memcpy(&new_conn->addr, &addr, sizeof(struct sockaddr_in));
    new_conn->status = 0;
    new_conn->last_activity = time(NULL);

    connections = realloc(connections, (num_connections + 1) * sizeof(Connection));
    if (!connections) {
        log("Failed to allocate memory for connection array");
        free(new_conn);
        pthread_mutex_unlock(&connections_lock);
        return;
    }

    connections[num_connections++] = new_conn;
    pthread_mutex_unlock(&connections_lock);
}

void remove_inactive_connections() {
    time_t current_time = time(NULL);

    pthread_mutex_lock(&connections_lock);
    for (size_t i = 0; i < num_connections; ++i) {
        if (current_time - connections[i]->last_activity > timeout) {
            Connection* conn = connections + i;
            connections[i] = connections + --num_connections;
            free(conn);
        }
    }
    pthread_mutex_unlock(&connections_lock);
}

void update_connection(int index, int status) {
    Connection* conn = connections + index;
    conn->status = status;
    conn->last_activity = time(NULL);
}

void* manage_connections(void* arg) {
    fd_set readfds;
    FD_ZERO(&readfds);

    while (true) {
        pthread_mutex_lock(&connections_lock);
        // Iterate through connections and add sockets to readfds that are active.
        for (size_t i = 0; i < num_connections; ++i) {
            if (connections[i]->status == 1) {
                FD_SET(connections[i]->sockfd, &readfds);
            }
        }
        pthread_mutex_unlock(&connections_lock);

        // Handle potential select() performance issues under high-concurrency scenarios.
        if (pselect(FD_SETSIZE, &readfds, NULL, NULL, NULL, NULL) < 0) {
            perror("pselect error");
