```cpp
#include <iostream>
#include <vector>
#include <boost/lockfree/spsc_queue.hpp>
#include <mutex>
#include <atomic>

struct NetworkStat {
    std::string id;
    double latency;
    double throughput;
    double errorRate;
};

class NetworkStatsManager {
private:
    std::vector<NetworkStat> data;
    boost::lockfree::spsc_queue<std::pair<int, NetworkStat>> updatesQueue;
    mutex mtx;
    atomic<size_t> nextId{0};

public:
    NetworkStatsManager() {}

    int addNetworkStat(const NetworkStat& stat) {
        auto id = nextId++;
        data.push_back({id, stat.latency, stat.throughput, stat.errorRate});
        updatesQueue.enqueue({id, stat});
        return id;
    }

    void updateNetworkStat(int id, const NetworkStat& stat) {
        updatesQueue.enqueue({id, stat});
    }

    const NetworkStat& getNetworkStat(int id) {
        auto it = std::find_if(data.begin(), data.end(), [=](const auto& stat) { return stat.id == id; });
        if (it != data.end()) {
            // Lock the mutex to ensure thread safety while modifying the structure
            std::lock_guard<std::mutex> lock(mtx);
            it->latency = it->latency * 0.9 + stat.latency * 0.1; // Simple average update example
            it->throughput = it->throughput * 0.9 + stat.throughput * 0.1;
            it->errorRate = it->errorRate * 0.9 + stat.errorRate * 0.1;
            return *it;
        }
        throw std::runtime_error("Invalid network interface ID");
    }
};
