    sem_t lock;
} NetworkInterface;

typedef struct StatisticEntry {
    unsigned int id;
    unsigned long long rx_bytes, tx_bytes;
    size_t num_interfaces;
    NetworkInterface** interfaces;
} StatisticEntry;

struct SharedData {
    StatisticEntry* entries;
    size_t capacity, count;
    size_t memory_limit;
    pthread_mutex_t lock;
};

void statistic_entry_init(StatisticEntry* entry) {
    entry->id = 0;
    entry->rx_bytes = entry->tx_bytes = 0;
    entry->num_interfaces = 0;
    entry->interfaces = NULL;
}

void statistic_entry_merge(StatisticEntry* dest, const StatisticEntry* src) {
    dest->rx_bytes += src->rx_bytes;
    dest->tx_bytes += src->tx_bytes;
    dest->num_interfaces += src->num_interfaces;
}

void network_interface_init(NetworkInterface* interface) {
    sem_init(&interface->lock, 0, 1);
    interface->id = 0;
    interface->rx_bytes = interface->tx_bytes = 0;
}

StatisticEntry* statistic_entry_create() {
    StatisticEntry* entry = malloc(sizeof(StatisticEntry));
    statistic_entry_init(entry);
    return entry;
}

NetworkInterface* network_interface_create() {
    NetworkInterface* interface = malloc(sizeof(NetworkInterface));
    network_interface_init(interface);
    return interface;
}

