// thread-safe function to add a new statistic entry
void add_statistic(struct SharedData* shared, unsigned int id) {
    StatisticEntry new_entry = { .id = id };
    pthread_mutex_lock(&shared->lock);

    if (shared->count + 1 > shared->capacity) {
        size_t new_capacity;

        if ((new_capacity = (size_t)(shared->memory_limit * 0.9)) <= shared->count) {
            fprintf(stderr, "Out of memory!\n");
            pthread_mutex_unlock(&shared->lock);
            return;
        }

        StatisticEntry* new_entries = realloc(shared->entries, new_capacity * sizeof(StatisticEntry));
        if (!new_entries) {
            fprintf(stderr, "Reallocation failed!\n");
            pthread_mutex_unlock(&shared->lock);
            return;
        }

        shared->capacity = new_capacity;
        shared->entries = new_entries;
    }

    StatisticEntry* entry = &shared->entries[shared->count];
    statistic_entry_init(entry);
    entry->id = id;
    shared->count++;

    pthread_mutex_unlock(&shared->lock);
}

// thread-safe function to update an existing statistic entry
void update_statistic(struct SharedData* shared, unsigned int id, unsigned long long rx_bytes, unsigned long long tx_bytes) {
    pthread_mutex_lock(&shared->lock);

    size_t i;
    for (i = 0; i < shared->count; ++i) {
        if (shared->entries[i].id == id) {
            NetworkInterface** interfaces = shared->entries[i].interfaces;
            unsigned int num_interfaces = shared->entries[i].num_interfaces;

            // Merge statistics from different network interfaces with the same interface ID
            for (size_t j = 0; j < num_interfaces; ++j) {
                sem_wait(&interfaces[j]->lock);
                shared->entries[i].rx_bytes += interfaces[j]->rx_bytes;
                shared->entries[i].tx_bytes += interfaces[j]->tx_bytes;
                sem_post(&interfaces[j]->lock);
            }

            // Update the local statistics for this interface
            sem_wait(&shared->entries[i].interfaces[0]->lock);
            shared->entries[i].rx_bytes += rx_bytes;
            shared->entries[i].tx_bytes += tx_bytes;
            sem_post(&shared->entries[i].interfaces[0]->lock);

            pthread_mutex_unlock(&shared->lock);
            return;
        }
    }

    pthread_mutex_unlock(&shared->lock);
}

// thread-safe function to retrieve statistics based on interface ID
StatisticEntry* get_statistics(const struct SharedData* shared, unsigned int id) {
    StatisticEntry result = { .id = 0 };
    pthread_mutex_lock(&shared->lock);

    size_t i;
    for (i = 0; i < shared->count; ++i) {
        if (shared->entries[i].id == id) {
            result = shared->entries[i];
            break;
        }
    }

    pthread_mutex_unlock(&shared->lock);
    return result.id ? &result : NULL;
}
