function traverseDOMTree(selector, callback) {
    let elements = [];

    function traverse(node) {
        if (node && node.matches && node.tagName) {
            if (callback(node)) elements.push(node);
            for (let i = 0; i < node.children.length; ++i) traverse(node.children[i]);
