#include <atomic>
#include <deque>
#include <unordered_map>
#include <mutex>
#include <condition_variable>
#include <memory>

struct NFAPI_MESSAGE_PDU_T {
    // Define message type and associated parameters here
};

class MessageManager {
public:
    void enqueue(const std::shared_ptr<NFAPI_MESSAGE_PDU_T>& message);
    std::shared_ptr<NFAPI_MESSAGE_PDU_T> dequeue(uint32_t messageType);
    size_t getMessageCount(uint32_t messageType) const;

private:
    std::mutex mtx_;
    std::condition_variable cv_;
    std::unordered_map<uint32_t, std::deque<std::shared_ptr<NFAPI_MESSAGE_PDU_T>>> messagesByType_;
    std::atomic<size_t> totalMessages_{0};

    void cleanup();
};

void MessageManager::enqueue(const std::shared_ptr<NFAPI_MESSAGE_PDU_T>& message) {
    std::unique_lock<std::mutex> lock(mtx_);
    messagesByType_[message->getType()].push_back(message);
    totalMessages_.fetch_add(1);
    cv_.notify_one();
}

std::shared_ptr<NFAPI_MESSAGE_PDU_T> MessageManager::dequeue(uint32_t messageType) {
    std::unique_lock<std::mutex> lock(mtx_);
    auto it = messagesByType_.find(messageType);
    if (it != messagesByType_.end() && !it->second.empty()) {
        auto message = it->second.front();
        it->second.pop_front();
        totalMessages_.fetch_sub(1);
        return message;
    }
    cv_.wait(lock, [this, messageType](){ return messagesByType_.count(messageType) > 0 || !messagesByType_.empty(); });
    return dequeue(messageType);
}

size_t MessageManager::getMessageCount(uint32_t messageType) const {
    std::unique_lock<std::mutex> lock(mtx_);
    auto it = messagesByType_.find(messageType);
    if (it != messagesByType_.end())
        return it->second.size();
    else
        return 0;
}

void MessageManager::cleanup() {
    // Implement memory deallocation strategy here
}
```

