typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} CRC_BUFFER;

CRC_BUFFER *crc_buffer_create(size_t size) {
    if (size < 1 || size > MAX_SIZE) {
        return NULL;
    }

    CRC_BUFFER *buf = mmap(NULL, sizeof(CRC_BUFFER), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (buf == MAP_FAILED) {
        return NULL;
    }

    buf->data = mmap(NULL, size * sizeof(NFAPI_CRC_INDICATION_PDU_T), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (buf->data == MAP_FAILED) {
        munmap(buf, sizeof(CRC_BUFFER));
        return NULL;
    }

    buf->size = size;
    buf->capacity = size;
    pthread_mutex_init(&buf->lock, NULL);

    return buf;
}

void crc_buffer_push(CRC_BUFFER *buf, const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (buf == NULL || pdu == NULL || buf->size >= buf->capacity) {
        return;
    }

    pthread_mutex_lock(&buf->lock);
    memcpy(buf->data + buf->size, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    buf->size++;
    pthread_mutex_unlock(&buf->lock);
}

void crc_buffer_log(const CRC_BUFFER *buf) {
    if (buf == NULL || buf->size > LOG_THRESHOLD) {
        return;
    }

    // Implement logging here, consider using a logging library for asynchronous processing.
}

void crc_buffer_destroy(CRC_BUFFER *buf) {
    if (buf == NULL) {
        return;
    }

    munmap(buf->data, buf->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    munmap(buf, sizeof(CRC_BUFFER));
}
