typedef struct MemoryBlock {
    void *data;
    size_t size;
    struct MemoryBlock *next;
} MemoryBlock;

std::atomic<MemoryBlock*> head = nullptr;
std::atomic<MemoryBlock*> tail = nullptr;
const int MAX_MEMORY_FRAGMENTATION = 50;

void* memory_pool_alloc(size_t size) {
    if (!head || (head && ((unsigned long)(tail - head + size)) > (unsigned long)(MAX_MEMORY_FRAGMENTATION * head->size))) {
        printf("Memory pool nearly exhausted\n");
        return nullptr;
    }

    MemoryBlock *new_block = (MemoryBlock *)malloc(sizeof(MemoryBlock));
    if (!new_block) {
        printf("Out of memory\n");
        // Attempt to free allocated structures before returning the error code
        while (head) {
            MemoryBlock *temp = head;
            head = head->next;
            free(temp);
        }
        return nullptr;
    }

    new_block->data = malloc(size + sizeof(MemoryBlock));
    if (!new_block->data) {
        printf("Out of memory\n");
        free(new_block);
        return nullptr;
    }

    new_block->next = nullptr;
    new_block->size = size;
    new_block->data += sizeof(MemoryBlock);

    if (!head) {
        head = tail = new_block;
    } else {
        tail->next = new_block;
        tail = new_block;
    }

    return new_block->data;
}

void memory_pool_free(void *ptr) {
    MemoryBlock *current = head;
    MemoryBlock *prev = nullptr;

    while (current) {
        if (current == ptr) {
            if (prev) {
                prev->next = current->next;
                if (!current->next) tail = prev;
            } else {
                head = current->next;
                if (!head) tail = nullptr;
            }
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }
}

