#include <pthread.h>
#include <stdbool.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>

typedef struct _Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct _Node *prev, *next;
    pthread_mutex_t lock;
} Node;

static Node* head = NULL;
static Node* tail = NULL;
static size_t count = 0;
static int lock_count = 0;
static pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t notempty = PTHREAD_COND_INITIALIZER;

void init_list() {
    head = (Node*)malloc(sizeof(Node));
    tail = (Node*)malloc(sizeof(Node));
    head->prev = NULL;
    tail->next = NULL;
    pthread_mutex_init(&head->lock, NULL);
    pthread_mutex_init(&tail->lock, NULL);
}

void destroy_list() {
    Node *current = head;
    while (current != NULL) {
        Node *next_node = current->next;
        free(current);
        current = next_node;
    }
    pthread_mutex_destroy(&head->lock);
    pthread_mutex_destroy(&tail->lock);
}

Node* new_node() {
    Node *new_node = (Node*)malloc(sizeof(Node));
    new_node->data.CRCFLAG = rand() % 2;
    new_node->prev = NULL;
    new_node->next = NULL;
    pthread_mutex_init(&new_node->lock, NULL);
    return new_node;
}

void enqueue(Node* node) {
    if (list_lock >= 0) {
        pthread_mutex_lock(&list_lock);
        lock_count++;
    }

    if (head == tail) {
        Node *new_node = new_node();
        node->prev = new_node;
        node->next = new_node;
        new_node->data = node->data;
        new_node->prev = NULL;
        new_node->next = NULL;
        head = new_node;
        tail = new_node;
    } else {
        Node *current = head;
        while (current->next != NULL) current = current->next;
        current->next = node;
        node->prev = current;
        node->next = tail;
        tail->prev = node;
        tail = node;
    }

    if (list_lock >= 0) {
        lock_count--;
        if (lock_count == 0) pthread_mutex_unlock(&list_lock);
    }
}

Node* dequeue() {
    Node *result = NULL;
    if (list_lock >= 0) {
        pthread_mutex_lock(&list_lock);
        lock_count++;
    }

    if (head != tail) {
        result = head;
        if (--count == 0) pthread_cond_signal(&notempty);
        head = head->next;
        if (head != NULL) head->prev = NULL;
        else tail = NULL;
    }

    if (list_lock >= 0) {
        lock_count--;
        if (lock_count == 0) {
            pthread_mutex_unlock(&list_lock);
            while (count == 0 && list_lock >= 0) {
                pthread_cond_wait(&notempty, &list_lock);
            }
        }
    }

    return result;
}
