    std::atomic<NFAPI_CRC_INDICATION_PDU_T*> data;
    struct node* next;
};

// Lock-free linked list structure
struct list {
    struct node* head;
    pthread_mutex_t lock;
    struct mem_alloc allocator;
};

void list_init(struct list* list, size_t capacity) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->allocator.pool = malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->allocator.capacity = capacity;
    list->allocator.allocated = 0;
}

void* list_alloc(struct mem_alloc* alloc) {
    void* ptr = NULL;
    if (alloc->allocated < alloc->capacity) {
        ptr = ((char*)alloc->pool) + alloc->allocated;
        alloc->allocated++;
    } else {
        void* new_pool = realloc(alloc->pool, alloc->capacity * 2);
        if (new_pool == NULL) {
            // Handle memory allocation failure
        }
        alloc->pool = new_pool;
        ptr = ((char*)alloc->pool) + alloc->allocated++;
    }
    return ptr;
}

bool list_insert(struct list* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    struct node* new_node = (struct node*)list_alloc(&list->allocator);
    if (!new_node) {
        // Handle memory allocation failure
        return false;
    }
    new_node->data.store(data, std::memory_order_relaxed);
    struct node* current = list->head;
    struct node** prev = &list->head;
    while (current != NULL) {
        if (current->data.load(std::memory_order_acquire) == data) {
            // Duplicate RNTI detected, discard the current node and its successors
            struct node* next_node = current->next;
            *prev = next_node;
            free(new_node);
            return false;
        }
        prev = &current->next;
        current = current->next;
    }
    // Insert the new node at the head of the list
    new_node->next = list->head;
    list->head = new_node;
    return true;
}

