Next, we define a `HashMap` class that manages the hash map, thread safety, and expiration of inactive sessions.

```cpp
#include <unordered_map>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <queue>
#include <functional>

class HashMap {
public:
    explicit HashMap(std::int64_t expirationThresholdInSeconds)
        : expirationThreshold_(expirationThresholdInSeconds),
          workQueue_(), expiredSessions_() {
        std::thread workerThread([this]() { this->workerLoop(); });
        workerThread.detach();
    }

    void insertOrUpdate(UserSessionData data) {
        std::scoped_lock lock(mutex_);
        auto it = hashMap_.find(data.userID);
        if (it != hashMap_.end()) {
            it->second.sessionID = data.sessionID;
            it->second.lastActivityTimestamp = Clock::now().time_since_epoch().count();
        } else {
            hashMap_[data.userID] = data;
        }
        lock.unlock();
        workQueue_.push(std::bind(&HashMap::process, this, std::ref(data)));
    }

private:
    void workerLoop() {
        while (true) {
            std::function<void(UserSessionData&)> task;
            {
                std::unique_lock<std::mutex> lock(mutex_);
                conditionVariable_.wait(lock, [this](){ return !workQueue_.empty(); });
                if (!workQueue_.empty()) {
                    task = workQueue_.front();
                    workQueue_.pop();
                }
            }
            if (task) {
                process(*task.arg());
            }
        }
    }

    void process(UserSessionData& data) {
        auto currentTimestamp = Clock::now().time_since_epoch().count();
        std::chrono::duration<double> elapsedSeconds = std::chrono::duration_cast<std::chrono::duration<double>>(currentTimestamp - data.lastActivityTimestamp);
        if (elapsedSeconds > std::chrono::seconds(expirationThreshold_)) {
            expiredSessions_.insert(data.userID);
            std::scoped_lock lock(mutex_);
            hashMap_.erase(data.userID);
        } else {
            data.lastActivityTimestamp = currentTimestamp;
        }
    }

    std::int64_t expirationThreshold_;
    std::unordered_map<int, UserSessionData> hashMap_;
    std::mutex mutex_;
    std::condition_variable conditionVariable_;
    std::queue<std::function<void(UserSessionData&)>> workQueue_;
    std::set<int> expiredSessions_;
};
```

