    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    manager->event_callback = NULL;
    return manager;
}

void add_connection(TCPManager *manager, int id) {
    Connection *new_connection = malloc(sizeof(Connection));
    new_connection->id = id;
    new_connection->last_activity = time(NULL);
    new_connection->next = NULL;

    pthread_mutex_lock(&manager->lock);
    if (manager->head == NULL) {
        manager->head = new_connection;
        manager->tail = new_connection;
    } else {
        manager->tail->next = new_connection;
        manager->tail = new_connection;
    }
    ++manager->count;
    if (manager->count > manager->capacity) {
        Connection *temp = manager->head;
        manager->head = temp->next;
        free(temp);
    }
    pthread_mutex_unlock(&manager->lock);
}

void update_connection_activity(TCPManager *manager, int id) {
    pthread_mutex_lock(&manager->lock);
    Connection *current = manager->head;
    while (current != NULL) {
        if (current->id == id) {
            current->last_activity = time(NULL);
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
}

void remove_inactive_connections(TCPManager *manager, int timeout) {
    pthread_mutex_lock(&manager->lock);
    Connection *current = manager->head;
    Connection *prev = NULL;
    while (current != NULL) {
        if (difftime(time(NULL), current->last_activity) > timeout) {
            if (prev == NULL) {
                manager->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            --manager->count;
        } else {
            prev = current;
            current = current->next;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

Connection* get_recent_event_connection(TCPManager *manager, int id) {
    Connection *current = manager->head;
    while (current != NULL) {
        if (current->id == id) {
            break;
        }
        current = current->next;
    }
    return current;
}

void set_event_callback(TCPManager *manager, void (*callback)(void*)) {
    pthread_mutex_lock(&manager->lock);
    manager->event_callback = callback;
    pthread_mutex_unlock(&manager->lock);
}

// Replace this function with the actual event-processing service callback function
