#define NR_CELL_MEASUREMENT_RECORDS_INITIAL_SIZE 1024

struct cell_measurement_system {
    size_t capacity;
    size_t count;
    CELL_MEASUREMENT_RECORD* records;
    pthread_mutex_t lock;
    bool running;
};

void destroy_cell_measurement_system(struct cell_measurement_system* system) {
    if (system->running) {
        system->running = false;
        pthread_mutex_lock(&system->lock);
        free(system->records);
        system->records = NULL;
        system->capacity = 0;
        system->count = 0;
        pthread_mutex_unlock(&system->lock);
    }
}

struct cell_measurement_system* create_cell_measurement_system() {
    struct cell_measurement_system* system = malloc(sizeof(*system));
    if (!system) return NULL;
    system->running = true;
    pthread_mutex_init(&system->lock, NULL);
    system->records = malloc(NR_CELL_MEASUREMENT_RECORDS_INITIAL_SIZE * sizeof(*(system->records)));
    if (!system->records) {
        destroy_cell_measurement_system(system);
        return NULL;
    }
    system->capacity = NR_CELL_MEASUREMENT_RECORDS_INITIAL_SIZE;
    system->count = 0;
    return system;
}

void add_cell_measurement(struct cell_measurement_system* system, MEASUREMENT_REPORT_TAG tag, CELL_ID cell_id, CHANNEL_QUALITY_INDICATOR_TAG cqi_tag, double sinr) {
    pthread_mutex_lock(&system->lock);
    if (system->count == system->capacity) {
        system->records = realloc(system->records, 2 * system->capacity * sizeof(*(system->records)));
        if (!system->records) {
            pthread_mutex_unlock(&system->lock);
            return;
        }
        system->capacity *= 2;
    }
    CELL_MEASUREMENT_RECORD* record = &(system->records[system->count]);
    record->tag = tag;
    record->cell_id = cell_id;
    record->cqi_tag = cqi_tag;
    record->sinr = sinr;
    system->count++;
    pthread_mutex_unlock(&system->lock);
}

