    bool current_status = (CRC_INDICATION_REL8_TAG > last_crc_status);
    if (current_status) crc_count++;
    last_crc_status = current_status;

    return (crc_count > CRCPOLLING_THRESHOLD) ? CRCPOLLING_THRESHOLD_EXCEEDED : NO_ERROR;
}

// Call this function to free the list memory when necessary
