            inet_pton(AF_INET6, serving_cell_str, &context->serving_cell);
        } else if (json_string_equal(key->string, "qos_settings")) {
            char *qos_settings_str = json_string_value(value);
            inet_pton(AF_INET6, qos_settings_str, &context->qos_settings);
        }
    }
}

void read_config(const char* config_file, lte_ue_context** contexts, size_t* contexts_len) {
    FILE *file = fopen(config_file, "r");
    json_t* root;
    json_error_t error;
    size_t i, len;

    root = json_loadf(file, &error);
    if (!root) {
        fprintf(stderr, "%s: %s\n", error.text, error.position);
        return;
    }

    json_array_foreach(root, index, element) {
        lte_ue_context* context = malloc(sizeof(lte_ue_context));
        init_lte_ue_context(context, json_object_get(element));
        if (!*contexts) {
            *contexts = context;
            len = 1;
        } else {
            lte_ue_context** current = contexts;
            while ((*current))
                current = &((*current)->next);
            (*current) = context;
            len++;
        }
    }

    *contexts_len = len;
}

