        NFAPI_CRC_INDICATION_PDU_T *newPool = realloc(pool, newPoolSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (newPool == NULL) {
            fprintf(stderr, "Failed to allocate memory for PDU pool.\n");
            currentPoolIndex = 0;
            poolSize /= 2;
        } else {
            pool = newPool;
            poolSize = newPoolSize;
        }
