    if (pool == NULL) {
        pool = calloc(num, sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (pool == NULL) {
            fprintf(stderr, "Failed to allocate memory for PDU generation.\n");
            return NULL;
        }
