        pool[i].CRC_INDICATION_REL8_TAG = rand() % 0xFFFF + 1;
        pool[i].CRCFLAG = rand() % 2 == 0 ? true : false;
    }

    return pool;
}

int findDuplicateRNTI(const NFAPI_CRC_INDICATION_PDU_T *list, size_t index, size_t listSize) {
