        if (list[index].RNTI == list[i].RNTI) {
            return i;
        }
    }

    for (size_t i = index + 1; i < listSize; ++i) {
        if (list[index].RNTI == list[i].RNTI) {
            return i;
        }
    }

    return -1;
}
