        // Handle out of memory error
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    new_node->data = data;
    new_node->next = NULL;

    current = head;
    if (!current || (new_node->data.RX_UE_INFORMATION_TAG < current->data.RX_UE_INFORMATION_TAG)) {
        new_node->next = head;
        head = new_node;
    } else {
        while (current && (current->next != NULL) && (new_node->data.RX_UE_INFORMATION_TAG > current->next->data.RX_UE_INFORMATION_TAG)) {
            current = current->next;
        }

        new_node->next = current->next;
        current->next = new_node;
    }

    pthread_mutex_unlock(&list_mutex);
}

void sortList() {
    Node *current, *temp;

    pthread_mutex_lock(&list_mutex);

    for (current = head; current != NULL; current = temp) {
        temp = current->next;
        if (current && (current->next != NULL) && (current->data.RNTI > current->next->data.RNTI)) {
            Node* swap_ptr = current;

            while ((swap_ptr != head) && (swap_ptr->data.RNTI < current->data.RNTI)) {
                swap(current, swap_ptr);
                swap_ptr = swap_ptr->next;
            }
        }
    }

    pthread_mutex_unlock(&list_mutex);
}

void batchProcessAndStore() {
    // Implement a temporary buffer mechanism to optimize performance
    Node* temp_head = NULL;
    Node* temp_current = NULL;

    int buffer_size = 1024; // Adjust this value as needed
    int num_nodes_in_buffer = 0;

    pthread_mutex_lock(&list_mutex);

    if (head != NULL) {
        temp_current = head;
        while ((temp_current != NULL) && (num_nodes_in_buffer < buffer_size)) {
            temp_head = temp_current;
            temp_current = temp_current->next;
            num_nodes_in_buffer++;
        }
    }

    if (num_nodes_in_buffer > 0) {
        head = temp_head->next;
        temp_head->next = NULL;

        // Process the buffer and store the data in the database using the data access layer API
        while (temp_head != NULL) {
            Node* next = temp_head->next;
            processAndStore(temp_head->data);
            free(temp_head);
            temp_head = next;
        }
    }

    pthread_mutex_unlock(&list_mutex);
}

void processAndStore(NFAPI_CRC_INDICATION_PDU_T data) {
    // Validate the integrity of each CRC_INDICATION_REL8_TAG before adding it to the list
    if (validateIntegrity(data.CRC_INDICATION_REL8_TAG)) {
        addNodeToList(data);
        storeInDatabase(data);
    } else {
        // Log an error message for invalid data structure
    }
}
```

