void* allocate_and_initialize(size_t long_size, size_t int_size, size_t record_size, size_t max_mem_usage, int linear, unsigned min, unsigned max, size_t seed) {
    void *long_ptr = NULL, *int_ptr = NULL, *record_ptr = NULL;
    long *long_arr = NULL, *int_arr = NULL;
