        posix_memalign(&int_ptr, getpagesize(), int_size * sizeof(int)) != 0 ||
        posix_memalign(&record_ptr, getpagesize(), record_size * sizeof(Record)) != 0) {
        free(long_ptr);
        free(int_ptr);
        free(record_ptr);
        return NULL;
    }

    long_arr = long_ptr;
    int_arr = int_ptr;
    record_arr = record_ptr;

    // Initialize 'int' and 'record' arrays
    for (size_t i = 0; i < int_size; ++i) {
        int_arr[i] = i + 1;
    }
    srand(seed);
    for (size_t i = 0; i < record_size; ++i) {
        record_arr[i].value = rand() % (max - min + 1) + min;
    }

    // Adjust memory allocation based on available system resources
    if ((long_ptr != mmap(long_ptr, long_size * sizeof(long), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0)) == MAP_FAILED ||
        (int_ptr != mmap(int_ptr, int_size * sizeof(int), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0)) == MMAP_FAILED ||
        (record_ptr != mmap(record_ptr, record_size * sizeof(Record), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0)) == MMAP_FAILED) {
        free(long_arr);
        free(int_arr);
        free(record_arr);
        munmap(long_ptr, long_size * sizeof(long));
        munmap(int_ptr, int_size * sizeof(int));
        munmap(record_ptr, record_size * sizeof(Record));
        return NULL;
    }

    // Linear or interleaved initialization
    if (linear) {
        for (size_t i = 0; i < long_size; ++i) {
            ((long*)((char*)long_arr + i * sizeof(long)))[0] = i;
            ((Record*)((char*)record_arr + i * sizeof(long)))[0] = record_arr[i];
        }
    } else {
        size_t index = 0;
        for (size_t i = 0; i < long_size; ++i) {
            ((long*)((char*)long_arr + index * sizeof(long)))[0] = i;
            index += (i % record_size == 0) ? record_size : 1;
            ((Record*)((char*)record_arr + index))[0] = record_arr[index];
        }
    }

    if (max_mem_usage && (long_size * sizeof(long) + int_size * sizeof(int) + record_size * sizeof(Record)) > max_mem_usage) {
        free(long_arr);
        free(int_arr);
        free(record_arr);
        munmap(long_ptr, long_size * sizeof(long));
        munmap(int_ptr, int_size * sizeof(int));
        munmap(record_ptr, record_size * sizeof(Record));
        return NULL;
    }

    return record_arr;
}

void deallocate(void **ptr) {
    if (ptr && *ptr) {
        free(*ptr);
        *ptr = NULL;
    }
}
