#include <stdbool.h>
#include <pthread.h>
#include <time.h>

typedef struct L2CAP_CONNECTION_REQUEST {
    uint16_t l2cap_channel_id;
    char source_address[SOME_ADDRESS_SIZE];
    char destination_address[SOME_ADDRESS_SIZE];
} L2CAP_CONNECTION_REQUEST;

typedef struct L2CAP_REQUEST_POOL {
    L2CAP_CONNECTION_REQUEST *requests;
    size_t capacity;
    size_t used;
    pthread_mutex_t mutex;
} L2CAP_REQUEST_POOL;

void l2cap_request_pool_init(L2CAP_REQUEST_Pool *pool, size_t initial_capacity) {
    pool->requests = calloc(initial_capacity, sizeof(L2CAP_CONNECTION_REQUEST));
    if (!pool->requests) {
        fprintf(stderr, "Failed to allocate memory for L2CAP request pool\n");
        return;
    }
    pool->capacity = initial_capacity;
    pool->used = 0;
    pthread_mutex_init(&pool->mutex, NULL);
}

L2CAP_CONNECTION_REQUEST *l2cap_request_pool_acquire(L2CAP_REQUEST_POOL *pool) {
    L2CAP_CONNECTION_REQUEST *req;
    pthread_mutex_lock(&pool->mutex);

    if (pool->used < pool->capacity) {
        req = &pool->requests[pool->used++];
        memset(req, 0, sizeof(L2CAP_CONNECTION_REQUEST));
        pthread_mutex_unlock(&pool->mutex);
        return req;
    }

    // Reuse previously allocated structures.
    size_t i;
    for (i = 0; i < pool->capacity; ++i) {
        if (!pool->requests[i].l2cap_channel_id) {
            req = &pool->requests[i];
            pool->used--;
            pthread_mutex_unlock(&pool->mutex);
            break;
        }
    }
    if (i == pool->capacity) {
        fprintf(stderr, "No available requests in the pool\n");
        pthread_mutex_unlock(&pool->mutex);
        return NULL;
    }

    // Generate a new request with a unique channel ID.
    srand(time(NULL));
    while (true) {
        req->l2cap_channel_id = rand() % MAX_L2CAP_CHANNEL_ID + 1;
        size_t j;
        for (j = 0; j < pool->used; ++j) {
            if (pool->requests[j].l2cap_channel_id == req->l2cap_channel_id) {
                break;
            }
        }
        if (j == pool->used) {
            break;
        }
    }
    memset(req->source_address, 0, sizeof(req->source_address));
    memset(req->destination_address, 0, sizeof(req->destination_address));

    pthread_mutex_unlock(&pool->mutex);
    return req;
}

void l2cap_request_pool_release(L2CAP_REQUEST_POOL *pool, L2CAP_CONNECTION_REQUEST *req) {
    pthread_mutex_lock(&pool->mutex);
    req->l2cap_channel_id = 0;
    pool->used++;
    pthread_mutex_unlock(&pool->mutex);
}
```

