struct mem_block {
    size_t capacity;
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct mem_block* next;
};

void log_event(const char* message) {
    // Log the event here, replace this with your logging implementation
}

struct mem_block* allocate_memory(size_t size, uint32_t rnti) {
    struct mem_block* block = malloc(sizeof(struct mem_block));
    if (!block) {
        log_event("Failed to allocate memory");
        return NULL;
    }

    block->capacity = size;
    block->data = calloc(size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!block->data) {
        log_event("Failed to allocate data within memory block");
        free(block);
        return NULL;
    }

    for (size_t i = 0; i < size; ++i) {
        block->data[i].RNTI = rnti ^ i;
        block->data[i].CRCFLAG = rand() % 2;
    }

    block->next = NULL;
    return block;
}

struct mem_block* find_appropriate_block(struct mem_block** list, size_t needed) {
    struct mem_block* current = *list;
    while (current && current->capacity >= needed) {
        if (!current->next || current->next->capacity >= needed) {
            return current;
        }
        current = current->next;
    }

    return NULL;
}

void merge_blocks(struct mem_block** list, struct mem_block* block) {
    if (!block || !block->data) {
        return;
    }

    if (*list == NULL) {
        *list = block;
        return;
    }

    struct mem_block* current = *list;
    while (current->next && current->next->capacity >= current->capacity) {
        current = current->next;
    }

    block->next = current->next;
    current->next = block;
}

NFAPI_CRC_INDICATION_PDU_T* generate_list(size_t N, size_t max_delay_ms, uint32_t seed) {
    srand(seed);
    struct mem_block* list = NULL;
    struct mem_block* current_block = NULL;
    size_t total_allocated = 0;
    size_t total_generated = 0;

    clock_t start = clock();
    for (size_t i = 0; i < N; ++i) {
        clock_t elapsed = clock() - start;
        if (elapsed >= max_delay_ms) {
            size_t needed = (N - total_generated) / 2;
            current_block = find_appropriate_block(&list, needed);

            if (!current_block) {
                current_block = allocate_memory(needed, rand());
                if (!current_block) {
                    log_event("Failed to allocate memory, reducing size");
                    continue;
                }
                merge_blocks(&list, current_block);
            }
        }

        total_allocated += current_block->capacity;
        total_generated += current_block->capacity;
    }

    log_event(asprintf("Generated %zu structures, allocated %zu bytes", total_generated, total_allocated));
    return list->data;
}
