/**
 * Retrieves the MD5 hash of a given string using the MessageDigest class.
 *
 * @param input The string to calculate the MD5 hash for.
 * @return The MD5 hash as a hexadecimal string.
 */
public String getMD5Hash(String input) throws Exception {
    // Create a new instance of MessageDigest and initialize it with the MD5 algorithm
    MessageDigest md = MessageDigest.getInstance("MD5");

    // Update the digest with the input bytes, then convert the result to a hexadecimal string
    byte[] messageDigest = md.digest(input.getBytes());
    StringBuilder sb = new StringBuilder();
    for (byte b : messageDigest) {
        sb.append(String.format("%02x", b));
    }

    return sb.toString();
}
