#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} Record;

typedef struct Data {
    long *offsets;
    int *keys;
    Record *records;
    size_t capacity;
    size_t size;
} Data;

Data* initialize_data(size_t capacity) {
    Data *data = malloc(sizeof(Data));
    if (!data) {
        perror("malloc");
        return NULL;
    }

    data->offsets = calloc(capacity + 1, sizeof(long));
    if (!data->offsets) {
        perror("calloc");
        free(data);
        return NULL;
    }

    data->keys = calloc(capacity, sizeof(int));
    if (!data->keys) {
        perror("calloc");
        free(data->offsets);
        free(data);
        return NULL;
    }

    data->records = malloc(sizeof(Record) * capacity);
    if (!data->records) {
        perror("malloc");
        free(data->offsets);
        free(data->keys);
        free(data);
        return NULL;
    }

    data->capacity = capacity;
    data->size = 0;

    srand(time(NULL));

    return data;
}

void resize_data(Data *data, size_t new_capacity) {
    if (new_capacity <= data->capacity)
        return;

    long *tmp_offsets = realloc(data->offsets, sizeof(long) * (new_capacity + 1));
    if (!tmp_offsets) {
        perror("realloc");
        return;
    }
    data->offsets = tmp_offsets;

    int *tmp_keys = realloc(data->keys, sizeof(int) * new_capacity);
    if (!tmp_keys) {
        perror("realloc");
        free(data->offsets);
        return;
    }
    data->keys = tmp_keys;

    Record *tmp_records = realloc(data->records, sizeof(Record) * new_capacity);
    if (!tmp_records) {
        perror("realloc");
        free(data->offsets);
        free(data->keys);
        return;
    }
    data->records = tmp_records;

    data->capacity = new_capacity;
}

int find_available_key(Data *data, size_t start) {
    for (size_t i = start; i < data->size; ++i) {
        if (!data->keys[i]) {
            return i;
        }
    }
    return -1; // key not found
}

int add_record(Data *data, int key, int value) {
    if (data->size >= data->capacity) {
        resize_data(data, 2 * data->capacity);
    }

    int available_key = find_available_key(data, data->size);
    if (available_key == -1) {
        return -1; // failed to find an available key
    }

    data->keys[available_key] = key;
    data->records[available_key].value = value;
