#include <iostream>
#include <random>
#include <chrono>
#include <vector>
#include <new>
#include <memory>
#include <atomic>
#include <mutex>

struct Record {
    int value;
};

class MemoryManager {
public:
    // Constructor with memory limit and maximum number of records
    explicit MemoryManager(size_t max_mem, size_t max_records)
        : max_memory_(max_mem), max_records_(max_records), next_idx_(0) {}

    // Allocate and initialize offsets and keys arrays
    void init();

    // Allocate and initialize records array with random values
    std::vector<Record>* getRecords(size_t num);

    // Dynamically resize records array if necessary
    void resizeRecords(size_t newSize);

private:
    struct MemoryBlock {
        char* data;
        size_t capacity;
        size_t used;
    };

    std::vector<long> offsets_;
    std::vector<int> keys_;
    std::vector<MemoryBlock> memoryBlocks_;
    std::vector<Record> records_;
    size_t next_idx_;

    // Memory limit and maximum number of records
    size_t max_memory_;
    size_t max_records_;

    // Atomic variable to track total used memory
    std::atomic<size_t> totalMemoryUsed{0};

    // Mutex for thread safety
    std::mutex mtx;

    // Random number generator with minimal performance impact
    std::mt19937 rng;
};

void MemoryManager::init() {
    offsets_.emplace_back(0);
    keys_.push_back(0);

    memoryBlocks_.emplace_back(new char[8], 8, 0); // Reserve initial block for overheads
}

std::vector<Record>* MemoryManager::getRecords(size_t num) {
    std::unique_ptr<Record[]> records(new Record[num]);
    for (auto& record : *records) {
        record.value = rng() % 100 + 50; // Random value between [50, 150]
    }
    resizeRecords(num);
    return records.release();
}

void MemoryManager::resizeRecords(size_t newSize) {
    if (newSize <= records_.size()) return;

    // Acquire lock before resizing
    std::unique_lock<std::mutex> lk(mtx);

    const size_t blockSize = sizeof(MemoryBlock) + sizeof(long) * 2 + sizeof(int) * newSize;
    MemoryBlock* memoryBlock = nullptr;

    if (memoryBlocks_.empty()) {
        memoryBlock = static_cast<MemoryBlock*>(operator new(blockSize));
        memoryBlocks_.push_back(*memoryBlock);
    } else {
        // Find a contiguous block with enough free space
        for (auto it = memoryBlocks_.rbegin(); it != memoryBlocks_.rend(); ++it) {
            if ((it->capacity - it->used) >= blockSize) {
                memoryBlock = it.base();
                break;
            }
        }

        // If no suitable block is found, allocate a new one
        if (!memoryBlock) {
            memoryBlock = static_cast<MemoryBlock*>(operator new(blockSize));
            memoryBlocks_.push_back(*memoryBlock);
        }
    }

    // Update memory block information
    memoryBlock->data += sizeof(MemoryBlock);
    memoryBlock->capacity -= blockSize;
    memoryBlock->used = sizeof(long) * 2 + sizeof(int) * newSize;

    // Calculate new offsets, keys and record pointers
    long* offsetPtr = reinterpret_cast<long*>(memoryBlock->data);
    int* keyPtr = reinterpret_cast<int*>(offsetPtr + 1);
    Record** recordPtr = reinterpret_cast<Record**>(keyPtr + newSize);

    // Update variables
    offsets_.push_back(*offsetPtr);
    keys_.insert(keys_.end(), keyPtr, keyPtr + newSize);
    records_.resize(newSize, Record{0});
    std::copy(recordPtr, recordPtr + newSize, records_.data());

    // Update total memory used
    totalMemoryUsed += blockSize;
}
```

