```cpp
#include <vector>
#include <random>
#include <eigen/Eigen>
#include <nlohmann/json.hpp>
#include <spdlog/spdlog.h>
#include <mutex>
#include <atomic>
#include <condition_variable>

class DynamicDataStructure {
public:
    DynamicDataStructure(size_t maxMemoryUsage) : _maxMemoryUsage(maxMemoryUsage),
                                                  _keys(_eigen::aligned_vector<int, 64>(16)),
                                                  _offsets(_eigen::aligned_vector<long, 64>(2)) {
        _keys.resize(1);
        _offsets[0] = 0;
        _offsets[1] = 0;
    }

    int addRecord(int key) {
        std::unique_lock<std::mutex> lock(_mutex);
        auto newKeyIndex = _keys.size();
        _keys.resize(_keys.size() + 1);
        _offsets[1] += (_offsets[1] - _offsets[0]) / _keys.size();
        _offsets[0] += sizeof(long) * 2 + sizeof(int); // long for the offset, int for the key
        _offsets[1] += sizeof(int);                   // store the new key
        _keys[newKeyIndex] = key;

        // Generate a random value within [0, 100) for the record
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, 100);
        _values[newKeyIndex] = dis(gen);

        lock.unlock(); // Notify other threads to continue
        _condition.notify_all();
        return newKeyIndex;
    }

    const int getRecord(size_t index) const {
        std::unique_lock<std::mutex> lock(_mutex);
        lock.unlock(); // Allow other threads to continue
        _condition.wait(lock, [this, index]() { return static_cast<bool>(_keys[index]); });
        return _values[index];
    }

    void serialize(const std::string& filename) const {
        nlohmann::json j;
        for (size_t i = 0; i < _keys.size(); ++i) {
            if (_keys[i]) {
                auto keyObj = j.create_item();
                keyObj["key"] = _keys[i];
                keyObj["value"] = _values[i];
            }
        }
        std::ofstream out(filename);
        out << j.dump(4);
    }

    bool deserialize(const std::string& filename) {
        std::ifstream in(filename);
        if (!in.is_open()) return false;
        nlohmann::json j;
        in >> j;
        for (auto&& item : j.items()) {
            auto key = item.key();
            auto value = item.value();
            addRecord(key);
            _values[key] = value["value"].get<int>();
        }
        return true;
    }

    size_t memoryUsage() const {
        std::unique_lock<std::mutex> lock(_mutex);
        auto usedMemory = (_offsets[1] - _offsets[0]) / sizeof(long) + _keys.size() * sizeof(int) + _values.size() * sizeof(int);
        return usedMemory <= _maxMemoryUsage ? usedMemory : _maxMemoryUsage;
    }

private:
    std::vector<int> _keys;
    Eigen::aligned_vector<long, 64> _offsets;
    Eigen::aligned_vector<int, 64> _values;
    std::mutex _mutex;
    std::condition_variable _condition;
    size_t _maxMemoryUsage;
};
```

