    NFAPI_CRC_INDICATION_PDU_T *pdu = cached_data ? cached_data + idx : NULL;

    for (size_t retries_local = 0; retries_local < MAX_RETRIES; ++retries_local) {
        if (!pdu) pdu = &allocate_array(1)[idx]; // Allocate on each retry to handle high-load conditions

        usleep(pow(2, retries_local)); // Exponential backoff

        if (check_integrity(pdu)) {
            return NULL;
        }

        if (!handle_ue_info_service_call(pdu)) { // Replace with the actual service call function
            ++failures[idx];
        } else {
            retries[idx] = retries_local;
            break;
        }
    }

    return pdu ? pdu : &allocate_array(1)[idx]; // Return allocated data on successful retrieval or after multiple failures
}

void process_data(NFAPI_CRC_INDICATION_PDU_T *pdu, size_t N) {
    if (N > 64) {
        size_t chunk_size = (N + 63) / 64; // Maximum number of chunks for 64-element buffer pool
        for (size_t i = 0; i < chunk_size; ++i) {
            void *thread_args[64];
            size_t j = i * 64;
            for (size_t k = 0; k < 64 && j + k < N; ++k) {
                thread_args[k] = (void*) j + k;
            }
            pthread_t threads[64];
            for (size_t k = 0; k < 64; ++k) {
                pthread_create(&threads[k], NULL, handle_request, thread_args[k]);
            }
            for (size_t k = 0; k < 64; ++k) {
                pthread_join(threads[k], NULL);
            }
        }
    } else {
        void *thread_args[N];
        for (size_t i = 0; i < N; ++i) {
            thread_args[i] = (void*) i;
        }
        pthread_t threads[N];
        for (size_t i = 0; i < N; ++i) {
            pthread_create(&threads[i], NULL, handle_request, thread_args[i]);
        }
        for (size_t i = 0; i < N; ++i) {
            pthread_join(threads[i], NULL);
        }
    }
}
