    packet->ip.ihl = 5;
    packet->ip.version = 4;
    packet->ip.tos = 0;
    packet->ip.tot_len = htons(sizeof(struct iphdr) + sizeof(struct tcphdr) + MAX_PAYLOAD_SIZE);
    packet->ip.id = htons(getpid());
    packet->ip.frag_off = 0;
    packet->ip.ttl = 64;
    packet->ip.protocol = IPPROTO_TCP;
    packet->ip.check = 0;
    packet->ip.saddr = inet_addr("127.0.0.1");
    packet->ip.daddr = inet_addr("127.0.0.1");

    packet->tcp.source = htons(12345);
    packet->tcp.dest = htons(67890);
    packet->tcp.seq = htonl(time(NULL));
    packet->tcp.ack_seq = htonl(time(NULL));
    packet->tcp.doff = 5;
    packet->tcp.res1 = 0;
    packet->tcp.res2 = 0;
    packet->tcp.window = htons(65535);
    packet->tcp.check = 0;
    packet->tcp.urg_ptr = 0;
}

void calc_tcp_checksum(Packet *packet) {
    unsigned short sum;
    char *data = (char*)&packet->ip + sizeof(struct iphdr);
    unsigned int len = htons(ntohs(packet->ip.tot_len) - sizeof(struct iphdr));
    for (int i = 0; i < len; i += 2) {
        sum += ((data[i] << 8) | data[i + 1]);
        if (sum > 0xFFFF) sum -= 0xFFFF;
    }
    packet->tcp.check = csum((u_short*)&packet->ip, sizeof(Packet));
}

int fetch_data(Packet *packet, int retries) {
