        log_error("Invalid checksum found\n");
        // Release allocated resources and return early
    }
}

void process_packets(unsigned int N) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    struct BufferPool buffer_pool;
    initBufferPool(&buffer_pool, 1024);

    for (int i = 0; i < N; ++i) {
        Packet* packet = get_packet_from_pool();
        if (!packet) continue; // Pool is empty, consider resizing or allocating new buffers

        init_packet(packet);
        calc_tcp_checksum(packet);

        int retries = 3;
        while (retries > 0) {
            if (fetch_data(packet, retries)) break; // Successfully fetched data, continue processing
            --retries;
            usleep((uint64_t)pow(2, retries - 1) * 1000); // Exponential backoff
        }

        validate_checksum(packet);

        if (pthread_mutex_trylock(&mutex)) {
            // Process packet here, taking into account caching and other performance considerations
        } else {
            log_error("Lock contention detected\n");
            pthread_mutex_unlock(&mutex);
        }
    }

    pthread_mutex_destroy(&mutex);
}
