typedef struct {
    int TX_POWER_LEVEL;
    float RX_QUALITY_INDICATOR;
    enum DEVICE_STATUS { ACTIVE, INACTIVE, UNKNOWN } DEVICE_STATUS;
} device_stats;

struct retrier {
    pthread_mutex_t lock;
    int retries;
    bool failed;
};

void* retry(void *arg) {
    struct retrier *r = arg;
    while (r->retries < 3 && r->failed == false) {
        sleep(1 << r->retries++);
    }
    return r->retries >= 3 ? (void*) -1 : (void*) 0;
}

int init_device_stats_array(device_stats **arr, int N, size_t buffer_size) {
    *arr = calloc(N, buffer_size);
    if (*arr == NULL) return -1;

    pthread_mutex_t array_lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_attr_t attr;
    pthread_attr_init(&attr);
    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_JOINABLE);

    struct retrier retrier = {.lock = array_lock};
    for (int i = 0; i < N; ++i) {
        struct retrier *local_retrier = &((struct retrier*) calloc(1, sizeof(struct retrier)));
        memcpy(local_retrier, &retrier, sizeof(struct retrier));

        pthread_t thread;
        if (pthread_create(&thread, &attr, retry, local_retrier) != 0) {
            free(local_retrier);
            return -1;
        }

        void* result = pthread_join(thread, NULL);
        if ((int)result == -1) { // error during thread creation or join
            continue;
        }
        if (result != 0) { // retry limit exceeded
            free(local_retrier);
            continue;
        }

        device_stats *d = (*arr) + i;
        d->TX_POWER_LEVEL = -1;
        d->RX_QUALITY_INDICATOR = NAN;
        d->DEVICE_STATUS = UNKNOWN;
    }

    pthread_attr_destroy(&attr);
    return 0;
}

