#define MAX_PACKETS 1024

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    int rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct list_node {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct list_node *next;
} list_node_t;

list_node_t *list_head = NULL;
list_node_t *temp_node = NULL;

void init_list() {
    if (list_head == NULL) {
        list_head = malloc(sizeof(list_node_t));
        list_head->data = NULL;
        list_head->next = NULL;
    }
}

bool is_full() {
    list_node_t *current = list_head;
    int count = 0;
    while (current != NULL) {
        if (current->data == NULL) {
            break;
        }
        current = current->next;
        count++;
    }
    return count >= MAX_PACKETS;
}

void push(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (is_full()) {
        list_node_t *new_head = malloc(sizeof(list_node_t));
        new_head->data = pdu;
        new_head->next = NULL;

        temp_node = list_head;
        while (temp_node->next != NULL) {
            temp_node = temp_node->next;
        }
        temp_node->next = new_head;
    } else {
        list_node_t *new_node = malloc(sizeof(list_node_t));
        new_node->data = pdu;
        new_node->next = list_head;
        list_head = new_node;
    }
}

NFAPI_CRC_INDICATION_PDU_T *pop() {
    if (list_head != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = list_head->data;
        list_node_t *temp = list_head;
        list_head = list_head->next;
        free(temp);
        return pdu;
    }
    return NULL;
}

void reset() {
    NFAPI_CRC_INDICATION_PDU_T *current, *next;
    while (list_head != NULL) {
        current = list_head->data;
        next = current->crc_indication.CRCFLAG; // Set CRCFLAG to zero for each packet in the list
        free(list_head);
        list_head = next;
    }
    init_list();
}
