    NFAPI_CRUC_INDICATION_PDU_T** array;
    semaphore_t mem_semaphore; // Semaphore to limit memory consumption
};

// Function to generate a unique RNTI value within the given range
unsigned int generate_rnti(unsigned int min, unsigned int max) {
    unsigned int rnti = (rand() % (max - min + 1)) + min;
    // Cache generated RNTIs to minimize random number generator calls
    static unsigned int cached_rntis[UINT_MAX / (max - min + 1)];
    if (rnti >= UINT_MAX / (max - min + 1)) {
        rnti = cached_rntis[rnti % (UINT_MAX / (max - min + 1))];
    } else {
        cached_rntis[rnti] = rnti;
    }
    return rnti;
}

void* allocate_and_populate(void* thread_data_ptr) {
    struct thread_data* td = thread_data_ptr;
    size_t index;

    pthread_mutex_lock(&td->mem_semaphore);

    for (index = 0; index < *td->num_allocated; ++index) {
        if (!td->array[index]) {
            td->array[index] = malloc(sizeof(NFAPI_CRUC_INDICATION_PDU_T));
            if (td->array[index]) {
                // Populate the structure here with required fields
                td->array[index]->tag.value = RX_UE_INFORMATION_TAG_VALUE;
                td->array[index]->rnti = generate_rnti(0, MAX_RNTI - 1);
                td->array[index]->crc_tag.value = CRC_INDICATION_REL8_TAG_VALUE;
                td->array[index]->crcflag = rand() % 2;
                // Populate other required fields here
            } else {
                pthread_mutex_unlock(&td->mem_semaphore);
                break;
            }
        } else {
            index++; // Skip over already allocated elements
        }
    }

    pthread_mutex_unlock(&td->mem_semaphore);

    return &index;
}

int create_pdus(size_t max_size, size_t* actual_num_allocated) {
    NFAPI_CRUC_INDICATION_PDU_T** array = NULL;
    struct thread_data td = { .num_allocated = &actual_num_allocated, .array = &array, .mem_semaphore = SEMAPHORE_INITIALIZER(1) };
    pthread_t threads[MAX_THREADS];
    size_t thread_index;

    // Allocate memory for the array
    if (!(array = calloc(max_size, sizeof(NFAPI_CRUC_INDICATION_PDU_T*)))) {
        return -1; // Handle error gracefully
    }

    // Launch threads to populate the array concurrently
    for (thread_index = 0; thread_index < MAX_THREADS && thread_index < max_size; ++thread_index) {
        if (pthread_create(&threads[thread_index], NULL, allocate_and_populate, &td)) {
            break;
        }
    }

    // Wait for all threads to finish
    for (thread_index = 0; thread_index < MAX_THREADS && thread_index < max_size; ++thread_index) {
        void* result;
        if (pthread_join(threads[thread_index], &result)) {
            break;
        }
        size_t index = *(size_t*)result;
        if (index > *actual_num_allocated) {
            *actual_num_allocated = index;
        }
    }

    // Free resources and log memory usage and performance metrics as needed

    return 0;
}
