#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/mman.h>
#include <semaphore.h>
#include <hash_map.h> // Assuming you have a custom hash_map implementation

typedef struct Node {
    char *key;
    double data;
    pthread_mutex_t mutex;
} Node;

struct DataStructure {
    hash_map_t *hash_map;
    Node **nodes;
    size_t capacity;
    size_t size;
    sem_t sem_read, sem_write;
};

DataStructure ds_init(size_t capacity) {
    DataStructure ds;
    ds.capacity = capacity;
    ds.size = 0;
    ds.nodes = mmap(NULL, sizeof(Node *) * capacity, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ds.nodes == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    ds.hash_map = hash_map_init();
    sem_init(&ds.sem_read, 0, 1);
    sem_init(&ds.sem_write, 0, 1);
    return ds;
}

void ds_destroy(DataStructure *ds) {
    if (ds->nodes != MAP_FAILED)
        munmap((void *)ds->nodes, sizeof(Node *) * ds->capacity);
    hash_map_destroy(ds->hash_map);
    sem_destroy(&ds->sem_read);
    sem_destroy(&ds->sem_write);
}

Node *ds_get_node(DataStructure *ds, const char *key) {
    if (hash_map_contains(ds->hash_map, key))
        return hash_map_get(ds->hash_map, key);
    return NULL;
}

void ds_put(DataStructure *ds, const char *key, double data) {
    Node *node = malloc(sizeof(Node));
    node->key = strdup(key);
    node->data = data;
    pthread_mutex_init(&node->mutex, NULL);

    sem_wait(&ds->sem_write);
    hash_map_put(ds->hash_map, key, node);
    ds->nodes[ds->size] = node;
    ds->size++;
    if (ds->size >= ds->capacity)
        ds->capacity *= 2;
    sem_post(&ds->sem_write);
}

void *iterate(void *arg) {
    DataStructure *ds = arg;
    pthread_mutex_lock(&ds->nodes[0]->mutex); // Acquire a lock for the first node to traverse in order

    Node *node = ds->nodes[0];
    while (node != NULL) {
        sem_wait(&ds->sem_read);
        pthread_mutex_lock(&node->mutex);
        Node *next = node->next;
        pthread_mutex_unlock(&node->mutex);
        sem_post(&ds->sem_read);
        node = next;
    }

    pthread_mutex_unlock(&ds->nodes[0]->mutex); // Release the lock after traversing all nodes
    return NULL;
}

void ds_iterate(DataStructure *ds) {
    pthread_t threads[ds->size];
    for (size_t i = 0; i < ds->size; ++i)
        pthread_create(&threads[i], NULL, &iterate, ds);

    for (size_t i = 0; i < ds->size; ++i)
        pthread_join(threads[i], NULL);
}

// Integration with the existing logging framework should be done in a separate function or macro.
