// Global variables for thread synchronization
pthread_mutex_t tasks_mutex = PTHREAD_MUTEX_INITIALIZER;
size_t num_tasks = 0;

TASK_INFO_T* create_task(int id, int priority) {
    TASK_INFO_T* task = malloc(sizeof(TASK_INFO_T));
    if (!task) return NULL;

    // Assign unique ID and current time for scheduled start time
    task->task_id = num_tasks++;
    task->priority = priority;
    time_t now = time(NULL);
    task->scheduled_start_time = now;

    return task;
}

void add_task(TASK_INFO_T* task) {
    pthread_mutex_lock(&tasks_mutex);
    // Handle memory fragmentation and potential resizing of the array here.
    // ...
    tasks[num_tasks] = task;
    num_tasks++;
    pthread_mutex_unlock(&tasks_mutex);
}

void remove_task(int task_id) {
    pthread_mutex_lock(&tasks_mutex);
    for (size_t i = 0; i < num_tasks; ++i) {
        if (tasks[i]->task_id == task_id) {
            free(tasks[i]);
            memmove(tasks + i, tasks + i + 1, --num_tasks * sizeof(TASK_INFO_T));
            break;
        }
    }
    pthread_mutex_unlock(&tasks_mutex);
}

void graceful_shutdown() {
    // Notify dependent services of the shutdown process here.
    // ...

    pthread_mutex_lock(&tasks_mutex);
    for (size_t i = 0; i < num_tasks; ++i) {
        TASK_INFO_T* task = tasks[i];
        free(task);
    }
    num_tasks = 0;
    pthread_mutex_destroy(&tasks_mutex);

    // Ensure that other system components are properly terminated as well.
}
