    pthread_mutex_unlock(&global_lock);
    log_operation("Inserted node with RNTI");
}

NFAPI_CRC_INDICATION_PDU_T* get_node(uint32_t rnti) {
    pthread_mutex_lock(&global_lock);

    Node *current = head;
    while (current != NULL) {
        if (current->data.rnti == rnti) {
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&global_lock);

    if (current == NULL) {
        return NULL;
