    pthread_mutex_lock(&current->lock);

    NFAPI_CRC_INDICATION_PDU_T* ret = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!ret) {
        perror("Error allocating memory\n");
        pthread_mutex_unlock(&current->lock);
        return NULL;
    }

    *ret = current->data;

    pthread_mutex_unlock(&current->lock);
    log_operation("Retrieved node with RNTI");
    return ret;
}
