// Custom memory pool
typedef struct mem_pool {
    void* buffer;
    size_t capacity;
    size_t allocated;
    struct mem_pool *next;
} MemPool;

// Thread-safe operations
pthread_mutex_t pdu_list_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t pdu_list_cond = PTHREAD_COND_INITIALIZER;

MemPool* mem_pool_head = NULL;
size_t num_pdus = 0;

// Memory pool functions
void* mem_pool_alloc(size_t size) {
    MemPool *current = mem_pool_head;
    if (!current) {
        current = malloc(sizeof(MemPool));
        if (!current) return NULL;
        current->capacity = size;
        current->allocated = 0;
        current->next = NULL;
        mem_pool_head = current;
    }

    void* data = NULL;
    if (current->allocated >= current->capacity) {
        current = current->next;
    }

    if (current && current->allocated < current->capacity) {
        data = ((char*)current->buffer) + current->allocated;
        current->allocated++;
    } else {
        void* new_data = malloc(size);
        if (!new_data) return NULL;
        MemPool *new_pool = malloc(sizeof(MemPool));
        if (!new_pool) {
            free(new_data);
            return NULL;
        }
        new_pool->capacity = size;
        new_pool->allocated = 1;
        new_pool->buffer = new_data;
        new_pool->next = current;
        current = new_pool;
    }

    return data;
}

void mem_pool_free(void* ptr) {
    if (!ptr) return;
    MemPool *current = mem_pool_head, *prev = NULL;
    for (; current; prev = current, current = current->next) {
        if (current->buffer == ptr) {
            void* old_data = ((char*)current->buffer) + current->allocated--;
            memmove(ptr, old_data, current->capacity - current->allocated);
            current->allocated = 0;
            return;
        }
    }
}

