static size_t total_records = 0;
static size_t num_calls = 0;

offset_t* offset_array(size_t max) {
    if (max > SIZE_MAX / sizeof(offset_t))
        return NULL;

    offset_t *offsets = malloc(max * sizeof(offset_t));
    if (!offsets)
        return NULL;

    for (size_t i = 0; i < max; ++i)
        offsets[i].offset = i;

    return offsets;
}

key_t* key_array(size_t size) {
    if (size > INT_MAX)
        return NULL;

    key_t *keys = malloc(size * sizeof(key_t));
    if (!keys)
        return NULL;

    for (size_t i = 0; i < size; ++i) {
        keys[i].key = i + 1;
        for (size_t j = 0; j < i; ++j) {
            while (keys[i].key == keys[j].key)
                keys[i].key = (++i + 1) % size + 1;
        }
    }

    return keys;
}

record_t* record_array(size_t num, int min, int max) {
    if (num > SIZE_MAX / sizeof(record_t))
        return NULL;

    record_t *records = malloc(num * sizeof(record_t));
    if (!records)
        return NULL;

    pthread_mutex_lock(&log_mutex);
    num_calls++;
    total_records += num;
    pthread_mutex_unlock(&log_mutex);

    for (size_t i = 0; i < num; ++i) {
        records[i].record = min + rand() % (max - min + 1);
        int found = false;
        for (size_t j = 0; j < i; ++j) {
            if (records[i].record == records[j].record) {
                --i;
                found = true;
                break;
            }
        }
        if (!found)
            continue;

        while (found) {
            records[i].record = min + rand() % (max - min + 1);
            found = false;
            for (size_t j = 0; j < i; ++j) {
                if (records[i].record == records[j].record) {
                    found = true;
                    break;
                }
            }
        }
    }

    return records;
}
