#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    sem_t mutex;
    size_t num_elements;
    NFAPI_CRC_INDICATION_PDU_T* data;
    void (*log_callback)(const char* message);
} PDU_BUFFER;

static void init_pdu_buffer(PDU_BUFFER* buffer, size_t max_packets) {
    buffer->num_elements = 0;
    buffer->data = calloc(max_packets, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!buffer->data) {
        fprintf(stderr, "Error allocating memory for PDU buffer\n");
        exit(-1);
    }
    buffer->mutex = sem_init(Semaphore_Unsigned, 1, 1);
}

static void destroy_pdu_buffer(PDU_BUFFER* buffer) {
    free(buffer->data);
    sem_destroy(buffer->mutex);
}

static bool validate_tag(RX_UE_INFORMATION_TAG tag, const RANGE_T* range) {
    return (tag >= range->min && tag <= range->max);
}

static bool validate_rnti(RNTI rnti, const RANGE_T* range) {
    return (rnti >= range->min && rnti <= range->max);
}

static NFAPI_CRC_INDICATION_PDU_T get_packet_data(void) {
    // Implement timely retrieval of packet data from external sources here.
    // Consider network latency and data throughput to minimize delays and optimize resource usage.
}

static void* fetch_and_process_packet(void* arg) {
    PDU_BUFFER* buffer = (PDU_BUFFER*)arg;

    while (true) {
        sem_wait(&buffer->mutex);

        if (buffer->num_elements >= MAX_PACKETS) {
            break;
        }

        NFAPI_CRC_INDICATION_PDU_T packet_data = get_packet_data();

        // Validate RX_UE_INFORMATION_TAG and RNTI fall within specified valid ranges.
        if (validate_tag(packet_data.tag, &VALID_RADIO_BEARER_CONTEXT_TAG_RANGE) &&
            validate_rnti(packet_data.rnti, &VALID_RNTI_RANGE)) {

            // Store the packet in the buffer and log if required.
            sem_post(&buffer->mutex);
            buffer->data[buffer->num_elements++] = packet_data;

            if (buffer->log_callback) {
                buffer->log_callback("Stored PDU");
            }
        } else {
            // Log error and skip the current packet.
            if (buffer->log_callback) {
                buffer->log_callback("Invalid PDU discarded");
            }
        }
    }

    return NULL;
}

void init_pdu_handler(PDU_BUFFER* buffer, size_t max_packets, void (*log_callback)(const char* message)) {
    init_pdu_buffer(buffer, max_packets);
    buffer->log_callback = log_callback;

    pthread_t thread_id;
    pthread_create(&thread_id, NULL, &fetch_and_process_packet, buffer);
}

void deinit_pdu_handler(PDU_BUFFER* buffer) {
    destroy_pdu_buffer(buffer);
}
```
In this code:
- `init_pdu_buffer()` initializes the PDU buffer with a given maximum size.
- `destroy_pdu_buffer()` frees the memory allocated for the buffer and cleans up semaphore resources.
- `validate_tag()` and `validate_rnti()` validate if the tag and RNTI fall within specified valid ranges.
- `get_packet_data()` retrieves the packet data from external sources, considering network latency and data throughput to minimize delays and optimize resource usage.
- `fetch_and_process_packet()` is a worker thread that fetches packets and stores them in the buffer if they are valid. It also logs errors for invalid packets.
- `init_pdu_handler()` initializes the buffer, sets up the log callback, and creates a worker thread.
- `deinit_pdu_handler()` destroys the buffer and terminates the worker thread.']

