    size_t capacity;
    size_t length;
    pthread_mutex_t lock;
} ListManager;

ListManager* list_manager_create(size_t max_structures) {
    ListManager *list = malloc(sizeof(ListManager));
    if (!list) return NULL;

    list->capacity = max_structures;
    list->length = 0;
    list->data = calloc(max_structures, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void list_manager_destroy(ListManager **list_ptr) {
    ListManager *list = *list_ptr;

    if (list && list->data) {
        free(list->data);
        pthread_mutex_destroy(&list->lock);
        free(list);
        *list_ptr = NULL;
    }
}

void list_manager_push(ListManager *list, const NFAPI_CRC_INDICATION_PDU_T *item) {
    pthread_mutex_lock(&list->lock);

    if (list->length >= list->capacity) {
        printf("Overflow: list is full.\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    memcpy(&(list->data[list->length]), item, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->length++;

    pthread_mutex_unlock(&list->lock);
}

void list_manager_pop(ListManager *list, NFAPI_CRC_INDICATION_PDU_T *item) {
    pthread_mutex_lock(&list->lock);

    if (list->length == 0) {
        printf("Underflow: list is empty.\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    memcpy(item, &(list->data[0]), sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memmove(&(list->data[0]), &(list->data[1]), (list->length - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->length--;

    pthread_mutex_unlock(&list->lock);
}

void check_crc(const NFAPI_CRC_INDICATION_PDU_T *item) {
    // Implement your CRC validation logic here
    // If the CRC is invalid, log an error message but do not halt the operation.
    if (!item->crc_indication.crcFlag) {
        printf("Error: Invalid CRC detected.\n");
    }
}

void periodically_check(ListManager *list, int interval) {
    struct timespec sleep_time = { .tv_sec = 0, .tv_nsec = interval * 100000000 };
    clock_gettime(CLOCK_MONOTONIC, &sleep_time);

    while (1) {
        check_crc(&(list->data[0]));

        nanosleep(&sleep_time, NULL);
        clock_gettime(CLOCK_MONOTONIC, &sleep_time);
    }
}
