record* create_data_pipeline(size_t offsets_size, size_t keys_size, unsigned max_key) {
    record *records = NULL;
    long *offsets = NULL;
    int *keys = NULL;

    // Check for non-zero input values
    if (!(offsets_size && keys_size && max_key)) return NULL;

    // Allocate memory and handle errors
    offsets = malloc(offsets_size * sizeof(long));
    if (!offsets) {
        perror("Error: failed to allocate memory for offsets");
        goto cleanup;
    }

    keys = malloc(keys_size * sizeof(int));
    if (!keys) {
        perror("Error: failed to allocate memory for keys");
        free(offsets);
        goto cleanup;
    }

    records = malloc(keys_size * sizeof(record));
    if (!records) {
        perror("Error: failed to allocate memory for records");
        free(offsets);
        free(keys);
        goto cleanup;
    }

    // Initialize offsets and keys arrays
    for (size_t i = 0; i < offsets_size; ++i) {
        offsets[i] = i + 1;
    }

    for (size_t i = 0; i < keys_size; ++i) {
        keys[i] = rand() % max_key + 1;
        // Validate key is present in the offsets array and is within the bounds of keys_size
        if (!binary_search(offsets, offsets_size, keys[i])) {
            fprintf(stderr, "Error: invalid key %d\n", keys[i]);
            goto cleanup;
        }
    }

    // Populate records array with random values and validate keys
    for (size_t i = 0; i < keys_size; ++i) {
        record *current_record = &records[i];
        int key_index = binary_search(offsets, offsets_size, keys[i]) - offsets;
        current_record->key = keys[i];
        current_record->id = 'A' + i;
        current_record->value = (double)rand() / RAND_MAX * 1.0;
    }

    // Return the records array on success
    return records;

cleanup:
    if (records) free(records);
    if (keys) free(keys);
    if (offsets) free(offsets);

    return NULL;
}

// Helper function for binary search in the offsets array
bool binary_search(long *array, size_t size, int key) {
    size_t start = 0;
    size_t end = size - 1;
    while (start <= end) {
        size_t mid = (start + end) / 2;
        if (array[mid] == key) return true;
        else if (array[mid] < key) start = mid + 1;
        else end = mid - 1;
    }
    return false;
}
