// Cache of section data
void* cache;
size_t cache_size;

int handle_post_request(const char *body, size_t body_len) {
    request_data *req = mmap(NULL, sizeof(request_data), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    sem_wait(&lock); // Acquire lock before parsing the request

    json_object *req_obj = json_tokener_parse(body);
    if (!json_object_get(req_obj, "user_id")) {
        sem_post(&lock); // Release lock and return error status
        goto cleanup;
    }
    memcpy(req->user_id, json_object_get_int(json_object_get(req_obj, "user_id")), sizeof(int));

    if (!json_object_get(req_obj, "session_token")) {
        sem_post(&lock); // Release lock and return error status
        goto cleanup;
    }
    strcpy(req->session_token, json_object_get_string(json_object_get(req_obj, "session_token")));

    if (!json_object_get(req_obj, "updates")) {
        sem_post(&lock); // Release lock and return error status
        goto cleanup;
    }
    req->updates = json_object_get(req_obj, "updates");

    bool authorized = is_authorized(req->user_id, req->session_token);
    if (!authorized) {
        sem_post(&lock); // Release lock and return error status
        goto cleanup;
    }

    process_updates(req->updates, cache, &cache_size);
    int status = handle_dependencies(req->user_id, req->session_token);
    if (status != HTTP_OK) {
        sem_post(&lock); // Release lock and return error status
        goto cleanup;
    }

    save_updates(req->updates);
    log_success("Update successful for user ID: " + to_string(req->user_id));

cleanup:
    munmap(req, sizeof(request_data));
    sem_post(&lock); // Release lock
    return status;
}
