typedef struct {
    char client_id[64];
    char file_path[256];
    char checksum[SHA256_DIGEST_LENGTH];
    uint32_t synchronization_flag;
} FILE_SYNC_REQUEST_T;

struct dependency {
    char* prerequisite;
    char* dependent;
};

struct system {
    pthread_mutex_t mutex;
    FILE_SYNC_REQUEST_T requests[MAX_FILES];
    struct dependency dependencies[MAX_FILES][MAX_FILES];
    int num_requests;
};

void compress_data(void* data, size_t* data_len, size_t* compressed_size);
void decompress_data(void* data, size_t compressed_size, size_t* data_len, void** output);

int is_authorized(const char* client_id, const char* session_token);
bool check_dependencies(FILE_SYNC_REQUEST_T request);
bool write_file(FILE_SYNC_REQUEST_T request);

void synchronize(struct system* sys, FILE_SYNC_REQUEST_T* requests, int num_requests) {
    for (int i = 0; i < num_requests; ++i) {
        if (!is_authorized(requests[i].client_id, requests[i].session_token)) {
            continue;
        }
        pthread_mutex_lock(&sys->mutex);
        sys->requests[sys->num_requests] = *requests[i];
        ++sys->num_requests;
        pthread_mutex_unlock(&sys->mutex);
    }

    for (int i = 0; i < sys->num_requests; ++i) {
        FILE_SYNC_REQUEST_T request = sys->requests[i];
        if (!check_dependencies(request)) {
            continue;
        }
        pthread_mutex_lock(&sys->mutex);
        for (int j = 0; j < sys->num_requests; ++j) {
            FILE_SYNC_REQUEST_T dependent_request = sys->requests[j];
            if (strcmp(dependent_request.file_path, request.file_path) == 0) {
                continue;
            }
            if (write_file(dependent_request)) {
                check_dependencies(request);
            }
        }
        pthread_mutex_unlock(&sys->mutex);
        if (!write_file(request)) {
            continue;
        }
    }
}
```

