    if (list->length >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        LTE_PHY_RX_FRAME_INFO_T* new_frames = realloc(list->frames, new_capacity * sizeof(LTE_PHY_RX_FRAME_INFO_T));
