#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define NUM_ELEMENTS 10000
#define ALIGNMENT 64

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

struct dyn_list {
    NFAPI_CRC_INDICATION_PDU_T *elements;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
};

void init_dyn_list(struct dyn_list *list) {
    list->capacity = 0;
    list->count = 0;
    list->elements = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void resize_up(struct dyn_list *list, size_t new_size) {
    if (new_size <= list->capacity) return;

    NFAPI_CRC_INDICATION_PDU_T *new_elements = (NFAPI_CRC_INDICATION_PDU_T *) aligned_alloc(ALIGNMENT, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (list->elements) {
        memcpy(new_elements, list->elements, list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        free(list->elements);
    }

    list->elements = new_elements;
    list->capacity = new_size;
}

void resize_down(struct dyn_list *list) {
    if (list->count <= list->capacity / 2) return;

    NFAPI_CRC_INDICATION_PDU_T *new_elements = (NFAPI_CRC_INDICATION_PDU_T *) aligned_alloc(ALIGNMENT, list->count * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    memcpy(new_elements, list->elements, list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    free(list->elements);
    list->elements = new_elements;
    list->capacity = list->count;
}

void push_back(struct dyn_list *list, const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list->lock);

    if (list->count == list->capacity) resize_up(list, list->capacity * 2);

    memcpy(&list->elements[list->count], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    ++list->count;

    pthread_mutex_unlock(&list->lock);
}

void pop_front(struct dyn_list *list) {
    if (list->count == 0) return;

    pthread_mutex_lock(&list->lock);

    memmove(&list->elements[0], &list->elements[1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (--list->count));

    pthread_mutex_unlock(&list->lock);
}

void delete_at(struct dyn_list *list, size_t index) {
    if (index >= list->count) return;

    pthread_mutex_lock(&list->lock);

    memmove(&list->elements[index], &list->elements[index + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list->count - index - 1));
    --list->count;

    pthread_mutex_unlock(&list->lock);
}

void deallocate_dyn_list(struct dyn_list *list) {
    free(list->elements);
    pthread_mutex_destroy(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T *get_at(const struct dyn_list *list, size_t index) {
    if (index >= list->count) return NULL;
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *pdu = &list->elements[index];
    pthread_mutex_unlock(&list->lock);
    return pdu;
}
```

