        free(uncertainties);
        fprintf(stderr, "Failed to allocate memory for points.\n");
        exit(EXIT_FAILURE);
    }

    Metadata *mds = malloc(num_values * sizeof(Metadata));
    if (!mds) {
        free(values);
        free(uncertainties);
        free(pts);
        fprintf(stderr, "Failed to allocate memory for metadata.\n");
        exit(EXIT_FAILURE);
    }

    // Initialize values and uncertainties arrays
