    // Initialize metadata array with descriptive strings based on value, index, timestamp, and location
    const char *location = "example_location"; // Replace with actual location or get from external source

    for (size_t i = 0; i < num_values; ++i) {
        size_t len = snprintf(NULL, 0, "%.6f[%d] (%s) %s", values[i], i + 1, timestamp, location);
        if (!len) {
            free(values);
            free(uncertainties);
            free(pts);
            free(mds);
            fprintf(stderr, "Failed to initialize metadata string.\n");
            exit(EXIT_FAILURE);
        }

        mds[i].description = malloc(len + 1);
        if (!mds[i].description) {
            free(values);
            free(uncertainties);
            free(pts);
            free(mds);
            fprintf(stderr, "Failed to allocate memory for metadata description.\n");
            exit(EXIT_FAILURE);
        }

