        snprintf(mds[i].description + strlen(timestamp), len - strlen(timestamp) + 1, "%.6f[%d] (%s) %s", values[i], i + 1, location);
        mds[i].description_len = len;
    }

    *points = pts;
    *metadata = mds;
}
