#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <sys/mman.h>

typedef struct Record {
    int value;
    long offset;
};

struct MemoryPool {
    void* data;
    size_t capacity;
    size_t used;
};

void log_memory(const char* msg, void* ptr, size_t size) {
    printf("%lu [%ld] %s @ %p, size: %zu\n",
           time(NULL), pthread_self(), msg, ptr, size);
}

MemoryPool* memory_pool_create(size_t capacity) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->capacity = capacity;
    pool->used = 0;
    pool->data = mmap(NULL, capacity, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    if (!pool->data) {
        free(pool);
        return NULL;
    }

    log_memory("Mmap", pool->data, capacity);
    return pool;
}

void* memory_pool_alloc(MemoryPool* pool) {
    void* mem = pool->data + pool->used;

    if (mem - pool->data >= pool->capacity - pool->used) {
        log_memory("Reallocating memory pool", pool->data, pool->capacity);
        pool->data = realloc(pool->data, 2 * pool->capacity);

        if (!pool->data) {
            log_memory("Failed to reallocate memory pool", pool->data, pool->capacity);
            free(pool);
            return NULL;
        }

        pool->capacity *= 2;
    }

    log_memory("Allocating from memory pool", mem, sizeof(long) + sizeof(int));
    pool->used += sizeof(long) + sizeof(int);
    return mem;
}

void memory_pool_free(MemoryPool* pool) {
    if (pool->data) {
        munmap(pool->data, pool->capacity);
        free(pool);
    }
}

long* offsets_alloc(size_t size) {
    long* offsets = malloc(size * sizeof(long));

    if (!offsets) return NULL;

    log_memory("Allocating offsets", offsets, size * sizeof(long));
    return offsets;
}

int* keys_alloc(size_t size) {
    int* keys = malloc(size * sizeof(int));

    if (!keys) return NULL;

    log_memory("Allocating keys", keys, size * sizeof(int));
    return keys;
}

Record* records_alloc(size_t size, MemoryPool* pool) {
    Record* records = malloc(size * sizeof(Record));

    if (!records) return NULL;

    for (size_t i = 0; i < size; ++i) {
        records[i].offset = memory_pool_alloc(pool);

        if (!records[i].offset) {
            free(records);
            return NULL;
        }
    }

    log_memory("Allocating records", records, size * sizeof(Record));
    return records;
}

void init_records(size_t count, Record* records, MemoryPool* pool, int min, int max) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    for (size_t i = 0; i < count; ++i) {
        pthread_mutex_lock(&lock);

        records[i].value = rand() % (max - min + 1) + min;
        records[i].offset += (long)pthread_self(); // Add thread ID to offset for debugging

        pthread_mutex_unlock(&lock);
    }
}

int* get_keys(const char* source, size_t* out_size) {
    *out_size = 0;

    FILE* file = fopen(source, "r");

    if (!file) return NULL;

    int key;
    while (fscanf(file, "%d", &key) == 1) ++(*out_size);

    rewind(file);
    int* keys = keys_alloc(*out_size);

    if (!keys) {
        fclose(file);
        return NULL;
    }

    for (size_t i = 0; i < *out_size; ++i) {
        if (fscanf(file, "%d", &key) != 1) break;
        keys[i] = key;
    }

    fclose(file);
    return keys;
}

long* get_offsets(const char* source, size_t* out_size) {
    *out_size = 0;

    FILE* file = fopen(source, "r");

    if (!file) return NULL;

    long offset;
    while (fscanf(file, "%ld", &offset) == 1) ++(*out_size);

    rewind(file);
    long* offsets = offsets_alloc(*out_size);

    if (!offsets) {
        fclose(file);
        return NULL;
    }

    for (size_t i = 0; i < *out_size; ++i) {
        if (fscanf(file, "%ld", &offset) != 1) break;
        offsets[i] = offset;
    }

    fclose(file);
    return offsets;
}

Record** create_records(const char* key_source, const char* offset_source, size_t count, MemoryPool* pool, int min, int max) {
    size_t keys_count = 0;
    int* keys = get_keys(key_source, &keys_count);

    if (!keys) {
        fprintf(stderr, "Error: Failed to read keys from source.\n");
        return NULL;
    }

    size_t offsets_count = 0;
    long* offsets = get_offsets(offset_source, &offsets_count);

    if (!offsets) {
        fprintf(stderr, "Error: Failed to read offsets from source.\n");
        free(keys);
        return NULL;
    }

    Record* records = records_alloc(keys_count, pool);

    if (!records) {
        fprintf(stderr, "Error: Failed to allocate memory for records.\n");
        free(keys);
        free(offsets);
        return NULL;
    }

    init_records(keys_count, records, pool, min, max);

    for (size_t i = 0; i < keys_count; ++i) {
        records[i].value += keys[i]; // Add key to value for debugging
    }

    free(offsets);
    free(keys);
    return records;
}

