size_t allocate_events(NetworkEvent** events, size_t capacity, size_t new_capacity) {
    if (new_capacity <= capacity) return capacity;

    NetworkEvent* temp = realloc(*events, new_capacity * sizeof(NetworkEvent));
    if (!temp) {
        fprintf(stderr, "Error: Failed to allocate memory for events\n");
        return capacity;
    }

    *events = temp;
    memset(&(*events)[capacity], 0, (new_capacity - capacity) * sizeof(NetworkEvent));

    return new_capacity;
}

