    LTE_ENBCONTEXT_CONFIG* configurations;
    size_t capacity;
    size_t num_configs;
    pthread_mutex_t lock;
};

void log_event(const char* event, size_t config_count) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    printf("%s: Allocated/Deallocated %zu configurations for %s event\n", timestamp, config_count, event);
}

struct enb_config_manager* create_enb_config_manager() {
    struct enb_config_manager * manager = malloc(sizeof(struct enb_config_manager));
    if (!manager) {
        perror("malloc");
        return NULL;
    }
    manager->capacity = 500;
    manager->num_configs = 0;
    manager->configurations = calloc(manager->capacity, sizeof(LTE_ENBCONTEXT_CONFIG));
    if (!manager->configurations) {
        perror("calloc");
        free(manager);
        return NULL;
    }
    pthread_mutex_init(&manager->lock, NULL);
    log_event("allocated", manager->capacity);
    return manager;
}

void destroy_enb_config_manager(struct enb_config_manager * manager) {
    free(manager->configurations);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
    log_event("deallocated", manager->capacity);
}

size_t find_empty_slot(const struct enb_config_manager * manager) {
    for (size_t i = 0; i < manager->capacity; ++i) {
        if (!manager->configurations[i].CELL_ID)
            return i;
    }
    return SIZE_MAX;
}

int add_enb_config(struct enb_config_manager * manager, const LTE_ENBCONTEXT_CONFIG* config) {
    size_t empty_slot = find_empty_slot(manager);
    if (empty_slot == SIZE_MAX)
        return -1; // no space available

    pthread_mutex_lock(&manager->lock);
    manager->configurations[empty_slot] = *config;
    manager->num_configs++;
    pthread_mutex_unlock(&manager->lock);

    log_event("allocated", 1);
    return empty_slot;
}

void remove_enb_config(struct enb_config_manager * manager, size_t index) {
    if (index >= manager->capacity || !manager->configurations[index].CELL_ID)
        return;

    pthread_mutex_lock(&manager->lock);
    memmove(&manager->configurations[index], &manager->configurations[index + 1], manager->num_configs - index - 1 * sizeof(LTE_ENBCONTEXT_CONFIG));
    manager->num_configs--;
    manager->configurations[manager->num_configs].CELL_ID = 0;
    pthread_mutex_unlock(&manager->lock);

    log_event("deallocated", 1);
}
```
