        pthread_mutex_unlock(&list_mutex);
        return NULL;
    }
    pthread_mutex_unlock(&list_mutex);
    return cur->bearer;
}

void add_bearer(LTE_RRC_EUTRA_BEARER_CONFIG *bearer) {
    bearer_list_node *new_node = malloc(sizeof(bearer_list_node));
    if (new_node == NULL) {
        fprintf(stderr, "Failed to allocate memory for new bearer node\n");
        return;
    }

    pthread_mutex_lock(&list_mutex);
    if (num_active_bearers >= max_bearers) {
        fprintf(stderr, "Maximum number of active bearers reached. Cannot add more bearers.\n");
        pthread_mutex_unlock(&list_mutex);
        free(new_node);
        return;
    }

    new_node->bearer = bearer;
    new_node->next = head->next;
    head->next = new_node;
    ++num_active_bearers;
    pthread_mutex_unlock(&list_mutex);
}

void remove_bearer(int index) {
    int i = 0;
    bearer_list_node *cur = head->next, *prev = head;

    pthread_mutex_lock(&list_mutex);
    while (cur != NULL && i < index) {
        prev = cur;
        cur = cur->next;
        ++i;
    }
    if (cur == NULL) {
        fprintf(stderr, "Index out of range\n");
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    prev->next = cur->next;
    free(cur->bearer); // Don't forget to free the bearer structure!
    free(cur);
    --num_active_bearers;
    pthread_mutex_unlock(&list_mutex);
}
```

This code provides a basic implementation of a dynamic array of `LTE_RRC_EUTRA_BEARER_CONFIG` structures. It utilizes a doubly-linked list to store the bearer configurations and employs a mutex lock for thread safety during read and write operations on the data structure.

The number of active bearers is tracked, with a configurable limit to prevent resource exhaustion. The function also includes mechanisms to optimize memory usage and minimize lock contention during peak traffic times.']

