```javascript
const fs = require('fs');
const https = require('https');
const { v4: uuidv4 } = require('uuid');

async function uploadFileFromURL(urls, config) {
    const workers = Math.min(Math.floor(urls.length / 3), OS.cpus().length);
    const results = Array(urls.length).fill(null);
    const workerPromises = [];

    for (let i = 0; i < workers; i++) {
        const worker = new WorkerScript('uploadWorker', { workerData: { config } });

        worker.onmessage = (event) => {
            if (event.data[0] === 'result') {
                results[event.data[1]] = event.data[2];
            }
        };

        const tasks = Math.min(urls.length / workers, Infinity);
        const taskChunk = urls.slice(i * tasks, (i + 1) * tasks);
        worker.postMessage({ index: i, urls: taskChunk });
        workerPromises.push(worker);
    }

    await Promise.all(workerPromises);
    return results;
}

// Upload Worker Script
function uploadWorker(config) {
    self.onmessage = (event) => {
        const { index, urls } = event.data;
        const currentUrlIndex = index * urls.length + Math.floor(self.workerData.concurrency * Math.random());

        https.get(urls[currentUrlIndex], (res) => {
            const fileStream = fs.createWriteStream(`file-${uuidv4()}.dat`);

            res.pipe(fileStream);
            res.on('end', () => {
                fileStream.on('finish', () => {
                    self.postMessage(['result', currentUrlIndex, `file-${uuidv4()}.dat`]);
                });
            });
        }).on('error', (err) => {
            console.error(`Error downloading ${urls[currentUrlIndex]}:`, err);
            self.postMessage(['error', currentUrlIndex]);
        });
    };
}
```

