};

std::vector<Transaction> processAndTransformData(const std::vector<Transaction>& transactions, const std::map<std::string, std::function<double(const Transaction&)>>& rules, const int targetTransactionId, std::mutex& dataMutex) {
    std::list<Transaction> transactionList; // dynamically resizable list for efficient insertion
    std::mutex transactionListMutex; // mutex for thread-safe operations on transactionList

    // Find the position to insert the new transaction
    auto it = transactions.begin();
    bool foundTarget = false;
    while (it != transactions.end() && !foundTarget) {
        if ((*it).transactionId == targetTransactionId) {
            foundTarget = true;
        }
        it++;
    }

    // Calculate scores and update statuses based on rules
    std::map<int, Transaction> transactionMap; // map for efficient lookup of transactions
    for (const auto& transaction : transactions) {
        dataMutex.lock();
        transactionMap[transaction.transactionId] = transaction;
        dataMutex.unlock();

        double score = 0.0;
        if (rules.find("amountRule") != rules.end()) {
            score += rules["amountRule"](transaction);
        }
        if (rules.find("statusRule") != rules.end()) {
            score += rules["statusRule"](transaction);
        }
        transactionListMutex.lock();
        Transaction updatedTransaction = transaction;
        updatedTransaction.status = "UPDATED_STATUS"; // specify the new status here
        updatedTransaction.amount = score; // calculate and set the score here
        if (foundTarget) {
            transactionList.insert(it, updatedTransaction);
        } else {
            transactionList.push_back(updatedTransaction);
        }
        transactionListMutex.unlock();
    }

    std::vector<Transaction> result; // final result vector for return
    transactionListMutex.lock();
    result = std::move(transactionList);
    transactionList.clear();
    transactionListMutex.unlock();

    return result;
}
