```c
#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>

#define NUM_THREADS 10
#define MAX_PDUS 10000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[4];
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void generate_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pdu->RX_UE_INFORMATION_TAG = rand();
    pdu->RNTI = rand() % 65536;
    pdu->CRC_INDICATION_REL8_TAG[0] = rand() % 256;
    pdu->CRC_INDICATION_REL8_TAG[1] = rand() % 256;
    pdu->CRC_INDICATION_REL8_TAG[2] = rand() % 256;
    pdu->CRC_INDICATION_REL8_TAG[3] = rand() % 256;
    pdu->CRCFLAG = rand() % 2 == 0 ? true : false;
}

void *generateNFAPDUList(void *arg) {
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)arg;
    int start = (int)(pthread_self() % MAX_PDUS);
    for(int i = start; i < start + MAX_PDUS / NUM_THREADS; ++i) {
        pdu_list[i] = (NFAPI_CRC_INDICATION_PDU_T){0};
        generate_pdu(&pdu_list[i]);
    }
}

void generateNFAPDUList(NFAPI_CRC_INDICATION_PDU_T *pdus, size_t pdus_len) {
    pthread_t threads[NUM_THREADS];
    NFAPI_CRC_INDICATION_PDU_T *pdu_slice;

    for(int i = 0; i < NUM_THREADS; ++i) {
        if((pdus + pdus_len / NUM_THREADS) <= pdus + MAX_PDUS)
            pdu_slice = pdus + pdus_len / NUM_THREADS * i;
        else
            pdu_slice = pdus + (pdus_len % NUM_THREADS == 0 ? pdus_len - pdus_len/NUM_THREADS : pdus_len - pdus_len/NUM_THREADS + i);

        pthread_create(&threads[i], NULL, &generateNFAPDUList, pdu_slice);
    }

    for(int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }
}
