#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>

#define MAX_BATCHES 1024
#define MAX_STRUCTURES_PER_BATCH 64
#define LOG_LEVEL_INFO 3
#define LOG_FILE "radio_communication.log"

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct priority_queue_node {
    time_t arrival_time;
    struct priority_queue_node *next;
    NFAPI_CRC_INDICATION_PDU_T data;
} priority_queue_node_t;

typedef struct priority_queue {
    struct priority_queue_node *head;
    struct priority_queue_node *tail;
    int size;
} priority_queue_t;

priority_queue_t batch_queues[MAX_BATCHES];
NFAPI_CRC_INDICATION_PDU_T *ue_identifiers = NULL;
int ue_identifier_count = 0;
pthread_mutex_t ue_identifiers_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t ue_identifiers_cond = PTHREAD_COND_INITIALIZER;

void generate_rnti(NFAPI_CRC_INDICATION_PDU_T *pdus, int batch_size) {
    for (int i = 0; i < batch_size; ++i) {
        pdus[i].RNTI = ue_identifier_count++;
    }
}

void log(const char *message, int level) {
    time_t now = time(NULL);
    if (level <= LOG_LEVEL_INFO) {
        fprintf(stderr, "%s: [%s] %s\n", ctime(&now), "INFO", message);
    }
}

void *process_batch(void *arg) {
    priority_queue_t *queue = (priority_queue_t *) arg;
    NFAPI_CRC_INDICATION_PDU_T pdus[MAX_STRUCTURES_PER_BATCH];
    double avg_processing_time = 0.0;
    int processed_count = 0;

    while (!queue->size) {
        pthread_cond_wait(&ue_identifiers_cond, &ue_identifiers_lock);
    }

    generate_rnti(pdus, queue->size);
    memcpy(ue_identifiers + processed_count, pdus, sizeof(NFAPI_CRC_INDICATION_PDU_T) * queue->size);

    for (int i = 0; i < queue->size; ++i) {
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);

        pdus[i].CRCFLAG = rand() % 2;

        clock_gettime(CLOCK_MONOTONIC, &end);
        double elapsed_seconds = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1_000_000_000;
        avg_processing_time += elapsed_seconds / processed_count++;
    }

    log(("Processed batch with %d structures in %.3f seconds, average processing time: %.6f\n"), queue->size, elapsed_seconds, avg_processing_time / processed_count);

    free(queue->head);
    queue->head = NULL;
    queue->size = 0;

    pthread_cond_signal(&ue_identifiers_cond);

    return NULL;
}

void manage_batches() {
    for (int i = 0; i < MAX_BATCHES; ++i) {
        batch_queues[i].head = NULL;
        batch_queues[i].tail = NULL;
        batch_queues[i].size = 0;
    }

    pthread_t thread_ids[MAX_BATCHES];

    while (true) {
        for (int i = 0; i < MAX_BATCHES; ++i) {
            if (!batch_queues[i].size && ue_identifier_count > 0) {
                priority_queue_node_t *node = (priority_queue_node_t *) malloc(sizeof(priority_queue_node_t));
                node->arrival_time = time(NULL);
                node->next = NULL;

                batch_queues[i].head = node;
                batch_queues[i].tail = node;
                batch_queues[i].size++;

                ue_identifier_count--;

                pthread_create(&thread_ids[i], NULL, &process_batch, (void *)&batch_queues[i]);
            }
        }

        for (int i = 0; i < MAX_BATCHES; ++i) {
            pthread_join(thread_ids[i], NULL);
        }
    }
}
```
