void* create_node(void* arg) {
    pthread_mutex_lock(&mutex);
    size_t i;
    for (i = 0; i < maxConcurrency && list[i] != NULL; ++i) {}
    if (i == maxConcurrency) {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T* data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!data) {
        pthread_mutex_unlock(&mutex);
