        free(data);
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
    newNode->data = *data;
    newNode->next = list[i];
    list[i] = newNode;
    ++count;
    pthread_mutex_unlock(&mutex);
    return newNode;
}

void validate_and_log_error(NFAPI_CRC_INDICATION_PDU_T* current, Node** first) {
    for (Node* node = *first; node != NULL; node = node->next) {
        if (node->data.rnti == current->rnti && node != current) {
