            destroy_list();
            exit(EXIT_FAILURE);
        }
    }
}

NFAPI_CRC_INDICATION_PDU_T* create_list(size_t n) {
    if (n > 0) {
        init_list(n);
        pthread_t threads[n];
        Node** current = list;
        for (size_t i = 0; i < n; ++i) {
            pthread_create(&threads[i], NULL, create_node, (void*)current++);
        }
        for (size_t i = 0; i < n; ++i)
            pthread_join(threads[i], NULL);
    }
    return list[0];
}
