pthread_cond_t list_notempty;

NR_CELL_INFO_T* create_cell_info() {
    NR_CELL_INFO_T* newNode = (NR_CELL_INFO_T*)malloc(sizeof(NR_CELL_INFO_T));
    if (!newNode) return NULL;
    pthread_mutex_init(&newNode->lock, NULL);
