void add_to_list(NR_CELL_INFO_T* node) {
    if (head == NULL) {
        head = node;
        list_size++;
        pthread_cond_signal(&list_notempty);
        return;
    }

    NR_CELL_INFO_T* current = head;
    while (current->PCI != node->PCI && current->next) {
        current = current->next;
    }

    if (current->PCI == node->PCI) { // Duplicate PCI detected, handle error.
        printf("Error: Duplicate PCI value %d\n", node->PCI);
        destroy_cell_info(node);
        return;
    }

    node->next = current->next;
    current->next = node;
    list_size++;
}

void* worker(void* arg) {
