        NR_CELL_INFO_T* newCellInfo = get_cell_info();
        if (!newCellInfo) continue;

        pthread_mutex_lock(&list_lock);
        // Wait for the list to be non-empty or until a spot becomes available.
        while (head == NULL && list_size >= MAX_CONCURRENCY) {
            pthread_cond_wait(&list_notempty, &list_lock);
