        if (head != NULL) { // Add new cell info to the list if it's not full.
            add_to_list(newCellInfo);
        } else { // Store the new cell info in a temporary buffer and continue iterating when space becomes available.
            NR_CELL_INFO_T* temp = newCellInfo;
        }
        pthread_mutex_unlock(&list_lock);
    }
}

NR_CELL_INFO_T* create_dynamic_list(size_t M, size_t maxConcurrency) {
    if (maxConcurrency > MAX_CONCURRENCY) maxConcurrency = MAX_CONCURRENCY;
    pthread_mutex_init(&list_lock, NULL);
    pthread_cond_init(&list_notempty, NULL);
    size_t workers_count = maxConcurrency + 1; // One additional worker for handling temporary buffer.

    pthread_t* workers = (pthread_t*)malloc(workers_count * sizeof(pthread_t));
    NR_CELL_INFO_T** temp_buffer = (NR_CELL_INFO_T**)calloc(MAX_CONCURRENCY, sizeof(NR_CELL_INFO_T*));

    for (size_t i = 0; i < workers_count; ++i) {
        pthread_create(&workers[i], NULL, worker, NULL);
    }

    size_t processed_cells = 0;
    clock_t start = clock();
    for (size_t i = 0; i < M; ++i) {
        NR_CELL_INFO_T* newCellInfo = get_cell_info();
        if (!newCellInfo) continue;

        pthread_mutex_lock(&list_lock);
        // Add new cell info to the list or store it in temp buffer if the list is full.
        if (head == NULL || list_size < MAX_CONCURRENCY) {
            add_to_list(newCellInfo);
            processed_cells++;
        } else {
            temp_buffer[processed_cells] = newCellInfo;
        }
        pthread_mutex_unlock(&list_lock);
    }

    clock_t end = clock();
    double average_time = (end - start) / (double)CLOCKS_PER_SEC / M;

    // Wait for all workers to finish their work.
    for (size_t i = 0; i < workers_count; ++i) {
        pthread_join(workers[i], NULL);
    }

    free(workers);
    free(temp_buffer);
    pthread_mutex_destroy(&list_lock);
    pthread_cond_destroy(&list_notempty);

    return head;
}
