```c
#include <stdlib.h>
#include <stdbool.h>
#include <stdio.h>
#include <pthread.h>
#include <atomic>
#include <new>

typedef struct UE_CONTEXT_INFO {
    uint64_t UE_ID;
    uint64_t CELL_ID;
    // PACKET_DELIVERY_STATUS is omitted for brevity
} UE_CONTEXT_INFO;

struct list_node {
    UE_CONTEXT_INFO context;
    struct list_node* next;
};

typedef struct {
    struct list_node* head;
    size_t capacity;
    size_t size;
    std::atomic<size_t> successes;
    std::atomic<size_t> failures;
} List;

List* create_list(size_t initial_capacity) {
    if (!initial_capacity || initial_capacity > 5000)
        return nullptr;

    auto list = (List*)malloc(sizeof(List));
    if (!list)
        return nullptr;

    list->head = nullptr;
    list->capacity = initial_capacity;
    list->size = 0;
    list->successes = 0;
    list->failures = 0;

    return list;
}

void destroy_list(List* list) {
    struct list_node *current, *next;
    for (current = list->head; current != nullptr; ) {
        next = current->next;
        free(current);
        current = next;
    }

    free(list);
}

void insert_head(List* list, const UE_CONTEXT_INFO& context) {
    if (list == nullptr || list->size + 1 > list->capacity)
        return;

    auto new_node = (struct list_node*)malloc(sizeof(struct list_node));
    if (!new_node)
        return;

    new_node->context = context;
    new_node->next = list->head;
    list->head = new_node;
    ++list->size;
}

void insert_tail(List* list, const UE_CONTEXT_INFO& context) {
    if (list == nullptr || list->size + 1 > list->capacity)
        return;

    auto new_node = (struct list_node*)malloc(sizeof(struct list_node));
    if (!new_node)
        return;

    new_node->context = context;
    new_node->next = nullptr;

    if (list->head == nullptr) {
        list->head = new_node;
    } else {
        auto current = list->head;
        while (current->next != nullptr)
            current = current->next;
        current->next = new_node;
    }
    ++list->size;
}

void insert_middle(List* list, size_t index, const UE_CONTEXT_INFO& context) {
    if (index >= list->size || list == nullptr || list->size + 1 > list->capacity)
        return;

    auto new_node = (struct list_node*)malloc(sizeof(struct list_node));
    if (!new_node)
        return;

    new_node->context = context;

    if (index == 0) {
        new_node->next = list->head;
        list->head = new_node;
    } else {
        auto current = list->head;
        for (size_t i = 0; i < index - 1 && current != nullptr; ++i)
            current = current->next;

        if (current == nullptr)
            return;

        new_node->next = current->next;
        current->next = new_node;
    }
    ++list->size;
}

void remove(List* list, size_t index) {
    if (index >= list->size || list == nullptr)
        return;

    auto current = list->head;
    for (size_t i = 0; i < index && current != nullptr; ++i)
        current = current->next;

    if (current == nullptr)
        return;

    auto next = current->next;
    free(current);
    --list->size;
    current = next;
}

// Implement traversal, serialization, deserialization, and real-time updates methods here.
```

