        } while (i != 0 && strcmp(records[keys[i - 1]].str, records[i].str));

        keys[i] = i; // Store key for each record
    }

    // Initialize offsets by iterating through the keys array
    offsets[0] = 0;
    for (i = 1; i < config->num_records; ++i) {
        offsets[i] = offsets[i - 1] + 1;
    }

    // Clean up and return the initialized data structures
