// External memory management framework enforcement functions (align, size_check, etc.)
typedef void* aligned_malloc(size_t size);
typedef void aligned_free(void* ptr);

// Custom record structure
typedef struct {
    long value;
    int key;
} record;

record* initialize_data(size_t num_records) {
    // Align and validate memory sizes
    size_t record_size = sizeof(record);
    size_t long_array_size = align(num_records * sizeof(long));
    size_t int_key_array_size = align(num_records * sizeof(int));
    size_t record_block_size = align((num_records + 1) * record_size);

    // Allocate memory for offset and key arrays
    long* offset_arr = (long*)aligned_malloc(long_array_size);
    int* key_arr = (int*)aligned_malloc(int_key_array_size);

    // Generate random values for offsets and keys
    srand(time(NULL));
    for (size_t i = 0; i < num_records; ++i) {
        offset_arr[i] = rand() % 2001 - 1000;
        key_arr[i] = rand() % 1001;
    }

    // Allocate memory for record block and fill with initialized records
    record* records = (record*)aligned_malloc(record_block_size);
    size_t index = 0;
    for (size_t i = 0; i < num_records; ++i) {
        records[index].value = offset_arr[i] + i;
        records[index++].key = key_arr[i];
    }

    // Free unused memory
    aligned_free(offset_arr);
    aligned_free(key_arr);

    return records;
}

