#define MAX_CONNECTIONS 1024
typedef struct {
    struct sockaddr_in addr;
    uint16_t port;
    TCP_CONNECTION_STATUS_T conn_status;
    HANDSHAKE_PROTOCOL_CONFIG_T handshake_cfg;
} TCP_CONNECTION_INFO_T;

TCP_CONNECTION_INFO_T* create_connection_list(size_t size) {
    TCP_CONNECTION_INFO_T *connections = malloc(sizeof(TCP_CONNECTION_INFO_T) * size);
    if (!connections) {
        perror("malloc");
        return NULL;
    }
    memset(connections, 0, sizeof(TCP_CONNECTION_INFO_T) * size);
    return connections;
}

void destroy_connection_list(TCP_CONNECTION_INFO_T* connections, size_t size) {
    free(connections);
}

size_t find_empty_connection(TCP_CONNECTION_INFO_T* connections, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        if (!connections[i].conn_status.connected) {
            return i;
        }
    }
    return SIZE_MAX;
}

TCP_CONNECTION_INFO_T* resize_connection_list(TCP_CONNECTION_INFO_T** connections, size_t current_size, size_t new_size) {
    TCP_CONNECTION_INFO_T *new_connections = realloc(*connections, sizeof(TCP_CONNECTION_INFO_T) * new_size);
    if (!new_connections) {
        perror("realloc");
        return NULL;
    }
    memset(new_connections + current_size, 0, sizeof(TCP_CONNECTION_INFO_T) * (new_size - current_size));
    *connections = new_connections;
    return &((*connections)[current_size]);
}

void setup_connection(TCP_CONNECTION_INFO_T* connection, struct hostent* hent, uint16_t port) {
    memset(&(connection->addr), 0, sizeof(struct sockaddr_in));
    connection->port = htons(port);
    memcpy(&(connection->addr.sin_addr), hent->h_addr_list[0], hent->h_length);
}

void handle_external_dependency_failure(int retry, int delay) {
    if (retry >= MAX_RETRIES) {
        fprintf(stderr, "External dependency failure: Giving up.\n");
        return;
    }
    sleep(delay);
    // Implement the logic for handling external dependency failures here.
}

TCP_CONNECTION_INFO_T* init_tcp_connection(struct hostent* hent, uint16_t port, HANDSHAKE_PROTOCOL_CONFIG_T handshake_cfg) {
    size_t connection_index = find_empty_connection(*connections, MAX_CONNECTIONS);
    if (connection_index == SIZE_MAX) {
        // Resize the connection list when it's full.
        TCP_CONNECTION_INFO_T* new_connections = resize_connection_list(&connections, MAX_CONNECTIONS, MAX_CONNECTIONS * 2);
        if (!new_connections) {
            perror("resize_connection_list");
            return NULL;
        }
        connection_index = find_empty_connection(new_connections, MAX_CONNECTIONS * 2);
    }

    setup_connection(&connections[connection_index], hent, port);
    connections[connection_index].handshake_cfg = handshake_cfg;

    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("socket");
        return NULL;
    }

    struct timeval tv = {TV_TIMEOUT, TV_TIMEOUT * 10}; // Set timeout to 10ms.
    setsockopt(sockfd, SOL_SOCKET, SO_SNDTIMEO, (char*)&tv, sizeof(tv));

    int retries = 0;
    do {
        if (connect(sockfd, (struct sockaddr*) &(connections[connection_index].addr), sizeof(struct sockaddr)) == -1) {
            perror("connect");
            handle_external_dependency_failure(retries++, delay * pow(2.0, retries));
        } else {
            connections[connection_index].conn_status.connected = true;
            break;
        }
    } while (true);

    return &connections[connection_index];
}
```

