    mm->num_records = num_records;
    mm->min_offset = min_offset;
    mm->max_offset = max_offset;
    mm->offsets = calloc(num_records, sizeof(Offset));
    mm->keys = malloc(num_records * sizeof(int));
    mm->records = calloc(num_records, sizeof(Record));
    pthread_mutex_init(&mm->mutex, NULL);
    return mm;
}

void* generate_random_offset(void *param) {
    MemManager *mm = param;
    long offset = (rand() % ((mm->max_offset - mm->min_offset + 1) + 1)) + mm->min_offset;
    pthread_mutex_lock(&mm->mutex);
    for (size_t i = 0; i < mm->num_records; ++i) {
        if (mm->offsets[i].offset == offset) {
            // Handle overflow condition, e.g., by generating a new random number or throwing an error
            pthread_mutex_unlock(&mm->mutex);
            return NULL;
        }
    }
    pthread_mutex_unlock(&mm->mutex);
    mm->offsets[current_index].offset = offset;
    return mm->offsets[current_index++]; // Assuming current_index is a global variable used to keep track of the index within the arrays
}

void* initialize_record(void *param) {
    MemManager *mm = param;
    Record *record = &mm->records[thread_index];
    record->offset = generate_random_offset(mm); // Call the function defined above to generate a random offset value
    if (record->offset == NULL) {
        // Handle failure, e.g., by skipping this iteration or throwing an error
        return NULL;
    }
    record->key = rand() % (max_key - min_key + 1) + min_key;
    pthread_mutex_lock(&mm->mutex);
    mm->keys[record->key] = record;
    pthread_mutex_unlock(&mm->mutex);
    return record;
}

MemManager* create_mem_manager(size_t num_records, size_t num_threads, long min_offset, long max_offset, long min_key, long max_key) {
    MemManager *mm = init_mem_manager(num_records, min_offset, max_offset);
    pthread_t threads[num_threads];
    current_index = 0;
    thread_index = -1; // Initialize the global variables for tracking the index within the arrays and the current thread index

    for (size_t i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, initialize_record, mm);
    }

    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    return mm;
}
