    fftw_data->in = (fftw_complex*) fftw_malloc(sizeof(fftw_complex) * 2*channel_bandwidth);
    fftw_data->out = (fftw_complex*) fftw_malloc(sizeof(fftw_complex) * 2*channel_bandwidth);
    fftw_data->plan = fftw_plan_dft_1d(channel_bandwidth, fftw_data->in, fftw_data->out, FFTW_FORWARD, FFTW_ESTIMATE);

    // Initialize UE information
    ctx->ue_info = (RX_UE_INFORMATION_TAG*) calloc(ue_count, sizeof(RX_UE_INFORMATION_TAG));
    if (!ctx->ue_info) return;

