```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Define the node structure
struct Node {
    int value;
    struct Node *prev, *next;
};

// Create a pool of preallocated nodes for efficient memory management
static struct Node* node_pool = NULL;
static size_t pool_size = 0;
static size_t pool_capacity = 0;

// Mutex to protect access to the node pool in multi-threaded environments
pthread_mutex_t pool_mutex;

// Function to generate a random integer within the specified range
int rand_in_range(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Initialize a node with a random value and link it to the given head and tail nodes
void init_node(struct Node **head, struct Node **tail, struct Node *new_node) {
    new_node->value = rand_in_range(0, 100);
    if (*head == NULL) {
        *head = *tail = new_node;
        new_node->prev = NULL;
        new_node->next = NULL;
    } else {
        new_node->prev = *tail;
        *tail->next = new_node;
        *tail = new_node;
        new_node->next = NULL;
        (*tail)->prev = new_node;
    }
}

// Function to insert a new node at the specified position in the list
void insert_node(struct Node **head, struct Node **tail, size_t pos, struct Node *new_node) {
    if (pos > list_length(*head)) return; // Invalid position

    if (pos == 1) {
        new_node->prev = NULL;
        new_node->next = *head;
        (*head)->prev = new_node;
        *head = new_node;
    } else {
        struct Node* current = *head;
        for (size_t i = 1; i < pos - 1 && current != NULL; ++i) current = current->next;
        if (current == NULL) return; // Position out of bounds

        new_node->prev = current;
        new_node->next = current->next;
        if (new_node->next != NULL) new_node->next->prev = new_node;
        current->next = new_node;
    }
}

// Function to delete a node from the list at the specified position
void delete_node(struct Node **head, struct Node **tail, size_t pos) {
    if (pos > list_length(*head)) return; // Invalid position

    if (pos == 1) {
        *head = (*head)->next;
        free((*head)->prev);
        (*head)->prev = NULL;
    } else {
        struct Node* current = *head;
        for (size_t i = 1; i < pos - 1 && current != NULL; ++i) current = current->next;
        if (current == NULL || current->next == NULL) return; // Position out of bounds

        free(current->next);
        current->next = current->next->next;
        if (current->next != NULL) current->next->prev = current;
    }
}

// Function to return the number of nodes in the list
size_t list_length(struct Node *head) {
    size_t count = 0;
    struct Node *current = head;
    while (current != NULL) {
        ++count;
        current = current->next;
    }
    return count;
}

// Function to reclaim unused nodes from the list and put them back into the node pool
void reclaim_nodes(struct Node *head) {
    struct Node* current = head;
    while (current != NULL) {
        struct Node* temp = current->next;
        free(current);
        current = temp;
    }
}

// Function to manage the node pool, ensuring it is not empty and has enough capacity
void manage_node_pool() {
    if (pool_size == 0) {
        // Initialize the pool with a fixed number of nodes
        pool_capacity = 1024;
        pool_size = pool_capacity;
        node_pool = malloc(sizeof(struct Node) * pool_capacity);
    }

    if (pool_size == pool_capacity) return; // Pool is full, no need to grow it

    struct Node* new_node = malloc(sizeof(struct Node));
    if (new_node == NULL) {
        // Failed to allocate memory for a new node, can't grow the pool
        printf("Failed to allocate memory for a new node!\n");
        return;
    }

    // Initialize the new node and link it to any existing nodes in the pool
    init_node(&node_pool, &node_pool + pool_size - 1, new_node);
    pool_size++;
}

// Function to get a node from the node pool if available; otherwise allocate a new one
struct Node* get_or_allocate_node() {
    pthread_mutex_lock(&pool_mutex);
    struct Node* node = NULL;
    if (pool_size > 0) {
        node = node_pool + pool_size - 1;
        pool_size--;
    } else {
        manage_node_pool();
        node = node_pool + pool_size - 1;
    }
    pthread_mutex_unlock(&pool_mutex);
    return node;
}
```

This implementation uses a doubly-linked list with a preallocated node pool to minimize memory fragmentation and optimize memory usage. The code provides functions for initializing, inserting, and deleting nodes in the list as well as handling errors and managing resources efficiently. It also includes thread safety mechanisms through the use of a mutex.']

