[' ```c
#include <pthread.h>
#include <stdlib.h>
#include <time.h>

#define MAX_THREADS 100
#define MAX_RECORDS 1000000
#define MAX_MEMORY 10000000
#define GARBAGE_COLLECTION_INTERVAL 1000000 // Garbage collection after this number of operations
#define RANDOM_SEED_OFFSET 4294967296ULL // Thread-local random seed offset

struct record {
    int value;
    int ref_count;
};

struct pool {
    struct record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    pthread_cond_t cond_empty;
    pthread_cond_t cond_full;
    long* offsets;
    int* keys;
};

struct pool* create_pool() {
    struct pool* pool = malloc(sizeof(*pool));
    if (!pool) return NULL;
    pool->records = calloc(1, sizeof(struct record));
    if (!pool->records) goto error;
    pool->capacity = 1;
    pool->size = 0;
    pthread_mutex_init(&pool->lock, NULL);
    pthread_cond_init(&pool->cond_empty, NULL);
    pthread_cond_init(&pool->cond_full, NULL);
    pool->offsets = calloc(1, sizeof(long));
    if (!pool->offsets) goto error;
    pool->keys = malloc(sizeof(int));
    if (!pool->keys) goto error;
    return pool;

error:
    free(pool);
    return NULL;
}

void destroy_pool(struct pool* pool) {
    free(pool->records);
    free(pool->offsets);
    free(pool->keys);
    pthread_mutex_destroy(&pool->lock);
    pthread_cond_destroy(&pool->cond_empty);
    pthread_cond_destroy(&pool->cond_full);
    free(pool);
}

int acquire_lock(struct pool* pool) {
    int res;
    pthread_mutex_lock(&pool->lock);
    res = 1;

    while (pool->size >= pool->capacity && pool->ref_count > 0) {
        pthread_cond_wait(&pool->cond_full, &pool->lock);
    }

    if (pool->size < pool->capacity) {
        pool->size++;
        pool->ref_count++;
    }

    return res;
}

void release_lock(struct pool* pool) {
    pthread_mutex_unlock(&pool->lock);
    pthread_cond_signal(&pool->cond_empty);
}

struct record* acquire_record(struct pool* pool) {
    struct record* rec;
    int res = acquire_lock(pool);

    if (res && pool->size < pool->capacity) {
        rec = &pool->records[pool->size];
        rec->ref_count++;
        rec->value = rand() % 100; // Use C random number generator for thread safety
    } else {
        rec = NULL;
    }

    if (res && pool->size == pool->capacity) {
        resize_pool(pool, pool->capacity * 2);
    }

    return rec;
}

void release_record(struct pool* pool, struct record* rec) {
    int res = acquire_lock(pool);

    if (res && --rec->ref_count == 0) {
        pool->size--;
        update_arrays(pool, rec - pool->records, -1);
    }

    release_lock(pool);
}

void resize_pool(struct pool* pool, size_t new_capacity) {
    struct record* old_records = pool->records;
    void* old_offsets = pool->offsets;
    void* old_keys = pool->keys;

    pool->records = malloc((new_capacity + 1) * sizeof(struct record));
    if (!pool->records) return;
    memmove(pool->records, old_records, (pool->size + 1) * sizeof(struct record));

    pool->offsets = realloc(old_offsets, new_capacity * sizeof(long));
    if (!pool->offsets) {
        free(pool->records);
        pool->records = old_records;
        return;
    }
    memmove(pool->offsets, old_offsets, old_capacity * sizeof(long));

    pool->keys = realloc(old_keys, new_capacity * sizeof(int));
    if (!pool->keys) {
        free(pool->records);
        free(pool->offsets);
        pool->records = old_records;
        pool->offsets = old_offsets;
        return;
    }
    memset(pool->keys + old_capacity, 0, (new_capacity - old_capacity) * sizeof(int));

    pool->capacity = new_capacity;
}

void update_arrays(struct pool* pool, long offset, int key) {
    if (offset >= 0 && offset < pool->size && pool->keys[key] == 0) {
        pool->keys[key] = 1;
        pool->offsets[offset + 1]++;
        pool->offsets[offset]--;
    }
}

void garbage_collect(struct pool* pool) {
    size_t i, j;
    int keep_count = 0;
    long* temp_offsets = malloc((pool->size + 1) * sizeof(long));
    if (!temp_offsets) return;
    memset(temp_offsets, 0, (pool->size + 1) * sizeof(long));

    for (i = 0; i < pool->capacity; ++i) {
        if (pool->ref_count[i]) {
            temp_offsets[pool->records[i].value]++;
        }
    }

    for (i = j = 0; i < pool->size + 1; ++i) {
        if (temp_offsets[i]) {
            pool->offsets[j] = temp_offsets[i];
            keep_count++;
        } else {
            pool->records[j++] = pool->records[i];
        }
    }

    pool->size = keep_count;
    free(temp_offsets);
}

void clean_up(struct pool* pool) {
    int i;

    for (i = 0; i < pool->capacity; ++i) {
        if (pool->ref_count[i] > 0) {
            release_record(pool, &pool->records[i]);
        }
    }
}']

