    if (!list) return NULL;
    list->head = NULL;
    list->total_frames = 0;
    list->last_frame_processed = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void insert_node(struct list *list, node* new_node) {
    pthread_mutex_lock(&list->lock);

    if (!list->head) {
        list->head = new_node;
    } else {
        node *temp = list->head;
        while (temp->next != NULL) temp = temp->next;
        temp->next = new_node;
    }

    list->total_frames++;
    pthread_mutex_unlock(&list->lock);
}
```

Lastly, let's implement a function to check if the LTESERIAL_ID is unique within the list:

```c
int is_unique(struct list *list, int serial_id) {
    pthread_mutex_lock(&list->lock);
    node* current = list->head;
    while (current != NULL) {
        if (current->serial_id == serial_id) {
            pthread_mutex_unlock(&list->lock);
            return 0; // Not unique
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return 1; // Unique
}
