['```c
#include <pthread.h>
#include <stdlib.h>
#include <stdbool.h>
#include <stdio.h>
#include <semaphore.h>

typedef struct MAC_CONTEXT_T {
    uint32_t id;
    MAC_PDCP_T pdcp;
    MAC_RLC_T rlc;
    MAC_PHY_T phy;
} MAC_CONTEXT;

typedef struct MAC_MANAGER_T {
    MAC_CONTEXT** contexts;
    size_t size;
    size_t capacity;
    sem_t mutex;
    pthread_cond_t notEmpty;
} MAC_MANAGER;

MAC_MANAGER* mac_manager_init(size_t initial_capacity) {
    MAC_MANAGER* manager = malloc(sizeof(MAC_MANAGER));
    manager->contexts = calloc(initial_capacity, sizeof(MAC_CONTEXT*));
    manager->size = 0;
    manager->capacity = initial_capacity;
    sem_init(&manager->mutex, 0, 1);
    pthread_cond_init(&manager->notEmpty, NULL);
    return manager;
}

void mac_manager_deinit(MAC_MANAGER* manager) {
    for (size_t i = 0; i < manager->size; ++i) {
        free(manager->contexts[i]);
    }
    free(manager->contexts);
    sem_destroy(&manager->mutex);
    pthread_cond_destroy(&manager->notEmpty);
    free(manager);
}

MAC_CONTEXT* mac_manager_find(MAC_MANAGER* manager, uint32_t id) {
    if (manager->size == 0) return NULL;

    sem_wait(&manager->mutex);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->contexts[i]->id == id) {
            sem_post(&manager->mutex);
            return manager->contexts[i];
        }
    }

    sem_post(&manager->mutex);
    pthread_cond_signal(&manager->notEmpty);
    return NULL;
}

void mac_manager_add(MAC_MANAGER* manager, MAC_CONTEXT* context) {
    if (manager->size == manager->capacity) {
        MAC_CONTEXT** new_contexts = realloc(manager->contexts, sizeof(MAC_CONTEXT*) * (manager->capacity + 1024));
        if (!new_contexts) return;
        manager->contexts = new_contexts;
        manager->capacity += 1024;
    }

    sem_wait(&manager->mutex);

    manager->contexts[manager->size++] = context;
    sem_post(&manager->mutex);
    pthread_cond_signal(&manager->notEmpty);
}

void mac_manager_remove(MAC_MANAGER* manager, uint32_t id) {
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->contexts[i]->id == id) {
            memmove(&manager->contexts[i], &manager->contexts[i + 1], sizeof(MAC_CONTEXT*) * (manager->size - i));
            --manager->size;
            sem_post(&manager->mutex);
            pthread_cond_signal(&manager->notEmpty);
            break;
        }
    }
}
```

This code provides the basic structure for a thread-safe MAC manager. It initializes, deallocates, adds, removes entities from a dynamic array of `MAC_CONTEXT` structures while ensuring concurrent access is handled correctly using semaphores and pthread conditional variables.']

