    void* configs_ptr = mmap(nullptr, required_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (configs_ptr == MAP_FAILED) {
        std::cerr << "Failed to allocate memory for TrafficFlowConfig array\n";
        return nullptr;
    }

    TrafficFlowConfig* configs = static_cast<TrafficFlowConfig*>(configs_ptr);

    // Fill in the TrafficFlowConfig structures
    for (size_t i = 0; i < n_flows; ++i) {
        configs[i].flow_id = min_id + i;
        configs[i].destination = config["destinations"][i].asString();
        configs[i].priority = priorities[i % priorities.size()];
    }

    // Synchronize access to the TrafficFlowConfig array when multiple threads are involved
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, nullptr);

    // Perform any additional thread-related operations here...

    munmap(configs_ptr, required_size);
    pthread_mutex_destroy(&mutex);
    return nullptr;
}

