    pthread_create(&threads.front(), nullptr, initialize_traffic_flow_configs, const_cast<char*>(config_file));

    // Wait for the thread to complete and join its results...

    TrafficFlowConfig* configs = static_cast<TrafficFlowConfig*>(...); // Access the resulting TrafficFlowConfig array

