        col->tail = newNode;
    } else {
        col->tail->next = newNode;
        col->tail = newNode;
    }
    pthread_mutex_unlock(&col->lock);
}

void* find_entity(Collection *col, unsigned int entity_id) {
    Node *current = col->head;
    while (current != NULL) {
        if (current->data && ((MAC_CONTEXT *)current->data)->rnti == entity_id)
            return current->data;
        current = current->next;
    }
    return NULL;
}

void update_entity(Collection *col, unsigned int entity_id, void (*update_func)(void*)) {
    Node *entityNode = find_entity(col, entity_id);
    if (entityNode) {
        pthread_mutex_lock(&col->lock);
        update_func(entityNode->data);
        pthread_mutex_unlock(&col->lock);
    }
}

void remove_entity(Collection *col, unsigned int entity_id) {
    Node *current = col->head;
    Node *prev = NULL;

    while (current != NULL) {
        if (current->data && ((MAC_CONTEXT *)current->data)->rnti == entity_id) {
            if (prev == NULL)
                col->head = current->next;
            else
                prev->next = current->next;

            if (current == col->tail)
                col->tail = prev;

            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }
}
```

Note that you will need to implement the MAC_CONTEXT, MAC_PDCP Entity, MAC_RLC Entity, and MAC_PHY Entity structures, as well as the update_func function for updating existing entities. Additionally, handle transient errors gracefully by retrying operations within the specified number of times before permanently failing. Implement logging functionality according to the given requirements, considering options to enable or disable it at runtime. Lastly, ensure proper synchronization using pthread_mutex_lock and pthread_mutex_unlock functions for thread safety in concurrent access scenarios.']

