CCCH_MESSAGE* create_message() {
    CCCH_MESSAGE* msg = (CCCH_MESSAGE*)malloc(sizeof(CCCH_MESSAGE));
    if (!msg) return NULL;

    msg->tag = generate_tag(); // Implement this function to generate a valid tag

    NFAPI_CRC_INDICATION_PDU* pdu = (NFAPI_CRC_INDICATION_PDU*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
    if (!pdu) {
