    pdu->rnti = generate_RNTI(); // Implement this function to generate a valid RNTI
    pdu->crc_indication.crcFlag = rand() % 2; // Set the CRC flag randomly

    msg->content = pdu;
    return msg;
}

void* thread_func(void* arg) {
    CCCH_MESSAGE* messages[MAX_THREADS];

    for (size_t i = 0; i < MAX_THREADS; ++i)
        messages[i] = create_message();

    // Process and use the messages here...

    return NULL;
}

void initialize_memory_pools() {
    message_pool.capacity = MESSAGE_POOL_SIZE;
    message_pool.count = 0;
    thread_data_pool.capacity = MAX_THREADS;
    thread_data_pool.count = 0;
}

void* allocate_message() {
    pthread_mutex_lock(&pool_mutex);

    if (message_pool.count < message_pool.capacity) {
        message_pool.count++;
        void* msg = message_pool.pool + (message_pool.count - 1) * sizeof(CCCH_MESSAGE);
        memset(msg, 0, sizeof(CCCH_MESSAGE));
        pthread_mutex_unlock(&pool_mutex);
        return msg;
    }

    pthread_mutex_unlock(&pool_mutex);
    return NULL;
}

void free_message(void* message) {
    if (message) {
        pthread_mutex_lock(&pool_mutex);
        CCCH_MESSAGE* msg = (CCCH_MESSAGE*)message;
        message_pool.pool[--message_pool.count] = *msg;
        pthread_mutex_unlock(&pool_mutex);
    }
}

void allocate_thread_data() {
    if (thread_data_pool.count < thread_data_pool.capacity) {
        thread_data_pool.count++;
        void* data = thread_data_pool.pool + (thread_data_pool.count - 1);
        memset(data, 0, sizeof(void*));
    }
}

int main() {
    initialize_memory_pools();
    pthread_t threads[MAX_THREADS];

    for (size_t i = 0; i < MAX_THREADS; ++i)
        if (pthread_create(&threads[i], NULL, &thread_func, NULL)) {
            fprintf(stderr, "Failed to create thread\n");
            return -1;
        }

    for (size_t i = 0; i < MAX_THREADS; ++i)
        if (pthread_join(threads[i], NULL)) {
            fprintf(stderr, "Failed to join thread\n");
            return -1;
        }

    return 0;
}
