void generate_hash(unsigned long *hash, const unsigned long key, size_t index) {
    *hash = (key + index) ^ (key << 10) ^ (index >> 3);
}

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu(size_t list_size) {
    if (list_size == 0) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *array = NULL;
    unsigned long hash;
    size_t i;

    array = (NFAPI_CRC_INDICATION_PDU_T*) malloc(list_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!array) {
        free(array);
        return NULL;
    }

    srand(time(NULL));

    for (i = 0; i < list_size; ++i) {
        generate_hash(&hash, i + rand() * 1e9, i); // Using a good hash function here to ensure consistency but not predictability
        array[i].tag = RX_UE_INFORMATION_TAG_DEFAULT;
        array[i].rnti = (uint16_t) hash;
        array[i].crc_indication.crcc = (hash & 0x0001); // Using only the least significant bit to set CRCFLAG
    }

    return array;
}

void verify_crc_flags(const NFAPI_CRC_INDICATION_PDU_T *array, size_t list_size) {
    unsigned long crcc;
    size_t i;

