// User-defined TickerEvent interface
typedef struct TickerEvent {
    time_t timestamp;
    enum EventType { TYPE_A, TYPE_B, TYPE_C } event_type;
    void* payload; // User-defined data payload
} TickerEvent;

// Custom serialization and deserialization interfaces can be implemented here.

// Custom allocator for TickerEvent structures to minimize memory fragmentation
TickerEvent* custom_alloc(size_t size) {
    return calloc(1, sizeof(TickerEvent) + (size - 1) * sizeof(void*));
}

// Custom free function for TickerEvent structures
void custom_free(void* ptr) {
    if (!ptr) return;

    size_t size = sizeof(TickerEvent) / sizeof(void*);
    void* data = (char*)ptr + size;
    for (size_t i = 0; i < size - 1; ++i) {
        free((char*)data + i * sizeof(void*));
    }

    free(ptr);
}

// Dynamic list structure with a guarded data section to ensure thread-safety
typedef struct ListNode {
    pthread_once_t once;
    TickerEvent event;
    struct ListNode *next;
} ListNode;

// Thread-safe function for adding events to the list
void list_push(ListNode** head, TickerEvent* event) {
    if (!event->timestamp || !event->event_type || !event->payload) {
        fprintf(stderr, "Invalid event data provided\n");
        return;
    }

    pthread_once(&(head[0]->once), [](void* arg) { head[1] = (ListNode*)calloc(1, sizeof(ListNode)); });

    ListNode* new_node = custom_alloc(2);
    new_node->event = *event;
    new_node->next = (*head)[1];

    pthread_once(&(head[0]->once), [](void* arg) { (void)arg; });
    (*head)[1] = new_node;
}

// Iterator structure for traversing the list in both forward and reverse order
struct ListIterator {
    ListNode** head;
    ListNode *current;
};

ListIterator list_begin(ListNode** head) {
    ListIterator it = {head, (*head)[1]};
    if (!*head || !(*head)[1]) return it;

    it.current = (*head)[1];
    while (it.current->next) it.current = it.current->next;

    return it;
}

ListIterator list_rbegin(ListNode** head) {
    ListIterator it = {head, NULL};
    if (!*head || !(*head)[1]) return it;

    it.current = (*head)[1];

    return it;
}

// Iterator interface for traversing the list in either order
TickerEvent* list_next(ListIterator* it) {
    if (!it->current) {
        fprintf(stderr, "Invalid iterator state\n");
        return NULL;
    }

    ListNode* temp = it->current;
    it->current = it->current->next;

    return &temp->event;
}

// Function to free all allocated resources when the list is no longer needed
void list_destroy(ListNode** head) {
    if (!head || !(*head)) return;

    ListIterator it = list_begin(head);
    while (list_next(&it)) {}

    custom_free((char*)(*head)[0] + sizeof(TickerEvent));
    free(*head);
}
```

