typedef struct Record {
    int value;
} Record;

typedef struct Config {
    char target_dir[256];
    int min_random;
    int max_random;
    size_t num_records;
    bool log_enabled;
    char log_filepath[256];
} Config;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static unsigned long long last_id = 0;
char extension_identifier[32] = "";

int allocateInitializeAndProcessFile(const char* filename, const Config* config, const char* log_filepath) {
    FILE *file = fopen(filename, "w");
    if (!file) {
        fprintf(stderr, "Error opening file: %s\n", filename);
        return 1;
    }

    struct stat st;
    char base_name[256];
    strcpy(base_name, basename(filename));

    if (stat(filename, &st) == -1) {
        fprintf(stderr, "Error getting file metadata: %s\n", filename);
        fclose(file);
        return 1;
    }

    snprintf(extension_identifier, sizeof(extension_identifier), "%llu_%lu_%lu", st.st_dev, st.st_ino, time(NULL));
    strcat(filename, extension_identifier);
    strcpy(log_filepath, config->target_dir);
    strcat(log_filepath, "/");
    strcat(log_filepath, basename(log_filepath));
    strcat(log_filepath, extension_identifier);

    pthread_mutex_lock(&mutex);
    last_id += config->num_records;
    pthread_mutex_unlock(&mutex);

    Record* records = malloc(config->num_records * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Error allocating memory for records.\n");
        fclose(file);
        return 1;
    }

    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < config->num_records; ++i) {
        records[i].value = rand() % (config->max_random - config->min_random + 1) + config->min_random;
    }

    if (config->log_enabled) {
        FILE *log = fopen(log_filepath, "w");
        if (log) {
            fprintf(log, "Generated %llu records with values between [%d, %d].\n", last_id, config->min_random, config->max_random);
            fclose(log);
        } else {
            fprintf(stderr, "Error opening log file: %s\n", log_filepath);
        }
    }

    if (fwrite(records, sizeof(Record), config->num_records, file) != config->num_records) {
        fprintf(stderr, "Error writing to file: %s\n", filename);
        free(records);
        fclose(file);
        return 1;
    }

    free(records);
    fclose(file);
    return 0;
}
