    for (size_t i = 0; i < data->threads_count; ++i) {
        LTE_DL_CCCH_Message* msg = data->messages[i];
        msg->tag = rand();
        msg->content = calloc(1, rand() % 1024 + 1); // Allocate dynamic content with random size
