            ((NFAPI_CRC_INDICATION_PDU_T*)((char*)msg->content + j * sizeof(NFAPI_CRC_INDICATION_PDU_T)))->RNTI = rand();
            ((NFAPI_CRC_INDICATION_PDU_T*)((char*)msg->content + j * sizeof(NFAPI_CRC_INDICATION_PDU_T)))->CRC_INDICATION_REL8_TAG = rand();
            ((NFAPI_CRC_INDICATION_PDU_T*)((char*)msg->content + j * sizeof(NFAPI_CRC_INDICATION_PDU_T)))->CRCFLAG = rand() % 2;
        }
    }
    return NULL;
}

void init_messaging(size_t M, size_t N, ThreadData** threads) {
    *threads = malloc(M * sizeof(ThreadData));

    for (size_t i = 0; i < M; ++i) {
        (*threads)[i].sem = sem_init(0, 0, 1);
        (*threads)[i].messages = calloc(N, sizeof(LTE_DL_CCCH_Message*));
    }

    pthread_t* thread_handles = malloc(M * sizeof(pthread_t));
    ThreadData* thread_data = *threads;

    for (size_t i = 0; i < M; ++i) {
        thread_data[i].threads_count = N;
        pthread_create(&thread_handles[i], NULL, randomize, &thread_data[i]);
