        log_cb("Memory allocation failed");
        return 1;
    }

    pthread_t update_thread;
    int update_thread_created = 0;

    for (i = 0; i < N; ++i) {
        indications[i].RX_UE_INFORMATION_TAG = i + 1;
        indications[i].RNTI = rnti_iface->get_rnti(rnti_iface);
        indications[i].CRC_INDICATION_REL8_TAG = (i % 2) ? 0x05 : 0x06;
