        pthread_create(&update_thread, NULL, &update_loop, (void *) &mutex);
        update_thread_created = 1;
    }

    for (j = num_generated = 0; j < N + update_frequency; ++j) {
        if (num_generated < N) {
            if (!pthread_mutex_trylock(&mutex, NULL)) {
                indications[num_generated].RX_UE_INFORMATION_TAG = num_generated + 1;
                indications[num_generated].RNTI = rnti_iface->get_rnti(rnti_iface);
                indications[num_generated++].CRC_INDICATION_REL8_TAG = (num_generated % 2) ? 0x05 : 0x06;
                indications[num_generated - 1].CRCFLAG = num_generated < update_frequency ? (rand() % 2) : (num_generated % 3) == 0 ? 1 : 0;
                pthread_mutex_unlock(&mutex);
            }
        }
    }

    if (!update_thread_created) return 0;

    void *status;
    pthread_join(update_thread, &status);

    FILE *fp = fopen((output_dir)/(filename), "wb");
    if (!fp) {
        log_cb("Could not open output file");
        return 1;
    }

    // Write the data to the file in a format compatible with the third-party tool.

    fclose(fp);

    free(indications);

    // Call the third-party tool conversion function here and handle its result appropriately.

    return 0;
}

void *update_loop(void *arg) {
    pthread_mutex_t *mutex = arg;
    usleep((rand() % 1000000) + 100000); // Simulate delays and inconsistencies in external data source.

    while (true) {
        pthread_mutex_lock(mutex);
        int i, num_generated = 0;

        for (i = 0; i < N; ++i) {
            if (indications[i].CRCFLAG) indications[i].CRCFLAG = !indications[i].CRCFLAG;
