size_t populate_pdu_array(NFAPI_CRC_INDICATION_PDU_T **arr, size_t N, bool sequential) {
    if (!arr || N == 0) return 0;

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
