    *arr = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*arr) {
        fprintf(stderr, "Memory allocation failed.\n");
        return 0;
    }

    size_t chunk_size = (N > 1024) ? N / 1024 : 1; // Adjust chunk size based on array size

    if (sequential) {
        for (size_t i = 0; allocated < N && i < N; ++i) {
            // Ensure unique RNTI values and populate CRC_INDICATION_REL8_TAG with random CRCFLAG
            while (true) {
                (*arr)[allocated].RNTI = i;
                if (!allocated || (*arr)[allocated].RNTI != (*arr)[allocated - 1].RNTI) break;
