            pthread_mutex_lock(&mutex);
            (*arr)[allocated].RX_UE_INFORMATION_TAG = i;
            (*arr)[allocated].CRC_INDICATION_REL8_TAG[0] = (i % 2) + 1; // Performance optimization: reduce number of RNG calls by using simple modulo operation
            pthread_mutex_unlock(&mutex);

            ++allocated;
