    } else {
        size_t active_threads = N > 1024 ? N / chunk_size : 1; // Adjust thread count based on array size

        pthread_t threads[active_threads];
        NFAPI_CRC_INDICATION_PDU_T *local_arr = *arr;

        for (size_t i = 0; i < active_threads; ++i) {
            pthread_create(&threads[i], NULL, populate_pdu_chunk, &local_arr + (i * chunk_size));
        }

        for (size_t i = 0; i < active_threads; ++i) {
            pthread_join(threads[i], NULL);
        }
    }

    return allocated;
}

void* populate_pdu_chunk(void *arg) {
    NFAPI_CRC_INDICATION_PDU_T *local_arr = arg;
    size_t chunk_size = (size_t)(local_arr - *((NFAPI_CRC_INDICATION_PDU_T **)&arg));
    size_t allocated = 0;

    pthread_mutex_t *mutex = (pthread_mutex_t*)malloc(chunk_size * sizeof(pthread_mutex_t));
    if (!mutex) {
        fprintf(stderr, "Mutex allocation failed.\n");
        return NULL;
    }

    for (size_t i = 0; i < chunk_size; ++i) {
        pthread_mutex_init(&mutex[i], NULL);
    }

    for (size_t i = 0; allocated < chunk_size && i < chunk_size; ++i) {
        // Ensure unique RNTI values and populate CRC_INDICATION_REL8_TAG with random CRCFLAG
        while (true) {
            local_arr[allocated].RNTI = i + (*((size_t*)arg) * chunk_size);
            if (!allocated || local_arr[allocated].RNTI != local_arr[allocated - 1].RNTI) break;
        }

        pthread_mutex_lock(&mutex[allocated]);
        local_arr[allocated].RX_UE_INFORMATION_TAG = allocated + (*((size_t*)arg) * chunk_size);
        local_arr[allocated].CRC_INDICATION_REL8_TAG[0] = (allocated % 2) + 1; // Performance optimization: reduce number of RNG calls by using simple modulo operation
        pthread_mutex_unlock(&mutex[allocated]);

        ++allocated;
    }

    free(mutex);
    return NULL;
