typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} Node;

static Node** list = NULL;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static size_t count = 0, capacity = 0;

void init_list() {
    if (capacity > 0) return;
    capacity = 10000;
    list = malloc(sizeof(Node*) * capacity);
    for (size_t i = 0; i < capacity; ++i) {
        list[i] = NULL;
    }
}

void push(NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&mutex);
    if (count == capacity) init_list();
    Node** current = &list[count];
    *current = malloc(sizeof(Node));
    if (!*current) {
        fprintf(stderr, "Failed to allocate memory\n");
        pthread_mutex_unlock(&mutex);
        return;
    }
    (*current)->data = data;
    (*current)->next = NULL;
    ++count;
    pthread_mutex_unlock(&mutex);
}

bool remove(RNTI rnti) {
    pthread_mutex_lock(&mutex);
    Node** current = &list[0];
    for (size_t i = 0; i < count; ++i, ++current) {
        if ((*current)->data.rnti == rnti) {
            Node* temp = *current;
            *current = (*current)->next;
            free(temp);
            --count;
            pthread_mutex_unlock(&mutex);
            return true;
        }
        current = &(*current)->next;
    }
    pthread_mutex_unlock(&mutex);
    return false;
}

