    for (size_t i = 0; i < count; ++i, ++current) {
        if ((*current)->data.rnti == rnti) {
            (*current)->data.crcflag = crcflag;
            pthread_mutex_unlock(&mutex);
            return;
        }
        current = &(*current)->next;
    }
    pthread_mutex_unlock(&mutex);
}
