    char buf[LOG_LENGTH];

    va_start(args, format);
    vsnprintf(buf, sizeof(buf), format, args);
    va_end(args);

    printf("%s\n", buf);
}

void* list_realloc(void* ptr, size_t new_capacity) {
    if (new_capacity == 0) {
        free(ptr);
        return NULL;
    }
    void* result = realloc(ptr, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
    if (!result) {
