    if (!data) {
        fprintf(stderr, "Out of memory during initialization\n");
        exit(EXIT_FAILURE);
    }
    return &((struct list){ .data = data });
}

void list_push(struct list* list, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    validate(pdu, "list_push");

    if (list->size == list->capacity) {
        list->capacity *= 2;
        list->data = list_realloc(list->data, list->capacity);
    }

    list->data[list->size++] = *pdu;
    if (list->size % 10 == 0) {
        list->data[list->size - 1].crcflag = true;
    } else {
        list->data[list->size - 1].crcflag = false;
    }

    log_message("Added new structure: RX_UE_INFORMATION_TAG=%u, RNTI=%hu, CRC_INDICATION_REL8_TAG=%hhu, CRCFLAG=%hhu",
                pdu->rx_ue_information_tag, pdu->rnti, pdu->crc_indication_rel8_tag, pdu->crcflag);
}

struct list* dynamic_list(void (*log)(const char*, ...)) {
