void initList(size_t frames) {
    Node* current = head;
    for (size_t i = 0; i < frames; ++i) {
        pthread_mutex_lock(&list_mutex);
        if (!head) {
            head = malloc(sizeof(Node));
            if (!head) {
                log("Failed to allocate memory for list header");
                pthread_mutex_unlock(&list_mutex);
                return;
            }
            head->next = NULL;
        } else {
            current = head;
            while (current->next) {
                current = current->next;
            }
        }

        Node* new_node = malloc(sizeof(Node));
        if (!new_node) {
            log("Failed to allocate memory for list node");
            pthread_mutex_unlock(&list_mutex);
            free(head);
            head = NULL;
            return;
        }
        new_node->next = NULL;
        current->next = new_node;

        new_node->data.header.timestamp = getSafeTime();
        new_node->data.header.sequence_number = i + 1;
        new_node->data.phy_info.sinr = rand() % 100; // Random SINR value between 0 and 99

        pthread_mutex_unlock(&list_mutex);
    }
}

void validateList() {
    pthread_mutex_lock(&list_mutex);
    Node* current = head;
    size_t valid_frames = 0;
    while (current) {
        if (current->data.header.timestamp > 0 &&
            current->data.header.sequence_number > 0 &&
            current->data.phy_info.sinr >= 0 &&
            current->data.phy_info.sinr <= 99) {
            ++valid_frames;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list_mutex);

    log(va("Validated %zu frames, encountered %zu errors", valid_frames, frames - valid_frames));
}
