void generate_crc(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Performance optimization: Use a fast CRC generator algorithm.
    pdu->crc_indication_rel8_tag = crc_generate(pdu);
}

int rnti_unique(const RNTI* rnti, size_t index) {
    for (size_t i = 0; i < num_ue; ++i) {
        if (i == index || memcmp(&ue_sessions[i].rnti, rnti, sizeof(RNTI)) == 0) {
            return 0;
        }
    }
    return 1;
}

void* allocate_and_initialize_ue(void* arg) {
    size_t index = (size_t)arg;
    NFAPI_CRC_INDICATION_PDU_T* pdu;

    do {
        pdu = calloc(1, RNTI_SIZE);
        if (!pdu) continue;

        generate_crc(pdu);

        // Race condition mitigation: Use atomic operations for RNTI validation.
        while (!rnti_unique(&pdu->rnti, index)) {
            pthread_mutex_lock(&mutex);
            if (rnti_unique(&pdu->rnti, index)) {
                memcpy(&ue_sessions[index], pdu, RNTI_SIZE);
                break;
            }
            pthread_mutex_unlock(&mutex);
        }
    } while (0);

    return NULL;
}

void manage_ue_sessions(void) {
    // Manage memory usage to prevent excessive fragmentation.
    if (num_ue >= MAX_UE - 100) {
        NFAPI_CRC_INDICATION_PDU_T* temp_array = realloc(ue_sessions, num_ue * 2 * RNTI_SIZE);
        if (!temp_array) return;
        ue_sessions = temp_array;
