Please note that the following code is a basic example using axios for HTTP requests and promises for handling asynchronous operations. You may need to adapt it to fit your specific requirements, such as using another HTTP client or adding error handling mechanisms based on your project's needs.

```javascript
const axios = require('axios');
const fs = require('fs');

async function uploadFileFromUrl(url, destinationPath) {
    try {
        const response = await axios({
            url: url,
            method: 'GET',
            responseType: 'stream'
        });

        const writerStream = fs.createWriteStream(destinationPath);

        response.data.pipe(writerStream);

        return new Promise((resolve, reject) => {
            writerStream.on('finish', () => resolve());
            writerStream.on('error', error => reject(error));
        });
    } catch (error) {
        console.error(`Error occurred while uploading file: ${error}`);
    }
}
```

