    pthread_mutex_t lock;
    int max_key;
    unsigned long total_offsets, unique_offsets;
    unsigned long* offset_histogram; // Use an array of size MAX_HISTOGRAM_SIZE to store the frequency of each offset value
} Stats;

// Function to initialize and validate data structures
Record* init_record(int key, long offset) {
    Record *r = malloc(sizeof(Record));
    if (!r) return NULL; // Handle memory allocation error
    r->key = key;
    pthread_mutex_init(&r->lock, NULL);
    r->offset = offset;
    return r;
}

// Function to initialize and validate statistics data structure
Stats* init_stats() {
    Stats *s = malloc(sizeof(Stats));
    if (!s) return NULL; // Handle memory allocation error
    pthread_mutex_init(&s->lock, NULL);
    s->max_key = INT_MIN;
    s->total_offsets = 0;
    s->unique_offsets = 0;
    s->offset_histogram = calloc(MAX_HISTOGRAM_SIZE, sizeof(unsigned long)); // Handle memory allocation error
    if (!s->offset_histogram) {
        free(s);
        return NULL;
    }
    return s;
}

// Function to update statistics upon record addition or modification
void update_stats(Stats *s, Record *r) {
    pthread_mutex_lock(&s->lock);
    if (r->key > s->max_key) s->max_key = r->key;
    s->total_offsets += r->offset;
    ++s->unique_offsets; // Increment unique offset count only once for each unique offset value
    unsigned long curr_val = r->offset % MAX_HISTOGRAM_SIZE;
    ++(s->offset_histogram[curr_val]); // Increment histogram for current offset value
    pthread_mutex_unlock(&s->lock);
}

// Function to access statistics data structure (read-only)
const Stats* get_stats() {
    static const Stats empty_stats = {0};
    static Stats *cached_stats = &empty_stats;
    pthread_mutex_lock(&cached_stats->lock);
    if (cached_stats != &empty_stats) {
        cached_stats = &empty_stats;
    } else {
        cached_stats = init_stats();
    }
    pthread_mutex_unlock(&cached_stats->lock);
    return cached_stats;
}
