typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} Node;

struct dynamic_array {
    Node** array;
    size_t length;
    pthread_mutex_t mutex;
};

void create_dynamic_array() {
    struct dynamic_array* da = malloc(sizeof(struct dynamic_array));
    da->length = 0;
    da->array = calloc(MAX_ELEMENTS, sizeof(Node*));
    pthread_mutex_init(&da->mutex, NULL);
}

void push(struct dynamic_array* da, NFAPI_CRC_INDICATION_PDU_T data) {
    Node *new_node = malloc(sizeof(Node));
    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&da->mutex);

    if (da->length == MAX_ELEMENTS) {
        free(new_node);
        pthread_mutex_unlock(&da->mutex);
        return; // Failure: array is full, drop the new data.
    }

    size_t index = da->length % MAX_ELEMENTS;
    new_node->next = da->array[index];
    da->array[index] = new_node;
    da->length++;

    pthread_mutex_unlock(&da->mutex);
}

NFAPI_CRC_INDICATION_PDU_T pop(struct dynamic_array* da) {
    if (da->length == 0) {
        return (NFAPI_CRC_INDICATION_PDU_T){}; // Empty array, return an empty structure.
    }

    pthread_mutex_lock(&da->mutex);

    size_t index = da->length - 1;
    Node* temp = da->array[index];
    NFAPI_CRC_INDICATION_PDU_T data = temp->data;
    da->array[index] = temp->next;
    free(temp);
    da->length--;

    pthread_mutex_unlock(&da->mutex);

    return data;
}

// Ensure the function can be extended with minimal changes to the existing codebase:
