    if (!new_task) return NULL;

    new_task->task_id = task_id;
    new_task->status = CREATED;
    new_task->num_subtasks = num_subtasks;

    // Allocate durations array with default size LIST_INITIAL_SIZE
    new_task->durations = calloc(LIST_INITIAL_SIZE, sizeof(size_t));
    if (!new_task->durations) {
        free(new_task);
        return NULL;
    }

    // Generate unique description
    pthread_mutex_lock(&description_mutex);
    snprintf(new_task->description, MAX_DESCRIPTION_LENGTH, "Task_%lu_Subtasks_%zu", task_id, num_subtasks);
    pthread_mutex_unlock(&description_mutex);

    // Initialize subtask durations with random values
    for (size_t i = 0; i < LIST_INITIAL_SIZE; ++i) {
        new_task->durations[i] = rand() % max_duration + 1;
    }

    return new_task;
}

void populate_subtasks(Task *task, size_t num_subtasks) {
    // Reallocate durations array to match the number of subtasks
    task->durations = realloc(task->durations, num_subtasks * sizeof(size_t));
    if (!task->durations) {
        free(task);
        return;
    }

    // Initialize remaining subtask durations with random values
    for (size_t i = LIST_INITIAL_SIZE; i < num_subtasks; ++i) {
        task->durations[i] = rand() % max_duration + 1;
    }
}

size_t create_tasks(size_t num_tasks, size_t num_subtasks, size_t max_duration, struct TaskListNode **task_list_head) {
    size_t total_tasks = 0;

    for (size_t i = 0; i < num_tasks; ++i) {
        Task *new_task = create_task(total_tasks++);
        if (!new_task) break;

        populate_subtasks(new_task, num_subtasks);

        new_task->next = *task_list_head;
        *task_list_head = new_task;
    }

    return total_tasks;
}
