    int segmentSize = MAX_RECORDS / *thread_ids;
    Record* records = mmap(NULL, MAX_RECORDS * RECORD_SIZE, PROT_WRITE | PROT_READ, MAP_PRIVATE | MAP_ANON, -1, 0);
    srand(time(NULL) + (*thread_ids * segmentSize));
