typedef struct {
    unsigned char rx_ue_information_tag[2];
    unsigned int rnti;
    unsigned char crc_indication_rel8_tag[10];
    unsigned char crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

int generateNFADynamicPDUList(void* buffer, size_t bufferSize, int pad, int *numPdus) {
    NFAPI_CRC_INDICATION_PDU_T *pduList = NULL;
    unsigned char *ptr = buffer;
    size_t pduSize = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    int i;

    if(!buffer || !numPdus) return 0;

    if(bufferSize < pduSize) {
        printf("Error: Provided buffer size is too small\n");
        return 0;
    }

    pduList = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * (bufferSize / pduSize));
    if(!pduList) {
        printf("Error: Failed to allocate memory for PDU list\n");
        return 0;
    }

    *numPdus = bufferSize / pduSize;

    if(pad) {
        for(i = 0; i < *numPdus; ++i) {
            // Add padding bytes here if needed
        }
    }

    for(i = 0; i < *numPdus; ++i) {
        pduList[i].rx_ue_information_tag[0] = 0x28;
        pduList[i].rx_ue_information_tag[1] = (unsigned char)(*numPdus + i);
        pduList[i].rnti = htonl(i + 1);
        pduList[i].crc_indication_rel8_tag[0] = 0x01;
        pduList[i].crc_indication_rel8_tag[1] = 0x05;
        pduList[i].crc_indication_rel8_tag[2] = (unsigned char)(i + 1);
        pduList[i].crcflag = rand() % 2;

        memcpy(ptr, &pduList[i], pduSize);
        ptr += pduSize;
    }

    return 1;
}
