#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct {
    uint16_t UE_INDEX;
    uint32_t RACH_PREAMBLE_SEQUENCE;
    DL_FRAME_MIB mib; // Define this structure based on your requirements
} LTE_DL_FRAME;

typedef struct frame_node {
    LTE_DL_FRAME frame;
    struct frame_node* next;
    pthread_mutex_t mutex;
} FrameNode;

void init_frame_list(FrameNode** head, size_t initial_size) {
    *head = malloc(sizeof(FrameNode) * initial_size);
    for (size_t i = 0; i < initial_size; ++i) {
        (*head)[i].next = (i + 1 < initial_size) ? &((*head)[i+1]) : NULL;
        pthread_mutex_init(&((*head)[i].mutex), NULL);
    }
}

FrameNode* find_empty(FrameNode** head) {
    for (FrameNode* current = *head; current != NULL; current = current->next) {
        pthread_mutex_lock(&current->mutex);
        if (current->next == NULL) {
            pthread_mutex_unlock(&current->mutex);
            return current;
        }
        pthread_mutex_unlock(&current->mutex);
    }
    return NULL;
}

void resize_frame_list(FrameNode** head, size_t new_size) {
    FrameNode* new_frames = malloc(sizeof(FrameNode) * new_size);
    for (size_t i = 0; i < new_size; ++i) {
        new_frames[i].next = (i + 1 < new_size) ? &new_frames[i+1] : NULL;
        pthread_mutex_init(&new_frames[i].mutex, NULL);
    }

    FrameNode* old_head = *head;
    size_t old_length = 0;
    while (old_head != NULL) {
        old_head = new_frames[old_length++];
    }

    *head = new_frames;
}

LTE_DL_FRAME* get_frame(FrameNode** head, uint16_t index) {
    FrameNode* current = *head;
    for (size_t i = 0; current != NULL && i < index; ++i, current = current->next);
    if (current == NULL) return NULL;
    pthread_mutex_lock(&current->mutex);
    LTE_DL_FRAME* frame = &current->frame;
    pthread_mutex_unlock(&current->mutex);
    return frame;
}

