// Define the Entry struct with a timestamp, status (enum), and description string.
struct Entry {
    std::chrono::steady_clock::time_point timestamp;
    enum Status { INVALID, VALID } status = INVALID;
    mutable std::string description;
};

// A thread-safe container to manage the list of entries.
class ThreadSafeList {
private:
    std::vector<std::unique_ptr<Entry>> entries; // Use unique_ptr for memory management.
    mutable std::mutex mtx;                     // Mutex for synchronizing access.
    size_t nextId = 0;

public:
    void insert(const std::string& description) {
        std::unique_lock<std::mutex> lock(mtx);

        auto entry = std::make_unique<Entry>(); // Create a new Entry.
        entry->timestamp = std::chrono::steady_clock::now(); // Set timestamp.
        entry->status = static_cast<Entry::Status>(rand() % 2); // Randomly set status.
        entry->description.reserve(description.length());   // Reserve space for the description string.
        entry->description.append(description);             // Append the description to the Entry.

        entries.emplace_back(std::move(entry));           // Insert the new entry.
    }

    const auto& getEntry(size_t index) {
        std::unique_lock<std::mutex> lock(mtx);
        return *entries[index];                          // Lock and return the specified entry.
    }

    size_t size() const {
        std::unique_lock<std::mutex> lock(mtx);
        return entries.size();                         // Lock and return the list size.
    }
};
