struct list* create_list(size_t initial_capacity) {
    struct list* list = malloc(sizeof(struct list));
    if (!list) return NULL;
    list->current_size = 0;
    list->capacity = initial_capacity;
    list->pdu_list = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!list->pdu_list) {
        free(list);
        return NULL;
    }
    list->record_list = calloc(initial_capacity, sizeof(RECORD_STRUCTURE*));
    if (!list->record_list) {
        free(list->pdu_list);
        free(list);
        return NULL;
    }
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void resize_list(struct list* list) {
    size_t new_capacity = (list->current_size > 0) ? list->capacity * 2 : 16;
    NFAPI_CRC_INDICATION_PDU_T** temp_pdu_list = realloc(list->pdu_list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!temp_pdu_list) return;
    RECORD_STRUCTURE** temp_record_list = realloc(list->record_list, new_capacity * sizeof(RECORD_STRUCTURE*));
    if (!temp_record_list) {
        free(temp_pdu_list);
        return;
    }

    list->pdu_list = temp_pdu_list;
    list->record_list = temp_record_list;
    list->capacity = new_capacity;
}

void add_to_list(struct list* list, NFAPI_CRC_INDICATION_PDU_T* pdu, RECORD_STRUCTURE* record) {
    if (list->current_size == list->capacity) resize_list(list);

    pthread_mutex_lock(&list->lock);
    list->pdu_list[list->current_size] = pdu;
    list->record_list[list->current_size] = record;
    ++list->current_size;
    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T* get_from_list(struct list* list, uint32_t rnti) {
    for (size_t i = 0; i < list->current_size; ++i) {
        if (list->pdu_list[i]->rnti == rnti) {
            pthread_mutex_lock(&list->lock);
            void* result = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            memcpy(result, list->pdu_list[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pthread_mutex_unlock(&list->lock);
            return result;
        }
    }
    return NULL;
}

void clean_up(struct list* list) {
    for (size_t i = 0; i < list->current_size; ++i) {
        free(list->pdu_list[i]);
        free(list->record_list[i]->buffer);
        free(list->record_list[i]);
    }
    free(list->pdu_list);
    free(list->record_list);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
