struct SYSTEM* init_system(int max_nodes, int max_records) {
    struct SYSTEM* sys = (struct SYSTEM*)malloc(sizeof(struct SYSTEM));
    sys->nodes = (struct NODE**)calloc(max_nodes, sizeof(struct NODE*));
    sys->size = max_nodes;
    sys->mutex = PTHREAD_MUTEX_INITIALIZER;
    sys->records = (RECORD**)malloc(max_records * sizeof(RECORD*));
    sys->max_records = max_records;
    sys->cur_records = 0;
    sys->total_memory = 0;
    sys->last_time = time(NULL);
    return sys;
}

void add_node(struct SYSTEM* sys, NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&sys->mutex);
    int index = hash(data->rnti.value); // replace hash with your desired hashing algorithm
    struct NODE** node_ptr = &sys->nodes[index];
    struct NODE* new_node = (struct NODE*)malloc(sizeof(struct NODE));
    new_node->data = data;
    new_node->next = *node_ptr;
    *node_ptr = new_node;
    pthread_mutex_unlock(&sys->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* find_node(struct SYSTEM* sys, RNTI rnti) {
    pthread_mutex_lock(&sys->mutex);
    int index = hash(rnti.value);
    struct NODE* node = sys->nodes[index];
    while (node != NULL) {
        if (memcmp(&node->data->rnti, &rnti, sizeof(RNTI)) == 0) {
            pthread_mutex_unlock(&sys->mutex);
            return node->data;
        }
        node = node->next;
    }
    pthread_mutex_unlock(&sys->mutex);
    return NULL;
}

void update_node(struct SYSTEM* sys, NFAPI_CRC_INDICATION_PDU_T* data) {
    NFAPI_CRC_INDICATION_PDU_T* old = find_node(sys, data->rnti);
    if (old != NULL) {
        pthread_mutex_lock(&sys->mutex);
        memcpy(old, data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        old->crcflag = data->crcflag; // update CRC flag
        pthread_mutex_unlock(&sys->mutex);
    }
}

// Implement other required functions for managing records, logging, distributed caching, etc.

void cleanup(struct SYSTEM* sys) {
    // Free all allocated memory and reset system state
}
