int lte_rx_frame_init(u_char **frame_info, const char *hostname) {
    int sockfd, num_frames = 0, dns_retries = 3, memory_usage = 0;
    struct addrinfo hints, *res;
    u_char *data = NULL;
    LTE_PHY_RX_FRAME_INFO_T *frame;

    if (getaddrinfo(hostname, NULL, &hints, &res) != 0) {
