        goto cleanup;
    }

    sockfd = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
    if (sockfd < 0) {
        perror("Socket creation failed");
        goto cleanup;
    }

    while (dns_retries--) {
        if (connect(sockfd, res->ai_addr, res->ai_addrlen) == 0)
            break;
        sleep(1);
    }

    if (dns_retries < 0) {
        perror("Connection failed");
        goto cleanup;
    }

    freeaddrinfo(res);

    while (num_frames < MAX_FRAMES && memory_usage + sizeof(LTE_PHY_RX_FRAME_INFO_T) <= MEMORY_THRESHOLD) {
        frame = data + memory_usage;
        memset(frame, 0, sizeof(*frame));
        frame->serial_id = (LTESERIAL_ID)memory_usage++; // Unique ID based on the memory usage
        // Initialize PHICH_INFO and DL_SRS with valid values within their respective ranges
        // ...
        memory_usage += sizeof(LTE_PHY_RX_FRAME_INFO_T);
        num_frames++;
    }

    if (num_frames == 0) {
        fprintf(stderr, "Exceeded maximum number of frames or memory threshold\n");
        goto cleanup;
    }

    *frame_info = data;
    return 0;

cleanup:
    if (data != NULL) free(data);
    if (sockfd >= 0) close(sockfd);
    return -1;
}
