// Function to populate list with N structures
NFAPI_CRC_INDICATION_PDU_T* populateList(int N) {
    NFAPI_CRC_INDICATION_PDU_T *list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    STATS_T stats;
    stats.num_entries = 0;
    stats.num_valid_entries = 0;
    stats.num_invalid_entries = 0;

    for (int i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = list + i;

        // Set random RX_UE_INFORMATION_TAG, RNTI, and CRCFLAG
        pdu->tag.id = rand() % 256;
        pdu->rnti = (RNTI)(rand() % MAX_RNTIS);
        pdu->crc_indication.crcFlag = rand() % 2;

        // Set last_crC_verification to current time
        pdu->last_crC_verification = time(NULL);

        // Check if RNTI is valid and update statistics
        bool isValidRnti = false;
        for (int j = 0; j < MAX_RNTIS && !isValidRnti; ++j) {
            isValidRnti = pdu->rnti == valid_rntis[j];
        }
        if (isValidRnti) {
            stats.num_valid_entries++;
        } else {
            stats.num_invalid_entries++;
        }
        stats.num_entries++;
    }

    // Log any invalid entries encountered
    for (int j = 0; j < MAX_RNTIS; ++j) {
        if (!valid_rntis[j]) {
            printf("Invalid RNTI found: %d\n", j);
        }
    }

    return list;
}

// Free memory associated with the list
