void* custom_malloc(size_t size) {
    void *ptr;
    if (sem_wait(&memory_pool) == -1) { // Wait for memory in pool
        perror("Memory pool wait failed");
        exit(EXIT_FAILURE);
    }
    ptr = malloc(size);
    if (!ptr) { // Allocate memory failure
        perror("Memory allocation failed");
        sem_post(&memory_pool); // Release the semaphore in case of failure
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void custom_free(void *ptr) {
    if (ptr) {
        free(ptr);
        sem_post(&memory_pool); // Release memory back to the pool
    }
}

Record* create_record(int key) {
