// Custom allocator using arena
struct arena {
    char *start;
    char *end;
    size_t used;
};

void* custom_malloc(size_t size) {
    struct arena* a = (struct arena*) malloc(sizeof(struct arena));
    if (!a) return NULL;
    a->used = 0;
    a->start = mmap(NULL, 1 << 20, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!a->start) {
        free(a);
        return NULL;
    }
    a->end = a->start + (1 << 20);

    void* result = a->start + a->used;
    if (result + size > a->end) {
        free(a);
        return NULL;
    }

    a->used += size;
    return result;
}

void custom_free(void *ptr, struct arena* a) {
    if (!ptr || !a) return;
    a->used -= (ptr - a->start);
    msync(a->start, a->end - a->start, MS_ASYNC);
}

// Concurrent PDUs generator function
void generate_pdus(process_func process, struct arena* allocator, int threshold) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER; // Lock for atomic operations
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER; // Conditional variable to signal data availability

    size_t num_pdus = 0;
    NFAPI_CRC_INDICATION_PDU_T* pdus = NULL;

