    if (!pdu_ptr) {
        // Handle error and log memory allocation failure
        return;
    }
    pdus = pdu_ptr;

    while (1) {
        // Acquire lock to ensure atomic operation
        pthread_mutex_lock(&mutex);

        num_pdus++;
        if (num_pdus >= threshold) {
            // Trigger data processing concurrently
            for (int i = 0; i < num_pdus && i < threshold; ++i) {
                PDUs[i].RX_UE_INFORMATION_TAG.tag = generateTag();
                PDUs[i].RNTI = generateRNTI();
                PDUs[i].CRC_INDICATION_REL8_TAG.crcflag = rand() % 2;
            }

            // Signal that data is available for processing
            pthread_cond_signal(&cond);
        }

        // Release lock
        pthread_mutex_unlock(&mutex);

        usleep(100000); // Adjust sleep duration based on performance requirements
    }
}

