    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* allocateUEs(size_t initialCapacity, size_t maxSize) {
    if (initialCapacity > maxSize) {
        fprintf(stderr, "Initial capacity exceeds maximum size.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *ues = malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!ues) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    size_t currentSize = initialCapacity;
    for (size_t i = 0; i < initialCapacity; ++i) {
        ues[i].rx_ue_information.tag = RX_UE_INFORMATION_TAG_VALUE1; // Replace with valid tag value
        ues[i].rnti = i + 1;                    // UE's RNTI is its index
        ues[i].crc_indication.crcflag = (rand() % 2);   // Randomly set CRC flag
    }

    size_t stepSize = initialCapacity * 2;  // Determine step size for reallocation

    while (currentSize < maxSize) {
        ues = realloc(ues, (currentSize + stepSize) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!ues) {
            fprintf(stderr, "Memory reallocation failed.\n");
            free(ues);
            return NULL;
        }

        for (size_t i = currentSize; i < currentSize + stepSize; ++i) {
            ues[i].rx_ue_information.tag = RX_UE_INFORMATION_TAG_VALUE2; // Replace with valid tag value
            ues[i].rnti = (currentSize + i + 1);    // UE's RNTI is calculated based on current size and index
            ues[i].crc_indication.crcflag = (rand() % 2);   // Randomly set CRC flag
        }

        currentSize += stepSize;
    }

    return ues;
}

void freeUEs(NFAPI_CRC_INDICATION_PDU_T *ues, size_t currentSize) {
    if (ues) {
        free(ues);
    }
}
