void create_node(NODE **head, NFAPI_CRC_INDICATION_PDU_T *data) {
    if (!(*head)) {
        *head = malloc(sizeof(NODE));
        if (!*head) {
            perror("malloc: head");
            exit(EXIT_FAILURE);
        }
        (*head)->next = NULL;
        pthread_mutex_init(&((*head)->mutex), NULL);
    } else {
        NODE *current = *head;
        while (current->next) current = current->next;
        current->next = malloc(sizeof(NODE));
        if (!current->next) {
            perror("malloc: next");
            exit(EXIT_FAILURE);
        }
        current->next->next = NULL;
        pthread_mutex_init(&(current->next)->mutex, NULL);
    }

    NODE *new_node = (*head)->next;
    new_node->data = *data;
    new_node->next = NULL;
}

void free_nodes(NODE **head) {
    if (!(*head)) return;

    NODE *current = *head;
    while (current) {
        NODE *temp = current;
        current = current->next;
        free(temp);
    }

    free(*head);
}

