typedef struct mem_block {
    size_t capacity;
    size_t used;
    TX_FRAME_INFO* frames;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} MemBlock;

MemBlock* create_mem_block(size_t initial_capacity) {
    MemBlock* mem = malloc(sizeof(MemBlock));
    if (!mem) {
        perror("Failed to allocate memory for MemBlock");
        return NULL;
    }

    mem->capacity = initial_capacity;
    mem->used = 0;
    mem->frames = calloc(initial_capacity, sizeof(TX_FRAME_INFO));
    if (!mem->frames) {
        perror("Failed to allocate memory for frames array");
        free(mem);
        return NULL;
    }

    pthread_mutex_init(&mem->lock, NULL);
    pthread_cond_init(&mem->cond, NULL);

    return mem;
}

void destroy_mem_block(MemBlock* mem) {
    if (!mem) {
        return;
    }

    free(mem->frames);
    pthread_mutex_destroy(&mem->lock);
    pthread_cond_destroy(&mem->cond);
    free(mem);
}

TX_FRAME_INFO* get_frame(MemBlock* mem) {
    TX_FRAME_INFO* frame;

    pthread_mutex_lock(&mem->lock);
    if (mem->used < mem->capacity) {
        frame = &mem->frames[mem->used];
        mem->used++;
    } else {
        pthread_cond_wait(&mem->cond, &mem->lock);
        frame = &mem->frames[mem->used - 1];
    }
    pthread_mutex_unlock(&mem->lock);

    return frame;
}

void put_frame(MemBlock* mem, TX_FRAME_INFO* frame) {
    pthread_mutex_lock(&mem->lock);
    if (mem->used > 0) {
        mem->frames[--mem->used] = *frame;
    } else {
        printf("Warning: Trying to free an empty memory block\n");
    }
    pthread_cond_signal(&mem->cond);
    pthread_mutex_unlock(&mem->lock);
}

MemBlock* grow_mem_block(MemBlock* mem, size_t new_capacity) {
    TX_FRAME_INFO* new_frames = realloc(mem->frames, new_capacity * sizeof(TX_FRAME_INFO));
    if (!new_frames) {
        perror("Failed to reallocate memory for frames array");
        return NULL;
    }

    mem->capacity = new_capacity;
    mem->frames = new_frames;
    return mem;
}
