#define LOG(...)
#endif

typedef struct NODE {
    TX_FRAME_INFO data;
    struct NODE* next;
} NODE;

static NODE** table; // hash table
static const int TABLE_SIZE = 1024;

// Hash function for uniform distribution
static inline int hash(uint32_t key) {
    return key % TABLE_SIZE;
}

void initialize() {
    table = malloc(TABLE_SIZE * sizeof(NODE*));
    if (!table) {
        LOG("Failed to allocate memory for the hash table.\n");
        exit(-1);
    }

    for (int i = 0; i < TABLE_SIZE; ++i) {
        table[i] = NULL;
    }
}

void destroy() {
    for (int i = 0; i < TABLE_SIZE; ++i) {
        NODE* current = table[i];
        while (current != NULL) {
            NODE* temp = current;
            current = current->next;
            free(temp);
        }
    }
    free(table);
}

