    }

    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void add(TX_FRAME_INFO data) {
    int index = hash(data.TX_UE_DATA_TAG);

    NODE* current = table[index];
    if (!current) {
        current = create_node(data);
        table[index] = current;
    } else {
        NODE* new_node = create_node(data);
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

void remove(uint32_t key) {
    int index = hash(key);

    NODE* current = table[index];
    if (!current) return;

    if (current->data.TX_UE_DATA_TAG == key) {
        NODE* temp = current;
        table[index] = current->next;
        free(temp);
        return;
    }

    while (current->next != NULL && current->next->data.TX_UE_DATA_TAG != key) {
        current = current->next;
    }

    if (current->next == NULL) return;

    NODE* temp = current->next;
    current->next = current->next->next;
    free(temp);
}

TX_FRAME_INFO* get(uint32_t key) {
    int index = hash(key);
    NODE* current = table[index];

    while (current != NULL && current->data.TX_UE_DATA_TAG != key) {
        current = current->next;
    }

    if (current == NULL) return NULL;
    return &current->data;
}
```

