#include <stdio.h>
#include <stdlib.h>
#include <arpa/inet.h>
#include <pthread.h>

typedef struct TCP_CONNECTION_INFO_T {
    int connection_id;
    struct sockaddr_in server_address;
    enum CONNECTION_STATUS { DISCONNECTED, CONNECTING, ACTIVE, DISCONNECTING } current_connection_status;
    struct TCP_CONNECTION_INFO_T* next; // cycle detection check
} TCP_CONNECTION_INFO;

typedef struct CONNECTION_POOL_T {
    size_t capacity;
    size_t size;
    TCP_CONNECTION_INFO** connections;
    pthread_mutex_t lock;
    void (*log_callback)(const char*, const char* format, ...);
} CONNECTION_POOL;

CONNECTION_POOL* create_connection_pool(void(*log_callback)(const char*, const char* format, ...), size_t initial_capacity) {
    if (!log_callback) return NULL;

    CONNECTION_POOL* pool = malloc(sizeof(CONNECTION_POOL));
    if (!pool) return NULL;

    pool->capacity = initial_capacity;
    pool->size = 0;
    pool->connections = calloc(initial_capacity, sizeof(TCP_CONNECTION_INFO*));
    if (!pool->connections) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);
    pool->log_callback = log_callback;

    return pool;
}

TCP_CONNECTION_INFO* get_connection(CONNECTION_POOL* pool) {
    if (pool->size == pool->capacity) {
        expand_capacity(pool);
    }

    pthread_mutex_lock(&pool->lock);

    size_t i;
    for (i = 0; i < pool->size; ++i) {
        if (!pool->connections[i]) {
            pool->connections[i] = malloc(sizeof(TCP_CONNECTION_INFO));
            if (!pool->connections[i]) {
                pthread_mutex_unlock(&pool->lock);
                return NULL;
            }

            pool->connections[i]->next = pool->connections[(pool->size - 1)->next];
            (pool->connections[(pool->size - 1)]->next) = pool->connections[i];

            break;
        }
    }

    pthread_mutex_unlock(&pool->lock);

    return pool->connections[i];
}

void expand_capacity(CONNECTION_POOL* pool) {
    size_t new_capacity = pool->capacity * 2;
    TCP_CONNECTION_INFO** new_connections = realloc(pool->connections, new_capacity * sizeof(TCP_CONNECTION_INFO*));

    if (!new_connections) return;

    pool->connections = new_connections;
    pool->capacity = new_capacity;
}

void free_connection_pool(CONNECTION_POOL* pool) {
    pthread_mutex_destroy(&pool->lock);

    size_t i;
    for (i = 0; i < pool->size; ++i) {
        if (pool->connections[i]) free(pool->connections[i]);
    }

    free(pool->connections);
    free(pool);
}
```

This code implements a simple connection pool, which manages the list of connections dynamically. It uses a linked list to store each connection's information and provides functionality for adding new connections, expanding the capacity of the list when needed, and handling memory allocation errors gracefully. The function `create_connection_pool` initializes the pool with a given callback function for logging connection lifecycle events.

The function `get_connection` returns a new TCP_CONNECTION_INFO structure from the pool if there is available capacity. It locks the mutex before searching for an empty slot in the connection array, creating a new one if necessary. After finding an empty slot, it updates the 'next' pointer of the last connection to point to the newly created connection and returns the new connection.

The function `expand_capacity` doubles the capacity of the connection pool when needed, while `free_connection_pool` destroys the mutex, frees all connections, and deallocates the memory allocated for the connection array and pool structure."]

