#include <semaphore.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

static const size_t MAX_STRUCTS = 1000;
static NFAPI_CRC_INDICATION_PDU_T *data;
static sem_t mutex;
static size_t num_elements = 0;

void init() {
    data = malloc(MAX_STRUCTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!data) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    sem_init(&mutex, 0, 1);
}

void add_element() {
    NFAPI_CRC_INDICATION_PDU_T *entry;
    size_t i;

    if (num_elements >= MAX_STRUCTS) return;

    sem_wait(&mutex);
    for (i = 0; i < num_elements; ++i) {
        if (data[i].RX_UE_INFORMATION_TAG == 0) {
            entry = &data[i];
            break;
        }
    }

    if (i == num_elements) { // resize array
        size_t new_size = MAX_STRUCTS * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(data, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            fprintf(stderr, "Memory resizing failed.\n");
            sem_post(&mutex);
            return;
        }
        data = new_data;
        MAX_STRUCTS *= 2;
    }

    entry->RX_UE_INFORMATION_TAG = RNTI << 16 | num_elements + 1;
    entry->CRC_INDICATION_REL8_TAG.CRCFLAG = (entry->RX_UE_INFORMATION_TAG & 0x01) ? 0xBAD : 0xDEAD;
    ++num_elements;
    sem_post(&mutex);
}

void iterate(void(*func)(NFAPI_CRC_INDICATION_PDU_T*)) {
    size_t i;

    sem_wait(&mutex);
    for (i = 0; i < num_elements; ++i) {
        if (func) func(&data[i]);
    }
    sem_post(&mutex);
}
