#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

#define MAX_STRUCTURES 1024
#define EXPANSION_FACTOR 2

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
    unsigned char crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* structurePool = NULL;
size_t currentSize = 0;
size_t maxSize = MAX_STRUCTURES;
pthread_mutex_t poolMutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t notFull = PTHREAD_COND_INITIALIZER;
pthread_cond_t notEmpty = PTHREAD_COND_INITIALIZER;

void * structurePoolInit(void) {
    if (!(structurePool = malloc(MAX_STRUCTURES * sizeof(NFAPI_CRC_INDICATION_PDU_T*)))) {
        fprintf(stderr, "Failed to allocate initial pool\n");
        return NULL;
    }

    for (size_t i = 0; i < MAX_STRUCTURES; ++i) {
        structurePool[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!structurePool[i]) {
            fprintf(stderr, "Failed to allocate initial pool element\n");
            return NULL;
        }
        memset(structurePool[i], 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    return structurePool;
}

void structurePoolExpand() {
    size_t newMaxSize = maxSize * EXPANSION_FACTOR;
    NFAPI_CRC_INDICATION_PDU_T** newPool = realloc(structurePool, newMaxSize * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    if (!newPool) {
        fprintf(stderr, "Failed to expand pool\n");
        return;
    }

    structurePool = newPool;
    for (size_t i = maxSize; i < newMaxSize; ++i) {
        structurePool[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!structurePool[i]) {
            fprintf(stderr, "Failed to allocate expanded pool element\n");
            return;
        }
        memset(structurePool[i], 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    maxSize = newMaxSize;
}

void structurePoolPush(NFAPI_CRC_INDICATION_PDU_T* structure) {
    pthread_mutex_lock(&poolMutex);

    if (currentSize >= maxSize) {
        structurePoolExpand();
    }

    size_t index = currentSize % MAX_STRUCTURES;
    memcpy(structurePool[index], structure, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_lock(&notEmpty);
    pthread_cond_signal(&notFull);
    pthread_mutex_unlock(&notEmpty);

    currentSize++;
    pthread_mutex_unlock(&poolMutex);
}

NFAPI_CRC_INDICATION_PDU_T* structurePoolPop() {
    NFAPI_CRC_INDICATION_PDU_T* structure;
    size_t index;

    pthread_mutex_lock(&poolMutex);

    while (currentSize == 0) {
        pthread_mutex_unlock(&poolMutex);
        pthread_cond_wait(&notEmpty, &poolMutex);
        pthread_mutex_lock(&poolMutex);
    }

    index = (currentSize - 1) % MAX_STRUCTURES;
    structure = structurePool[index];

    memset(structure, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_lock(&notFull);
    pthread_cond_signal(&notEmpty);
    pthread_mutex_unlock(&notFull);

    currentSize--;
    pthread_mutex_unlock(&poolMutex);

    return structure;
}

void structurePoolCleanup() {
    for (size_t i = 0; i < maxSize; ++i) {
        free(structurePool[i]);
    }

    free(structurePool);
}
```
The code above creates a `structurePoolInit()` function to initialize the pool, a `structurePoolPush()` function to add new structures, and a `structurePoolPop()` function to retrieve a structure from the pool. The pool is managed with a mutex lock to ensure thread-safety, and condition variables are used to minimize contention when the pool is empty or full. The pool dynamically expands as needed, but only by a factor of 2 at a time to prevent excessive memory consumption. Error handling is in place to manage allocation failures gracefully. A `structurePoolCleanup()` function is provided for proper resource deallocation upon exit.']

