NicData nic_init(size_t initial_capacity) {
    if (initial_capacity == 0)
        initial_capacity = 4;
    NicData data = { .capacity = initial_capacity, .count = 0, .data = NULL, .listLock = PTHREAD_MUTEX_INITIALIZER };
    data.data = malloc(initial_capacity * sizeof(NICConfig));
    if (!data.data) {
        fprintf(stderr, "Error: Failed to allocate memory for NIC configurations.\n");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < initial_capacity; ++i) {
        data.data[i].lock = PTHREAD_MUTEX_INITIALIZER;
        memset(data.data[i].mac, 0, sizeof(data.data[i].mac));
    }
    return data;
}

void nic_destroy(NicData *nic) {
    if (nic->data) {
        free(nic->data);
        nic->data = NULL;
    }
    nic->count = 0;
    nic->capacity = 0;
}

size_t nic_get_count(const NicData *nic) {
    return nic->count;
}

NICConfig* nic_get(NicData *nic, size_t index) {
    pthread_mutex_lock(&nic->listLock);
    if (index >= nic->capacity) {
        fprintf(stderr, "Error: Invalid index provided for NIC configuration.\n");
        pthread_mutex_unlock(&nic->listLock);
        return NULL;
    }
    pthread_mutex_lock(&nic->data[index].lock);
    NICConfig* config = &nic->data[index];
    pthread_mutex_unlock(&nic->listLock);
    return config;
}

NICConfig* nic_push(NICConfig *config, NicData *nic) {
    pthread_mutex_lock(&nic->listLock);
    if (nic->capacity == nic->count) {
        size_t new_capacity = nic->capacity ? nic->capacity * 2 : 4;
        NICConfig *tmp_data = realloc(nic->data, new_capacity * sizeof(NICConfig));
        if (!tmp_data) {
            fprintf(stderr, "Error: Failed to resize memory for NIC configurations.\n");
            pthread_mutex_unlock(&nic->listLock);
            return NULL;
        }
        nic->data = tmp_data;
        nic->capacity = new_capacity;
    }
    memcpy(&nic->data[nic->count], config, sizeof(NICConfig));
    ++nic->count;
    pthread_mutex_unlock(&nic->listLock);
    return &nic->data[nic->count - 1];
}
