typedef struct {
    uint32_t NR_UL_CCID;
    uint8_t NR_CQI;
    uint8_t NR_DMRS_CONFIG;
    float NR_Uplink_Tx_Power_Report;
    time_t timestamp; // UNIX timestamp
} NR_Uplink_Tx_Report;

typedef struct node {
    NR_Uplink_Tx_Report data;
    struct node *next;
} Node;

static Node** head = NULL;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static const int max_reports = 10000;
static const time_t purge_interval = 5 * 60; // 5 minutes

void init() {
    if (head) return;
    head = malloc(max_reports * sizeof(Node*));
}

void free_list() {
    for (int i = 0; i < max_reports; ++i) {
        Node* temp = head[i];
        while (temp != NULL) {
            Node* next = temp->next;
            free(temp);
            temp = next;
        }
    }
    free(head);
    head = NULL;
}

void purge_old_reports() {
    time_t current_time = time(NULL);
    for (int i = 0; i < max_reports; ++i) {
        Node* temp = head[i];
        while (temp != NULL && temp->data.timestamp + purge_interval < current_time) {
            Node* next = temp->next;
            free(temp);
            temp = next;
        }
    }
}

void insert_report(NR_Uplink_Tx_Report report) {
    pthread_mutex_lock(&mutex);
    int idx = (size_t)(&report - head[0]) % max_reports;
    Node* newNode = malloc(sizeof(Node));
    newNode->data = report;
    newNode->next = head[idx];
    head[idx] = newNode;
    purge_old_reports();
    pthread_mutex_unlock(&mutex);
}

float average_tx_power() {
    float total_power = 0.0f;
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < max_reports; ++i) {
        Node* temp = head[i];
        while (temp != NULL) {
            total_power += temp->data.NR_Uplink_Tx_Power_Report;
            temp = temp->next;
        }
    }
    pthread_mutex_unlock(&mutex);
    return total_power / (float)max_reports;
}
```

