#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_DATA_CHUNKS 1000
#define MAX_BYTES_PER_CHUNK 1024

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* generateNfadataAndCopyBytes(const void** data_chunks, size_t num_data_chunks, size_t bytes_to_copy, uint8_t* dest_buffer) {
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_data_chunks * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        perror("Error allocating memory for NFAPI_CRC_INDICATION_PDU_T list");
        return NULL;
    }

    uint8_t* src = (uint8_t*)calloc(MAX_DATA_CHUNKS * MAX_BYTES_PER_CHUNK, sizeof(uint8_t));
    if (!src) {
        perror("Error allocating memory for temporary buffer");
        free(pdu_list);
        return NULL;
    }

    size_t total_data = 0;
    for (size_t i = 0; i < num_data_chunks; ++i) {
        if (!data_chunks[i]) continue;
        total_data += *(size_t*)data_chunks[i];
    }

    if (bytes_to_copy > total_data) {
        fprintf(stderr, "Error: Specified number of bytes to copy exceeds available data\n");
        free(src);
        free(pdu_list);
        return NULL;
    }

    size_t src_index = 0;
    for (size_t i = 0; i < num_data_chunks; ++i) {
        if (!data_chunks[i]) continue;
        memcpy(src + src_index, data_chunks[i], *(size_t*)data_chunks[i]);
        src_index += *(size_t*)data_chunks[i];
    }

    size_t dest_index = 0;
    for (size_t i = 0; i < num_data_chunks; ++i) {
        pdu_list[i].RX_UE_INFORMATION_TAG = i + 1;
        pdu_list[i].RNTI = i % 256; // RNTIs should be unique, adjust as necessary
        pdu_list[i].CRCFLAG = (rand() & 1) != 0;

        size_t chunk_size = *(size_t*)(src + src_index);
        if (chunk_size > bytes_to_copy) {
            chunk_size = bytes_to_copy;
        }

        memcpy(dest_buffer + dest_index, src + src_index, chunk_size);
        dest_index += chunk_size;
        src_index += chunk_size;
    }

    free(src);
    return pdu_list;
}
