struct Session {
    std::string authToken;
    time_t expirationTime;
    time_t lastActivityTimestamp;
};

class UserSessions final {
public:
    explicit UserSessions(size_t initialCapacity) : sessions_(initialCapacity) {}

    boost::optional<Session&> getSessionByToken(const std::string& authToken) {
        boost::mutex::scoped_lock lock(mutex_);
        auto iter = sessions_.find(authToken);
        return (iter != sessions_.end()) ? &*iter : boost::none;
    }

    void addSession(const Session& session) {
        boost::mutex::scoped_lock lock(mutex_);
        sessions_[session.authToken] = session;
    }

    void updateLastActivity(const std::string& authToken) {
        boost::mutex::scoped_lock lock(mutex_);
        auto iter = sessions_.find(authToken);
        if (iter != sessions_.end()) {
            iter->second.lastActivityTimestamp = time(nullptr);
        }
    }

    void evictExpiredSessions() {
        boost::mutex::scoped_lock lock(mutex_);
        auto now = time(nullptr);

        for (auto& session : sessions_) {
            if (session.second.expirationTime < now) {
                sessions_.erase(session.first);
            }
        }
    }

private:
    std::unordered_map<std::string, Session> sessions_;
    boost::mutex mutex_;
};
