} LTE_PHY_RX_FRAME_INFO_T;

typedef struct _tagged_data {
    size_t data_size;      // Size of the tag's payload
    int payload_type;     // Type of the tag's payload
} TAGGED_DATA;

struct _frame_info {
    LTE_PHY_RX_FRAME_INFO_T *array;  // Dynamic array of frame info structures
    size_t capacity;               // Maximum number of elements in the array
    size_t count;                   // Current number of populated elements
    pthread_mutex_t mutex;          // Mutex for synchronization
    TAGGED_DATA *tags;              // Array of tagged data structures
};

struct _frame_info* create_frame_info(size_t max_size) {
    if (max_size <= 0) return NULL;

    struct _frame_info *fi = calloc(1, sizeof(_frame_info));
    if (!fi) return NULL;

    fi->capacity = max_size;
    fi->count = 0;

    // Align frame info and tagged data structures for optimal cache locality
#if defined(__x86_64__) || defined(_M_X64)
    const size_t align = 64;
#else
    const size_t align = 16;
#endif

    fi->array = (LTE_PHY_RX_FRAME_INFO_T *)__builtin_alignvec(malloc((max_size + align - 1) * sizeof(LTE_PHY_RX_FRAME_INFO_T)), align);
    if (!fi->array) {
        free(fi);
        return NULL;
    }
    fi->tags = (TAGGED_DATA *)__builtin_alignvec(malloc((max_size + align - 1) * sizeof(TAGGED_DATA)), align);
    if (!fi->tags) {
        free(fi->array);
        free(fi);
        return NULL;
    }

    pthread_mutex_init(&fi->mutex, NULL);

    return fi;
}

size_t add_frame_info(struct _frame_info *fi, const LTE_PHY_RX_FRAME_INFO_T *info) {
    size_t i = 0;

    // Iterate through the array, ensuring no duplicate RNTIs
    for (; i < fi->count; ++i) {
        if (fi->array[i].RNTI == info->RNTI) break;
    }

    if (i < fi->capacity && i != fi->count) { // Ensure array has space and no duplicate RNTIs found
        memcpy(&fi->array[i], info, sizeof(LTE_PHY_RX_FRAME_INFO_T));
        ++fi->count;
    } else if (i == fi->capacity) {           // Array is full - reallocate if possible
        const size_t new_cap = fi->capacity * 2;
        LTE_PHY_RX_FRAME_INFO_T *new_array = (LTE_PHY_RX_FRAME_INFO_T *)__builtin_alignvec(realloc(fi->array, new_cap * sizeof(LTE_PHY_RX_FRAME_INFO_T)), align);
        TAGGED_DATA *new_tags = (TAGGED_DATA *)__builtin_alignvec(realloc(fi->tags, new_cap * sizeof(TAGGED_DATA)), align);

        if (!new_array || !new_tags) {
            fi->capacity = 0;
            return 0;
        }

        fi->capacity = new_cap;
        fi->array = new_array;
        fi->tags = new_tags;
    }

    // Add the tagged data to the corresponding structure, handle edge cases for tag size and type
    if (info->tags) {
        const size_t idx = info - fi->array;
        fi->tags[idx].data_size = info->tags->data_size;
        fi->tags[idx].payload_type = info->tags->payload_type;
    }

    return i < fi->count ? 1 : 0;
}

void log_memory_usage(const struct _frame_info *fi) {
    // Implement logging of memory usage and performance metrics here...
}

void destroy_frame_info(struct _frame_info **fi) {
    if (!*fi || !(*fi)->array) return;

    free((*fi)->tags);
    free((*fi)->array);
    pthread_mutex_destroy(&(*fi)->mutex);
    free(*fi);
    *fi = NULL;
}
