#include <stdio.h>
#include <stdlib.h>
#include <tiffio.h>
#include "image_processing_framework.h"

typedef struct {
    uint32_t width;
    uint32_t height;
    sametype samples;
    uint16_t compression;
    uint16_t photometric;
    uint32_t rows_per_strip;
    uint32_t strips_per_image;
    uint32_t image_number;
} tiff_page_info;

void tiff_parse(const char *filename, tiff_page_info **pages, size_t *num_pages) {
    TIFF *tif = TIFFOpen(filename, "r");
    if (!tif) {
        fprintf(stderr, "Error: Unable to open file '%s'\n", filename);
        exit(EXIT_FAILURE);
    }

    size_t i = 0;
    tiff_page_info *pages_array = NULL;

    while (1) {
        tiff_page_info *current_page = &pages_array[i];
        if (TIFFGetField(tif, TIFFTAG_IMAGEWIDTH, &(current_page->width)) != 1 ||
            TIFFGetField(tif, TIFFTAG_IMAGELENGTH, &(current_page->height)) != 1) {
                break;
        }

        current_page->samples = sametype(TIFFGetFieldDefaulted(tif, TIFFTAG_SAMPLESPERPIXEL, 1));
        current_page->compression = TIFFCompression(tif);
        current_page->photometric = TIFFPhotometricInterpretation(tif);
        current_page->rows_per_strip = TIFFStripSize(tif);
        current_page->strips_per_image = TIFFNumberOfStrips(tif);
        current_page->image_number = TIFFScanlineSize(tif) / current_page->samples * current_page->rows_per_strip;

        if (current_page->compression == COMPRESSION_ERROR ||
            current_page->photometric == PHOTOMETRIC_ERROR) {
            fprintf(stderr, "Error: Unsupported compression or photometric type in page %zu\n", i);
            continue;
        }

        i++;
    }

    *pages = pages_array;
    *num_pages = i;

    TiffClose(tif);
}
```
