typedef enum {
    SUCCESS,
    FAILURE_INVALID_INPUT,
    FAILURE_MEMORY,
    FAILURE_NETWORK,
    FAILURE_DUPLICATE,
    FAILURE_COLLISION,
    FAILURE_IP_CONFLICT,
    FAILURE_MAX_INTERFACES
} StatusCode;

StatusCode configure_interface(const char *name, const char *mac, const char *ip, const char *netmask) {
    struct in_addr ip_addr;
    struct in6_addr ip6_addr;
    struct ifreq req;
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    StatusCode status = SUCCESS;

    memset(&req, 0, sizeof(req));
    strncpy(req.ifr_name, name, IFNAMSIZ-1);

    if (inet_pton(AF_INET, ip, &ip_addr) <= 0 || inet_pton(AF_INET, netmask, &((struct sockaddr_in *)&req).sin_netmask) <= 0) {
        status = FAILURE_INVALID_INPUT;
        goto cleanup;
    }

    if (getifaddrs() < 0) {
        status = FAILURE_NETWORK;
        goto cleanup;
    }

    struct ifaddrs *ifa, *current;
    current = ifa = getifaddrs();

    int found = 0;
    while (ifa != NULL) {
        if (!strcmp(ifa->ifa_name, name)) {
            if ((ifa->ifa_flags & IFF_UP) && strcmp(iface->ifa_hwaddr.sa_data, mac)) {
                status = FAILURE_DUPLICATE;
                goto cleanup;
            }
            found = 1;
        }
        ifa = ifa->ifa_next;
    }

    if (found) {
        status = FAILURE_COLLISION;
        goto cleanup;
    }

    req.ifr_addr = *((struct sockaddr *) &ip_addr);
    req.ifr_mask = *((struct sockaddr *) &((struct sockaddr_in *)&req).sin_netmask);

    if (nfapi_set_mac(name, mac) < 0 || nfapi_set_ip(name, ip) < 0 || nfapi_up(name) < 0) {
        status = FAILURE_NETWORK;
        goto cleanup;
    }

cleanup:
    freeifaddrs(current);
    close(sockfd);
    return status;
}
