    atomic_size_t payloadSize;  // RX_PAYLOAD_SIZE
    atomic_int64_t timestamp;  // RX_TIMESTAMP
    struct NFAPI_L2_RX_BUFFER_T* next; // Next and prev pointers for doubly-linked list
};

// Define a wrapper for the double-linked list
struct double_list {
    struct NFAPI_L2_RX_BUFFER_T *head, *tail;  // Head and tail of the list
    size_t size;                              // Current number of elements in the list
    const size_t maxSize;                     // Maximum allowable size of the list (10,000)
};

// Function to initialize the double-linked list with default settings
void initDoubleList(struct double_list *dList) {
    dList->head = NULL;
    dList->tail = NULL;
    dList->size = 0;
    dList->maxSize = 10000;
}

// Function to insert a new element at the head of the list
void insertHead(struct double_list *dList, struct NFAPI_L2_RX_BUFFER_T* item) {
    // Use atomic operations for thread safety
    if (dList->head == NULL) {
        dList->head = item;
        dList->tail = item;
    } else {
        item->next = dList->head;
        dList->head->prev = item;
        dList->head = item;
    }
    __sync_synchronize(); // Memory barrier to ensure the changes are visible to other threads
}

// Function to insert a new element at the tail of the list
void insertTail(struct double_list *dList, struct NFAPI_L2_RX_BUFFER_T* item) {
    if (dList->tail == NULL) {
        dList->head = item;
        dList->tail = item;
    } else {
        item->prev = dList->tail;
        dList->tail->next = item;
        dList->tail = item;
    }
    __sync_synchronize(); // Memory barrier to ensure the changes are visible to other threads
}

// Function to insert a new element in the middle of the list (at position 'pos')
void insertMiddle(struct double_list *dList, size_t pos, struct NFAPI_L2_RX_BUFFER_T* item) {
    if (pos > dList->size || pos < 1) return; // Invalid position

    // Find the node before the desired insertion point
    struct NFAPI_L2_RX_BUFFER_T *prevNode = dList->head;
    for (size_t i = 1; i < pos; ++i) {
        prevNode = prevNode->next;
    }

    item->next = prevNode->next;
    item->prev = prevNode;

    if (item->next != NULL) {
        item->next->prev = item;
    } else {
        dList->tail = item;
    }

    prevNode->next = item;
    __sync_synchronize(); // Memory barrier to ensure the changes are visible to other threads
}

// Function to remove an element from the list by its unique id (L2_RX_ID)
void removeById(struct double_list *dList, uint32_t id) {
    struct NFAPI_L2_RX_BUFFER_T* current = dList->head;
    while (current != NULL) {
        if (current->id.load() == id) { // Check if the current item has the specified ID
            if (current == dList->head) {
                dList->head = current->next;
            } else if (current == dList->tail) {
                dList->tail = current->prev;
            } else {
                current->prev->next = current->next;
                current->next->prev = current->prev;
            }
            free(current); // Free the memory used by the removed item
            __sync_synchronize(); // Memory barrier to ensure the changes are visible to other threads
            break;
        }
        current = current->next;
    }
}

