void generate_crc_indication(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pdu->crc_indication_rel8_tag.crcflag = rand() % 2;
}

bool validate_crc_indication(const NFAPI_CRC_INDICATION_PDU_T *pdu) {
