void *request_data(void *data) {
    size_t N = *(size_t *) data;
    NFAPI_CRC_INDICATION_PDU_T *elements = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!elements) {
        log_error("Memory allocation failed");
        return NULL;
    }

    pthread_mutex_lock(&buffer_pool_mutex);
    size_t num_from_pool = buffer_pool_size - buffer_pool_index;
    if (num_from_pool >= N) {
        memcpy(elements, buffer_pool + buffer_pool_index, num_from_pool * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        buffer_pool_index += num_from_pool;
        if (buffer_pool_index == buffer_pool_size) {
            buffer_pool_index = 0;
        }
        pthread_mutex_unlock(&buffer_pool_mutex);
    } else {
        size_t remaining = N - num_from_pool;
        elements += num_from_pool;
        pthread_mutex_unlock(&buffer_pool_mutex);

        for (size_t i = 0; i < remaining; ++i) {
            generate_crc_indication(elements + i);
        }
    }

    return elements;
}

size_t populate_array(size_t N, size_t *populated_elements) {
    if (N == 0) {
        return 0;
    }

    void *results = request_data((void *) &N);
    if (!results) {
        return 0;
    }

    size_t actual_populated_elements = 0;
    for (size_t i = 0; i < N; ++i) {
        if (validate_crc_indication((NFAPI_CRC_INDICATION_PDU_T *) ((char *) results + (actual_populated_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T)))) {
            ++actual_populated_elements;
        } else {
            free(results);
            log_error("Invalid CRC flag encountered");
            return 0;
        }
    }

    *populated_elements = actual_populated_elements;
    return actual_populated_elements;
}
