void init_pool(struct pool *pool, size_t capacity) {
    pool->capacity = capacity;
    pool->count = 0;
    pool->data = malloc(capacity * sizeof(NFAPI_CRCI_PDU_T));
    if (!pool->data) {
        fprintf(stderr, "Error: Memory allocation failure\n");
        exit(-1);
    }
    pool->mutex = PTHREAD_MUTEX_INITIALIZER;
}

void destroy_pool(struct pool *pool) {
    free(pool->data);
}

struct pool *resize_pool(struct pool *pool, size_t new_capacity) {
    if (new_capacity > pool->capacity) {
        void *tmp = realloc(pool->data, new_capacity * sizeof(NFAPI_CRCI_PDU_T));
        if (!tmp) {
            fprintf(stderr, "Error: Memory allocation failure\n");
            exit(-1);
        }
        pool->data = tmp;
        pool->capacity = new_capacity;
    }
    return pool;
}

NFAPI_CRCI_PDU_T *pool_get(struct pool *pool) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->count < pool->capacity) {
        pool->count++;
        pthread_mutex_unlock(&pool->mutex);
        return &pool->data[pool->count - 1];
    }
    struct pool *new_pool = resize_pool(pool, pool->capacity * 2);
    NFAPI_CRCI_PDU_T *pdus = new_pool->data + pool->count;
    pool->count++;
    pthread_mutex_unlock(&pool->mutex);
    return pdus;
