} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_STRUCTURES 1000 // Adjust as per the memory budget
#define SEMAPHORE_COUNT MAX_STRUCTURES

static sem_t semaphore_array[SEMAPHORE_COUNT];
static NFAPI_CRC_INDICATION_PDU_T *list = NULL;
static size_t list_size = 0;
static size_t list_capacity = 0;
static sem_t list_mutex;

void init_semaphores() {
    for (size_t i = 0; i < SEMAPHORE_COUNT; ++i) {
        if(sem_init(&semaphore_array[i], 1, 1)) {
            perror("Failed to initialize semaphore");
            exit(EXIT_FAILURE);
        }
    }

    if(sem_init(&list_mutex, 1, 1)) {
        perror("Failed to initialize list mutex");
        exit(EXIT_FAILURE);
    }
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu() {
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if(!pdu) {
