        return NULL;
    }

    pdu->RX_UE_INFORMATION_TAG = rand(); // Replace with appropriate value source
    pdu->RNTI = rand() % 65536; // RNTI should be within the valid range
    pdu->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    sem_init(&pdu->semaphore, 1, 0); // Initializing semaphore to block creation of RNTIs with the same value

    return pdu;
}

int populate_list(size_t n) {
    if((list_capacity + n) > MAX_STRUCTURES) {
        fprintf(stderr, "Error: Memory limit exceeded\n");
        return -1;
    }

    sem_wait(&list_mutex);
    for (size_t i = list_size; i < list_size + n && i < MAX_STRUCTURES; ++i) {
        if(sem_trywait(&semaphore_array[i])) {
            // RNTI is free to be used, so proceed with adding the PDU
            list[i] = create_pdu();
            if(!list[i]) {
                sem_post(&list_mutex);
                return -1;
            }
        } else {
            // RNTI is currently in use, skip this iteration
            continue;
        }
    }
    list_size += n;
    sem_post(&list_mutex);

    return 0;
}

void free_list() {
    for (size_t i = 0; i < list_size; ++i) {
        free(list[i]);
    }
    free(list);
    list = NULL;
    list_size = 0;
    list_capacity = 0;
}
