struct memory_block {
    size_t capacity;
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct memory_block *next;
};

struct memory_pool {
    struct memory_block *head;
    sem_t free_list_lock;
};

void init_memory_pool(struct memory_pool *pool, size_t block_size) {
    pool->head = NULL;
    sem_init(&pool->free_list_lock, 0, 1);
}

struct memory_block* allocate_memory_block(struct memory_pool *pool, size_t block_size) {
    struct memory_block *new_block = malloc(sizeof(struct memory_block));
    if (!new_block) return NULL;

    new_block->capacity = block_size;
    new_block->data = calloc(block_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_block->data) {
        free(new_block);
        return NULL;
    }

    sem_wait(&pool->free_list_lock);
    new_block->next = pool->head;
    pool->head = new_block;
    sem_post(&pool->free_list_lock);

    return new_block;
}

void free_memory_block(struct memory_pool *pool, struct memory_block *block) {
    if (block == NULL) return;

    sem_wait(&pool->free_list_lock);
    block->next = pool->head;
    pool->head = block;
    sem_post(&pool->free_list_lock);

    free(block->data);
    free(block);
}

