        memcpy(new_block->data + (*size - capacity), array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * capacity);

        *array = realloc(*array, (*size + capacity) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (*array == NULL) {
            free_memory_block(pool, new_block);
            return;
        }
        *size += capacity;
    }
}

