#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    RX_QAM_MAP qam_map;
    RX_SYMBOL_POWER symbol_power;
    RX_CQI cqi;
} PHY_STATS_PDU_T;

struct phy_stats_context {
    PHY_STATS_PDU_T* buffer;
    size_t capacity;
    size_t head;
    size_t tail;
    semaphore_t lock;
};

PHY_STATS_CONTEXT* phy_stats_context_create(size_t capacity) {
    PHY_STATS_CONTEXT* ctx = malloc(sizeof(PHY_STATS_CONTEXT));
    ctx->capacity = capacity;
    ctx->head = ctx->tail = 0;
    sem_init(&ctx->lock, 0, 1);
    ctx->buffer = calloc(capacity, sizeof(PHY_STATS_PDU_T));
    return ctx;
}

void phy_stats_context_push(PHY_STATS_CONTEXT* ctx, const PHY_STATS_PDU_T* pdu) {
    sem_wait(&ctx->lock);
    size_t next = (ctx->head + 1) % ctx->capacity;
    if (next != ctx->tail) { // Circular buffer is not full, so push the new data.
        ctx->buffer[ctx->head] = *pdu;
        ctx->head = next;
    }
    sem_post(&ctx->lock);
}

PHY_STATS_PDU_T* phy_stats_context_pop(PHY_STATS_CONTEXT* ctx) {
    sem_wait(&ctx->lock);
    PHY_STATS_PDU_T* result = NULL;
    if (ctx->head != ctx->tail) { // Circular buffer is not empty, so pop the oldest data.
        result = &ctx->buffer[ctx->tail];
        ctx->tail++;
        if (ctx->tail == ctx->capacity)
            ctx->tail = 0;
    }
    sem_post(&ctx->lock);
    return result;
}

void phy_stats_context_destroy(PHY_STATS_CONTEXT** ctx) {
    if (*ctx) {
        free((*ctx)->buffer);
        sem_destroy(&(*ctx)->lock);
        free(*ctx);
        *ctx = NULL;
    }
}
```

This implementation provides a thread-safe, dynamically-sized buffer for storing `PHY_STATS_PDU_T` structures. The `phy_stats_context_push()` function can be called concurrently from multiple threads to add new data points, while the `phy_stats_context_pop()` function removes and returns the oldest data point when needed.

Memory management is handled by using dynamic allocation for the buffer and a destructor for graceful shutdown. The semaphore lock ensures consistency of the data inside the buffer. The design also anticipates potential delays or data inconsistencies due to real-time updates from an external system.']

