typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node *next;
} Node;

static Node* head = NULL;
static unsigned int max_elements = 10000;
static unsigned int current_size = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void nfapi_crc_indication_pdu_init(unsigned int max) {
    if (max < 1 || max > 10000) {
        fprintf(stderr, "Invalid maximum number of elements: %d\n", max);
        return;
    }

    max_elements = max;
}

bool nfapi_crc_indication_pdu_push(NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&mutex);

    if (current_size >= max_elements) {
        fprintf(stderr, "List is full. Cannot add more elements.\n");
        pthread_mutex_unlock(&mutex);
        return false;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory.");
        pthread_mutex_unlock(&mutex);
        return false;
    }

    new_node->data = data;
    new_node->next = head;
    head = new_node;
    current_size++;
    pthread_mutex_unlock(&mutex);

    return true;
}

NFAPI_CRC_INDICATION_PDU_T nfapi_crc_indication_pdu_pop() {
    pthread_mutex_lock(&mutex);

    if (current_size == 0) {
        fprintf(stderr, "List is empty. Cannot remove elements.\n");
        pthread_mutex_unlock(&mutex);
        return (NFAPI_CRC_INDICATION_PDU_T){0};
    }

    Node* temp = head;
    NFAPI_CRC_INDICATION_PDU_T data = temp->data;
    head = temp->next;
    free(temp);
    current_size--;
    pthread_mutex_unlock(&mutex);

    return data;
}
