typedef struct FrequencyTracking {
    size_t capacity;
    size_t size;
    unsigned long *hashes;
    size_t *counts;
} FrequencyTracking;

FrequencyTracking* create_frequency_tracking(size_t initial_capacity) {
    FrequencyTracking *freq = (FrequencyTracking *) malloc(sizeof(FrequencyTracking));
    if (!freq) return NULL;

    freq->capacity = initial_capacity;
    freq->size = 0;
    freq->hashes = calloc(initial_capacity, sizeof(unsigned long));
    if (!freq->hashes) {
        free(freq);
        return NULL;
    }
    freq->counts = calloc(initial_capacity, sizeof(size_t));
    if (!freq->counts) {
        free(freq->hashes);
        free(freq);
        return NULL;
    }

    return freq;
}

void resize_frequency_tracking(FrequencyTracking *freq) {
    unsigned long *new_hashes = realloc(freq->hashes, (freq->capacity *= HASH_SCALE_FACTOR) * sizeof(unsigned long));
    if (!new_hashes) return;
    freq->hashes = new_hashes;

    size_t *new_counts = realloc(freq->counts, (freq->capacity *= HASH_SCALE_FACTOR) * sizeof(size_t));
    if (!new_counts) return;
    freq->counts = new_counts;
}

void populate_records(size_t num_offsets, Record **records) {
    *records = malloc(num_offsets * sizeof(Record));
    if (*records == NULL) exit(EXIT_FAILURE);

