    }
}

void populate_freq(FrequencyTracking *freq, Record *records, size_t num_offsets) {
    for (size_t i = 0; i < num_offsets; ++i) {
        unsigned long hash = hash_string((*records + i)->str);
        freq->hashes[hash % freq->capacity] = hash;
        ++freq->counts[hash % freq->capacity];
    }
}

unsigned long hash_string(const char *str) {
    unsigned long hash = 5381;
    int c;

    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash % ULONG_MAX;
}

void print_records(size_t num_offsets, Record *records) {
    for (size_t i = 0; i < num_offsets; ++i)
