This C code initializes a 2D array of integers (a matrix) and populates it with random values. The function `populate_matrix` takes the dimensions (rows and columns) as arguments and creates an appropriate-sized 2D array dynamically.

The code then calculates the sum of all the elements in the matrix using a nested loop, and prints out both the original matrix and the calculated sum.

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

int **populate_matrix(size_t rows, size_t columns) {
    int **matrix;

    matrix = malloc(rows * sizeof(int*));

    if (matrix == NULL) return NULL;

    for (size_t i = 0; i < rows; ++i) {
        matrix[i] = calloc(columns, sizeof(int));

        if (matrix[i] == NULL) {
            free(matrix);
            return NULL;
        }
    }

    for (size_t i = 0; i < rows; ++i) {
        for (size_t j = 0; j < columns; ++j) {
            matrix[i][j] = rand() % 100 + 1;
        }
    }

    return matrix;
}

void print_matrix(int **matrix, size_t rows, size_t columns) {
    for (size_t i = 0; i < rows; ++i) {
        for (size_t j = 0; j < columns; ++j)
            printf("%3d ", matrix[i][j]);
        printf("\n");
    }
}

int sum_matrix(int **matrix, size_t rows, size_t columns) {
    int sum = 0;

    for (size_t i = 0; i < rows; ++i) {
        for (size_t j = 0; j < columns; ++j)
            sum += matrix[i][j];
    }

    return sum;
}

int main() {
    srand(time(NULL));
    size_t rows = 3, columns = 4;
    int **matrix = populate_matrix(rows, columns);

    if (matrix == NULL) return EXIT_FAILURE;

    print_matrix(matrix, rows, columns);
    printf("Sum of matrix elements: %d\n", sum_matrix(matrix, rows, columns));

    for (size_t i = 0; i < rows; ++i) free(matrix[i]);
    free(matrix);

    return EXIT_SUCCESS;
}
