#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    TX_UE_DATA_TAG rx_ue_information_tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    SFN_SFNSSB sfn_sfnssb;
    TX_FRAME_INFO* next;
} TX_FRAME_INFO;

typedef struct MemPool {
    TX_FRAME_INFO** data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} MemPool;

MemPool* create_mempool(size_t capacity, size_t initial_size) {
    MemPool* pool = (MemPool*)malloc(sizeof(MemPool));
    if (!pool) return NULL;

    pool->capacity = capacity;
    pool->size = initial_size;
    pool->data = (TX_FRAME_INFO**)calloc(capacity, sizeof(TX_FRAME_INFO*));
    if (!pool->data) {
        free(pool);
        return NULL;
    }
    pool->lock = PTHREAD_MUTEX_INITIALIZER;

    for (size_t i = 0; i < initial_size; ++i) {
        pool->data[i] = (TX_FRAME_INFO*)calloc(1, sizeof(TX_FRAME_INFO));
        if (!pool->data[i]) {
            free(pool->data);
            free(pool);
            return NULL;
        }
    }
    return pool;
}

void destroy_mempool(MemPool* pool) {
    for (size_t i = 0; i < pool->size; ++i) {
        free(pool->data[i]);
    }
    free(pool->data);
    free(pool);
}

TX_FRAME_INFO* get_entry(MemPool* pool) {
    pthread_mutex_lock(&pool->lock);

    TX_FRAME_INFO* entry;
    if (pool->size < pool->capacity) {
        entry = pool->data[pool->size];
        pool->size++;
    } else {
        entry = (TX_FRAME_INFO*)realloc(pool->data[0], sizeof(TX_FRAME_INFO) * (pool->capacity + 1));
        if (!entry) {
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }

        for (size_t i = pool->capacity; i > 1; --i) {
            pool->data[i] = pool->data[i - 1];
        }
        entry = pool->data[0];
        pool->data[0] = NULL;
    }

    pthread_mutex_unlock(&pool->lock);

    memset(entry, 0, sizeof(TX_FRAME_INFO));
    return entry;
}

void free_entry(MemPool* pool, TX_FRAME_INFO* entry) {
    if (entry) {
        pthread_mutex_lock(&pool->lock);
        entry->next = pool->data[0];
        pool->data[0] = entry;
        pthread_mutex_unlock(&pool->lock);
    }
}

void log_memory_usage(MemPool* pool) {
    printf("Current memory usage: %zu entries\n", pool->size);
}
```

