    int reading_status; // 0 for OK, 1 for ERROR
} NFIT_DEVICE_INFO_T;

// Error codes
#define SUCCESS 0
#define BUFFER_OVERFLOW -1
#define MEMORY_FAILURE -2
#define SYSTEM_LIMIT_EXCEEDED -3

int validate_input(size_t* n) {
    if (*n <= 0 || *n > (sysconf(_SC_PAGE_SIZE) * 60 / 100))
        return BUFFER_OVERFLOW;
    return SUCCESS;
}

NFIT_DEVICE_INFO_T* create_devices(size_t n) {
    int status = validate_input(&n);
    if (status != SUCCESS)
        return NULL;

    NFIT_DEVICE_INFO_T *devices = calloc(n, sizeof(NFIT_DEVICE_INFO_T));
    if (!devices) {
        free(devices);
        return NULL;
    }

    pthread_t threads[n];
    for (size_t i = 0; i < n; ++i) {
        devices[i].reading_status = rand() % 2;
        snprintf(devices[i].serial, sizeof(devices[i].serial), "%d", i);
        pthread_create(&threads[i], NULL, populate_sensor_data, &devices[i]);
    }

    for (size_t i = 0; i < n; ++i) {
        pthread_join(threads[i], NULL);
    }

    return devices;
}

void* populate_sensor_data(void *device_ptr) {
    NFIT_DEVICE_INFO_T *device = static_cast<NFIT_DEVICE_INFO_T*>(device_ptr);
    device->record.timestamp = time(NULL);
    device->record.value = rand() / (float)RAND_MAX; // Simulate sensor data
}

void deallocate_devices(NFIT_DEVICE_INFO_T* devices, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        free_aligned(devices[i].serial);
    }
    free(devices);
}
