        return -1;
    }

    // Main workflow continues without waiting for PDF generation to complete
    // ...

    pthread_join(pdfThread, NULL);

    free(structures);

    // Log completion status and any relevant performance metrics based on the provided perfMetric
    // ...

    return 0;
}

void* generatePDFWrapper(void* arg) {
    int pdfFileDescriptor = *(int*)arg;
    const int MAX_RETRY_ATTEMPTS = 3;
    int retries = 0;

    while (true) {
        if (generatePDF(pdfFileDescriptor)) {
            break;
        } else if (++retries < MAX_RETRY_ATTEMPTS) {
            sleep(1);
        } else {
            // Handle transient failures and log accordingly
            return -1;
        }
    }

    return 0;
}
