struct MEMORY_POOL_CFG_T {
    size_t max_elements;
    unsigned int rnti_start;
    unsigned int rnti_end;
    bool log_enabled;
    int log_level;
    pthread_mutex_t mutex;
};

struct MEMORY_POOL_T {
    struct NFAPI_CRC_INDICATION_PDU_T* data;
    size_t used_elements;
    size_t capacity;
    struct MEMORY_POOL_CFG_T* config;
};

static inline void log(struct MEMORY_POOL_T* pool, const char* message, int level) {
    if (level <= pool->config->log_level && pool->config->log_enabled) {
        printf("%s\n", message);
    }
}

static inline bool validate_rnti(unsigned int rnti, unsigned int start, unsigned int end) {
    return (rnti >= start && rnti < end);
}

static inline bool validate_crcflag(bool crcflag) {
    return crcflag == true || crcflag == false;
}

void initialize_memory_pool(struct MEMORY_POOL_T* pool, const struct MEMORY_POOL_CFG_T* config) {
    pool->data = malloc(config->max_elements * sizeof(*pool->data));
    if (!pool->data) {
        log(pool, "Failed to allocate memory for the array", ERROR);
        exit(-1);
    }
    pool->capacity = config->max_elements;
    pool->used_elements = 0;
    pool->config = config;
}

void destroy_memory_pool(struct MEMORY_POOL_T* pool) {
    free(pool->data);
    pool->data = NULL;
    pool->capacity = 0;
    pool->used_elements = 0;
}

struct NFAPI_CRC_INDICATION_PDU_T* get_or_allocate_pdu(struct MEMORY_POOL_T* pool) {
    pthread_mutex_lock(&pool->config->mutex);
    if (pool->used_elements < pool->capacity) {
        log(pool, "Reusing previously allocated memory", DEBUG);
        struct NFAPI_CRC_INDICATION_PDU_T* pdu = &(pool->data[pool->used_elements]);
        pool->used_elements++;
        pthread_mutex_unlock(&pool->config->mutex);
        return pdu;
    }
    pthread_mutex_unlock(&pool->config->mutex);

    struct NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(*pdu));
    if (!pdu) {
        log(pool, "Failed to allocate memory for a new PDU", ERROR);
        exit(-1);
    }
    log(pool, "Allocating new memory for a PDU", INFO);

    pdu->rxi_tag = 0;
    pdu->rnti = pool->config->rnti_start + pool->used_elements;
    while (!validate_rnti(pdu->rnti, pool->config->rnti_start, pool->config->rnti_end)) {
        pdu->rnti = pool->config->rnti_start + (pool->config->rnti_end - pool->config->rnti_start + 1) * rand() / RAND_MAX;
    }
    pdu->crc_indication_rel8_tag = 0;
    pdu->crcflag = false;

    pthread_mutex_lock(&pool->config->mutex);
    pool->used_elements++;
    pthread_mutex_unlock(&pool->config->mutex);

    return pdu;
}

void release_pdu(struct MEMORY_POOL_T* pool, struct NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!pthread_mutex_trylock(&pool->config->mutex)) {
        pthread_mutex_unlock(&pool->config->mutex);
        return;
    }

    pool->used_elements--;
    pthread_mutex_unlock(&pool->config->mutex);
}
