#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <semaphore.h>

// Data structures
typedef struct {
    uint32_t rxi;
    uint32_t rnti;
    uint16_t crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    sem_t fill_slot;
    sem_t empty_slot;
    volatile size_t head, tail, count;
    NFAPI_CRCI_DATA_T buffer[20000];
} RingBuffer;

// CRC validation function
uint8_t validate_crc(uint16_t crc) {
    static uint32_t moving_avg_sum = 0, success_count = 0, check_count = 0;
    static time_t last_check = 0;
    time_t current_time = time(NULL);

    if (current_time - last_check >= 10) {
        float rate = ((float)success_count / check_count) * 100.0f;
        if (rate < 95.0f)
            moving_avg_sum -= check_count;
        success_count = 0;
        check_count = 0;
    }

    check_count++;
    uint8_t is_valid = crc == moving_avg_sum % 256;
    if (is_valid)
        success_count++;

    last_check = current_time;
    return is_valid;
}

// RingBuffer initialization and filling function
void init_and_fill_buffer(RingBuffer* rb, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        sem_wait(&rb->empty_slot);
        rb->buffer[rb->head].rxi = i;
        rb->buffer[rb->head].rnti = rand();
        rb->buffer[rb->head].crc_indication = rand() % 256;
        ++rb->head;
        if (rb->head == ARRAY_SIZE(rb->buffer))
            rb->head = 0;
        sem_post(&rb->fill_slot);
    }
}

// Function to initialize and process NFAPI_CRC_INDICATION_PDU_T structures
void init_and_process(RingBuffer* rb, size_t n) {
    init_and_fill_buffer(rb, n);

    pthread_t threads[20];
    for (size_t i = 0; i < ARRAY_SIZE(threads); ++i) {
        int errcode = pthread_create(&threads[i], NULL, process_pdu, rb);
        if (errcode != 0) {
            fprintf(stderr, "Error creating thread: %d\n", errcode);
            exit(EXIT_FAILURE);
        }
    }

    for (size_t i = 0; i < ARRAY_SIZE(threads); ++i)
        pthread_join(threads[i], NULL);
}

// Thread-safe function to process one structure
void* process_pdu(void* arg) {
    RingBuffer* rb = (RingBuffer*)arg;
    sem_t *full_slot, *empty_slot;
    NFAPI_CRCI_DATA_T* data;

    while (1) {
        sem_wait(&rb->empty_slot);

        full_slot = &rb->empty_slot;
        empty_slot = &rb->fill_slot;
        data = &rb->buffer[rb->tail];

        if (validate_crc(data->crc_indication)) {
            ++rb->count;
            sem_post(full_slot);
        } else {
            sem_wait(empty_slot);
            rb->tail++;
            if (rb->tail == ARRAY_SIZE(rb->buffer))
                rb->tail = 0;
            sem_post(empty_slot);
        }
    }

    return NULL;
}

// Unit tests for init_and_process function
void test_init_and_process() {
    RingBuffer rb;
    rb.head = rb.tail = rb.count = 0;
    sem_init(&rb.fill_slot, 0, 0);
    sem_init(&rb.empty_slot, 0, ARRAY_SIZE(rb.buffer));

    // Test under steady-state conditions
    init_and_process(&rb, 10);

    // Test under high load conditions
    init_and_process(&rb, 20000);

    // Test edge cases with intermittent network disruptions and bursts of incoming data
    // Add additional test cases here as needed
}
