static CRC_LIST* create_crc_list(size_t capacity) {
    if (!capacity || capacity > 1024) return NULL;
    CRC_LIST* list = malloc(sizeof(CRC_LIST));
    if (!list) return NULL;
    list->list = calloc(capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->list) {
        free(list);
        return NULL;
    }
    list->capacity = capacity;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

static void destroy_crc_list(CRC_LIST* list) {
    if (list) {
        free(list->list);
        pthread_mutex_destroy(&list->mutex);
        free(list);
    }
}

void populate_nfaapi_crc_list(CRC_LIST** crc_list, size_t max_capacity) {
    if (!max_capacity || max_capacity > 1024) return;

