#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <deque>
#define MAX_STRUCTURES 200000
#define WINDOW_SIZE 60

struct TAI_INFO {
    uint32_t LTE_CELL_ID;
    uint16_t TAI;
    float SNR_TAG;
};

std::deque<struct TAI_INFO> queue;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
float moving_avg = 0.0;
int success_count = 0;

void update_moving_average(float new_value) {
    pthread_mutex_lock(&mutex);
    if (success_count >= WINDOW_SIZE) {
        moving_avg = (moving_avg * (WINDOW_SIZE - 1) + new_value) / WINDOW_SIZE;
        success_count--;
    } else {
        moving_avg += new_value;
        success_count++;
    }
    pthread_mutex_unlock(&mutex);
}

float get_moving_average() {
    pthread_mutex_lock(&mutex);
    float avg = moving_avg;
    pthread_mutex_unlock(&mutex);
    return avg;
}

bool validate_snr(struct TAI_INFO current) {
    float threshold = get_moving_average() * 0.98f;
    if (current.SNR_TAG > threshold)
        return true;
    else
        return false;
}

void init_and_populate(struct TAI_INFO** structures, int num_structures) {
    for(int i = 0; i < num_structures; i++) {
        struct TAI_INFO* structure = (struct TAI_INFO*) malloc(sizeof(struct TAI_INFO));
        structure->LTE_CELL_ID = i + 1;
        structure->TAI = i * 50 + 20000;
        structure->SNR_TAG = (float)(rand() % 100) + 1.0; // Random SNR value between 1 and 100
        if(validate_snr(*structure)) {
            queue.push_back(*structure);
        } else {
            free(structure);
        }
    }
}

// Function to handle individual structure processing, ensuring thread safety and minimal contention
void process_structure(struct TAI_INFO* structure) {
    pthread_mutex_lock(&mutex);
    if (validate_snr(*structure)) {
        queue.push_back(*structure);
        success_count++;
        update_moving_average(structure->SNR_TAG);
    }
    pthread_mutex_unlock(&mutex);
}
