class SlidingWindow {
public:
    explicit SlidingWindow(int window_size) : window_(window_size), last_processed_(0), processed_(0) {}

    void push(const LocationData& data) {
        if (data.timestamp < last_processed_)
            return;

        data_queue_.push_back(data);
        updateWindow();
    }

