        if (processed_ + data_queue_.size() > window_) {
            processed_ -= last_processed_;
            last_processed_ = std::max(last_processed_, processed_);
            if (!data_queue_.empty()) {
                auto it = std::next(std::begin(data_queue_), last_processed_);
                data_queue_.erase(std::begin(data_queue_), it);
                processData();
