// Function to allocate memory for an array of MAC_PDUs, with dynamic resizing support
MAC_PDU* allocate_mac_pdu_array(size_t size) {
    MAC_PDU** array = (MAC_PDU**)malloc(sizeof(MAC_PDU*) * size);
    if (!array) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    for (size_t i = 0; i < size; ++i) {
        array[i] = create_mac_pdu();
        if (!array[i]) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            // Free previously allocated memory and return error
            for (size_t j = 0; j < i; ++j)
                free(array[j]);
            free(array);
            return NULL;
        }
    }

