    mac_pdu->id = 0;
    mac_pdu->length = 0;
    mac_pdu->data = NULL;
    pthread_mutex_init(&mac_pdu->mutex, NULL);
    mac_pdu->next = NULL;

    return mac_pdu;
}

// Function to handle dynamic updates to the payload based on network conditions or user requests
void update_payload(MAC_PDU* mac_pdu, const void* data, size_t length) {
    // Reallocate memory for the payload if necessary
    if (mac_pdu->length < length) {
        void* new_data = realloc(mac_pdu->data, length);
        if (!new_data) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            return;
        }
        mac_pdu->data = new_data;
    }

    // Copy the new data into the payload and update its length
    memcpy(mac_pdu->data, data, length);
    mac_pdu->length = length;
}

