typedef struct point {
    float x, y;
} Point;

typedef struct vector {
    float magnitude;
    Point* point;
} Vector;

void* reduce_sum(void* arg) {
    Vector* vec = (Vector*)arg;
    return vec->magnitude;
}

int compute_reduced_sum(Vector* vectors, int num_vectors, float(*reduce)(void*)) {
    pthread_t threads[num_vectors];
    float sum = 0.0f;

    for (int i = 0; i < num_vectors; ++i) {
        pthread_create(&threads[i], NULL, reduce, &vectors[i]);
    }

    for (int i = 0; i < num_vectors; ++i) {
        void* tmp;
        pthread_join(threads[i], &tmp);
        sum += (*reduce)(tmp);
    }

    return sum;
}

