// Custom memory management using a smart pointer wrapper
struct SmartPointer {
    void *ptr;
    size_t size;
    void (*free)(void*);
};

inline void smart_pointer_init(struct SmartPointer *sp, void *ptr, size_t size, void (*destructor)(void*)) {
    sp->ptr = ptr;
    sp->size = size;
    sp->free = destructor;
}

inline void smart_pointer_delete(struct SmartPointer *sp) {
    if (sp && sp->free)
        sp->free(sp->ptr);
}

// Function to validate input and allocate memory for offsets and keys arrays
void allocate_buffers(size_t *input_size, struct SmartPointer *offsets, struct SmartPointer *keys) {
    if (*input_size <= 0) {
        fprintf(stderr, "Invalid input size\n");
        return;
    }

    offsets->ptr = malloc(*input_size * sizeof(long));
    keys->ptr = malloc(*input_size * sizeof(int));

    if (!offsets->ptr || !keys->ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    offsets->free = free;
    keys->free = free;
}

// Function to generate unique random int values for the keys array
int generate_unique_key() {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    static int max_key = 0;

    pthread_mutex_lock(&mutex);
    int key = rand();
    if (max_key < key)
        max_key = key;
    pthread_mutex_unlock(&mutex);

    return key;
}

// Function to populate the records array with keys and timestamps, ensuring no duplicates
void populate_records(struct SmartPointer *records, size_t num_records) {
    Record *data = static_cast<Record*>(records->ptr);
    int *keys = static_cast<int*>(keys->ptr);
    int unique_keys[num_records];

    for (size_t i = 0; i < num_records; ++i) {
        int key = generate_unique_key();
        data[i].key = key;
        data[i].timestamp = time(NULL);
        unique_keys[i] = key;
    }

    // Ensure no duplicates in the keys array
    for (size_t i = 1; i < num_records; ++i) {
        if (unique_keys[i] == unique_keys[i - 1]) {
            generate_unique_key(); // regenerate the key and start the loop again
        }
    }
}

// Function to dynamically allocate memory for the records array using efficient memory management practices
struct SmartPointer allocate_records(size_t num_records) {
    struct SmartPointer records;
    Record *data = static_cast<Record*>(malloc(num_records * sizeof(Record)));

    if (!data) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    records.ptr = data;
    records.size = num_records * sizeof(Record);
    records.free = free;

    return records;
}

// Function to manage dynamic memory allocation for multiple data structures under the given operational constraints
void create_dataset(size_t input_size, size_t num_records) {
    struct SmartPointer offsets, keys, records;

    allocate_buffers(&input_size, &offsets, &keys);

    if (input_size * sizeof(long) + input_size * sizeof(int) > num_records * sizeof(Record)) {
        fprintf(stderr, "Insufficient memory for the requested dataset size\n");
        exit(EXIT_FAILURE);
    }

