    struct Node* next;
} Node;

typedef struct HashTable {
    unsigned long size;
    Node** buckets;
} HashTable;

HashTable* create_hash_table(unsigned long size) {
    HashTable* table = malloc(sizeof(HashTable));
    if (!table) {
        perror("malloc: failed to allocate hash table");
        exit(EXIT_FAILURE);
    }
    table->size = size;
    table->buckets = calloc(size, sizeof(Node*));
    if (!table->buckets) {
        perror("calloc: failed to allocate buckets array");
        free(table);
        exit(EXIT_FAILURE);
    }
    return table;
}

Node* create_node(long offset, int key, Record* record, Node* next) {
    Node* node = malloc(sizeof(Node));
    if (!node) {
        perror("malloc: failed to allocate node");
        exit(EXIT_FAILURE);
    }
    node->offset = offset;
    node->key = key;
    node->record = record;
    node->next = next;
    return node;
}

Record* create_record(int value, void* next) {
    Record* record = malloc(sizeof(Record));
    if (!record) {
        perror("malloc: failed to allocate record");
        exit(EXIT_FAILURE);
    }
    record->value = value;
    record->next = next;
    return record;
}

void fill_records(unsigned long num_records, unsigned int min_val, unsigned int max_val) {
    srand(time(NULL));
    for (unsigned long i = 0; i < num_records; ++i) {
        Record* record = create_record(rand() % (max_val - min_val + 1) + min_val, NULL);
        if (!record) {
            perror("malloc: failed to allocate record");
            exit(EXIT_FAILURE);
        }
    }
}

void populate_hash_table(unsigned long num_elements, unsigned long table_size, Record** records, HashTable* hash_table) {
    for (unsigned long i = 0; i < num_elements; ++i) {
        Node* node = create_node(i, i, records[i], hash_table->buckets[(i % table_size)]);
        if (!node) {
            perror("malloc: failed to allocate node");
            exit(EXIT_FAILURE);
        }
        hash_table->buckets[(i % table_size)] = node;
    }
}

void free_hash_table(HashTable* hash_table) {
    for (unsigned long i = 0; i < hash_table->size; ++i) {
        Node* current = hash_table->buckets[i];
        while (current != NULL) {
            Node* temp = current;
            current = current->next;
            free(temp);
        }
    }
    free(hash_table->buckets);
    free(hash_table);
}
