#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct {
    int value;
    long offset;
    int key;
} record;

struct data_structure {
    record* data;
    size_t capacity;
    size_t count;
    sem_t lock;
    sem_t garbage_collection;
};

void init_data_structure(struct data_structure* ds, size_t initial_size) {
    ds->data = malloc(initial_size * sizeof(record));
    if (!ds->data) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    ds->capacity = initial_size;
    ds->count = 0;
    sem_init(&ds->lock, 0, 1);
    sem_init(&ds->garbage_collection, 0, 0);
}

void resize_data_structure(struct data_structure* ds) {
    if (ds->count >= ds->capacity * 0.75) { // Resize when 75% full
        size_t new_capacity = ds->capacity * 2;
        record* new_data = realloc(ds->data, new_capacity * sizeof(record));
        if (!new_data) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }
        ds->data = new_data;
        ds->capacity = new_capacity;
    }
}

void garbage_collection(struct data_structure* ds) {
    sem_wait(&ds->garbage_collection);

    for (size_t i = 0; i < ds->count; ++i) {
        if (ds->data[i].key == -1) { // Marked for garbage collection
            memmove(ds->data + i, ds->data + i + 1, (ds->count - i - 1) * sizeof(record));
            --ds->count;
        }
    }

    sem_post(&ds->garbage_collection);
}

bool initializeDataStructures(struct data_structure** ds_array, size_t array_size, size_t initial_size) {
    *ds_array = malloc(array_size * sizeof(struct data_structure));
    if (!*ds_array) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < array_size; ++i) {
        init_data_structure(&(*ds_array)[i], initial_size);
    }

    return true;
}

void enqueue(struct data_structure* ds, record new_record) {
    sem_wait(&ds->lock);

    resize_data_structure(ds);

    ds->data[ds->count] = new_record;
    ++ds->count;

    if (ds->count % 10 == 0) { // Trigger garbage collection periodically
        sem_post(&ds->garbage_collection);
    }

    sem_post(&ds->lock);
}

// Implement other functions for dequeue, iterate, etc. as needed
