void* array_resize(struct ArrayManager* manager, size_t new_capacity) {
    void** new_data = realloc(manager->data, new_capacity * manager->element_size);
    if (!new_data) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    manager->data = new_data;
    manager->capacity = new_capacity;
    return manager->data;
