    manager->data = calloc(initial_size, manager->element_size);
    if (!manager->data) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    manager->capacity = initial_size;
    manager->size = initial_size;
}

struct ArrayManager array_new(size_t element_size) {
