    manager.element_size = element_size;
    return manager;
}

void array_free(struct ArrayManager* manager) {
    free(manager->data);
}

double* dynamic_array_init(struct ArrayManager* manager) {
    if (manager->size == manager->capacity)
        manager->data = array_resize(manager, manager->capacity * 2);
    double* data = manager->data;
    if (!data)
        exit(EXIT_FAILURE);
    return data + manager->size++;
}

char* dynamic_string_init(struct ArrayManager* manager) {
    if (manager->size == manager->capacity)
        manager->data = array_resize(manager, manager->capacity * 2);
    char* data = manager->data + manager->size++;
    memset(data, 0, sizeof(char) * manager->element_size);
    return data;
}

