    Record* data = manager->data + manager->size++;
    return data;
}

void fill_arrays(struct ArrayManager* manager) {
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->element_size == sizeof(double)) {
            *((double*)(manager->data + i)) = rand();
        } else if (manager->element_size == sizeof(char*)) {
            char str[128];
            snprintf(str, 128, "%ld", rand());
            *(char**)((char*)(manager->data + i)) = strdup(str);
        } else if (manager->element_size == sizeof(Record)) {
            Record* record = manager->data + i;
            record->value = rand();
            snprintf(record->string, 128, "%ld", rand());
            record->timestamp = time(NULL);
        }
    }
}

void* fill_and_insert(void* data, size_t index) {
    struct ArrayManager* manager = data;
    if (index >= manager->size)
        manager->data = array_resize(manager, index + 1);
    void** new_data = manager->data;
    memmove(new_data + index + 1, new_data + index, (manager->size - index) * manager->element_size);

    if (manager->element_size == sizeof(double)) {
        *(double*)(new_data + index) = rand();
    } else if (manager->element_size == sizeof(char*)) {
        char str[128];
        snprintf(str, 128, "%ld", rand());
        *(char**)((char*)(new_data + index)) = strdup(str);
    } else if (manager->element_size == sizeof(Record)) {
        Record* record = new_data + index;
        record->value = rand();
        snprintf(record->string, 128, "%ld", rand());
        record->timestamp = time(NULL);
    }
    manager->size++;
}
