void* mmap_aligned(size_t size, size_t alignment) {
    void *ptr;
    ptr = mmap(NULL, size + alignment - 1, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ptr == MAP_FAILED) {
        return NULL;
    }
    size_t offset = (size_t)(ptr) % alignment;
    if (offset != 0) {
        ptr += alignment - offset;
    }
    return ptr;
}

