typedef struct MemPool {
    void* memory;
    size_t capacity;
    size_t used;
} MemPool;

MemPool* mem_pool_create(size_t initial_capacity) {
    if (initial_capacity > MAX_ELEMENTS) {
        fprintf(stderr, "Initial pool capacity too large\n");
        return NULL;
    }
    MemPool *mem_pool = malloc(sizeof(MemPool));
    mem_pool->memory = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    mem_pool->capacity = initial_capacity;
    mem_pool->used = 0;
    return mem_pool;
}

void* mem_pool_alloc(MemPool *mem_pool) {
    if (mem_pool->used >= mem_pool->capacity) {
        mem_pool->capacity *= 2;
        mem_pool->memory = realloc(mem_pool->memory, mem_pool->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    void* ptr = (char*)mem_pool->memory + mem_pool->used * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    mem_pool->used++;
    return ptr;
}

void mem_pool_free(MemPool *mem_pool) {
    free(mem_pool->memory);
    free(mem_pool);
}

NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_indication_pdu_allocate(size_t N, MemPool *mem_pool) {
