import os
import sys
import time
from collections import OrderedDict
from threading import Thread, Lock

class LRUCache:
    def __init__(self, max_size):
        self.cache = OrderedDict()
        self.max_size = max_size
        self.lock = Lock()

    def get(self, key):
        with self.lock:
            if key not in self.cache:
                return None
            self.cache.move_to_end(key)
        return self.cache[key]

    def put(self, key, value):
        with self.lock:
            if key in self.cache and len(self.cache) > self.max_size:
                evicted_key = self.cache.popitem(last=False)[0]
                del self.cache[evicted_key]
            self.cache[key] = value

class FileSystemCache:
    def __init__(self, cache_instance):
        self.cache = cache_instance
        self.file_path = "/path/to/cache/file"
        self.load_from_disk()
        self.save_to_disk_thread = Thread(target=self.save_to_disk)
        self.save_to_disk_thread.start()

    def load_from_disk(self):
