        foreach (array_chunk($clinicIds, 100) as $chunk) {
            $queryParams = [];
            foreach ($chunk as $clinicId) {
                // Check if the clinic ID exists in the database before updating...
                $stmt = $db->prepare("SELECT id FROM clinics WHERE id = :clinicId");
                $stmt->execute([':clinicId' => $clinicId]);
