                    throw new Exception("Failed to verify clinic status for ID: {$clinicId}");
                }

                $ipAddress = $_SERVER['REMOTE_ADDR']; // Get the IP address of the request...
                $lastModifiedDate = new \DateTime(); // Set the last modified date and time...

                $queryParams[] = [':clinicId' => $clinicId, ':status' => $status, ':ipAddress' => $ipAddress, ':lastModifiedDate' => $lastModifiedDate];
            }

            if (empty($queryParams)) {
                continue; // Skip the iteration if there are no clinics to update...
            }

            $stmt = $db->prepare("UPDATE clinics SET status = :status, last_modified_ip = :ipAddress, last_modified_date = :lastModifiedDate WHERE id IN (:" . implode(',:', array_keys($queryParams)) . ")");
            $stmt->execute($queryParams);
            $affectedRows += $stmt->rowCount();
        }

        if ($affectedRows > 0) {
            $service->logUpdate(...array_merge([$affectedRows], array_map(fn($params) => $params[':clinicId'], $queryParams)));
            $service->sendNotification(...array_map(fn($params) => $params[':clinicId'], $queryParams));
        }

        $db->commit();

        return "Successfully updated {$affectedRows} clinics.";
    } catch (\Exception $e) {
        $db->rollback();
        return "Error updating clinics: {$e->getMessage()}";
    }
}
