typedef enum {
    LOG_LEVEL_DEBUG,
    LOG_LEVEL_INFO,
    LOG_LEVEL_WARNING,
    LOG_LEVEL_ERROR,
    LOG_LEVEL_CRITICAL,
    LOG_LEVEL_COUNT
} log_level;

struct log_config {
    char *log_file_path;
    int log_rotation_interval;
    log_level log_level;
};

int init_logging(const char *config_path, struct log_config *out_config) {
    json_t *root, *log_section;
    int log_level_index;
    struct stat file_stat;
    int fd, ret = 0;

    root = json_load_file(config_path, 0, NULL);
    if (!root) {
        perror("Error loading JSON configuration");
        return 1;
    }

    log_section = json_object_get(root, "logging");
    if (!log_section || !json_is_object(log_section)) {
        fprintf(stderr, "Invalid logging section in configuration\n");
        ret = 1;
        goto cleanup;
    }

    out_config->log_file_path = json_string_value(json_object_get(log_section, "log_file"));
    if (!out_config->log_file_path || strchr(out_config->log_file_path, '/') == NULL) {
        fprintf(stderr, "Invalid log file path in configuration\n");
        ret = 1;
        goto cleanup;
    }

    if (stat(out_config->log_file_path, &file_stat) < 0 || !S_ISDIR(file_stat.st_mode)) {
        fprintf(stderr, "Log file path is not a valid directory\n");
        ret = 1;
        goto cleanup;
    }

    out_config->log_rotation_interval = json_integer_value(json_object_get(log_section, "log_rotation_interval"));
    if (out_config->log_rotation_interval < 0) {
        fprintf(stderr, "Invalid log rotation interval in configuration\n");
        ret = 1;
        goto cleanup;
    }

    out_config->log_level = LOG_LEVEL_INFO; // Default log level

    if (json_object_has_member(log_section, "log_level")) {
        const char *log_level_str = json_string_value(json_object_get(log_section, "log_level"));

        for (log_level_index = 0; log_level_index < LOG_LEVEL_COUNT; ++log_level_index) {
            if (strcmp(log_level_str, log_level_strings[log_level_index]) == 0) {
                out_config->log_level = (log_level)log_level_index;
                break;
            }
        }

        if (log_level_index >= LOG_LEVEL_COUNT) {
            fprintf(stderr, "Invalid log level in configuration\n");
            ret = 1;
            goto cleanup;
        }
    }

cleanup:
    json_decref(root);

    if (ret == 0 && out_config->log_rotation_interval > 0) {
        // Implement log rotation mechanism here, e.g., using a named pipe or rotating files.
    }

    if (ret) {
        fd = open("/dev/null", O_WRONLY);
        if (fd >= 0) {
            setvbuf(stdout, NULL, _IONBF, 0);
            setvbuf(stderr, NULL, _IONBF, 0);
            fprintf(stderr, "Using default log configuration\n");
        } else {
            perror("Error opening /dev/null for fallback logging");
        }
    }

    return ret;
}
```

