void init_element(NFAPI_CRC_INDICATION_PDU_T* element) {
    element->tag = (RX_UE_INFORMATION_TAG)rand() % MAX_TAG_VALUE;
    element->rnti = ++global_rnti;
    element->crc_indication.crcflag = rand() % 2;
}

size_t find_empty_slot(NFAPI_CRC_INDICATION_PDU_T* array, size_t N) {
    for (size_t i = 0; i < N; ++i) {
        if (!array[i].tag) {
            return i;
        }
    }
    return -1; // Array is full
}

void resize_array(NFAPI_CRC_INDICATION_PDU_T** array, size_t* capacity, size_t* size) {
    *capacity *= 2;
    NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(*array, *capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        fprintf(stderr, "Failed to allocate memory for resized array\n");
        exit(EXIT_FAILURE);
    }
    *array = new_array;
    *size = *capacity;
}

NFAPI_CRC_INDICATION_PDU_T* get_element_by_index(const NFAPI_CRC_INDICATION_PDU_T* array, size_t index) {
    return &array[index];
}

void free_array(NFAPI_CRC_INDICATION_PDU_T* array, size_t capacity) {
    free(array);
}

int main() {
    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T* array = create_array(10);
    size_t capacity = 10;
    size_t size = 0;
    global_rnti = 0;

    while (1) {
        size_t empty_slot = find_empty_slot(array, capacity);
        if (empty_slot == -1) {
            resize_array(&array, &capacity, &size);
        }
        init_element(get_element_by_index(array, empty_slot));
        log_change("Element added");
    }

    free_array(array, capacity);
    return 0;
}
