#define MAX_LIST_SIZE M // Configurable parameter

typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    struct _NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

static NFAPI_CRC_INDICATION_PDU_T* head = NULL;
static NFAPI_CRC_INDICATION_PDU_T* tail = NULL;
static pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
static size_t list_size = 0;
static bool is_valid[MAX_LIST_SIZE + 1]; // Valid range: [0, MAX_LIST_SIZE]
static pthread_mutex_t valid_range_lock = PTHREAD_MUTEX_INITIALIZER;
static size_t resize_count = 0;

void init_list() {
    for (size_t i = 0; i <= MAX_LIST_SIZE; ++i) {
        is_valid[i] = true;
    }
}

bool is_tag_and_rnti_valid(RX_UE_INFORMATION_TAG tag, uint32_t rnti) {
    pthread_mutex_lock(&valid_range_lock);
    if (is_valid[tag] && is_valid[rnti]) {
        is_valid[tag] = false;
        is_valid[rnti] = false;
        pthread_mutex_unlock(&valid_range_lock);
        return true;
    }
    pthread_mutex_unlock(&valid_range_lock);
    return false;
}

void add_to_list(NFAPI_CRC_INDICATION_PDU_T* node) {
    pthread_mutex_lock(&list_lock);
    if (list_size < MAX_LIST_SIZE) {
        if (!node->next) {
            node->next = NULL;
            if (!tail) head = node;
            else tail->next = node;
            tail = node;
            ++list_size;
        }
    } else { // List reached maximum size, remove the oldest element and add new one
        resize_count++;
        NFAPI_CRC_INDICATION_PDU_T* temp = head;
        if (temp->next) {
            head = temp->next;
            free(temp);
        } else {
            tail = NULL;
            free(head);
            head = node;
            tail = node;
        }
        if (!node->next) {
            node->next = NULL;
            if (!tail) head = node;
            else tail->next = node;
            tail = node;
            ++list_size;
        }
    }
    pthread_mutex_unlock(&list_lock);
}
```

