void* pool_alloc(size_t size) {
    if (mem_pool.capacity == 0) {
        void* new_mem = mmap(NULL, mem_pool.size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (new_mem == MAP_FAILED) {
            perror("mmap");
            exit(EXIT_FAILURE);
        }
        memset(new_mem, 0, mem_pool.size);
        mem_pool.mem_pool = new_mem;
        mem_pool.capacity += mem_pool.size;
    }

    void* result = mem_pool.mem_pool;
    mem_pool.mem_pool += size;
    return result;
}

void pool_free(void *ptr) {
    if (mem_pool.capacity > mem_pool.size) {
        memset(ptr, 0, mem_pool.size);
        mem_pool.mem_pool = ptr;
        mem_pool.capacity -= mem_pool.size;
    }
}

